INSERT INTO public.scholars_authors (id, slug, name_arabic, name_english, name_urdu, death_year_ah, death_year_ce, era, role, biography_summary) VALUES ('00000000-0000-0000-0001-000000000001', 'imam-bukhari', 'الإمام محمد بن إسماعيل البخاري', 'Imam Muhammad ibn Isma''il al-Bukhari', 'امام محمد بن اسماعیل بخاری', 256, 870, 'classical', 'compiler', 'Amir al-Mu''minin fi al-Hadith; compiler of Sahih al-Bukhari (Al-Jami'' al-Sahih al-Musnad al-Mukhtasar min Umuri Rasulillahi wa Sunanihi wa Ayyamihi).')
INSERT INTO public.scholars_authors (id, slug, name_arabic, name_english, name_urdu, death_year_ah, death_year_ce, era, role, biography_summary) VALUES ('00000000-0000-0000-0001-000000000002', 'imam-muslim', 'الإمام مسلم بن الحجاج النيسابوري', 'Imam Muslim ibn al-Hajjaj an-Naysaburi', 'امام مسلم بن الحجاج نیشاپوری', 261, 875, 'classical', 'compiler', 'Great Hadith master and compiler of Sahih Muslim (Al-Musnad al-Sahih al-Mukhtasar bi Naql al-''Adl ''an al-''Adl ila Rasulillahi).')
INSERT INTO public.scholars_authors (id, slug, name_arabic, name_english, name_urdu, death_year_ah, death_year_ce, era, role, biography_summary) VALUES ('00000000-0000-0000-0001-000000000003', 'imam-abu-dawud', 'الإمام أبو داود سليمان بن الأشعث السجستاني', 'Imam Abu Dawud Sulayman ibn al-Ash''ath as-Sijistani', 'امام ابو داود سلیمان بن اشعث سجستانی', 275, 889, 'classical', 'compiler', 'Master jurist-muhaddith; author of Sunan Abi Dawud, the primary collection devoted to Ahkam (legal rulings) narrations.')
INSERT INTO public.scholars_authors (id, slug, name_arabic, name_english, name_urdu, death_year_ah, death_year_ce, era, role, biography_summary) VALUES ('00000000-0000-0000-0001-000000000004', 'imam-tirmidhi', 'الإمام محمد بن عيسى الترمذي', 'Imam Muhammad ibn ''Isa at-Tirmidhi', 'امام محمد بن عیسیٰ ترمذی', 279, 892, 'classical', 'compiler', 'Renowned Hadith master and student of al-Bukhari; compiler of Jami'' at-Tirmidhi, pioneer in documenting hadith gradings and jurisprudential differences.')
INSERT INTO public.scholars_authors (id, slug, name_arabic, name_english, name_urdu, death_year_ah, death_year_ce, era, role, biography_summary) VALUES ('00000000-0000-0000-0001-000000000005', 'imam-nasai', 'الإمام أحمد بن شعيب النسائي', 'Imam Ahmad ibn Shu''ayb an-Nasa''i', 'امام احمد بن شعیب نسائی', 303, 915, 'classical', 'compiler', 'Hadith master of Khurasan and Egypt; compiler of Al-Sunan al-Sughra (Al-Mujtaba), celebrated for extremely rigorous narrator criteria.')
INSERT INTO public.scholars_authors (id, slug, name_arabic, name_english, name_urdu, death_year_ah, death_year_ce, era, role, biography_summary) VALUES ('00000000-0000-0000-0001-000000000006', 'imam-ibn-majah', 'الإمام محمد بن يزيد بن ماجه القزويني', 'Imam Muhammad ibn Yazid Ibn Majah', 'امام محمد بن یزید ابن ماجہ', 273, 887, 'classical', 'compiler', 'Hadith scholar of Qazwin; compiler of Sunan Ibn Majah, completing the traditional Kutub al-Sittah corpus.')
INSERT INTO public.scholars_authors (id, slug, name_arabic, name_english, name_urdu, death_year_ah, death_year_ce, era, role, biography_summary) VALUES ('00000000-0000-0000-0002-000000000001', 'al-albani', 'الشيخ محمد ناصر الدين الألباني', 'Shaykh Muhammad Nasir al-Din al-Albani', 'شیخ محمد ناصر الدین البانی', 1420, 1999, 'contemporary', 'evaluator', 'Major 20th-century Muhaddith; author of Silsilat al-Ahadith al-Sahihah, Silsilat al-Ahadith al-Da''ifah, Sahih wa Da''if Sunan Abi Dawud, Sahih wa Da''if al-Tirmidhi, and Irwa'' al-Ghalil.')
INSERT INTO public.scholars_authors (id, slug, name_arabic, name_english, name_urdu, death_year_ah, death_year_ce, era, role, biography_summary) VALUES ('00000000-0000-0000-0002-000000000002', 'arnaut', 'الشيخ شعيب الأرنؤوط', 'Shaykh Shu''ayb al-Arna''ut', 'شیخ شعیب الارناؤوط', 1438, 2016, 'contemporary', 'evaluator', 'Distinguished Syrian-Albanian Muhaddith and critical editor; tahqiq and verification of Musnad Ahmad, Sunan Abi Dawud, Sahih Ibn Hibban, and Sharh al-Sunnah.')
INSERT INTO public.scholars_authors (id, slug, name_arabic, name_english, name_urdu, death_year_ah, death_year_ce, era, role, biography_summary) VALUES ('00000000-0000-0000-0002-000000000003', 'ahmad-shakir', 'الشيخ أحمد محمد شاكر', 'Shaykh Ahmad Muhammad Shakir', 'شیخ احمد محمد شاکر', 1377, 1958, 'contemporary', 'evaluator', 'Eminent Egyptian jurist and Hadith scholar; pioneering tahqiq and verification of Jami'' at-Tirmidhi, Musnad Ahmad, and Al-Ba''ith al-Hathith.')
INSERT INTO public.scholars_authors (id, slug, name_arabic, name_english, name_urdu, death_year_ah, death_year_ce, era, role, biography_summary) VALUES ('00000000-0000-0000-0002-000000000004', 'zubair-ali-zai', 'الشيخ حافظ زبير علي زئي', 'Shaykh Hafiz Zubair Ali Zai', 'شیخ حافظ زبیر علی زئی', 1435, 2013, 'contemporary', 'evaluator', 'Pakistani Hadith scholar and researcher; critical verification and tahqiq of the Kutub al-Sittah and Mishkat al-Masabih for Darussalam Publishers.')
INSERT INTO public.scholars_authors (id, slug, name_arabic, name_english, name_urdu, death_year_ah, death_year_ce, era, role, biography_summary) VALUES ('00000000-0000-0000-0002-000000000005', 'darussalam-committee', 'لجنة البحث العلمي بدار السلام', 'Darussalam Research Committee', 'دار السلام ریسرچ کمیٹی', NULL, NULL, 'contemporary', 'evaluator', 'Scholarly editorial research division of Darussalam Publishers (Riyadh); verified international numbering and cross-referencing for Kutub al-Sittah.')
INSERT INTO public.scholars_authors (id, slug, name_arabic, name_english, name_urdu, death_year_ah, death_year_ce, era, role, biography_summary) VALUES ('00000000-0000-0000-0002-000000000006', 'abdul-hamid', 'الشيخ محمد محيي الدين عبد الحميد', 'Shaykh Muhammad Muhyi al-Din Abdul Hamid', 'شیخ محمد محیی الدین عبد الحمید', 1392, 1972, 'contemporary', 'evaluator', 'Egyptian scholar and editor of Sunan Abi Dawud and classical Arabic grammatical and hadith literature.')
INSERT INTO public.scholars_authors (id, slug, name_arabic, name_english, name_urdu, death_year_ah, death_year_ce, era, role, biography_summary) VALUES ('00000000-0000-0000-0002-000000000007', 'abd-al-baqi', 'الشيخ محمد فؤاد عبد الباقي', 'Shaykh Muhammad Fouad Abd al-Baqi', 'شیخ محمد فواد عبد الباقی', 1388, 1968, 'contemporary', 'evaluator', 'Renowned Egyptian hadith indexer and scholar; standardized indexing and numbering of Sahih Muslim and Sunan Ibn Majah.')
INSERT INTO public.scholars_authors (id, slug, name_arabic, name_english, name_urdu, death_year_ah, death_year_ce, era, role, biography_summary) VALUES ('00000000-0000-0000-0002-000000000008', 'abu-ghuddah', 'الشيخ عبد الفتاح أبو غدة', 'Shaykh Abd al-Fattah Abu Ghuddah', 'شیخ عبد الفتاح ابو غدہ', 1417, 1997, 'contemporary', 'evaluator', 'Syrian Hadith scholar and educator; tahqiq and notes on Sunan an-Nasa''i and classical biographical works.')
INSERT INTO public.scholars_authors (id, slug, name_arabic, name_english, name_urdu, death_year_ah, death_year_ce, era, role, biography_summary) VALUES ('00000000-0000-0000-0002-000000000009', 'bashar-awad', 'الدكتور بشار عواد معروف', 'Dr. Bashar Awad Ma''rouf', 'ڈاکٹر بشار عواد معروف', NULL, NULL, 'contemporary', 'evaluator', 'Contemporary Iraqi-Jordanian critical editor; tahqiq and verification of Jami'' at-Tirmidhi, Sunan Ibn Majah, and Musnad Ahmad.')
INSERT INTO public.hadith_collections (id, slug, name_arabic, name_english, name_urdu, author_id, total_hadiths, total_books, description, provenance_notes, source_edition, source_url, status) VALUES ('bukhari', 'sahih-al-bukhari', 'صحيح البخاري', 'Sahih al-Bukhari', 'صحیح البخاری', '00000000-0000-0000-0001-000000000001', 7563, 97, 'Al-Jami'' al-Sahih al-Musnad al-Mukhtasar min Umuri Rasulillahi wa Sunanihi wa Ayyamihi, compiled by Imam Muhammad ibn Isma''il al-Bukhari. The most authentic book of Hadith in Sunni Islam.', 'Transmitted via verified chains, canonical Al-Firabri recension, standardized Darussalam international numbering.', 'Darussalam / Shamela / Sunnah.com reference edition', 'https://sunnah.com/bukhari', 'published')
INSERT INTO public.hadith_collections (id, slug, name_arabic, name_english, name_urdu, author_id, total_hadiths, total_books, description, provenance_notes, source_edition, source_url, status) VALUES ('muslim', 'sahih-muslim', 'صحيح مسلم', 'Sahih Muslim', 'صحیح مسلم', '00000000-0000-0000-0001-000000000002', 7563, 56, 'Al-Musnad al-Sahih al-Mukhtasar bi Naql al-''Adl ''an al-''Adl ila Rasulillahi, compiled by Imam Muslim ibn al-Hajjaj. Peer of Sahih al-Bukhari in authority and superior in arrangement.', 'Transmitted through Abu Ishaq Ibrahim ibn Muhammad ibn Sufyan al-Faqih; standardized numbering of Muhammad Fouad Abd al-Baqi.', 'Darussalam / Sunnah.com reference edition', 'https://sunnah.com/muslim', 'published')
INSERT INTO public.hadith_collections (id, slug, name_arabic, name_english, name_urdu, author_id, total_hadiths, total_books, description, provenance_notes, source_edition, source_url, status) VALUES ('abudawud', 'sunan-abi-dawud', 'سنن أبي داود', 'Sunan Abi Dawud', 'سنن ابوداؤد', '00000000-0000-0000-0001-000000000003', 5274, 43, 'Sunan Abi Dawud, compiled by Imam Abu Dawud as-Sijistani. The premier Sunan focusing on legal ahkam narrations, annotated with critical evaluations.', 'Transmitted via Abu ''Ali al-Lu''lu''i and Ibn Dasah recensions; verified with annotations by contemporary hadith evaluators.', 'Darussalam / Sunnah.com reference edition', 'https://sunnah.com/abudawud', 'published')
INSERT INTO public.hadith_collections (id, slug, name_arabic, name_english, name_urdu, author_id, total_hadiths, total_books, description, provenance_notes, source_edition, source_url, status) VALUES ('tirmidhi', 'jami-at-tirmidhi', 'جامع الترمذي', 'Jami'' at-Tirmidhi', 'جامع ترمذی', '00000000-0000-0000-0001-000000000004', 3956, 49, 'Al-Jami'' al-Kabir (Sunan at-Tirmidhi), compiled by Imam Abu ''Isa at-Tirmidhi. Renowned for documenting Hadith gradings (Sahih, Hasan, Gharib) and legal opinions of classical jurists.', 'Standardized text based on critical editions of Ahmad Shakir and Bashar Awad Ma''rouf.', 'Darussalam / Sunnah.com reference edition', 'https://sunnah.com/tirmidhi', 'published')
INSERT INTO public.hadith_collections (id, slug, name_arabic, name_english, name_urdu, author_id, total_hadiths, total_books, description, provenance_notes, source_edition, source_url, status) VALUES ('nasai', 'sunan-an-nasai', 'سنن النسائي (المجتبى)', 'Sunan an-Nasa''i', 'سنن نسائی', '00000000-0000-0000-0001-000000000005', 5758, 51, 'Al-Sunan al-Sughra (Al-Mujtaba), compiled by Imam Ahmad ibn Shu''ayb an-Nasa''i. Esteemed for its rigorous narrator selection and analysis of hidden narrator defects.', 'Transmitted via Ibn al-Sunni; standardized international Darussalam numbering.', 'Darussalam / Sunnah.com reference edition', 'https://sunnah.com/nasai', 'published')
INSERT INTO public.hadith_collections (id, slug, name_arabic, name_english, name_urdu, author_id, total_hadiths, total_books, description, provenance_notes, source_edition, source_url, status) VALUES ('ibnmajah', 'sunan-ibn-majah', 'سنن ابن ماجه', 'Sunan Ibn Majah', 'سنن ابن ماجہ', '00000000-0000-0000-0001-000000000006', 4341, 37, 'Sunan Ibn Majah, compiled by Imam Muhammad ibn Yazid Ibn Majah al-Qazwini. The sixth canonical Sunan work, recognized for valuable unique legal narrations.', 'Standardized numbering of Muhammad Fouad Abd al-Baqi and Darussalam research division.', 'Darussalam / Sunnah.com reference edition', 'https://sunnah.com/ibnmajah', 'published')
