INSERT INTO public.hadith_narrations (id, collection_id, book_id, hadith_number, in_book_reference, international_number, chapter_title_arabic, chapter_title_english, sanad_arabic, matn_arabic, matn_clean, translation_english, translation_urdu, text_checksum, source_edition, version_number, is_current, status) VALUES
  (1, 'bukhari', 2, 1, 'Book 1, Hadith 1', 1, NULL, NULL, 'حَدَّثَنَا الْحُمَيْدِيُّ عَبْدُ اللَّهِ بْنُ الزُّبَيْرِ ، قَالَ : حَدَّثَنَا سُفْيَانُ ، قَالَ : حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ الْأَنْصَارِيُّ ، قَالَ : أَخْبَرَنِي مُحَمَّدُ بْنُ إِبْرَاهِيمَ التَّيْمِيُّ ، أَنَّهُ سَمِعَ عَلْقَمَةَ بْنَ وَقَّاصٍ اللَّيْثِيَّ ، يَقُولُ : سَمِعْتُ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ عَلَى الْمِنْبَرِ، قَالَ : سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ', ': " إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى دُنْيَا يُصِيبُهَا أَوْ إِلَى امْرَأَةٍ يَنْكِحُهَا، فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ', ': " انما الاعمال بالنيات، وانما لكل امرئ ما نوي، فمن كانت هجرته الي دنيا يصيبها او الي امراه ينكحها، فهجرته الي ما هاجر اليه', 'Narrated ''Umar bin Al-Khattab: I heard Allah''s Messenger (ﷺ) saying, "The reward of deeds depends upon the intentions and every person will get the reward according to what he has intended. So whoever emigrated for worldly benefits or for a woman to marry, his emigration was for what he emigrated for', NULL, '7bac86fa69bba97ef28425fc73c3bb3be1f5f83d0177eaf2d088a1670bcab744', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (2, 'bukhari', 2, 2, 'Book 1, Hadith 2', 2, NULL, NULL, 'حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، قَالَ أَخْبَرَنَا مَالِكٌ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ـ رضى الله عنها ـ أَنَّ الْحَارِثَ بْنَ هِشَامٍ ـ رضى الله عنه ـ سَأَلَ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقَالَ يَا رَسُولَ اللَّهِ كَيْفَ يَأْتِيكَ الْوَحْىُ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ أَحْيَانًا يَأْتِينِي مِثْلَ صَلْصَلَةِ الْجَرَسِ ـ وَهُوَ أَشَدُّهُ عَلَىَّ ـ فَيُفْصَمُ عَنِّي وَقَدْ وَعَيْتُ عَنْهُ مَا قَالَ، وَأَحْيَانًا يَتَمَثَّلُ لِيَ الْمَلَكُ رَجُلاً فَيُكَلِّمُنِي فَأَعِي مَا يَقُولُ ‏"‏‏.‏ قَالَتْ عَائِشَةُ رضى الله عنها وَلَقَدْ رَأَيْتُهُ يَنْزِلُ عَلَيْهِ الْوَحْىُ فِي الْيَوْمِ الشَّدِيدِ الْبَرْدِ، فَيَفْصِمُ عَنْهُ وَإِنَّ جَبِينَهُ لَيَتَفَصَّدُ عَرَقًا‏.‏', '"‏ احيانا ياتيني مثل صلصله الجرس وهو اشده علي فيفصم عني وقد وعيت عنه ما قال، واحيانا يتمثل لي الملك رجلا فيكلمني فاعي ما يقول ‏"‏‏.‏ قالت عائشه رضي الله عنها ولقد رايته ينزل عليه الوحي في اليوم الشديد البرد، فيفصم عنه وان جبينه ليتفصد عرقا‏.‏', 'Narrated ''Aisha: (the mother of the faithful believers) Al-Harith bin Hisham asked Allah''s Messenger (ﷺ) "O Allah''s Messenger (ﷺ)! How is the Divine Inspiration revealed to you?" Allah''s Messenger (ﷺ) replied, "Sometimes it is (revealed) like the ringing of a bell, this form of Inspiration is the hardest of all and then this state passes off after I have grasped what is inspired. Sometimes the Angel comes in the form of a man and talks to me and I grasp whatever he says." ''Aisha added: Verily I saw the Prophet (ﷺ) being inspired divinely on a very cold day and noticed the sweat dropping from his forehead (as the Inspiration was over)', NULL, '2ac48f88657e6494b5cd1b43b04f4ec6fb90acbb5c3e54adbfc3a5c0f9656b00', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (3, 'bukhari', 2, 3, 'Book 1, Hadith 3', 3, NULL, NULL, 'حَدَّثَنَا يَحْيَى بْنُ بُكَيْرٍ، قَالَ حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، عَنِ ابْنِ شِهَابٍ، عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ، عَنْ عَائِشَةَ أُمِّ الْمُؤْمِنِينَ، أَنَّهَا قَالَتْ أَوَّلُ مَا بُدِئَ بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم مِنَ الْوَحْىِ الرُّؤْيَا الصَّالِحَةُ فِي النَّوْمِ، فَكَانَ لاَ يَرَى رُؤْيَا إِلاَّ جَاءَتْ مِثْلَ فَلَقِ الصُّبْحِ، ثُمَّ حُبِّبَ إِلَيْهِ الْخَلاَءُ، وَكَانَ يَخْلُو بِغَارِ حِرَاءٍ فَيَتَحَنَّثُ فِيهِ ـ وَهُوَ التَّعَبُّدُ ـ اللَّيَالِيَ ذَوَاتِ الْعَدَدِ قَبْلَ أَنْ يَنْزِعَ إِلَى أَهْلِهِ، وَيَتَزَوَّدُ لِذَلِكَ، ثُمَّ يَرْجِعُ إِلَى خَدِيجَةَ، فَيَتَزَوَّدُ لِمِثْلِهَا، حَتَّى جَاءَهُ الْحَقُّ وَهُوَ فِي غَارِ حِرَاءٍ، فَجَاءَهُ الْمَلَكُ فَقَالَ اقْرَأْ‏.‏ قَالَ ‏"‏ مَا أَنَا بِقَارِئٍ ‏"‏‏.‏ قَالَ ‏"‏ فَأَخَذَنِي فَغَطَّنِي حَتَّى بَلَغَ مِنِّي الْجَهْدَ، ثُمَّ أَرْسَلَنِي فَقَالَ اقْرَأْ‏.‏ قُلْتُ مَا أَنَا بِقَارِئٍ‏.‏ فَأَخَذَنِي فَغَطَّنِي الثَّانِيَةَ حَتَّى بَلَغَ مِنِّي الْجَهْدَ، ثُمَّ أَرْسَلَنِي فَقَالَ اقْرَأْ‏.‏ فَقُلْتُ مَا أَنَا بِقَارِئٍ‏.‏ فَأَخَذَنِي فَغَطَّنِي الثَّالِثَةَ، ثُمَّ أَرْسَلَنِي فَقَالَ ‏{‏اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ * خَلَقَ الإِنْسَانَ مِنْ عَلَقٍ * اقْرَأْ وَرَبُّكَ الأَكْرَمُ‏}‏ ‏"‏‏.‏ فَرَجَعَ بِهَا رَسُولُ اللَّهِ صلى الله عليه وسلم يَرْجُفُ فُؤَادُهُ، فَدَخَلَ عَلَى خَدِيجَةَ بِنْتِ خُوَيْلِدٍ رضى الله عنها فَقَالَ ‏"‏ زَمِّلُونِي زَمِّلُونِي ‏"‏‏.‏ فَزَمَّلُوهُ حَتَّى ذَهَبَ عَنْهُ الرَّوْعُ، فَقَالَ لِخَدِيجَةَ وَأَخْبَرَهَا الْخَبَرَ ‏"‏ لَقَدْ خَشِيتُ عَلَى نَفْسِي ‏"‏‏.‏ فَقَالَتْ خَدِيجَةُ كَلاَّ وَاللَّهِ مَا يُخْزِيكَ اللَّهُ أَبَدًا، إِنَّكَ لَتَصِلُ الرَّحِمَ، وَتَحْمِلُ الْكَلَّ، وَتَكْسِبُ الْمَعْدُومَ، وَتَقْرِي الضَّيْفَ، وَتُعِينُ عَلَى نَوَائِبِ الْحَقِّ‏.‏ فَانْطَلَقَتْ بِهِ خَدِيجَةُ حَتَّى أَتَتْ بِهِ وَرَقَةَ بْنَ نَوْفَلِ بْنِ أَسَدِ بْنِ عَبْدِ الْعُزَّى ابْنَ عَمِّ خَدِيجَةَ ـ وَكَانَ امْرَأً تَنَصَّرَ فِي الْجَاهِلِيَّةِ، وَكَانَ يَكْتُبُ الْكِتَابَ الْعِبْرَانِيَّ، فَيَكْتُبُ مِنَ الإِنْجِيلِ بِالْعِبْرَانِيَّةِ مَا شَاءَ اللَّهُ أَنْ يَكْتُبَ، وَكَانَ شَيْخًا كَبِيرًا قَدْ عَمِيَ ـ فَقَالَتْ لَهُ خَدِيجَةُ يَا ابْنَ عَمِّ اسْمَعْ مِنَ ابْنِ أَخِيكَ‏.‏ فَقَالَ لَهُ وَرَقَةُ يَا ابْنَ أَخِي مَاذَا تَرَى فَأَخْبَرَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم خَبَرَ مَا رَأَى‏.‏ فَقَالَ لَهُ وَرَقَةُ هَذَا النَّامُوسُ الَّذِي نَزَّلَ اللَّهُ عَلَى مُوسَى صلى الله عليه وسلم يَا لَيْتَنِي فِيهَا جَذَعًا، لَيْتَنِي أَكُونُ حَيًّا إِذْ يُخْرِجُكَ قَوْمُكَ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏', 'أَوَمُخْرِجِيَّ هُمْ ‏"‏‏.‏ قَالَ نَعَمْ، لَمْ يَأْتِ رَجُلٌ قَطُّ بِمِثْلِ مَا جِئْتَ بِهِ إِلاَّ عُودِيَ، وَإِنْ يُدْرِكْنِي يَوْمُكَ أَنْصُرْكَ نَصْرًا مُؤَزَّرًا‏.‏ ثُمَّ لَمْ يَنْشَبْ وَرَقَةُ أَنْ تُوُفِّيَ وَفَتَرَ الْوَحْىُ‏.‏', 'اومخرجي هم ‏"‏‏.‏ قال نعم، لم يات رجل قط بمثل ما جئت به الا عودي، وان يدركني يومك انصرك نصرا مؤزرا‏.‏ ثم لم ينشب ورقه ان توفي وفتر الوحي‏.‏', 'Narrated ''Aisha (the mother of the faithful believers):The commencement of the Divine Inspiration to Allah''s Messenger (ﷺ) was in the form of good dreams which came true like bright daylight, and then the love of seclusion was bestowed upon him. He used to go in seclusion in the cave of Hira where he used to worship (Allah alone) continuously for many days before his desire to see his family. He used to take with him the journey food for the stay and then come back to (his wife) Khadija to take his food likewise again till suddenly the Truth descended upon him while he was in the cave of Hira. The angel came to him and asked him to read. The Prophet (ﷺ) replied, "I do not know how to read." The Prophet (ﷺ) added, "The angel caught me (forcefully) and pressed me so hard that I could not bear it any more. He then released me and again asked me to read and I replied, ''I do not know how to read.'' Thereupon he caught me again and pressed me a second time till I could not bear it any more. He then released me and again asked me to read but again I replied, ''I do not know how to read (or what shall I read)?'' Thereupon he caught me for the third time and pressed me, and then released me and said, ''Read in the name of your Lord, who has created (all that exists), created man from a clot. Read! And your Lord is the Most Generous." (96.1, 96.2, 96.3) Then Allah''s Messenger (ﷺ) returned with the Inspiration and with his heart beating severely. Then he went to Khadija bint Khuwailid and said, "Cover me! Cover me!" They covered him till his fear was over and after that he told her everything that had happened and said, "I fear that something may happen to me." Khadija replied, "Never! By Allah, Allah will never disgrace you. You keep good relations with your kith and kin, help the poor and the destitute, serve your guests generously and assist the deserving calamity-afflicted ones." Khadija then accompanied him to her cousin Waraqa bin Naufal bin Asad bin ''Abdul ''Uzza, who, during the pre-Islamic Period became a Christian and used to write the writing with Hebrew letters. He would write from the Gospel in Hebrew as much as Allah wished him to write. He was an old man and had lost his eyesight. Khadija said to Waraqa, "Listen to the story of your nephew, O my cousin!" Waraqa asked, "O my nephew! What have you seen?" Allah''s Messenger (ﷺ) described whatever he had seen. Waraqa said, "This is the same one who keeps the secrets (angel Gabriel) whom Allah had sent to Moses. I wish I were young and could live up to the time when your people would turn you out." Allah''s Messenger (ﷺ) asked, "Will they drive me out?" Waraqa replied in the affirmative and said, "Anyone (man) who came with something similar to what you have brought was treated with hostility; and if I should remain alive till the day when you will be turned out then I would support you strongly." But after a few days Waraqa died and the Divine Inspiration was also paused for a while', NULL, 'c3ab45b205a52f87b265425a1930552ff41ce4cde45457ec57e4f9807d107d57', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (4, 'bukhari', 2, 4, 'Book 1, Hadith 4', 4, NULL, NULL, NULL, 'قَالَ ابْنُ شِهَابٍ وَأَخْبَرَنِي أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ، أَنَّ جَابِرَ بْنَ عَبْدِ اللَّهِ الأَنْصَارِيَّ، قَالَ ـ وَهُوَ يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ، فَقَالَ ـ فِي حَدِيثِهِ ‏"‏ بَيْنَا أَنَا أَمْشِي، إِذْ سَمِعْتُ صَوْتًا، مِنَ السَّمَاءِ، فَرَفَعْتُ بَصَرِي فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ، فَرُعِبْتُ مِنْهُ، فَرَجَعْتُ فَقُلْتُ زَمِّلُونِي‏.‏ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنْذِرْ‏}‏ إِلَى قَوْلِهِ ‏{‏وَالرُّجْزَ فَاهْجُرْ‏}‏ فَحَمِيَ الْوَحْىُ وَتَتَابَعَ ‏"‏‏.‏ تَابَعَهُ عَبْدُ اللَّهِ بْنُ يُوسُفَ وَأَبُو صَالِحٍ‏.‏ وَتَابَعَهُ هِلاَلُ بْنُ رَدَّادٍ عَنِ الزُّهْرِيِّ‏.‏ وَقَالَ يُونُسُ وَمَعْمَرٌ ‏"‏ بَوَادِرُهُ ‏"‏‏.‏', 'قال ابن شهاب واخبرني ابو سلمه بن عبد الرحمن، ان جابر بن عبد الله الانصاري، قال وهو يحدث عن فتره الوحي، فقال في حديثه ‏"‏ بينا انا امشي، اذ سمعت صوتا، من السماء، فرفعت بصري فاذا الملك الذي جاءني بحراء جالس علي كرسي بين السماء والارض، فرعبت منه، فرجعت فقلت زملوني‏.‏ فانزل الله تعالي ‏{‏يا ايها المدثر * قم فانذر‏}‏ الي قوله ‏{‏والرجز فاهجر‏}‏ فحمي الوحي وتتابع ‏"‏‏.‏ تابعه عبد الله بن يوسف وابو صالح‏.‏ وتابعه هلال بن رداد عن الزهري‏.‏ وقال يونس ومعمر ‏"‏ بوادره ‏"‏‏.‏', 'Narrated Jabir bin ''Abdullah Al-Ansari (while talking about the period of pause in revelation) reporting the speech of the Prophet:"While I was walking, all of a sudden I heard a voice from the sky. I looked up and saw the same angel who had visited me at the cave of Hira'' sitting on a chair between the sky and the earth. I got afraid of him and came back home and said, ''Wrap me (in blankets).'' And then Allah revealed the following Holy Verses (of Quran): ''O you (i.e. Muhammad)! wrapped up in garments!'' Arise and warn (the people against Allah''s Punishment),... up to ''and desert the idols.'' (74.1-5) After this the revelation started coming strongly, frequently and regularly', NULL, '6e4a722dc0d3dc8f5b7d8fe1828de95cc4429ac9107bdf569fc5071a0866acc5', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (5, 'bukhari', 2, 5, 'Book 1, Hadith 5', 5, NULL, NULL, 'حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، قَالَ حَدَّثَنَا أَبُو عَوَانَةَ، قَالَ حَدَّثَنَا مُوسَى بْنُ أَبِي عَائِشَةَ، قَالَ حَدَّثَنَا سَعِيدُ بْنُ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ، فِي قَوْلِهِ تَعَالَى', '{لاَ تُحَرِّكْ بِهِ لِسَانَكَ لِتَعْجَلَ بِهِ} قَالَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُعَالِجُ مِنَ التَّنْزِيلِ شِدَّةً، وَكَانَ مِمَّا يُحَرِّكُ شَفَتَيْهِ ـ فَقَالَ ابْنُ عَبَّاسٍ فَأَنَا أُحَرِّكُهُمَا لَكُمْ كَمَا كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُحَرِّكُهُمَا. وَقَالَ سَعِيدٌ أَنَا أُحَرِّكُهُمَا كَمَا رَأَيْتُ ابْنَ عَبَّاسٍ يُحَرِّكُهُمَا. فَحَرَّكَ شَفَتَيْهِ ـ فَأَنْزَلَ اللَّهُ تَعَالَى {لاَ تُحَرِّكْ بِهِ لِسَانَكَ لِتَعْجَلَ بِهِ* إِنَّ عَلَيْنَا جَمْعَهُ وَقُرْآنَهُ} قَالَ جَمْعُهُ لَهُ فِي صَدْرِكَ، وَتَقْرَأَهُ {فَإِذَا قَرَأْنَاهُ فَاتَّبِعْ قُرْآنَهُ} قَالَ فَاسْتَمِعْ لَهُ وَأَنْصِتْ {ثُمَّ إِنَّ عَلَيْنَا بَيَانَهُ} ثُمَّ إِنَّ عَلَيْنَا أَنْ تَقْرَأَهُ. فَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم بَعْدَ ذَلِكَ إِذَا أَتَاهُ جِبْرِيلُ اسْتَمَعَ، فَإِذَا انْطَلَقَ جِبْرِيلُ قَرَأَهُ النَّبِيُّ صلى الله عليه وسلم كَمَا قَرَأَهُ.', '{لا تحرك به لسانك لتعجل به} قال كان رسول الله صلي الله عليه وسلم يعالج من التنزيل شده، وكان مما يحرك شفتيه فقال ابن عباس فانا احركهما لكم كما كان رسول الله صلي الله عليه وسلم يحركهما. وقال سعيد انا احركهما كما رايت ابن عباس يحركهما. فحرك شفتيه فانزل الله تعالي {لا تحرك به لسانك لتعجل به* ان علينا جمعه وقرانه} قال جمعه له في صدرك، وتقراه {فاذا قراناه فاتبع قرانه} قال فاستمع له وانصت {ثم ان علينا بيانه} ثم ان علينا ان تقراه. فكان رسول الله صلي الله عليه وسلم بعد ذلك اذا اتاه جبريل استمع، فاذا انطلق جبريل قراه النبي صلي الله عليه وسلم كما قراه.', 'Narrated Said bin Jubair: Ibn ''Abbas in the explanation of the statement of Allah "Move not your tongue concerning (the Quran) to make haste therewith." (75.16) said "Allah''s Messenger (ﷺ) used to bear the revelation with great trouble and used to move his lips (quickly) with the Inspiration." Ibn ''Abbas moved his lips saying, "I am moving my lips in front of you as Allah''s Messenger (ﷺ) used to move his." Said moved his lips saying: "I am moving my lips, as I saw Ibn ''Abbas moving his." Ibn ''Abbas added, "So Allah revealed ''Move not your tongue concerning (the Qur''an) to make haste therewith. It is for Us to collect it and to give you (O Muhammad) the ability to recite it (the Quran)'' (75.16-17) which means that Allah will make him (the Prophet) remember the portion of the Qur''an which was revealed at that time by heart and recite it. The statement of Allah: ''And when we have recited it to you (O Muhammad through Gabriel) then you follow its (Quran) recital'' (75.18) means ''listen to it and be silent.'' Then it is for Us (Allah) to make it clear to you'' (75.19) means ''Then it is (for Allah) to make you recite it (and its meaning will be clear by itself through your tongue). Afterwards, Allah''s Messenger (ﷺ) used to listen to Gabriel whenever he came and after his departure he used to recite it as Gabriel had recited it', NULL, 'd70944b55d84a7654515c551df43340351ecf1d32bbf94bc5d9c06048c3f2c70', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (6, 'bukhari', 2, 6, 'Book 1, Hadith 6', 6, NULL, NULL, 'حَدَّثَنَا عَبْدَانُ، قَالَ أَخْبَرَنَا عَبْدُ اللَّهِ، قَالَ أَخْبَرَنَا يُونُسُ، عَنِ الزُّهْرِيِّ، ح وَحَدَّثَنَا بِشْرُ بْنُ مُحَمَّدٍ، قَالَ أَخْبَرَنَا عَبْدُ اللَّهِ، قَالَ أَخْبَرَنَا يُونُسُ، وَمَعْمَرٌ، عَنِ الزُّهْرِيِّ، نَحْوَهُ قَالَ أَخْبَرَنِي عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ، عَنِ ابْنِ عَبَّاسٍ، قَالَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم أَجْوَدَ النَّاسِ، وَكَانَ أَجْوَدُ مَا يَكُونُ فِي رَمَضَانَ حِينَ يَلْقَاهُ جِبْرِيلُ، وَكَانَ يَلْقَاهُ فِي كُلِّ لَيْلَةٍ مِنْ رَمَضَانَ فَيُدَارِسُهُ الْقُرْآنَ، فَلَرَسُولُ اللَّهِ صلى الله عليه وسلم أَجْوَدُ بِالْخَيْرِ مِنَ الرِّيحِ الْمُرْسَلَةِ', '.', '.', 'Narrated Ibn ''Abbas: Allah''s Messenger (ﷺ) was the most generous of all the people, and he used to reach the peak in generosity in the month of Ramadan when Gabriel met him. Gabriel used to meet him every night of Ramadan to teach him the Qur''an. Allah''s Messenger (ﷺ) was the most generous person, even more generous than the strong uncontrollable wind (in readiness and haste to do charitable deeds)', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (7, 'bukhari', 2, 7, 'Book 1, Hadith 7', 7, NULL, NULL, 'حَدَّثَنَا أَبُو الْيَمَانِ الْحَكَمُ بْنُ نَافِعٍ، قَالَ أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ أَخْبَرَنِي عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ، أَنَّ عَبْدَ اللَّهِ بْنَ عَبَّاسٍ، أَخْبَرَهُ أَنَّ أَبَا سُفْيَانَ بْنَ حَرْبٍ أَخْبَرَهُ أَنَّ هِرَقْلَ أَرْسَلَ إِلَيْهِ فِي رَكْبٍ مِنْ قُرَيْشٍ ـ وَكَانُوا تُجَّارًا بِالشَّأْمِ ـ فِي الْمُدَّةِ الَّتِي كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم مَادَّ فِيهَا أَبَا سُفْيَانَ وَكُفَّارَ قُرَيْشٍ، فَأَتَوْهُ وَهُمْ بِإِيلِيَاءَ فَدَعَاهُمْ فِي مَجْلِسِهِ، وَحَوْلَهُ عُظَمَاءُ الرُّومِ ثُمَّ دَعَاهُمْ وَدَعَا بِتَرْجُمَانِهِ فَقَالَ أَيُّكُمْ أَقْرَبُ نَسَبًا بِهَذَا الرَّجُلِ الَّذِي يَزْعُمُ أَنَّهُ نَبِيٌّ فَقَالَ أَبُو سُفْيَانَ فَقُلْتُ أَنَا أَقْرَبُهُمْ نَسَبًا', '. فَقَالَ أَدْنُوهُ مِنِّي، وَقَرِّبُوا أَصْحَابَهُ، فَاجْعَلُوهُمْ عِنْدَ ظَهْرِهِ. ثُمَّ قَالَ لِتَرْجُمَانِهِ قُلْ لَهُمْ إِنِّي سَائِلٌ هَذَا عَنْ هَذَا الرَّجُلِ، فَإِنْ كَذَبَني فَكَذِّبُوهُ. فَوَاللَّهِ لَوْلاَ الْحَيَاءُ مِنْ أَنْ يَأْثِرُوا عَلَىَّ كَذِبًا لَكَذَبْتُ عَنْهُ، ثُمَّ كَانَ أَوَّلَ مَا سَأَلَنِي عَنْهُ أَنْ قَالَ كَيْفَ نَسَبُهُ فِيكُمْ قُلْتُ هُوَ فِينَا ذُو نَسَبٍ. قَالَ فَهَلْ قَالَ هَذَا الْقَوْلَ مِنْكُمْ أَحَدٌ قَطُّ قَبْلَهُ قُلْتُ لاَ. قَالَ فَهَلْ كَانَ مِنْ آبَائِهِ مِنْ مَلِكٍ قُلْتُ لاَ. قَالَ فَأَشْرَافُ النَّاسِ يَتَّبِعُونَهُ أَمْ ضُعَفَاؤُهُمْ فَقُلْتُ بَلْ ضُعَفَاؤُهُمْ. قَالَ أَيَزِيدُونَ أَمْ يَنْقُصُونَ قُلْتُ بَلْ يَزِيدُونَ. قَالَ فَهَلْ يَرْتَدُّ أَحَدٌ مِنْهُمْ سَخْطَةً لِدِينِهِ بَعْدَ أَنْ يَدْخُلَ فِيهِ قُلْتُ لاَ. قَالَ فَهَلْ كُنْتُمْ تَتَّهِمُونَهُ بِالْكَذِبِ قَبْلَ أَنْ يَقُولَ مَا قَالَ قُلْتُ لاَ. قَالَ فَهَلْ يَغْدِرُ قُلْتُ لاَ، وَنَحْنُ مِنْهُ فِي مُدَّةٍ لاَ نَدْرِي مَا هُوَ فَاعِلٌ فِيهَا. قَالَ وَلَمْ تُمْكِنِّي كَلِمَةٌ أُدْخِلُ فِيهَا شَيْئًا غَيْرُ هَذِهِ الْكَلِمَةِ. قَالَ فَهَلْ قَاتَلْتُمُوهُ قُلْتُ نَعَمْ. قَالَ فَكَيْفَ كَانَ قِتَالُكُمْ إِيَّاهُ قُلْتُ الْحَرْبُ بَيْنَنَا وَبَيْنَهُ سِجَالٌ، يَنَالُ مِنَّا وَنَنَالُ مِنْهُ. قَالَ مَاذَا يَأْمُرُكُمْ قُلْتُ يَقُولُ اعْبُدُوا اللَّهَ وَحْدَهُ، وَلاَ تُشْرِكُوا بِهِ شَيْئًا، وَاتْرُكُوا مَا يَقُولُ آبَاؤُكُمْ، وَيَأْمُرُنَا بِالصَّلاَةِ وَالصِّدْقِ وَالْعَفَافِ وَالصِّلَةِ. فَقَالَ لِلتَّرْجُمَانِ قُلْ لَهُ سَأَلْتُكَ عَنْ نَسَبِهِ، فَذَكَرْتَ أَنَّهُ فِيكُمْ ذُو نَسَبٍ، فَكَذَلِكَ الرُّسُلُ تُبْعَثُ فِي نَسَبِ قَوْمِهَا، وَسَأَلْتُكَ هَلْ قَالَ أَحَدٌ مِنْكُمْ هَذَا الْقَوْلَ فَذَكَرْتَ أَنْ لاَ، فَقُلْتُ لَوْ كَانَ أَحَدٌ قَالَ هَذَا الْقَوْلَ قَبْلَهُ لَقُلْتُ رَجُلٌ يَأْتَسِي بِقَوْلٍ قِيلَ قَبْلَهُ، وَسَأَلْتُكَ هَلْ كَانَ مِنْ آبَائِهِ مِنْ مَلِكٍ فَذَكَرْتَ أَنْ لاَ، قُلْتُ فَلَوْ كَانَ مِنْ آبَائِهِ مِنْ مَلِكٍ قُلْتُ رَجُلٌ يَطْلُبُ مُلْكَ أَبِيهِ، وَسَأَلْتُكَ هَلْ كُنْتُمْ تَتَّهِمُونَهُ بِالْكَذِبِ قَبْلَ أَنْ يَقُولَ مَا قَالَ فَذَكَرْتَ أَنْ لاَ، فَقَدْ أَعْرِفُ أَنَّهُ لَمْ يَكُنْ لِيَذَرَ الْكَذِبَ عَلَى النَّاسِ وَيَكْذِبَ عَلَى اللَّهِ، وَسَأَلْتُكَ أَشْرَافُ النَّاسِ اتَّبَعُوهُ أَمْ ضُعَفَاؤُهُمْ فَذَكَرْتَ أَنَّ ضُعَفَاءَهُمُ اتَّبَعُوهُ، وَهُمْ أَتْبَاعُ الرُّسُلِ، وَسَأَلْتُكَ أَيَزِيدُونَ أَمْ يَنْقُصُونَ فَذَكَرْتَ أَنَّهُمْ يَزِيدُونَ، وَكَذَلِكَ أَمْرُ الإِيمَانِ حَتَّى يَتِمَّ، وَسَأَلْتُكَ أَيَرْتَدُّ أَحَدٌ سَخْطَةً لِدِينِهِ بَعْدَ أَنْ يَدْخُلَ فِيهِ فَذَكَرْتَ أَنْ لاَ، وَكَذَلِكَ الإِيمَانُ حِينَ تُخَالِطُ بَشَاشَتُهُ الْقُلُوبَ، وَسَأَلْتُكَ هَلْ يَغْدِرُ فَذَكَرْتَ أَنْ لاَ، وَكَذَلِكَ الرُّسُلُ لاَ تَغْدِرُ، وَسَأَلْتُكَ بِمَا يَأْمُرُكُمْ، فَذَكَرْتَ أَنَّهُ يَأْمُرُكُمْ أَنْ تَعْبُدُوا اللَّهَ، وَلاَ تُشْرِكُوا بِهِ شَيْئًا، وَيَنْهَاكُمْ عَنْ عِبَادَةِ الأَوْثَانِ، وَيَأْمُرُكُمْ بِالصَّلاَةِ وَالصِّدْقِ وَالْعَفَافِ. فَإِنْ كَانَ مَا تَقُولُ حَقًّا فَسَيَمْلِكُ مَوْضِعَ قَدَمَىَّ هَاتَيْنِ، وَقَدْ كُنْتُ أَعْلَمُ أَنَّهُ خَارِجٌ، لَمْ أَكُنْ أَظُنُّ أَنَّهُ مِنْكُمْ، فَلَوْ أَنِّي أَعْلَمُ أَنِّي أَخْلُصُ إِلَيْهِ لَتَجَشَّمْتُ لِقَاءَهُ، وَلَوْ كُنْتُ عِنْدَهُ لَغَسَلْتُ عَنْ قَدَمِهِ. ثُمَّ دَعَا بِكِتَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم الَّذِي بَعَثَ بِهِ دِحْيَةُ إِلَى عَظِيمِ بُصْرَى، فَدَفَعَهُ إِلَى هِرَقْلَ فَقَرَأَهُ فَإِذَا فِيهِ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. مِنْ مُحَمَّدٍ عَبْدِ اللَّهِ وَرَسُولِهِ إِلَى هِرَقْلَ عَظِيمِ الرُّومِ. سَلاَمٌ عَلَى مَنِ اتَّبَعَ الْهُدَى، أَمَّا بَعْدُ فَإِنِّي أَدْعُوكَ بِدِعَايَةِ الإِسْلاَمِ، أَسْلِمْ تَسْلَمْ، يُؤْتِكَ اللَّهُ أَجْرَكَ مَرَّتَيْنِ، فَإِنْ تَوَلَّيْتَ فَإِنَّ عَلَيْكَ إِثْمَ الأَرِيسِيِّينَ وَ{يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ أَنْ لاَ نَعْبُدَ إِلاَّ اللَّهَ وَلاَ نُشْرِكَ بِهِ شَيْئًا وَلاَ يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِنْ دُونِ اللَّهِ فَإِنْ تَوَلَّوْا فَقُولُوا اشْهَدُوا بِأَنَّا مُسْلِمُونَ} قَالَ أَبُو سُفْيَانَ فَلَمَّا قَالَ مَا قَالَ، وَفَرَغَ مِنْ قِرَاءَةِ الْكِتَابِ كَثُرَ عِنْدَهُ الصَّخَبُ، وَارْتَفَعَتِ الأَصْوَاتُ وَأُخْرِجْنَا، فَقُلْتُ لأَصْحَابِي حِينَ أُخْرِجْنَا لَقَدْ أَمِرَ أَمْرُ ابْنِ أَبِي كَبْشَةَ، إِنَّهُ يَخَافُهُ مَلِكُ بَنِي الأَصْفَرِ. فَمَا زِلْتُ مُوقِنًا أَنَّهُ سَيَظْهَرُ حَتَّى أَدْخَلَ اللَّهُ عَلَىَّ الإِسْلاَمَ. وَكَانَ ابْنُ النَّاظُورِ صَاحِبُ إِيلِيَاءَ وَهِرَقْلَ سُقُفًّا عَلَى نَصَارَى الشَّأْمِ، يُحَدِّثُ أَنَّ هِرَقْلَ حِينَ قَدِمَ إِيلِيَاءَ أَصْبَحَ يَوْمًا خَبِيثَ النَّفْسِ، فَقَالَ بَعْضُ بَطَارِقَتِهِ قَدِ اسْتَنْكَرْنَا هَيْئَتَكَ. قَالَ ابْنُ النَّاظُورِ وَكَانَ هِرَقْلُ حَزَّاءً يَنْظُرُ فِي النُّجُومِ، فَقَالَ لَهُمْ حِينَ سَأَلُوهُ إِنِّي رَأَيْتُ اللَّيْلَةَ حِينَ نَظَرْتُ فِي النُّجُومِ مَلِكَ الْخِتَانِ قَدْ ظَهَرَ، فَمَنْ يَخْتَتِنُ مِنْ هَذِهِ الأُمَّةِ قَالُوا لَيْسَ يَخْتَتِنُ إِلاَّ الْيَهُودُ فَلاَ يُهِمَّنَّكَ شَأْنُهُمْ وَاكْتُبْ إِلَى مَدَايِنِ مُلْكِكَ، فَيَقْتُلُوا مَنْ فِيهِمْ مِنَ الْيَهُودِ. فَبَيْنَمَا هُمْ عَلَى أَمْرِهِمْ أُتِيَ هِرَقْلُ بِرَجُلٍ أَرْسَلَ بِهِ مَلِكُ غَسَّانَ، يُخْبِرُ عَنْ خَبَرِ رَسُولِ اللَّهِ صلى الله عليه وسلم فَلَمَّا اسْتَخْبَرَهُ هِرَقْلُ قَالَ اذْهَبُوا فَانْظُرُوا أَمُخْتَتِنٌ هُوَ أَمْ لاَ. فَنَظَرُوا إِلَيْهِ، فَحَدَّثُوهُ أَنَّهُ مُخْتَتِنٌ، وَسَأَلَهُ عَنِ الْعَرَبِ فَقَالَ هُمْ يَخْتَتِنُونَ. فَقَالَ هِرَقْلُ هَذَا مَلِكُ هَذِهِ الأُمَّةِ قَدْ ظَهَرَ. ثُمَّ كَتَبَ هِرَقْلُ إِلَى صَاحِبٍ لَهُ بِرُومِيَةَ، وَكَانَ نَظِيرَهُ فِي الْعِلْمِ، وَسَارَ هِرَقْلُ إِلَى حِمْصَ، فَلَمْ يَرِمْ حِمْصَ حَتَّى أَتَاهُ كِتَابٌ مِنْ صَاحِبِهِ يُوَافِقُ رَأْىَ هِرَقْلَ عَلَى خُرُوجِ النَّبِيِّ صلى الله عليه وسلم وَأَنَّهُ نَبِيٌّ، فَأَذِنَ هِرَقْلُ لِعُظَمَاءِ الرُّومِ فِي دَسْكَرَةٍ لَهُ بِحِمْصَ ثُمَّ أَمَرَ بِأَبْوَابِهَا فَغُلِّقَتْ، ثُمَّ اطَّلَعَ فَقَالَ يَا مَعْشَرَ الرُّومِ، هَلْ لَكُمْ فِي الْفَلاَحِ وَالرُّشْدِ وَأَنْ يَثْبُتَ مُلْكُكُمْ فَتُبَايِعُوا هَذَا النَّبِيَّ، فَحَاصُوا حَيْصَةَ حُمُرِ الْوَحْشِ إِلَى الأَبْوَابِ، فَوَجَدُوهَا قَدْ غُلِّقَتْ، فَلَمَّا رَأَى هِرَقْلُ نَفْرَتَهُمْ، وَأَيِسَ مِنَ الإِيمَانِ قَالَ رُدُّوهُمْ عَلَىَّ. وَقَالَ إِنِّي قُلْتُ مَقَالَتِي آنِفًا أَخْتَبِرُ بِهَا شِدَّتَكُمْ عَلَى دِينِكُمْ، فَقَدْ رَأَيْتُ. فَسَجَدُوا لَهُ وَرَضُوا عَنْهُ، فَكَانَ ذَلِكَ آخِرَ شَأْنِ هِرَقْلَ. رَوَاهُ صَالِحُ بْنُ كَيْسَانَ وَيُونُسُ وَمَعْمَرٌ عَنِ الزُّهْرِيِّ.', '. فقال ادنوه مني، وقربوا اصحابه، فاجعلوهم عند ظهره. ثم قال لترجمانه قل لهم اني سائل هذا عن هذا الرجل، فان كذبني فكذبوه. فوالله لولا الحياء من ان ياثروا علي كذبا لكذبت عنه، ثم كان اول ما سالني عنه ان قال كيف نسبه فيكم قلت هو فينا ذو نسب. قال فهل قال هذا القول منكم احد قط قبله قلت لا. قال فهل كان من ابائه من ملك قلت لا. قال فاشراف الناس يتبعونه ام ضعفاؤهم فقلت بل ضعفاؤهم. قال ايزيدون ام ينقصون قلت بل يزيدون. قال فهل يرتد احد منهم سخطه لدينه بعد ان يدخل فيه قلت لا. قال فهل كنتم تتهمونه بالكذب قبل ان يقول ما قال قلت لا. قال فهل يغدر قلت لا، ونحن منه في مده لا ندري ما هو فاعل فيها. قال ولم تمكني كلمه ادخل فيها شيئا غير هذه الكلمه. قال فهل قاتلتموه قلت نعم. قال فكيف كان قتالكم اياه قلت الحرب بيننا وبينه سجال، ينال منا وننال منه. قال ماذا يامركم قلت يقول اعبدوا الله وحده، ولا تشركوا به شيئا، واتركوا ما يقول اباؤكم، ويامرنا بالصلاه والصدق والعفاف والصله. فقال للترجمان قل له سالتك عن نسبه، فذكرت انه فيكم ذو نسب، فكذلك الرسل تبعث في نسب قومها، وسالتك هل قال احد منكم هذا القول فذكرت ان لا، فقلت لو كان احد قال هذا القول قبله لقلت رجل ياتسي بقول قيل قبله، وسالتك هل كان من ابائه من ملك فذكرت ان لا، قلت فلو كان من ابائه من ملك قلت رجل يطلب ملك ابيه، وسالتك هل كنتم تتهمونه بالكذب قبل ان يقول ما قال فذكرت ان لا، فقد اعرف انه لم يكن ليذر الكذب علي الناس ويكذب علي الله، وسالتك اشراف الناس اتبعوه ام ضعفاؤهم فذكرت ان ضعفاءهم اتبعوه، وهم اتباع الرسل، وسالتك ايزيدون ام ينقصون فذكرت انهم يزيدون، وكذلك امر الايمان حتي يتم، وسالتك ايرتد احد سخطه لدينه بعد ان يدخل فيه فذكرت ان لا، وكذلك الايمان حين تخالط بشاشته القلوب، وسالتك هل يغدر فذكرت ان لا، وكذلك الرسل لا تغدر، وسالتك بما يامركم، فذكرت انه يامركم ان تعبدوا الله، ولا تشركوا به شيئا، وينهاكم عن عباده الاوثان، ويامركم بالصلاه والصدق والعفاف. فان كان ما تقول حقا فسيملك موضع قدمي هاتين، وقد كنت اعلم انه خارج، لم اكن اظن انه منكم، فلو اني اعلم اني اخلص اليه لتجشمت لقاءه، ولو كنت عنده لغسلت عن قدمه. ثم دعا بكتاب رسول الله صلي الله عليه وسلم الذي بعث به دحيه الي عظيم بصري، فدفعه الي هرقل فقراه فاذا فيه بسم الله الرحمن الرحيم. من محمد عبد الله ورسوله الي هرقل عظيم الروم. سلام علي من اتبع الهدي، اما بعد فاني ادعوك بدعايه الاسلام، اسلم تسلم، يؤتك الله اجرك مرتين، فان توليت فان عليك اثم الاريسيين و{يا اهل الكتاب تعالوا الي كلمه سواء بيننا وبينكم ان لا نعبد الا الله ولا نشرك به شيئا ولا يتخذ بعضنا بعضا اربابا من دون الله فان تولوا فقولوا اشهدوا بانا مسلمون} قال ابو سفيان فلما قال ما قال، وفرغ من قراءه الكتاب كثر عنده الصخب، وارتفعت الاصوات واخرجنا، فقلت لاصحابي حين اخرجنا لقد امر امر ابن ابي كبشه، انه يخافه ملك بني الاصفر. فما زلت موقنا انه سيظهر حتي ادخل الله علي الاسلام. وكان ابن الناظور صاحب ايلياء وهرقل سقفا علي نصاري الشام، يحدث ان هرقل حين قدم ايلياء اصبح يوما خبيث النفس، فقال بعض بطارقته قد استنكرنا هيئتك. قال ابن الناظور وكان هرقل حزاء ينظر في النجوم، فقال لهم حين سالوه اني رايت الليله حين نظرت في النجوم ملك الختان قد ظهر، فمن يختتن من هذه الامه قالوا ليس يختتن الا اليهود فلا يهمنك شانهم واكتب الي مداين ملكك، فيقتلوا من فيهم من اليهود. فبينما هم علي امرهم اتي هرقل برجل ارسل به ملك غسان، يخبر عن خبر رسول الله صلي الله عليه وسلم فلما استخبره هرقل قال اذهبوا فانظروا امختتن هو ام لا. فنظروا اليه، فحدثوه انه مختتن، وساله عن العرب فقال هم يختتنون. فقال هرقل هذا ملك هذه الامه قد ظهر. ثم كتب هرقل الي صاحب له بروميه، وكان نظيره في العلم، وسار هرقل الي حمص، فلم يرم حمص حتي اتاه كتاب من صاحبه يوافق راي هرقل علي خروج النبي صلي الله عليه وسلم وانه نبي، فاذن هرقل لعظماء الروم في دسكره له بحمص ثم امر بابوابها فغلقت، ثم اطلع فقال يا معشر الروم، هل لكم في الفلاح والرشد وان يثبت ملككم فتبايعوا هذا النبي، فحاصوا حيصه حمر الوحش الي الابواب، فوجدوها قد غلقت، فلما راي هرقل نفرتهم، وايس من الايمان قال ردوهم علي. وقال اني قلت مقالتي انفا اختبر بها شدتكم علي دينكم، فقد رايت. فسجدوا له ورضوا عنه، فكان ذلك اخر شان هرقل. رواه صالح بن كيسان ويونس ومعمر عن الزهري.', 'Narrated ''Abdullah bin ''Abbas: Abu Sufyan bin Harb informed me that Heraclius had sent a messenger to him while he had been accompanying a caravan from Quraish. They were merchants doing business in Sham (Syria, Palestine, Lebanon and Jordan), at the time when Allah''s Messenger (ﷺ) had truce with Abu Sufyan and Quraish infidels. So Abu Sufyan and his companions went to Heraclius at Ilya (Jerusalem). Heraclius called them in the court and he had all the senior Roman dignitaries around him. He called for his translator who, translating Heraclius''s question said to them, "Who amongst you is closely related to that man who claims to be a Prophet?" Abu Sufyan replied, "I am the nearest relative to him (amongst the group)." Heraclius said, "Bring him (Abu Sufyan) close to me and make his companions stand behind him." Abu Sufyan added, Heraclius told his translator to tell my companions that he wanted to put some questions to me regarding that man (The Prophet) and that if I told a lie they (my companions) should contradict me." Abu Sufyan added, "By Allah! Had I not been afraid of my companions labeling me a liar, I would not have spoken the truth about the Prophet. The first question he asked me about him was: ''What is his family status amongst you?'' I replied, ''He belongs to a good (noble) family amongst us.'' Heraclius further asked, ''Has anybody amongst you ever claimed the same (i.e. to be a Prophet) before him?'' I replied, ''No.'' He said, ''Was anybody amongst his ancestors a king?'' I replied, ''No.'' Heraclius asked, ''Do the nobles or the poor follow him?'' I replied, ''It is the poor who follow him.'' He said, ''Are his followers increasing decreasing (day by day)?'' I replied, ''They are increasing.'' He then asked, ''Does anybody amongst those who embrace his religion become displeased and renounce the religion afterwards?'' I replied, ''No.'' Heraclius said, ''Have you ever accused him of telling lies before his claim (to be a Prophet)?'' I replied, ''No. '' Heraclius said, ''Does he break his promises?'' I replied, ''No. We are at truce with him but we do not know what he will do in it.'' I could not find opportunity to say anything against him except that. Heraclius asked, ''Have you ever had a war with him?'' I replied, ''Yes.'' Then he said, ''What was the outcome of the battles?'' I replied, ''Sometimes he was victorious and sometimes we.'' Heraclius said, ''What does he order you to do?'' I said, ''He tells us to worship Allah and Allah alone and not to worship anything along with Him, and to renounce all that our ancestors had said. He orders us to pray, to speak the truth, to be chaste and to keep good relations with our Kith and kin.'' Heraclius asked the translator to convey to me the following, I asked you about his family and your reply was that he belonged to a very noble family. In fact all the Apostles come from noble families amongst their respective peoples. I questioned you whether anybody else amongst you claimed such a thing, your reply was in the negative. If the answer had been in the affirmative, I would have thought that this man was following the previous man''s statement. Then I asked you whether anyone of his ancestors was a king. Your reply was in the negative, and if it had been in the affirmative, I would have thought that this man wanted to take back his ancestral kingdom. I further asked whether he was ever accused of telling lies before he said what he said, and your reply was in the negative. So I wondered how a person who does not tell a lie about others could ever tell a lie about Allah. I, then asked you whether the rich people followed him or the poor. You replied that it was the poor who followed him. And in fact all the Apostle have been followed by this very class of people. Then I asked you whether his followers were increasing or decreasing. You replied that they were increasing, and in fact this is the way of true faith, till it is complete in all respects. I further asked you whether there was anybody, who, after embracing his religion, became displeased and discarded his religion. Your reply was in the negative, and in fact this is (the sign of) true faith, when its delight enters the hearts and mixes with them completely. I asked you whether he had ever betrayed. You replied in the negative and likewise the Apostles never betray. Then I asked you what he ordered you to do. You replied that he ordered you to worship Allah and Allah alone and not to worship any thing along with Him and forbade you to worship idols and ordered you to pray, to speak the truth and to be chaste. If what you have said is true, he will very soon occupy this place underneath my feet and I knew it (from the scriptures) that he was going to appear but I did not know that he would be from you, and if I could reach him definitely, I would go immediately to meet him and if I were with him, I would certainly wash his feet.'' Heraclius then asked for the letter addressed by Allah''s Apostle which was delivered by Dihya to the Governor of Busra, who forwarded it to Heraclius to read. The contents of the letter were as follows: "In the name of Allah the Beneficent, the Merciful (This letter is) from Muhammad the slave of Allah and His Apostle to Heraclius the ruler of Byzantine. Peace be upon him, who follows the right path. Furthermore I invite you to Islam, and if you become a Muslim you will be safe, and Allah will double your reward, and if you reject this invitation of Islam you will be committing a sin of Arisiyin (tillers, farmers i.e. your people). And (Allah''s Statement:) ''O people of the scripture! Come to a word common to you and us that we worship none but Allah and that we associate nothing in worship with Him, and that none of us shall take others as Lords beside Allah. Then, if they turn away, say: Bear witness that we are Muslims (those who have surrendered to Allah).'' (3:64). Abu Sufyan then added, "When Heraclius had finished his speech and had read the letter, there was a great hue and cry in the Royal Court. So we were turned out of the court. I told my companions that the question of Ibn-Abi-Kabsha) (the Prophet Muhammad (ﷺ)) has become so prominent that even the King of Bani Al-Asfar (Byzantine) is afraid of him. Then I started to become sure that he (the Prophet) would be the conqueror in the near future till I embraced Islam (i.e. Allah guided me to it)." The sub narrator adds, "Ibn An-Natur was the Governor of Ilya'' (Jerusalem) and Heraclius was the head of the Christians of Sham. Ibn An-Natur narrates that once while Heraclius was visiting ilya'' (Jerusalem), he got up in the morning with a sad mood. Some of his priests asked him why he was in that mood? Heraclius was a foreteller and an astrologer. He replied, ''At night when I looked at the stars, I saw that the leader of those who practice circumcision had appeared (become the conqueror). Who are they who practice circumcision?'' The people replied, ''Except the Jews nobody practices circumcision, so you should not be afraid of them (Jews). ''Just Issue orders to kill every Jew present in the country.'' While they were discussing it, a messenger sent by the king of Ghassan to convey the news of Allah''s Messenger (ﷺ) to Heraclius was brought in. Having heard the news, he (Heraclius) ordered the people to go and see whether the messenger of Ghassan was circumcised. The people, after seeing him, told Heraclius that he was circumcised. Heraclius then asked him about the Arabs. The messenger replied, ''Arabs also practice circumcision.'' (After hearing that) Heraclius remarked that sovereignty of the ''Arabs had appeared. Heraclius then wrote a letter to his friend in Rome who was as good as Heraclius in knowledge. Heraclius then left for Homs. (a town in Syrian and stayed there till he received the reply of his letter from his friend who agreed with him in his opinion about the emergence of the Prophet (ﷺ) and the fact that he was a Prophet. On that Heraclius invited all the heads of the Byzantines to assemble in his palace at Homs. When they assembled, he ordered that all the doors of his palace be closed. Then he came out and said, ''O Byzantines! If success is your desire and if you seek right guidance and want your empire to remain then give a pledge of allegiance to this Prophet (i.e. embrace Islam).'' (On hearing the views of Heraclius) the people ran towards the gates of the palace like onagers but found the doors closed. Heraclius realized their hatred towards Islam and when he lost the hope of their embracing Islam, he ordered that they should be brought back in audience. (When they returned) he said, ''What already said was just to test the strength of your conviction and I have seen it.'' The people prostrated before him and became pleased with him, and this was the end of Heraclius''s story (in connection with his faith)', NULL, '7ebc2b17962b63d9ed5ac81742a4dc4a04096147cd88b8a3b986787472bb5118', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (8, 'bukhari', 3, 8, 'Book 2, Hadith 1', 8, NULL, NULL, 'حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُوسَى، قَالَ أَخْبَرَنَا حَنْظَلَةُ بْنُ أَبِي سُفْيَانَ، عَنْ عِكْرِمَةَ بْنِ خَالِدٍ، عَنِ ابْنِ عُمَرَ ـ رضى الله عنهما ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلاَةِ، وَإِيتَاءِ الزَّكَاةِ، وَالْحَجِّ، وَصَوْمِ رَمَضَانَ ‏"‏‏.‏', '"‏ بني الاسلام علي خمس شهاده ان لا اله الا الله وان محمدا رسول الله، واقام الصلاه، وايتاء الزكاه، والحج، وصوم رمضان ‏"‏‏.‏', 'Narrated Ibn ''Umar: Allah''s Messenger (ﷺ) said: Islam is based on (the following) five (principles): 1. To testify that none has the right to be worshipped but Allah and Muhammad is Allah''s Messenger (ﷺ). 2. To offer the (compulsory congregational) prayers dutifully and perfectly. 3. To pay Zakat (i.e. obligatory charity) . 4. To perform Hajj. (i.e. Pilgrimage to Mecca) 5. To observe fast during the month of Ramadan', NULL, '2e35ebe22fc4d05745e41ec64273fe98ae1ba69cd35472e494d3f64fc94804af', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (9, 'bukhari', 3, 9, 'Book 2, Hadith 2', 9, NULL, NULL, 'حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ، قَالَ حَدَّثَنَا أَبُو عَامِرٍ الْعَقَدِيُّ، قَالَ حَدَّثَنَا سُلَيْمَانُ بْنُ بِلاَلٍ، عَنْ عَبْدِ اللَّهِ بْنِ دِينَارٍ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ الإِيمَانُ بِضْعٌ وَسِتُّونَ شُعْبَةً، وَالْحَيَاءُ شُعْبَةٌ مِنَ الإِيمَانِ ‏"‏‏.‏', '"‏ الايمان بضع وستون شعبه، والحياء شعبه من الايمان ‏"‏‏.‏', 'Narrated Abu Huraira: The Prophet (ﷺ) said, "Faith (Belief) consists of more than sixty branches (i.e. parts). And Haya (This term "Haya" covers a large number of concepts which are to be taken together; amongst them are self respect, modesty, bashfulness, and scruple, etc.) is a part of faith', NULL, '4c061c865df1a685e14bf269bd37eb89c6312816d76fed8c24b2896ee2ac9227', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (10, 'bukhari', 3, 10, 'Book 2, Hadith 3', 10, NULL, NULL, 'حَدَّثَنَا آدَمُ بْنُ أَبِي إِيَاسٍ، قَالَ حَدَّثَنَا شُعْبَةُ، عَنْ عَبْدِ اللَّهِ بْنِ أَبِي السَّفَرِ، وَإِسْمَاعِيلَ، عَنِ الشَّعْبِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو ـ رضى الله عنهما ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ، وَالْمُهَاجِرُ مَنْ هَجَرَ مَا نَهَى اللَّهُ عَنْهُ ‏"‏‏.‏ قَالَ أَبُو عَبْدِ اللَّهِ وَقَالَ أَبُو مُعَاوِيَةَ حَدَّثَنَا دَاوُدُ عَنْ عَامِرٍ قَالَ سَمِعْتُ عَبْدَ اللَّهِ عَنِ النَّبِيِّ صلى الله عليه وسلم‏.‏ وَقَالَ عَبْدُ الأَعْلَى عَنْ دَاوُدَ عَنْ عَامِرٍ عَنْ عَبْدِ اللَّهِ عَنِ النَّبِيِّ صلى الله عليه وسلم‏.‏', '"‏ المسلم من سلم المسلمون من لسانه ويده، والمهاجر من هجر ما نهي الله عنه ‏"‏‏.‏ قال ابو عبد الله وقال ابو معاويه حدثنا داود عن عامر قال سمعت عبد الله عن النبي صلي الله عليه وسلم‏.‏ وقال عبد الاعلي عن داود عن عامر عن عبد الله عن النبي صلي الله عليه وسلم‏.‏', 'Narrated ''Abdullah bin ''Amr: The Prophet (ﷺ) said, "A Muslim is the one who avoids harming Muslims with his tongue and hands. And a Muhajir (emigrant) is the one who gives up (abandons) all what Allah has forbidden', NULL, '5ef45900b9182c6ecc58786e24ccd984ac8796776a1f3fb184b491bca1b9b942', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (11, 'bukhari', 3, 11, 'Book 2, Hadith 4', 11, NULL, NULL, 'حَدَّثَنَا سَعِيدُ بْنُ يَحْيَى بْنِ سَعِيدٍ الْقُرَشِيِّ، قَالَ حَدَّثَنَا أَبِي قَالَ، حَدَّثَنَا أَبُو بُرْدَةَ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي بُرْدَةَ، عَنْ أَبِي بُرْدَةَ، عَنْ أَبِي مُوسَى ـ رضى الله عنه ـ قَالَ قَالُوا يَا رَسُولَ اللَّهِ أَىُّ الإِسْلاَمِ أَفْضَلُ قَالَ', 'مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ .', 'من سلم المسلمون من لسانه ويده .', 'Narrated Abu Musa: Some people asked Allah''s Messenger (ﷺ), "Whose Islam is the best? i.e. (Who is a very good Muslim)?" He replied, "One who avoids harming the Muslims with his tongue and hands', NULL, '2ec858d6d1dcc3807f7978d8017ddbfb6224a641ef3c296ab9a8c5a1752d0ff0', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (12, 'bukhari', 3, 12, 'Book 2, Hadith 5', 12, NULL, NULL, 'حَدَّثَنَا عَمْرُو بْنُ خَالِدٍ، قَالَ حَدَّثَنَا اللَّيْثُ، عَنْ يَزِيدَ، عَنْ أَبِي الْخَيْرِ، عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو ـ رضى الله عنهما ـ أَنَّ رَجُلاً، سَأَلَ النَّبِيَّ صلى الله عليه وسلم أَىُّ الإِسْلاَمِ خَيْرٌ قَالَ', 'تُطْعِمُ الطَّعَامَ، وَتَقْرَأُ السَّلاَمَ عَلَى مَنْ عَرَفْتَ وَمَنْ لَمْ تَعْرِفْ .', 'تطعم الطعام، وتقرا السلام علي من عرفت ومن لم تعرف .', 'Narrated ''Abdullah bin ''Amr: A man asked the Prophet (ﷺ) , "What sort of deeds or (what qualities of) Islam are good?" The Prophet (ﷺ) replied, ''To feed (the poor) and greet those whom you know and those whom you do not Know (See Hadith No)', NULL, 'dd2b7358703f704173aed0ff4316549002304288a11b464385daac354e321e1d', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (13, 'bukhari', 3, 13, 'Book 2, Hadith 6', 13, NULL, NULL, 'حَدَّثَنَا مُسَدَّدٌ، قَالَ حَدَّثَنَا يَحْيَى، عَنْ شُعْبَةَ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم‏.‏ وَعَنْ حُسَيْنٍ الْمُعَلِّمِ، قَالَ حَدَّثَنَا قَتَادَةُ، عَنْ أَنَسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ لا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ ‏"‏‏.‏', '"‏ لا يؤمن احدكم حتي يحب لاخيه ما يحب لنفسه ‏"‏‏.‏', 'Narrated Anas: The Prophet (ﷺ) said, "None of you will have faith till he wishes for his (Muslim) brother what he likes for himself', NULL, '0b2b5d146263b04d9235545add77b77da62495e8eb1ffcd2b741e48e01e7267e', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (14, 'bukhari', 3, 14, 'Book 2, Hadith 7', 14, NULL, NULL, 'حَدَّثَنَا أَبُو الْيَمَانِ، قَالَ أَخْبَرَنَا شُعَيْبٌ، قَالَ حَدَّثَنَا أَبُو الزِّنَادِ، عَنِ الأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏', '"‏ فَوَالَّذِي نَفْسِي بِيَدِهِ لاَ يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَالِدِهِ وَوَلَدِهِ ‏"‏‏.‏', '"‏ فوالذي نفسي بيده لا يؤمن احدكم حتي اكون احب اليه من والده وولده ‏"‏‏.‏', 'Narrated Abu Huraira: "Allah''s Messenger (ﷺ) said, "By Him in Whose Hands my life is, none of you will have faith till he loves me more than his father and his children', NULL, 'fa0dbbcf71fd997947a68bc6a00f8ecb10963b72bbbfee6b335975851d00b697', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (15, 'bukhari', 3, 15, 'Book 2, Hadith 8', 15, NULL, NULL, 'حَدَّثَنَا يَعْقُوبُ بْنُ إِبْرَاهِيمَ، قَالَ حَدَّثَنَا ابْنُ عُلَيَّةَ، عَنْ عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ، عَنْ أَنَسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم', 'ح وَحَدَّثَنَا آدَمُ، قَالَ حَدَّثَنَا شُعْبَةُ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ، قَالَ قَالَ النَّبِيُّ صلى الله عليه وسلم ‏ "‏ لاَ يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَالِدِهِ وَوَلَدِهِ وَالنَّاسِ أَجْمَعِينَ ‏"‏‏.‏', 'ح وحدثنا ادم، قال حدثنا شعبه، عن قتاده، عن انس، قال قال النبي صلي الله عليه وسلم ‏ "‏ لا يؤمن احدكم حتي اكون احب اليه من والده وولده والناس اجمعين ‏"‏‏.‏', 'Narrated Anas: The Prophet (ﷺ) said "None of you will have faith till he loves me more than his father, his children and all mankind', NULL, '286c17b94c02389f052d6bfbcbd2ed6c565f198dad5bd718ea81a7ae7e4dec91', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (16, 'bukhari', 3, 16, 'Book 2, Hadith 9', 16, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، قَالَ حَدَّثَنَا عَبْدُ الْوَهَّابِ الثَّقَفِيُّ، قَالَ حَدَّثَنَا أَيُّوبُ، عَنْ أَبِي قِلاَبَةَ، عَنْ أَنَسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ ثَلاَثٌ مَنْ كُنَّ فِيهِ وَجَدَ حَلاَوَةَ الإِيمَانِ أَنْ يَكُونَ اللَّهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا، وَأَنْ يُحِبَّ الْمَرْءَ لاَ يُحِبُّهُ إِلاَّ لِلَّهِ، وَأَنْ يَكْرَهَ أَنْ يَعُودَ فِي الْكُفْرِ كَمَا يَكْرَهُ أَنْ يُقْذَفَ فِي النَّارِ ‏"‏‏.‏', '"‏ ثلاث من كن فيه وجد حلاوه الايمان ان يكون الله ورسوله احب اليه مما سواهما، وان يحب المرء لا يحبه الا لله، وان يكره ان يعود في الكفر كما يكره ان يقذف في النار ‏"‏‏.‏', 'Narrated Anas: The Prophet (ﷺ) said, "Whoever possesses the following three qualities will have the sweetness (delight) of faith: 1. The one to whom Allah and His Apostle become dearer than anything else. 2. Who loves a person and he loves him only for Allah''s sake. 3. Who hates to revert to Atheism (disbelief) as he hates to be thrown into the fire', NULL, '6253f5efd7e9b7ff7b3fa56edff27f275a8f28c5f26c5af45568c2399e21252b', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (17, 'bukhari', 3, 17, 'Book 2, Hadith 10', 17, NULL, NULL, 'حَدَّثَنَا أَبُو الْوَلِيدِ، قَالَ حَدَّثَنَا شُعْبَةُ، قَالَ أَخْبَرَنِي عَبْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ جَبْرٍ، قَالَ سَمِعْتُ أَنَسًا، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ آيَةُ الإِيمَانِ حُبُّ الأَنْصَارِ، وَآيَةُ النِّفَاقِ بُغْضُ الأَنْصَارِ ‏"‏‏.‏', '"‏ ايه الايمان حب الانصار، وايه النفاق بغض الانصار ‏"‏‏.‏', 'Narrated Anas: The Prophet (ﷺ) said, "Love for the Ansar is a sign of faith and hatred for the Ansar is a sign of hypocrisy', NULL, '088b17d0c56d65ea9af16f1a645962b4d6ac34bef87bd74c3e3144785e00a26c', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (18, 'bukhari', 3, 18, 'Book 2, Hadith 11', 18, NULL, NULL, 'حَدَّثَنَا أَبُو الْيَمَانِ، قَالَ أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّهْرِيِّ، قَالَ أَخْبَرَنِي أَبُو إِدْرِيسَ، عَائِذُ اللَّهِ بْنُ عَبْدِ اللَّهِ أَنَّ عُبَادَةَ بْنَ الصَّامِتِ ـ رضى الله عنه ـ وَكَانَ شَهِدَ بَدْرًا، وَهُوَ أَحَدُ النُّقَبَاءِ لَيْلَةَ الْعَقَبَةِ ـ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ', 'وَحَوْلَهُ عِصَابَةٌ مِنْ أَصْحَابِهِ ‏ "‏ بَايِعُونِي عَلَى أَنْ لاَ تُشْرِكُوا بِاللَّهِ شَيْئًا، وَلاَ تَسْرِقُوا، وَلاَ تَزْنُوا، وَلاَ تَقْتُلُوا أَوْلاَدَكُمْ، وَلاَ تَأْتُوا بِبُهْتَانٍ تَفْتَرُونَهُ بَيْنَ أَيْدِيكُمْ وَأَرْجُلِكُمْ، وَلاَ تَعْصُوا فِي مَعْرُوفٍ، فَمَنْ وَفَى مِنْكُمْ فَأَجْرُهُ عَلَى اللَّهِ، وَمَنْ أَصَابَ مِنْ ذَلِكَ شَيْئًا فَعُوقِبَ فِي الدُّنْيَا فَهُوَ كَفَّارَةٌ لَهُ، وَمَنْ أَصَابَ مِنْ ذَلِكَ شَيْئًا ثُمَّ سَتَرَهُ اللَّهُ، فَهُوَ إِلَى اللَّهِ إِنْ شَاءَ عَفَا عَنْهُ، وَإِنْ شَاءَ عَاقَبَهُ ‏"‏‏.‏ فَبَايَعْنَاهُ عَلَى ذَلِكَ‏.‏', 'وحوله عصابه من اصحابه ‏ "‏ بايعوني علي ان لا تشركوا بالله شيئا، ولا تسرقوا، ولا تزنوا، ولا تقتلوا اولادكم، ولا تاتوا ببهتان تفترونه بين ايديكم وارجلكم، ولا تعصوا في معروف، فمن وفي منكم فاجره علي الله، ومن اصاب من ذلك شيئا فعوقب في الدنيا فهو كفاره له، ومن اصاب من ذلك شيئا ثم ستره الله، فهو الي الله ان شاء عفا عنه، وان شاء عاقبه ‏"‏‏.‏ فبايعناه علي ذلك‏.‏', 'Narrated ''Ubada bin As-Samit: who took part in the battle of Badr and was a Naqib (a person heading a group of six persons), on the night of Al-''Aqaba pledge: Allah''s Apostle said while a group of his companions were around him, "Swear allegiance to me for: 1. Not to join anything in worship along with Allah. 2. Not to steal. 3. Not to commit illegal sexual intercourse. 4. Not to kill your children. 5. Not to accuse an innocent person (to spread such an accusation among people). 6. Not to be disobedient (when ordered) to do good deed." The Prophet (ﷺ) added: "Whoever among you fulfills his pledge will be rewarded by Allah. And whoever indulges in any one of them (except the ascription of partners to Allah) and gets the punishment in this world, that punishment will be an expiation for that sin. And if one indulges in any of them, and Allah conceals his sin, it is up to Him to forgive or punish him (in the Hereafter)." ''Ubada bin As-Samit added: "So we swore allegiance for these." (points to Allah''s Apostle)', NULL, 'c9b448107bd66ee5878f9eba48b1feb1b01b2cff130d1e5793540a71203ea3ea', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (19, 'bukhari', 3, 19, 'Book 2, Hadith 12', 19, NULL, NULL, 'حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ، عَنْ مَالِكٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَةَ، عَنْ أَبِيهِ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّهُ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ يُوشُِ أَنْ يَكُونَ خَيْرَ مَالِ الْمُسْلِمِ غَنَمٌ يَتْبَعُ بِهَا شَعَفَ الْجِبَالِ وَمَوَاقِعَ الْقَطْرِ، يَفِرُّ بِدِينِهِ مِنَ الْفِتَنِ ‏"‏‏.‏', '"‏ يوش ان يكون خير مال المسلم غنم يتبع بها شعف الجبال ومواقع القطر، يفر بدينه من الفتن ‏"‏‏.‏', 'Narrated Abu Said Al-Khudri: Allah''s Messenger (ﷺ) said, "A time will soon come when the best property of a Muslim will be sheep which he will take on the top of mountains and the places of rainfall (valleys) so as to flee with his religion from afflictions', NULL, 'f42adfec1bb368de5f04900cf276cb66b541bbfc9e7dc85411498b297cface47', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (20, 'bukhari', 3, 20, 'Book 2, Hadith 13', 20, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ سَلاَمٍ، قَالَ أَخْبَرَنَا عَبْدَةُ، عَنْ هِشَامٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِذَا أَمَرَهُمْ أَمَرَهُمْ مِنَ الأَعْمَالِ بِمَا يُطِيقُونَ قَالُوا إِنَّا لَسْنَا كَهَيْئَتِكَ يَا رَسُولَ اللَّهِ، إِنَّ اللَّهَ قَدْ غَفَرَ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ', '. فَيَغْضَبُ حَتَّى يُعْرَفَ الْغَضَبُ فِي وَجْهِهِ ثُمَّ يَقُولُ   إِنَّ أَتْقَاكُمْ وَأَعْلَمَكُمْ بِاللَّهِ أَنَا .', '. فيغضب حتي يعرف الغضب في وجهه ثم يقول ان اتقاكم واعلمكم بالله انا .', 'Narrated ''Aisha: Whenever Allah''s Messenger (ﷺ) ordered the Muslims to do something, he used to order them deeds which were easy for them to do, (according to their strength and endurance). They said, "O Allah''s Messenger (ﷺ)! We are not like you. Allah has forgiven your past and future sins." So Allah''s Apostle became angry and it was apparent on his face. He said, "I am the most Allah fearing, and know Allah better than all of you do', NULL, 'acc6d72bf6336b4aa524081d4de5e9eb86fb593989d2f96e80001147d975c7a1', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (21, 'bukhari', 3, 21, 'Book 2, Hadith 14', 21, NULL, NULL, 'حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، قَالَ حَدَّثَنَا شُعْبَةُ، عَنْ قَتَادَةَ، عَنْ أَنَسٍ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ ثَلاَثٌ مَنْ كُنَّ فِيهِ وَجَدَ حَلاَوَةَ الإِيمَانِ مَنْ كَانَ اللَّهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا، وَمَنْ أَحَبَّ عَبْدًا لاَ يُحِبُّهُ إِلاَّ لِلَّهِ، وَمَنْ يَكْرَهُ أَنْ يَعُودَ فِي الْكُفْرِ بَعْدَ إِذْ أَنْقَذَهُ اللَّهُ، كَمَا يَكْرَهُ أَنْ يُلْقَى فِي النَّارِ ‏"‏‏.‏', '"‏ ثلاث من كن فيه وجد حلاوه الايمان من كان الله ورسوله احب اليه مما سواهما، ومن احب عبدا لا يحبه الا لله، ومن يكره ان يعود في الكفر بعد اذ انقذه الله، كما يكره ان يلقي في النار ‏"‏‏.‏', 'Narrated Anas: The Prophet (ﷺ) said, "Whoever possesses the following three qualities will taste the sweetness of faith: 1. The one to whom Allah and His Apostle become dearer than anything else. 2. Who loves a person and he loves him only for Allah''s sake. 3. Who hates to revert to disbelief (Atheism) after Allah has brought (saved) him out from it, as he hates to be thrown in fire', NULL, 'f4b44328b1f1ce34e53b48ffd5dabbb96019aeb9cddb139ec8b7fbadd123b0de', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (22, 'bukhari', 3, 22, 'Book 2, Hadith 15', 22, NULL, NULL, 'حَدَّثَنَا إِسْمَاعِيلُ، قَالَ حَدَّثَنِي مَالِكٌ، عَنْ عَمْرِو بْنِ يَحْيَى الْمَازِنِيِّ، عَنْ أَبِيهِ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، رضى الله عنه ـ عَنِ الَّبِيِّ صلى الله عليه وسلم قَالَ ‏"‏', 'يَدْخُلُ أَهْلُ الْجَنَّةِ الْجَنَّةَ، وَأَهْلُ النَّارِ النَّارَ، ثُمَّ يَقُولُ اللَّهُ تَعَالَى أَخْرِجُوا مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ خَرْدَلٍ مِنْ إِيمَانٍ‏.‏ فَيُخْرَجُونَ مِنْهَا قَدِ اسْوَدُّوا فَيُلْقَوْنَ فِي نَهَرِ الْحَيَا ـ أَوِ الْحَيَاةِ، شَكَّ مَالِكٌ ـ فَيَنْبُتُونَ كَمَا تَنْبُتُ الْحِبَّةُ فِي جَانِبِ السَّيْلِ، أَلَمْ تَرَ أَنَّهَا تَخْرُجُ صَفْرَاءَ مُلْتَوِيَةً ‏"‏‏.‏ قَالَ وُهَيْبٌ حَدَّثَنَا عَمْرٌو ‏"‏ الْحَيَاةِ ‏"‏‏.‏ وَقَالَ ‏"‏ خَرْدَلٍ مِنْ خَيْرٍ ‏"‏‏.‏', 'يدخل اهل الجنه الجنه، واهل النار النار، ثم يقول الله تعالي اخرجوا من كان في قلبه مثقال حبه من خردل من ايمان‏.‏ فيخرجون منها قد اسودوا فيلقون في نهر الحيا او الحياه، شك مالك فينبتون كما تنبت الحبه في جانب السيل، الم تر انها تخرج صفراء ملتويه ‏"‏‏.‏ قال وهيب حدثنا عمرو ‏"‏ الحياه ‏"‏‏.‏ وقال ‏"‏ خردل من خير ‏"‏‏.‏', 'Narrated Abu Said Al-Khudri: The Prophet (ﷺ) said, "When the people of Paradise will enter Paradise and the people of Hell will go to Hell, Allah will order those who have had faith equal to the weight of a grain of mustard seed to be taken out from Hell. So they will be taken out but (by then) they will be blackened (charred). Then they will be put in the river of Haya'' (rain) or Hayat (life) (the Narrator is in doubt as to which is the right term), and they will revive like a grain that grows near the bank of a flood channel. Don''t you see that it comes out yellow and twisted?', NULL, 'c8512b79e899ddae37a1cecfabb6614be460b770335bda2655d0922e8b334c63', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (23, 'bukhari', 3, 23, 'Book 2, Hadith 16', 23, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ عُبَيْدِ اللَّهِ، قَالَ حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ، عَنْ صَالِحٍ، عنِ ابْنِ شِهَابٍ، عَنْ أَبِي أُمَامَةَ بْنِ سَهْلٍ، أَنَّهُ سَمِعَ أَبَا سَعِيدٍ الْخُدْرِيَّ، يَقُولُ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏', 'بَيْنَا أَنَا نَائِمٌ رَأَيْتُ النَّاسَ يُعْرَضُونَ عَلَىَّ، وَعَلَيْهِمْ قُمُصٌ مِنْهَا مَا يَبْلُغُ الثُّدِيَّ، وَمِنْهَا مَا دُونَ ذَلِكَ، وَعُرِضَ عَلَىَّ عُمَرُ بْنُ الْخَطَّابِ وَعَلَيْهِ قَمِيصٌ يَجُرُّهُ ‏"‏‏.‏ قَالُوا فَمَا أَوَّلْتَ ذَلِكَ يَا رَسُولَ اللَّهِ قَالَ ‏"‏ الدِّينَ ‏"‏‏.‏', 'بينا انا نائم رايت الناس يعرضون علي، وعليهم قمص منها ما يبلغ الثدي، ومنها ما دون ذلك، وعرض علي عمر بن الخطاب وعليه قميص يجره ‏"‏‏.‏ قالوا فما اولت ذلك يا رسول الله قال ‏"‏ الدين ‏"‏‏.‏', 'Narrated Abu Said Al-Khudri: Allah''s Messenger (ﷺ) said, "While I was sleeping I saw (in a dream) some people wearing shirts of which some were reaching up to the breasts only while others were even shorter than that. Umar bin Al-Khattab was shown wearing a shirt that he was dragging." The people asked, "How did you interpret it? (What is its interpretation) O Allah''s Messenger (ﷺ)?" He (the Prophet (ﷺ) ) replied, "It is the Religion', NULL, '5610df903f47f4415ab006ee636d261370593d680428e9377154ef90e143b4c3', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (24, 'bukhari', 3, 24, 'Book 2, Hadith 17', 24, NULL, NULL, 'حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، قَالَ أَخْبَرَنَا مَالِكُ بْنُ أَنَسٍ، عَنِ ابْنِ شِهَابٍ، عَنْ سَالِمِ بْنِ عَبْدِ اللَّهِ، عَنْ أَبِيهِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم مَرَّ عَلَى رَجُلٍ مِنَ الأَنْصَارِ وَهُوَ يَعِظُ أَخَاهُ فِي الْحَيَاءِ، فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ دَعْهُ فَإِنَّ الْحَيَاءَ مِنَ الإِيمَانِ ‏"‏‏.‏', '"‏ دعه فان الحياء من الايمان ‏"‏‏.‏', 'Narrated ''Abdullah (bin ''Umar): Once Allah''s Messenger (ﷺ) passed by an Ansari (man) who was admonishing his brother regarding Haya''. On that Allah''s Messenger (ﷺ) said, "Leave him as Haya'' is a part of faith." (See Hadith)', NULL, '5bb139ea0ea2d9605311c572f2313538d41986ae7fc404d8c6808a4015081310', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (25, 'bukhari', 3, 25, 'Book 2, Hadith 18', 25, NULL, NULL, 'حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ الْمُسْنَدِيُّ، قَالَ حَدَّثَنَا أَبُو رَوْحٍ الْحَرَمِيُّ بْنُ عُمَارَةَ، قَالَ حَدَّثَنَا شُعْبَةُ، عَنْ وَاقِدِ بْنِ مُحَمَّدٍ، قَالَ سَمِعْتُ أَبِي يُحَدِّثُ، عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏', '"‏ أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَيُقِيمُوا الصَّلاَةَ، وَيُؤْتُوا الزَّكَاةَ، فَإِذَا فَعَلُوا ذَلِكَ عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالهُمْ إِلاَّ بِحَقِّ الإِسْلاَمِ، وَحِسَابُهُمْ عَلَى اللَّهِ ‏"‏‏.‏', '"‏ امرت ان اقاتل الناس حتي يشهدوا ان لا اله الا الله وان محمدا رسول الله، ويقيموا الصلاه، ويؤتوا الزكاه، فاذا فعلوا ذلك عصموا مني دماءهم واموالهم الا بحق الاسلام، وحسابهم علي الله ‏"‏‏.‏', 'Narrated Ibn ''Umar: Allah''s Messenger (ﷺ) said: "I have been ordered (by Allah) to fight against the people until they testify that none has the right to be worshipped but Allah and that Muhammad is Allah''s Messenger (ﷺ), and offer the prayers perfectly and give the obligatory charity, so if they perform that, then they save their lives and property from me except for Islamic laws and then their reckoning (accounts) will be done by Allah', NULL, '5199104e5674d45a3e78bc03c7798313663a86f2fcc13a943c1b528497ab8c42', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (26, 'bukhari', 3, 26, 'Book 2, Hadith 19', 26, NULL, NULL, 'حَدَّثَنَا أَحْمَدُ بْنُ يُونُسَ، وَمُوسَى بْنُ إِسْمَاعِيلَ، قَالاَ حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ، قَالَ حَدَّثَنَا ابْنُ شِهَابٍ، عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم', 'سُئِلَ أَىُّ الْعَمَلِ أَفْضَلُ فَقَالَ ‏"‏ إِيمَانٌ بِاللَّهِ وَرَسُولِهِ ‏"‏‏.‏ قِيلَ ثُمَّ مَاذَا قَالَ ‏"‏ الْجِهَادُ فِي سَبِيلِ اللَّهِ ‏"‏‏.‏ قِيلَ ثُمَّ مَاذَا قَالَ ‏"‏ حَجٌّ مَبْرُورٌ ‏"‏‏.‏', 'سئل اي العمل افضل فقال ‏"‏ ايمان بالله ورسوله ‏"‏‏.‏ قيل ثم ماذا قال ‏"‏ الجهاد في سبيل الله ‏"‏‏.‏ قيل ثم ماذا قال ‏"‏ حج مبرور ‏"‏‏.‏', 'Narrated Abu Huraira: Allah''s Messenger (ﷺ) was asked, "What is the best deed?" He replied, "To believe in Allah and His Apostle (Muhammad). The questioner then asked, "What is the next (in goodness)? He replied, "To participate in Jihad (religious fighting) in Allah''s Cause." The questioner again asked, "What is the next (in goodness)?" He replied, "To perform Hajj (Pilgrim age to Mecca) ''Mubrur, (which is accepted by Allah and is performed with the intention of seeking Allah''s pleasure only and not to show off and without committing a sin and in accordance with the traditions of the Prophet)', NULL, '31cb471fdfa3780a032ed04e157454956b8ed9352e79235f22d374778b469038', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (27, 'bukhari', 3, 27, 'Book 2, Hadith 20', 27, NULL, NULL, 'حَدَّثَنَا أَبُو الْيَمَانِ، قَالَ أَخْبَرَنَا شُعَيْبٌ، عَنِ الزُّْرِيِّ، قَالَ أَخْبَرَنِي عَامِرُ بْنُ سَعْدِ بْنِ أَبِي وَقَّاصٍ، عَنْ سَعْدٍ، رضى الله عنه أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم', 'أَعْطَى رَهْطًا وَسَعْدٌ جَالِسٌ، فَتَرَكَ رَسُولُ اللَّهِ صلى الله عليه وسلم رَجُلاً هُوَ أَعْجَبُهُمْ إِلَىَّ فَقُلْتُ يَا رَسُولَ اللَّهِ مَا لَكَ عَنْ فُلاَنٍ فَوَاللَّهِ إِنِّي لأَرَاهُ مُؤْمِنًا‏.‏ فَقَالَ ‏"‏ أَوْ مُسْلِمًا ‏"‏‏.‏ فَسَكَتُّ قَلِيلاً، ثُمَّ غَلَبَنِي مَا أَعْلَمُ مِنْهُ فَعُدْتُ لِمَقَالَتِي فَقُلْتُ مَا لَكَ عَنْ فُلاَنٍ فَوَاللَّهِ إِنِّي لأَرَاهُ مُؤْمِنًا فَقَالَ ‏"‏ أَوْ مُسْلِمًا ‏"‏‏.‏ ثُمَّ غَلَبَنِي مَا أَعْلَمُ مِنْهُ فَعُدْتُ لِمَقَالَتِي وَعَادَ رَسُولُ اللَّهِ صلى الله عليه وسلم ثُمَّ قَالَ ‏"‏ يَا سَعْدُ، إِنِّي لأُعْطِي الرَّجُلَ وَغَيْرُهُ أَحَبُّ ِلَىَّ مِنْهُ، خَشْيَةَ أَنْ يَكُبَّهُ اللَّهُ فِي النَّارِ ‏"‏‏.‏ وَرَوَاهُ يُونُسُ وَصَالِحٌ وَمَعْمَرٌ وَابْنُ أَخِي الزُّهْرِيِّ عَنِ الزُّهْرِيِّ‏.‏', 'اعطي رهطا وسعد جالس، فترك رسول الله صلي الله عليه وسلم رجلا هو اعجبهم الي فقلت يا رسول الله ما لك عن فلان فوالله اني لاراه مؤمنا‏.‏ فقال ‏"‏ او مسلما ‏"‏‏.‏ فسكت قليلا، ثم غلبني ما اعلم منه فعدت لمقالتي فقلت ما لك عن فلان فوالله اني لاراه مؤمنا فقال ‏"‏ او مسلما ‏"‏‏.‏ ثم غلبني ما اعلم منه فعدت لمقالتي وعاد رسول الله صلي الله عليه وسلم ثم قال ‏"‏ يا سعد، اني لاعطي الرجل وغيره احب لي منه، خشيه ان يكبه الله في النار ‏"‏‏.‏ ورواه يونس وصالح ومعمر وابن اخي الزهري عن الزهري‏.‏', 'Narrated Sa''d: Allah''s Messenger (ﷺ) distributed (Zakat) amongst (a group of) people while I was sitting there but Allah''s Messenger (ﷺ) left a man whom I thought the best of the lot. I asked, "O Allah''s Messenger (ﷺ)! Why have you left that person? By Allah I regard him as a faithful believer." The Prophet (ﷺ) commented: "Or merely a Muslim." I remained quiet for a while, but could not help repeating my question because of what I knew about him. And then asked Allah''s Messenger (ﷺ), "Why have you left so and so? By Allah! He is a faithful believer." The Prophet (ﷺ) again said, "Or merely a Muslim." And I could not help repeating my question because of what I knew about him. Then the Prophet (ﷺ) said, "O Sa''d! I give to a person while another is dearer to me, for fear that he might be thrown on his face in the Fire by Allah', NULL, '0bcf7686ece5d396c0ff0e8f68684b48d7d5614d9eb64b203085f433b023355d', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (28, 'bukhari', 3, 28, 'Book 2, Hadith 21', 28, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ، قَالَ حَدَّثَنَا اللَّيْثُ، عَنْ يَزِيدَ بْنِ أَبِي حَبِيبٍ، عَنْ أَبِي الْخَيْرِ، عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنَّ رَجُلاً، سَأَلَ رَسُولَ اللَّهِ صلى الله عليه وسلم', 'أَىُّ الإِسْلاَمِ خَيْرٌ قَالَ ‏ "‏ تُطْعِمُ الطَّعَامَ، وَتَقْرَأُ السَّلاَمَ عَلَى مَنْ عَرَفْتَ وَمَنْ لَمْ تَعْرِفْ ‏"‏‏.‏', 'اي الاسلام خير قال ‏ "‏ تطعم الطعام، وتقرا السلام علي من عرفت ومن لم تعرف ‏"‏‏.‏', 'Narrated ''Abdullah bin ''Amr: A person asked Allah''s Messenger (ﷺ), "What (sort of) deeds in or (what qualities of) Islam are good?" He replied, "To feed (the poor) and greet those whom you know and those whom you don''t know', NULL, '61122ca67176e52bd3498bfd6df5b94af3858e930cb2514f3d97f7dd0df47909', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (29, 'bukhari', 3, 29, 'Book 2, Hadith 22', 29, NULL, NULL, 'حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ، عَنْ مَالِكٍ، عَنْ زَيْدِ بْنِ أَسْلَمَ، عَنْ عَطَاءِ بْنِ يَسَارٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ النَّبِيُّ صلى الله عليه وسلم', 'أُرِيتُ النَّارَ فَإِذَا أَكْثَرُ أَهْلِهَا النِّسَاءُ يَكْفُرْنَ . قِيلَ أَيَكْفُرْنَ بِاللَّهِ قَالَ  يَكْفُرْنَ الْعَشِيرَ، وَيَكْفُرْنَ الإِحْسَانَ، لَوْ أَحْسَنْتَ إِلَى إِحْدَاهُنَّ الدَّهْرَ ثُمَّ رَأَتْ مِنْكَ شَيْئًا قَالَتْ مَا رَأَيْتُ مِنْكَ خَيْرًا قَطُّ .', 'اريت النار فاذا اكثر اهلها النساء يكفرن . قيل ايكفرن بالله قال يكفرن العشير، ويكفرن الاحسان، لو احسنت الي احداهن الدهر ثم رات منك شيئا قالت ما رايت منك خيرا قط .', 'Narrated Ibn ''Abbas: The Prophet (ﷺ) said: "I was shown the Hell-fire and that the majority of its dwellers were women who were ungrateful." It was asked, "Do they disbelieve in Allah?" (or are they ungrateful to Allah?) He replied, "They are ungrateful to their husbands and are ungrateful for the favors and the good (charitable deeds) done to them. If you have always been good (benevolent) to one of them and then she sees something in you (not of her liking), she will say, ''I have never received any good from you', NULL, 'f551d47b749ad9c30247557b4c9ce438e879fdc7ffb4ddf8e6e91a51340560fa', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (30, 'bukhari', 3, 30, 'Book 2, Hadith 23', 30, NULL, NULL, 'حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، قَالَ حَدَّثَنَا شُعْبَةُ، عَنْ وَاصِلٍ الأَحْدَبِ، عَنِ الْمَعْرُورِ، قَالَ لَقِيتُ أَبَا ذَرٍّ بِالرَّبَذَةِ، وَعَلَيْهِ حُلَّةٌ، وَعَلَى غُلاَمِهِ حُلَّةٌ، فَسَأَلْتُهُ عَنْ ذَلِكَ، فَقَالَ إِنِّي سَابَبْتُ رَجُلاً، فَعَيَّرْتُهُ بِأُمِّهِ، فَقَلَ لِيَ النَّبِيُّ صلى الله عليه وسلم', 'يَا أَبَا ذَرٍّ أَعَيَّرْتَهُ بِأُمِّهِ إِنَّكَ امْرُؤٌ فِيكَ جَاهِلِيَّةٌ، إِخْوَانُكُمْ خَوَلُكُمْ، جَعَلَهُمُ اللَّهُ تَحْتَ أَيْدِيكُمْ، فَمَنْ كَانَ أَخُوهُ تَحْتَ يَدِهِ فَلْيُطْعِمْهُ مِمَّا يَأْكُلُ، وَلْيُلْبِسْهُ مِمَّا يَلْبَسُ، وَلاَ تُكَلِّفُوهُمْ مَا يَغْلِبُهُمْ، فَإِنْ كَلَّفْتُمُوهُمْ فَأَعِينُوهُمْ .', 'يا ابا ذر اعيرته بامه انك امرؤ فيك جاهليه، اخوانكم خولكم، جعلهم الله تحت ايديكم، فمن كان اخوه تحت يده فليطعمه مما ياكل، وليلبسه مما يلبس، ولا تكلفوهم ما يغلبهم، فان كلفتموهم فاعينوهم .', 'Narrated Al-Ma''rur: At Ar-Rabadha I met Abu Dhar who was wearing a cloak, and his slave, too, was wearing a similar one. I asked about the reason for it. He replied, "I abused a person by calling his mother with bad names." The Prophet said to me, ''O Abu Dhar! Did you abuse him by calling his mother with bad names You still have some characteristics of ignorance. Your slaves are your brothers and Allah has put them under your command. So whoever has a brother under his command should feed him of what he eats and dress him of what he wears. Do not ask them (slaves) to do things beyond their capacity (power) and if you do so, then help them', NULL, 'fce460617160837368e358c715ec0aae304718f36b79c539020b4a9cebb3fd54', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (31, 'bukhari', 3, 31, 'Book 2, Hadith 24', 31, NULL, NULL, 'حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ الْمُبَارَكِ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، حَدَّثَنَا أَيُّوبُ، وَيُونُسُ، عَنِ الْحَسَنِ، عَنِ الأَحْنَفِ بْنِ قَيْسٍ، قَالَ ذَهَبْتُ لأَنْصُرَ هَذَا الرَّجُلَ، فَلَقِيَنِي أَبُو بَكْرَةَ فَقَالَ أَيْنَ تُرِيدُ قُلْتُ أَنْصُرُ هَذَا الرَّجَُ‏.‏ قَالَ ارْجِعْ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏"‏', 'إِذَا الْتَقَى الْمُسْلِمَانِ بِسَيْفَيْهِمَا فَالْقَاتِلُ وَالْمَقْتُولُ فِي النَّارِ ‏"‏‏.‏ فَقُلْتُ يَا رَسُولَ اللَّهِ هَذَا الْقَاتِلُ فَمَا بَالُ الْمَقْتُولِ قَالَ ‏"‏ إِنَّهُ كَانَ حَرِيصًا عَلَى قَتْلِ صَاحِبِهِ ‏"‏‏.‏', 'اذا التقي المسلمان بسيفيهما فالقاتل والمقتول في النار ‏"‏‏.‏ فقلت يا رسول الله هذا القاتل فما بال المقتول قال ‏"‏ انه كان حريصا علي قتل صاحبه ‏"‏‏.‏', 'Narrated Al-Ahnaf bin Qais: While I was going to help this man (''Ali Ibn Abi Talib), Abu Bakra met me and asked, "Where are you going?" I replied, "I am going to help that person." He said, "Go back for I have heard Allah''s Messenger (ﷺ) saying, ''When two Muslims fight (meet) each other with their swords, both the murderer as well as the murdered will go to the Hell-fire.'' I said, ''O Allah''s Messenger (ﷺ)! It is all right for the murderer but what about the murdered one?'' Allah''s Messenger (ﷺ) replied, "He surely had the intention to kill his companion', NULL, '40d85fab17187d9822aac314bd4d3b1a913cafbce585cd7559871424ddee80dd', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (32, 'bukhari', 3, 32, 'Book 2, Hadith 25', 32, NULL, NULL, 'حَدَّثَنَا أَبُو الْوَلِيدِ، قَالَ حَدَّثَنَا شُعْبَةُ، ح', '. قَالَ وَحَدَّثَنِي بِشْرٌ، قَالَ حَدَّثَنَا مُحَمَّدٌ، عَنْ شُعْبَةَ، عَنْ سُلَيْمَانَ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ، قَالَ لَمَّا نَزَلَتِ {الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ} قَالَ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم أَيُّنَا لَمْ يَظْلِمْ فَأَنْزَلَ اللَّهُ {إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ}.', '. قال وحدثني بشر، قال حدثنا محمد، عن شعبه، عن سليمان، عن ابراهيم، عن علقمه، عن عبد الله، قال لما نزلت {الذين امنوا ولم يلبسوا ايمانهم بظلم} قال اصحاب رسول الله صلي الله عليه وسلم اينا لم يظلم فانزل الله {ان الشرك لظلم عظيم}.', 'Narrated ''Abdullah: When the following Verse was revealed: "It is those who believe and confuse not their belief with wrong (worshipping others besides Allah.)" (6:83), the companions of Allah''s Messenger (ﷺ) asked, "Who is amongst us who had not done injustice (wrong)?" Allah revealed: "No doubt, joining others in worship with Allah is a great injustice (wrong) indeed', NULL, '880ac1eb26e7c0646f461d6f36b3beb06190025705a65f140ff5d65ad55d0026', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (33, 'bukhari', 3, 33, 'Book 2, Hadith 26', 33, NULL, NULL, 'حَدَّثَنَا سُلَيْمَانُ أَبُو الرَّبِيعِ، قَالَ حَدَّثَنَا إِسْمَاعِيلُ بْنُ جَعْفَرٍ، قَالَ حَدَّثَنَا نَافِعُ بْنُ مَالِكِ بْنِ أَبِي عَامِرٍ أَبُو سُهَيْلٍ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ آيَةُ الْمُنَافِقِ ثَلاَثٌ إِذَا حَدَّثَ كَذَبَ، وَإِذَا وَعَدَ أَخْلَفَ، وَإِذَا اؤْتُمِنَ خَانَ ‏"‏‏.‏', '"‏ ايه المنافق ثلاث اذا حدث كذب، واذا وعد اخلف، واذا اؤتمن خان ‏"‏‏.‏', 'Narrated Abu Huraira: The Prophet (ﷺ) said, "The signs of a hypocrite are three: 1. Whenever he speaks, he tells a lie. 2. Whenever he promises, he always breaks it (his promise ). 3. If you trust him, he proves to be dishonest. (If you keep something as a trust with him, he will not return it)', NULL, '3f760091c9f625e9f19e879aa72a172e975510c1e609df4bde5d69eefcd46ee9', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (34, 'bukhari', 3, 34, 'Book 2, Hadith 27', 34, NULL, NULL, 'حَدَّثَنَا قَبِيصَةُ بْنُ عُقْبَةَ، قَالَ حَدَّثَنَا سُفْيَانُ، عَنِ الأَعْمَشِ، عَنْ عَبْدِ اللَّهِ بْنِ مُرَّةَ، عَنْ مَسْرُوقٍ، عَنْ َبْدِ اللَّهِ بْنِ عَمْرٍو، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏', '"‏ أَرْبَعٌ مَنْ كُنَّ فِيهِ كَانَ مُنَافِقًا خَالِصًا، وَمَنْ كَانَتْ فِيهِ خَصْلَةٌ مِنْهُنَّ كَانَتْ فِيهِ خَصْلَةٌ مِنَ النِّفَاقِ حَتَّى يَدَعَهَا إِذَا اؤْتُمِنَ خَانَ وَإِذَا حَدَّثَ كَذَبَ وَإِذَا عَاهَدَ غَدَرَ، وَإِذَا خَاصَمَ فَجَرَ ‏"‏‏.‏ تَابَعَهُ شُعْبَةُ عَنِ الأَعْمَشِ‏.‏', '"‏ اربع من كن فيه كان منافقا خالصا، ومن كانت فيه خصله منهن كانت فيه خصله من النفاق حتي يدعها اذا اؤتمن خان واذا حدث كذب واذا عاهد غدر، واذا خاصم فجر ‏"‏‏.‏ تابعه شعبه عن الاعمش‏.‏', 'Narrated ''Abdullah bin ''Amr: The Prophet (ﷺ) said, "Whoever has the following four (characteristics) will be a pure hypocrite and whoever has one of the following four characteristics will have one characteristic of hypocrisy unless and until he gives it up. 1. Whenever he is entrusted, he betrays. 2. Whenever he speaks, he tells a lie. 3. Whenever he makes a covenant, he proves treacherous. 4. Whenever he quarrels, he behaves in a very imprudent, evil and insulting manner', NULL, 'dc099207a2dc96b3a08e60503be8315bb90ed10abe251b2918e78895cd918ae2', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (35, 'bukhari', 3, 35, 'Book 2, Hadith 28', 35, NULL, NULL, 'حَدَّثَنَا أَبُو الْيَمَانِ، قَالَ أَخْبَرَنَا شُعَيْبٌ، قَالَ حَدَّثَنَا أَبُو الزِّنَادِ، عَنِ الأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ مَنْ يَقُمْ لَيْلَةَ الْقَدْرِ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏"‏‏.‏', '"‏ من يقم ليله القدر ايمانا واحتسابا غفر له ما تقدم من ذنبه ‏"‏‏.‏', 'Narrated Abu Huraira: Allah''s Messenger (ﷺ) said, "Whoever establishes the prayers on the night of Qadr out of sincere faith and hoping to attain Allah''s rewards (not to show off) then all his past sins will be forgiven', NULL, 'b7be2b0fecbb861cc31e9c6c3124a418ef7e8a6d57d9411b81a628c8dbc68e63', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (36, 'bukhari', 3, 36, 'Book 2, Hadith 29', 36, NULL, NULL, 'حَدَّثَنَا حَرَمِيُّ بْنُ حَفْصٍ، قَالَ حَدَّثَنَا عَبْدُ الْوَاحِدِ، قَالَ حَدَّثَنَا عُمَارَةُ، قَالَ حَدَّثَنَا أَبُو زُرْعَةَ بْنُ عَمْرِو بْنِ جَرِيرٍ، قَالَ سَمِعْتُ أَبَا هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ انْتَدَبَ اللَّهُ لِمَنْ خَرَجَ فِي سَبِيلِهِ لاَ يُخْرِجُهُ إِلاَّ إِيمَانٌ بِي وَتَصْدِيقٌ بِرُسُلِي أَنْ أُرْجِعَهُ بِمَا نَالَ مِنْ أَجْرٍ أَوْ غَنِيمَةٍ، أَوْ أُدْخِلَهُ الْجَنَّةَ، وَلَوْلاَ أَنْ أَشُقَّ عَلَى أُمَّتِي مَا قَعَدْتُ خَلْفَ سَرِيَّةٍ، وَلَوَدِدْتُ أَنِّي أُقْتَلُ فِي سَبِيلِ اللَّهِ ثُمَّ أُحْيَا، ثُمَّ أُقْتَلُ ثُمَّ أُحْيَا، ثُمَّ أُقْتَلُ ‏"‏‏.‏', '"‏ انتدب الله لمن خرج في سبيله لا يخرجه الا ايمان بي وتصديق برسلي ان ارجعه بما نال من اجر او غنيمه، او ادخله الجنه، ولولا ان اشق علي امتي ما قعدت خلف سريه، ولوددت اني اقتل في سبيل الله ثم احيا، ثم اقتل ثم احيا، ثم اقتل ‏"‏‏.‏', 'Narrated Abu Huraira: The Prophet (ﷺ) said, "The person who participates in (Holy battles) in Allah''s cause and nothing compels him to do so except belief in Allah and His Apostles, will be recompensed by Allah either with a reward, or booty (if he survives) or will be admitted to Paradise (if he is killed in the battle as a martyr). Had I not found it difficult for my followers, then I would not remain behind any sariya going for Jihad and I would have loved to be martyred in Allah''s cause and then made alive, and then martyred and then made alive, and then again martyred in His cause', NULL, 'dd0020285015b93becd97312fb536de3b9e27fab6a1a32393c93e0a47a40e40a', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (37, 'bukhari', 3, 37, 'Book 2, Hadith 30', 37, NULL, NULL, 'حَدَّثَنَا إِسْمَاعِيلُ، قَالَ حَدَّثَنِي مَالِكٌ، عَنِ ابْنِ شِهَابٍ، عَنْ حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏', '"‏ مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏"‏‏.‏', '"‏ من قام رمضان ايمانا واحتسابا غفر له ما تقدم من ذنبه ‏"‏‏.‏', 'Narrated Abu Huraira: Allah''s Messenger (ﷺ) said: "Whoever establishes prayers during the nights of Ramadan faithfully out of sincere faith and hoping to attain Allah''s rewards (not for showing off), all his past sins will be forgiven', NULL, '53b10b20501a7e46f40db4af67e7098c2c065b0fe95d76e3fc5c52eb39419d59', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (38, 'bukhari', 3, 38, 'Book 2, Hadith 31', 38, NULL, NULL, 'حَدَّثَنَا ابْنُ سَلاَمٍ، قَالَ أَخْبَرَنَا مُحَمَّدُ بْنُ فُضَيْلٍ، قَالَ حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، عَنْ أَبِي سَلَمَةَ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏"‏‏.‏', '"‏ من صام رمضان ايمانا واحتسابا غفر له ما تقدم من ذنبه ‏"‏‏.‏', 'Narrated Abu Huraira: Allah''s Messenger (ﷺ) said, "Whoever observes fasts during the month of Ramadan out of sincere faith, and hoping to attain Allah''s rewards, then all his past sins will be forgiven', NULL, '0182fa4b9c6fdf63447ed51be417fca041450f385d5cfaadb8fbe0d70dc1627d', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (39, 'bukhari', 3, 39, 'Book 2, Hadith 32', 39, NULL, NULL, 'حَدَّثَنَا عَبْدُ السَّلاَمِ بْنُ مُطَهَّرٍ، قَالَ حَدَّثَنَا عُمَرُ بْنُ عَلِيٍّ، عَنْ مَعْنِ بْنِ مُحَمَّدٍ الْغِفَارِيِّ، عَنْ سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ إِنَّ الدِّينَ يُسْرٌ، وَلَنْ يُشَادَّ الدِّينَ أَحَدٌ إِلاَّ غَلَبَهُ، فَسَدِّدُوا وَقَارِبُوا وَأَبْشِرُوا، وَاسْتَعِينُوا بِالْغَدْوَةِ وَالرَّوْحَةِ وَشَىْءٍ مِنَ الدُّلْجَةِ ‏"‏‏.‏', '"‏ ان الدين يسر، ولن يشاد الدين احد الا غلبه، فسددوا وقاربوا وابشروا، واستعينوا بالغدوه والروحه وشيء من الدلجه ‏"‏‏.‏', 'Narrated Abu Huraira: The Prophet (ﷺ) said, "Religion is very easy and whoever overburdens himself in his religion will not be able to continue in that way. So you should not be extremists, but try to be near to perfection and receive the good tidings that you will be rewarded; and gain strength by worshipping in the mornings, the afternoons, and during the last hours of the nights." (See Fath-ul-Bari, Page 102, Vol)', NULL, '12bda48513940c06aed06ca7f302ca56aa399436741e9744c717cec4e17ec51b', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (40, 'bukhari', 3, 40, 'Book 2, Hadith 33', 40, NULL, NULL, 'حَدَّثَنَا عَمْرُو بْنُ خَالِدٍ، قَالَ حَدَّثَنَا زُهَيْرٌ، قَالَ حَدَّثَنَا أَبُو إِسْحَاقَ، عَنِ الْبَرَاءِ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'كَانَ أَوَّلَ مَا قَدِمَ الْمَدِينَةَ نَزَلَ عَلَى أَجْدَادِهِ ـ أَوْ قَالَ أَخْوَالِهِ ـ مِنَ الأَنْصَارِ، وَأَنَّهُ صَلَّى قِبَلَ بَيْتِ الْمَقْدِسِ سِتَّةَ عَشَرَ شَهْرًا، أَوْ سَبْعَةَ عَشَرَ شَهْرًا، وَكَانَ يُعْجِبُهُ أَنْ تَكُونَ قِبْلَتُهُ قِبَلَ الْبَيْتِ، وَأَنَّهُ صَلَّى أَوَّلَ صَلاَةٍ صَلاَّهَا صَلاَةَ الْعَصْرِ، وَصَلَّى مَعَهُ قَوْمٌ، فَخَرَجَ رَجُلٌ مِمَّنْ صَلَّى مَعَهُ، فَمَرَّ عَلَى أَهْلِ مَسْجِدٍ، وَهُمْ رَاكِعُونَ فَقَالَ أَشْهَدُ بِاللَّهِ لَقَدْ صَلَّيْتُ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم قِبَلَ مَكَّةَ، فَدَارُوا كَمَا هُمْ قِبَلَ الْبَيْتِ، وَكَانَتِ الْيَهُودُ قَدْ أَعْجَبَهُمْ إِذْ كَانَ يُصَلِّي قِبَلَ بَيْتِ الْمَقْدِسِ، وَأَهْلُ الْكِتَابِ، فَلَمَّا وَلَّى وَجْهَهُ قِبَلَ الْبَيْتِ أَنْكَرُوا ذَلِكَ‏.‏ قَالَ زُهَيْرٌ حَدَّثَنَا أَبُو إِسْحَاقَ عَنِ الْبَرَاءِ فِي حَدِيثِهِ هَذَا أَنَّهُ مَاتَ عَلَى الْقِبْلَةِ قَبْلَ أَنْ تُحَوَّلَ رِجَالٌ وَقُتِلُوا، فَلَمْ نَدْرِ مَا نَقُولُ فِيهِمْ، فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏وَمَا كَانَ اللَّهُ لِيُضِيعَ إِيمَانَكُمْ‏}‏', 'كان اول ما قدم المدينه نزل علي اجداده او قال اخواله من الانصار، وانه صلي قبل بيت المقدس سته عشر شهرا، او سبعه عشر شهرا، وكان يعجبه ان تكون قبلته قبل البيت، وانه صلي اول صلاه صلاها صلاه العصر، وصلي معه قوم، فخرج رجل ممن صلي معه، فمر علي اهل مسجد، وهم راكعون فقال اشهد بالله لقد صليت مع رسول الله صلي الله عليه وسلم قبل مكه، فداروا كما هم قبل البيت، وكانت اليهود قد اعجبهم اذ كان يصلي قبل بيت المقدس، واهل الكتاب، فلما ولي وجهه قبل البيت انكروا ذلك‏.‏ قال زهير حدثنا ابو اسحاق عن البراء في حديثه هذا انه مات علي القبله قبل ان تحول رجال وقتلوا، فلم ندر ما نقول فيهم، فانزل الله تعالي ‏{‏وما كان الله ليضيع ايمانكم‏}‏', 'Narrated Al-Bara'' (bin ''Azib): When the Prophet (ﷺ) came to Medina, he stayed first with his grandfathers or maternal uncles from Ansar. He offered his prayers facing Baitul-Maqdis (Jerusalem) for sixteen or seventeen months, but he wished that he could pray facing the Ka''ba (at Mecca). The first prayer which he offered facing the Ka''ba was the ''Asr prayer in the company of some people. Then one of those who had offered that prayer with him came out and passed by some people in a mosque who were bowing during their prayers (facing Jerusalem). He said addressing them, "By Allah, I testify that I have prayed with Allah''s Messenger (ﷺ) facing Mecca (Ka''ba).'' Hearing that, those people changed their direction towards the Ka''ba immediately. Jews and the people of the scriptures used to be pleased to see the Prophet (ﷺ) facing Jerusalem in prayers but when he changed his direction towards the Ka''ba, during the prayers, they disapproved of it. Al-Bara'' added, "Before we changed our direction towards the Ka''ba (Mecca) in prayers, some Muslims had died or had been killed and we did not know what to say about them (regarding their prayers.) Allah then revealed: And Allah would never make your faith (prayers) to be lost (i.e. the prayers of those Muslims were valid).'' " (2:)', NULL, 'be2111cf218d91fe2ad8db0b7407b32510afd931d660b2b8a15259ac7c8f8d6b', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (41, 'bukhari', 3, 41, 'Book 2, Hadith 34', 41, NULL, NULL, 'قَالَ مَالِكٌ أَخْبَرَنِي زَيْدُ بْنُ أَسْلَمَ، أَنَّ عَطَاءَ بْنَ يَسَارٍ، أَخْبَرَهُ أَنَّ أَبَا سَعِيدٍ الْخُدْرِيَّ أَخْبَرَهُ أَنَّهُ، سَمِعَ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏', '"‏ إِذَا أَسْلَمَ الْعَبْدُ فَحَسُنَ إِسْلاَمُهُ يُكَفِّرُ اللَّهُ عَنْهُ كُلَّ سَيِّئَةٍ كَانَ زَلَفَهَا، وَكَانَ بَعْدَ ذَلِكَ الْقِصَاصُ، الْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا إِلَى سَبْعِمِائَةِ ضِعْفٍ، وَالسَّيِّئَةُ بِمِثْلِهَا إِلَّ أَنْ يَتَجَاوَزَ اللَّهُ عَنْهَا ‏"‏‏.‏', '"‏ اذا اسلم العبد فحسن اسلامه يكفر الله عنه كل سيئه كان زلفها، وكان بعد ذلك القصاص، الحسنه بعشر امثالها الي سبعمائه ضعف، والسيئه بمثلها ال ان يتجاوز الله عنها ‏"‏‏.‏', 'Narrated Abu Sa''id Al Khudri:Allah''s Messenger (ﷺ) said, "If a person embraces Islam sincerely, then Allah shall forgive all his past sins, and after that starts the settlement of accounts, the reward of his good deeds will be ten times to seven hundred times for each good deed and one evil deed will be recorded as it is unless Allah forgives it', NULL, '40a3698d9ed9d38b0ad64971e07f911e53f69f9bdf7d0d489de87095c05f1c73', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (42, 'bukhari', 3, 42, 'Book 2, Hadith 35', 42, NULL, NULL, 'حَدَّثَنَا إِسْحَاقُ بْنُ مَنْصُورٍ، قَالَ حَدَّثَنَا عَبْدُ الرَّزَّاقِ، قَالَ أَخْبَرَنَا مَعْمَرٌ، عَنْ هَمَّامٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ إِذَا أَحْسَنَ أَحَدُكُمْ إِسْلاَمَهُ، فَكُلُّ حَسَنَةٍ يَعْمَلُهَا تُكْتَبُ لَهُ بِعَشْرِ أَمْثَالِهَا إِلَى سَبْعِمِائَةِ ضِعْفٍ، وَكُلُّ سَيِّئَةٍ يَعْمَلُهَا تُكْتَبُ لَهُ بِمِثْلِهَا ‏"‏‏.‏', '"‏ اذا احسن احدكم اسلامه، فكل حسنه يعملها تكتب له بعشر امثالها الي سبعمائه ضعف، وكل سيئه يعملها تكتب له بمثلها ‏"‏‏.‏', 'Narrated Abu Huraira: Allah''s Messenger (ﷺ) said, "If any one of you improves (follows strictly) his Islamic religion then his good deeds will be rewarded ten times to seven hundred times for each good deed and a bad deed will be recorded as it is', NULL, '37f22e51658c892a56b2d8e657be170bc4cdb28da3c9b21bede36613c8e8bf7f', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (43, 'bukhari', 3, 43, 'Book 2, Hadith 36', 43, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا يَحْيَى، عَنْ هِشَامٍ، قَالَ أَخْبَرَنِي أَبِي، عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'دَخَلَ عَلَيْهَا وَعِنْدَهَا امْرَأَةٌ قَالَ ‏"‏ مَنْ هَذِهِ ‏"‏‏.‏ قَالَتْ فُلاَنَةُ‏.‏ تَذْكُرُ مِنْ صَلاَتِهَا‏.‏ قَالَ ‏"‏ مَهْ، عَلَيْكُمْ بِمَا تُطِيقُونَ، فَوَاللَّهِ لاَ يَمَلُّ اللَّهُ حَتَّى تَمَلُّوا ‏"‏‏.‏ وَكَانَ أَحَبَّ الدِّينِ إِلَيْهِ مَا دَامَ عَلَيْهِ صَاحِبُهُ‏.‏', 'دخل عليها وعندها امراه قال ‏"‏ من هذه ‏"‏‏.‏ قالت فلانه‏.‏ تذكر من صلاتها‏.‏ قال ‏"‏ مه، عليكم بما تطيقون، فوالله لا يمل الله حتي تملوا ‏"‏‏.‏ وكان احب الدين اليه ما دام عليه صاحبه‏.‏', 'Narrated ''Aisha: Once the Prophet (ﷺ) came while a woman was sitting with me. He said, "Who is she?" I replied, "She is so and so," and told him about her (excessive) praying. He said disapprovingly, "Do (good) deeds which is within your capacity (without being overtaxed) as Allah does not get tired (of giving rewards) but (surely) you will get tired and the best deed (act of Worship) in the sight of Allah is that which is done regularly', NULL, 'c7eef1221be3642cb5b8813d8aef4abcfb42b071ed601de1bdb88a904766102f', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (44, 'bukhari', 3, 44, 'Book 2, Hadith 37', 44, NULL, NULL, 'حَدَّثَنَا مُسْلِمُ بْنُ إِبْرَاهِيمَ، قَالَ حَدَّثَنَا هِشَامٌ، قَالَ حَدَّثَنَا قَتَادَةُ، عَنْ أَنَسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏"‏', 'يَخْرُجُ مِنَ النَّارِ مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ، وَفِي قَلْبِهِ وَزْنُ شَعِيرَةٍ مِنْ خَيْرٍ، وَيَخْرُجُ مِنَ النَّارِ مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ، وَفِي قَلْبِهِ وَزْنُ بُرَّةٍ مِنْ خَيْرٍ، وَيَخْرُجُ مِنَ النَّارِ مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ، وَفِي قَلْبِهِ وَزْنُ ذَرَّةٍ مِنْ خَيْرٍ ‏"‏‏.‏ قَالَ أَبُو عَبْدِ اللَّهِ قَالَ أَبَانُ حَدَّثَنَا قَتَادَةُ حَدَّثَنَا أَنَسٌ عَنِ النَّبِيِّ صلى الله عليه وسلم ‏"‏ مِنْ إِيمَانٍ ‏"‏‏.‏ مَكَانَ ‏"‏ مِنْ خَيْرٍ ‏"‏‏.‏', 'يخرج من النار من قال لا اله الا الله، وفي قلبه وزن شعيره من خير، ويخرج من النار من قال لا اله الا الله، وفي قلبه وزن بره من خير، ويخرج من النار من قال لا اله الا الله، وفي قلبه وزن ذره من خير ‏"‏‏.‏ قال ابو عبد الله قال ابان حدثنا قتاده حدثنا انس عن النبي صلي الله عليه وسلم ‏"‏ من ايمان ‏"‏‏.‏ مكان ‏"‏ من خير ‏"‏‏.‏', 'Narrated Anas: The Prophet (ﷺ) said, "Whoever said "None has the right to be worshipped but Allah and has in his heart good (faith) equal to the weight of a barley grain will be taken out of Hell. And whoever said: "None has the right to be worshipped but Allah and has in his heart good (faith) equal to the weight of a wheat grain will be taken out of Hell. And whoever said, "None has the right to be worshipped but Allah and has in his heart good (faith) equal to the weight of an atom will be taken out of Hell', NULL, '25d93e0ce13c562c6641da7fecb86e14831ac91c7f473673cccbcd8bc3d303f2', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (45, 'bukhari', 3, 45, 'Book 2, Hadith 38', 45, NULL, NULL, 'حَدَّثَنَا الْحَسَنُ بْنُ الصَّبَّاحِ، سَمِعَ جَعْفَرَ بْنَ عَوْنٍ، حَدَّثَنَا أَبُو الْعُمَيْسِ، أَخْبَرَنَا قَيْسُ بْنُ مُسْلِمٍ، عَنْ طَارِقِ بْنِ شِهَابٍ، عَنْ عُمَرَ بْنِ الْخَطَّابِ، أَنَّ رَجُلاً، مِنَ الْيَهُودِ قَالَ لَهُ يَا أَمِيرَ الْمُؤْمِنِينَ، آيَةٌ فِي كِتَابِكُمْ تَقْرَءُونَهَا لَوْ عَلَيْنَا مَعْشَرَ الْيَهُودِ نَزَلَتْ لاَتَّخَذْنَا ذَلِكَ الْيَوْمَ عِيدًا', '. قَالَ أَىُّ آيَةٍ قَالَ {الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الإِسْلاَمَ دِينًا}. قَالَ عُمَرُ قَدْ عَرَفْنَا ذَلِكَ الْيَوْمَ وَالْمَكَانَ الَّذِي نَزَلَتْ فِيهِ عَلَى النَّبِيِّ صلى الله عليه وسلم وَهُوَ قَائِمٌ بِعَرَفَةَ يَوْمَ جُمُعَةٍ.', '. قال اي ايه قال {اليوم اكملت لكم دينكم واتممت عليكم نعمتي ورضيت لكم الاسلام دينا}. قال عمر قد عرفنا ذلك اليوم والمكان الذي نزلت فيه علي النبي صلي الله عليه وسلم وهو قائم بعرفه يوم جمعه.', 'Narrated ''Umar bin Al-Khattab: Once a Jew said to me, "O the chief of believers! There is a verse in your Holy Book Which is read by all of you (Muslims), and had it been revealed to us, we would have taken that day (on which it was revealed as a day of celebration." ''Umar bin Al-Khattab asked, "Which is that verse?" The Jew replied, "This day I have perfected your religion For you, completed My favor upon you, And have chosen for you Islam as your religion." (5:3) ''Umar replied,"No doubt, we know when and where this verse was revealed to the Prophet. It was Friday and the Prophet (ﷺ) was standing at ''Arafat (i.e. the Day of Hajj)', NULL, 'd7e8559a881cce514c066d751ec49b025a6f532b7e6ba649f1ea96ab1e43d6ca', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (46, 'bukhari', 3, 46, 'Book 2, Hadith 39', 46, NULL, NULL, 'حَدَّثَنَا إِسْمَاعِيلُ، قَالَ حَدَّثَنِي مَالِكُ بْنُ أَنَسٍ، عَنْ عَمِّهِ أَبِي سُهَيْلِ بْنِ مَالِكٍ، عَنْ أَبِيهِ، أَنَّهُ سَمِعَ طَلْحَةَ بْنَ عُبَيْدِ اللَّهِ، يَقُولُ جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم مِنْ أَهْلِ نَجْدٍ، ثَائِرُ الرَّأْسِ، يُسْمَعُ دَوِيُّ صَوْتِهِ، وَلاَ يُفْقَهُ مَا يَقُولُ حَتَّى دَنَا، فَإِذَا هُوَ يَسْأَلُ عَنِ الإِسْلاَمِ فَقَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ‏"‏ خَمْسُ صَلَوَاتٍ فِي الْيَوْمِ وَاللَّيْلَةِ ‏"‏‏.‏ فَقَالَ هَلْ عَلَىَّ غَيْرُهَا قَالَ ‏"‏ لاَ، إِلاَّ أَنْ تَطَوَّعَ ‏"‏‏.‏ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏', 'وَصِيَامُ رَمَضَانَ ‏"‏‏.‏ قَالَ هَلْ عَلَىَّ غَيْرُهُ قَالَ ‏"‏ لاَ، إِلاَّ أَنْ تَطَوَّعَ ‏"‏‏.‏ قَالَ وَذَكَرَ لَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم الزَّكَاةَ‏.‏ قَالَ هَلْ عَلَىَّ غَيْرُهَا قَالَ ‏"‏ لاَ، إِلاَّ أَنْ تَطَوَّعَ ‏"‏‏.‏ قَالَ فَأَدْبَرَ الرَّجُلُ وَهُوَ يَقُولُ وَاللَّهِ لاَ أَزِيدُ عَلَى هَذَا وَلاَ أَنْقُصُ‏.‏ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏ أَفْلَحَ إِنْ صَدَقَ ‏"‏‏.‏', 'وصيام رمضان ‏"‏‏.‏ قال هل علي غيره قال ‏"‏ لا، الا ان تطوع ‏"‏‏.‏ قال وذكر له رسول الله صلي الله عليه وسلم الزكاه‏.‏ قال هل علي غيرها قال ‏"‏ لا، الا ان تطوع ‏"‏‏.‏ قال فادبر الرجل وهو يقول والله لا ازيد علي هذا ولا انقص‏.‏ قال رسول الله صلي الله عليه وسلم ‏"‏ افلح ان صدق ‏"‏‏.‏', 'Narrated Talha bin ''Ubaidullah: A man from Najd with unkempt hair came to Allah''s Messenger (ﷺ) and we heard his loud voice but could not understand what he was saying, till he came near and then we came to know that he was asking about Islam. Allah''s Messenger (ﷺ) said, "You have to offer prayers perfectly five times in a day and night (24 hours)." The man asked, "Is there any more (praying)?" Allah''s Messenger (ﷺ) replied, "No, but if you want to offer the Nawafil prayers (you can)." Allah''s Messenger (ﷺ) further said to him: "You have to observe fasts during the month of Ramadan." The man asked, "Is there any more fasting?" Allah''s Messenger (ﷺ) replied, "No, but if you want to observe the Nawafil fasts (you can.)" Then Allah''s Messenger (ﷺ) further said to him, "You have to pay the Zakat (obligatory charity)." The man asked, "Is there any thing other than the Zakat for me to pay?" Allah''s Messenger (ﷺ) replied, "No, unless you want to give alms of your own." And then that man retreated saying, "By Allah! I will neither do less nor more than this." Allah''s Messenger (ﷺ) said, "If what he said is true, then he will be successful (i.e. he will be granted Paradise)', NULL, '2336608a09dd46aa8b9851f8988417beabe669b0fd476665f1f4e889b0957310', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (47, 'bukhari', 3, 47, 'Book 2, Hadith 40', 47, NULL, NULL, 'حَدَّثَنَا أَحْمَدُ بْنُ عَبْدِ اللَّهِ بْنِ عَلِيٍّ الْمَنْجُوفِيُّ، قَالَ حَدَّثَنَا رَوْحٌ، قَالَ حَدَّثَنَا عَوْفٌ، عَنِ الْحَسَنِ، وَمُحَمَّدٍ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ "‏ مَنِ اتَّبَعَ جَنَازَةَ مُسْلِمٍ إِيمَانًا وَاحْتِسَابًا، وَكَانَ مَعَهُ حَتَّى يُصَلَّى عَلَيْهَا، وَيَفْرُغَ مِنْ دَفْنِهَا، فَإِنَّهُ يَرْجِعُ مِنَ الأَجْرِ بِقِيرَاطَيْنِ، كُلُّ قِيرَاطٍ مِثْلُ أُحُدٍ، وَمَنْ صَلَّى عَلَيْهَا ثُمَّ رَجَعَ قَبْلَ أَنْ تُدْفَنَ فَإِنَّهُ يَرْجِعُ بِقِيرَاطٍ ‏"‏‏.‏ تَابَعَهُ عُثْمَانُ الْمُؤَذِّنُ قَالَ حَدَّثَنَا عَوْفٌ عَنْ مُحَمَّدٍ عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صلى الله عليه وسلم', 'نَحْوَهُ‏.‏', 'نحوه‏.‏', 'Narrated Abu Huraira: Allah''s Messenger (ﷺ) said, "(A believer) who accompanies the funeral procession of a Muslim out of sincere faith and hoping to attain Allah''s reward and remains with it till the funeral prayer is offered and the burial ceremonies are over, he will return with a reward of two Qirats. Each Qirat is like the size of the (Mount) Uhud. He who offers the funeral prayer only and returns before the burial, will return with the reward of one Qirat only', NULL, 'ba30bcf75ddfe23072aeb7129aeef835ce2c4ac39553d56ca5bf48cbcdc6d808', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (48, 'bukhari', 3, 48, 'Book 2, Hadith 41', 48, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ عَرْعَرَةَ، قَالَ حَدَّثَنَا شُعْبَةُ، عَنْ زُبَيْدٍ، قَالَ سَأَلْتُ أَبَا وَائِلٍ عَنِ الْمُرْجِئَةِ،، فَقَالَ حَدَّثَنِي عَبْدُ اللَّهِ، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏', '"‏ سِبَابُ الْمُسْلِمِ فُسُوقٌ، وَقِتَالُهُ كُفْرٌ ‏"‏‏.‏', '"‏ سباب المسلم فسوق، وقتاله كفر ‏"‏‏.‏', 'Narrated ''Abdullah: The Prophet (ﷺ) said, "Abusing a Muslim is Fusuq (an evil doing) and killing him is Kufr (disbelief)', NULL, '974e11089dc67aed7504f97ea9c5caeae1704f2fb48d88345dfdb51c92a2cc1b', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (49, 'bukhari', 3, 49, 'Book 2, Hadith 42', 49, NULL, NULL, 'أَخْبَرَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا إِسْمَاعِيلُ بْنُ جَعْفَرٍ، عَنْ حُمَيْدٍ، عَنْ أَنَسٍ، قَالَ أَخْبَرَنِي عُبَادَةُ بْنُ الصَّامِتِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم', 'خَرَجَ يُخْبِرُ بِلَيْلَةِ الْقَدْرِ، فَتَلاَحَى رَجُلاَنِ مِنَ الْمُسْلِمِينَ فَقَالَ ‏ "‏ إِنِّي خَرَجْتُ لأُخْبِرَكُمْ بِلَيْلَةِ الْقَدْرِ، وَإِنَّهُ تَلاَحَى فُلاَنٌ وَفُلاَنٌ فَرُفِعَتْ وَعَسَى أَنْ يَكُونَ خَيْرًا لَكُمُ الْتَمِسُوهَا فِي السَّبْعِ وَالتِّسْعِ وَالْخَمْسِ ‏"‏‏.‏', 'خرج يخبر بليله القدر، فتلاحي رجلان من المسلمين فقال ‏ "‏ اني خرجت لاخبركم بليله القدر، وانه تلاحي فلان وفلان فرفعت وعسي ان يكون خيرا لكم التمسوها في السبع والتسع والخمس ‏"‏‏.‏', 'Narrated ''Ubada bin As-Samit:"Allah''s Messenger (ﷺ) went out to inform the people about the (date of the) night of decree (Al-Qadr) but there happened a quarrel between two Muslim men. The Prophet (ﷺ) said, "I came out to inform you about (the date of) the night of Al-Qadr, but as so and so and so and so quarrelled, its knowledge was taken away (I forgot it) and maybe it was better for you. Now look for it in the 7th, the 9th and the 5th (of the last 10 nights of the month of Ramadan)', NULL, '380fc4e180ef27141001341db72000105928afc94b1511552973fdd6a2059051', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (50, 'bukhari', 3, 50, 'Book 2, Hadith 43', 50, NULL, NULL, 'حَدَّثَنَا مُسَدَّدٌ، قَالَ حَدَّثَنَا إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ، أَخْبَرَنَا أَبُو حَيَّانَ التَّيْمِيُّ، عَنْ أَبِي زُرْعَةَ، عَنْ أَبِي هُرَيْرَةَ، قَالَ كَانَ النَّبِيُّ صلى الله عليه وسلم بَارِزًا يَوْمًا لِلنَّاسِ، فَأَتَاهُ جِبْرِيلُ فَقَالَ مَا الإِيمَانُ قَالَ', 'الإِيمَانُ أَنْ تُؤْمِنَ بِاللَّهِ وَمَلاَئِكَتِهِ وَبِلِقَائِهِ وَرُسُلِهِ، وَتُؤْمِنَ بِالْبَعْثِ . قَالَ مَا الإِسْلاَمُ قَالَ  الإِسْلاَمُ أَنْ تَعْبُدَ اللَّهَ وَلاَ تُشْرِكَ بِهِ، وَتُقِيمَ الصَّلاَةَ، وَتُؤَدِّيَ الزَّكَاةَ الْمَفْرُوضَةَ، وَتَصُومَ رَمَضَانَ . قَالَ مَا الإِحْسَانُ قَالَ  أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ . قَالَ مَتَى السَّاعَةُ قَالَ  مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِلِ، وَسَأُخْبِرُكَ عَنْ أَشْرَاطِهَا إِذَا وَلَدَتِ الأَمَةُ رَبَّهَا، وَإِذَا تَطَاوَلَ رُعَاةُ الإِبِلِ الْبُهْمُ فِي الْبُنْيَانِ، فِي خَمْسٍ لاَ يَعْلَمُهُنَّ إِلاَّ اللَّهُ . ثُمَّ تَلاَ النَّبِيُّ صلى الله عليه وسلم {إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ} الآيَةَ. ثُمَّ أَدْبَرَ فَقَالَ  رُدُّوهُ . فَلَمْ يَرَوْا شَيْئًا. فَقَالَ  هَذَا جِبْرِيلُ جَاءَ يُعَلِّمُ النَّاسَ دِينَهُمْ . قَالَ أَبُو عَبْدِ اللَّهِ جَعَلَ ذَلِكَ كُلَّهُ مِنَ الإِيمَانِ.', 'الايمان ان تؤمن بالله وملائكته وبلقائه ورسله، وتؤمن بالبعث . قال ما الاسلام قال الاسلام ان تعبد الله ولا تشرك به، وتقيم الصلاه، وتؤدي الزكاه المفروضه، وتصوم رمضان . قال ما الاحسان قال ان تعبد الله كانك تراه، فان لم تكن تراه فانه يراك . قال متي الساعه قال ما المسئول عنها باعلم من السائل، وساخبرك عن اشراطها اذا ولدت الامه ربها، واذا تطاول رعاه الابل البهم في البنيان، في خمس لا يعلمهن الا الله . ثم تلا النبي صلي الله عليه وسلم {ان الله عنده علم الساعه} الايه. ثم ادبر فقال ردوه . فلم يروا شيئا. فقال هذا جبريل جاء يعلم الناس دينهم . قال ابو عبد الله جعل ذلك كله من الايمان.', 'Narrated Abu Huraira: One day while the Prophet (ﷺ) was sitting in the company of some people, (The angel) Gabriel came and asked, "What is faith?" Allah''s Messenger (ﷺ) replied, ''Faith is to believe in Allah, His angels, (the) meeting with Him, His Apostles, and to believe in Resurrection." Then he further asked, "What is Islam?" Allah''s Messenger (ﷺ) replied, "To worship Allah Alone and none else, to offer prayers perfectly to pay the compulsory charity (Zakat) and to observe fasts during the month of Ramadan." Then he further asked, "What is Ihsan (perfection)?" Allah''s Messenger (ﷺ) replied, "To worship Allah as if you see Him, and if you cannot achieve this state of devotion then you must consider that He is looking at you." Then he further asked, "When will the Hour be established?" Allah''s Messenger (ﷺ) replied, "The answerer has no better knowledge than the questioner. But I will inform you about its portents. 1. When a slave (lady) gives birth to her master. 2. When the shepherds of black camels start boasting and competing with others in the construction of higher buildings. And the Hour is one of five things which nobody knows except Allah. The Prophet (ﷺ) then recited: "Verily, with Allah (Alone) is the knowledge of the Hour--." (31. 34) Then that man (Gabriel) left and the Prophet (ﷺ) asked his companions to call him back, but they could not see him. Then the Prophet (ﷺ) said, "That was Gabriel who came to teach the people their religion." Abu ''Abdullah said: He (the Prophet) considered all that as a part of faith', NULL, '20f26a7396aa10f62cced6134cc1317682b30cbd475f95b13be0dbdb0bcdea6c', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published')
INSERT INTO public.hadith_narrations (id, collection_id, book_id, hadith_number, in_book_reference, international_number, chapter_title_arabic, chapter_title_english, sanad_arabic, matn_arabic, matn_clean, translation_english, translation_urdu, text_checksum, source_edition, version_number, is_current, status) VALUES
  (51, 'bukhari', 3, 51, 'Book 2, Hadith 44', 51, NULL, NULL, 'حَدَّثَنَا إِبْرَاهِيمُ بْنُ حَمْزَةَ، قَالَ حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدٍ، عَنْ صَالِحٍ، عَنِ ابْنِ شِهَابٍ، عَنْ عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ، أَنَّ عَبْدَ اللَّهِ بْنَ عَبَّاسٍ، أَخْبَرَهُ قَالَ أَخْبَرَنِي أَبُو سُفْيَانَ، أَنَّ هِرَقْلَ، قَالَ لَهُ سَأَلْتُكَ هَلْ يَزِيدُونَ أَمْ يَنْقُصُونَ، فَزَعَمْتَ أَنَّهُمْ يَزِيدُونَ، وَكَذَلِكَ الإِيمَانُ حَتَّى يَتِمَّ', '. وَسَأَلْتُكَ هَلْ يَرْتَدُّ أَحَدٌ سَخْطَةً لِدِينِهِ بَعْدَ أَنْ يَدْخُلَ فِيهِ، فَزَعَمْتَ أَنْ لاَ، وَكَذَلِكَ الإِيمَانُ حِينَ تُخَالِطُ بَشَاشَتُهُ الْقُلُوبَ، لاَ يَسْخَطُهُ أَحَدٌ.', '. وسالتك هل يرتد احد سخطه لدينه بعد ان يدخل فيه، فزعمت ان لا، وكذلك الايمان حين تخالط بشاشته القلوب، لا يسخطه احد.', 'Narrated ''Abdullah bin ''Abbas: I was informed by Abu Sufyan that Heraclius said to him, "I asked you whether they (followers of Muhammad) were increasing or decreasing. You replied that they were increasing. And in fact, this is the way of true Faith till it is complete in all respects. I further asked you whether there was anybody, who, after embracing his (the Prophets) religion (Islam) became displeased and discarded it. You replied in the negative, and in fact, this is (a sign of) true faith. When its delight enters the heart and mixes with them completely, nobody can be displeased with it', NULL, 'dd503fe39fa3307f3e2587da1648d310ff783d9b251b58fc479043b36cd19302', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (52, 'bukhari', 3, 52, 'Book 2, Hadith 45', 52, NULL, NULL, 'حَدَّثَنَا أَبُو نُعَيْمٍ، حَدَّثَنَا زَكَرِيَّاءُ، عَنْ عَامِرٍ، قَالَ سَمِعْتُ النُّعْمَانَ بْنَ بَشِيرٍ، يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏', '"‏ الْحَلاَلُ بَيِّنٌ وَالْحَرَامُ بَيِّنٌ، وَبَيْنَهُمَا مُشَبَّهَاتٌ لاَ يَعْلَمُهَا كَثِيرٌ مِنَ النَّاسِ، فَمَنِ اتَّقَى الْمُشَبَّهَاتِ اسْتَبْرَأَ لِدِيِنِهِ وَعِرْضِهِ، وَمَنْ وَقَعَ فِي الشُّبُهَاتِ كَرَاعٍ يَرْعَى حَوْلَ الْحِمَى، يُوشِكُ أَنْ يُوَاقِعَهُ‏.‏ أَلاَ وَإِنَّ لِكُلِّ مَلِكٍ حِمًى، أَلاَ إِنَّ حِمَى اللَّهِ فِي أَرْضِهِ مَحَارِمُهُ، أَلاَ وَإِنَّ فِي الْجَسَدِ مُضْغَةً إِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ، وَإِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ‏.‏ أَلاَ وَهِيَ الْقَلْبُ ‏"‏‏.‏', '"‏ الحلال بين والحرام بين، وبينهما مشبهات لا يعلمها كثير من الناس، فمن اتقي المشبهات استبرا لدينه وعرضه، ومن وقع في الشبهات كراع يرعي حول الحمي، يوشك ان يواقعه‏.‏ الا وان لكل ملك حمي، الا ان حمي الله في ارضه محارمه، الا وان في الجسد مضغه اذا صلحت صلح الجسد كله، واذا فسدت فسد الجسد كله‏.‏ الا وهي القلب ‏"‏‏.‏', 'Narrated An-Nu''man bin Bashir: I heard Allah''s Messenger (ﷺ) saying, ''Both legal and illegal things are evident but in between them there are doubtful (suspicious) things and most of the people have no knowledge about them. So whoever saves himself from these suspicious things saves his religion and his honor. And whoever indulges in these suspicious things is like a shepherd who grazes (his animals) near the Hima (private pasture) of someone else and at any moment he is liable to get in it. (O people!) Beware! Every king has a Hima and the Hima of Allah on the earth is His illegal (forbidden) things. Beware! There is a piece of flesh in the body if it becomes good (reformed) the whole body becomes good but if it gets spoilt the whole body gets spoilt and that is the heart', NULL, '6609dc9e3e71b6c3bb7c80814b99f301347f922c812177ceaec1e8561fa67e38', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (53, 'bukhari', 3, 53, 'Book 2, Hadith 46', 53, NULL, NULL, 'حَدَّثَنَا عَلِيُّ بْنُ الْجَعْدِ، قَالَ أَخْبَرَنَا شُعْبَةُ، عَنْ أَبِي جَمْرَةَ، قَالَ كُنْتُ أَقْعُدُ مَعَ ابْنِ عَبَّاسٍ، يُجْلِسُنِي عَلَى سَرِيرِهِ فَقَالَ أَقِمْ عِنْدِي حَتَّى أَجْعَلَ لَكَ سَهْمًا مِنْ مَالِي، فَأَقَمْتُ مَعَهُ شَهْرَيْنِ، ثُمَّ قَالَ إِنَّ وَفْدَ عَبْدِ الْقَيْسِ لَمَّا أَتَوُا النَّبِيَّ صلى الله عليه وسلم قَالَ ‏"‏', 'مَنِ الْقَوْمُ أَوْ مَنِ الْوَفْدُ ‏"‏‏.‏ قَالُوا رَبِيعَةُ‏.‏ قَالَ ‏"‏ مَرْحَبًا بِالْقَوْمِ ـ أَوْ بِالْوَفْدِ ـ غَيْرَ خَزَايَا وَلاَ نَدَامَى ‏"‏‏.‏ فَقَالُوا يَا رَسُولَ اللَّهِ، إِنَّا لاَ نَسْتَطِيعُ أَنْ نَأْتِيَكَ إِلاَّ فِي شَهْرِ الْحَرَامِ، وَبَيْنَنَا وَبَيْنَكَ هَذَا الْحَىُّ مِنْ كُفَّارِ مُضَرَ، فَمُرْنَا بِأَمْرٍ فَصْلٍ، نُخْبِرْ بِهِ مَنْ وَرَاءَنَا، وَنَدْخُلْ بِهِ الْجَنَّةَ‏.‏ وَسَأَلُوهُ عَنِ الأَشْرِبَةِ‏.‏ فَأَمَرَهُمْ بِأَرْبَعٍ، وَنَهَاهُمْ عَنْ أَرْبَعٍ، أَمَرَهُمْ بِالإِيمَانِ بِاللَّهِ وَحْدَهُ‏.‏ قَالَ ‏"‏ أَتَدْرُونَ مَا الإِيمَانُ بِاللَّهِ وَحْدَهُ ‏"‏‏.‏ قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ‏.‏ قَالَ ‏"‏ شَهَادَةُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامُ الصَّلاَةِ، وَإِيتَاءُ الزَّكَاةِ، وَصِيَامُ رَمَضَانَ، وَأَنْ تُعْطُوا مِنَ الْمَغْنَمِ الْخُمُسَ ‏"‏‏.‏ وَنَهَاهُمْ عَنْ أَرْبَعٍ عَنِ الْحَنْتَمِ وَالدُّبَّاءِ وَالنَّقِيرِ وَالْمُزَفَّتِ‏.‏ وَرُبَّمَا قَالَ الْمُقَيَّرِ‏.‏ وَقَالَ ‏"‏ احْفَظُوهُنَّ وَأَخْبِرُوا بِهِنَّ مَنْ وَرَاءَكُمْ ‏"‏‏.‏', 'من القوم او من الوفد ‏"‏‏.‏ قالوا ربيعه‏.‏ قال ‏"‏ مرحبا بالقوم او بالوفد غير خزايا ولا ندامي ‏"‏‏.‏ فقالوا يا رسول الله، انا لا نستطيع ان ناتيك الا في شهر الحرام، وبيننا وبينك هذا الحي من كفار مضر، فمرنا بامر فصل، نخبر به من وراءنا، وندخل به الجنه‏.‏ وسالوه عن الاشربه‏.‏ فامرهم باربع، ونهاهم عن اربع، امرهم بالايمان بالله وحده‏.‏ قال ‏"‏ اتدرون ما الايمان بالله وحده ‏"‏‏.‏ قالوا الله ورسوله اعلم‏.‏ قال ‏"‏ شهاده ان لا اله الا الله وان محمدا رسول الله، واقام الصلاه، وايتاء الزكاه، وصيام رمضان، وان تعطوا من المغنم الخمس ‏"‏‏.‏ ونهاهم عن اربع عن الحنتم والدباء والنقير والمزفت‏.‏ وربما قال المقير‏.‏ وقال ‏"‏ احفظوهن واخبروا بهن من وراءكم ‏"‏‏.‏', 'Narrated Abu Jamra: I used to sit with Ibn ''Abbas and he made me sit on his sitting place. He requested me to stay with him in order that he might give me a share from his property. So I stayed with him for two months. Once he told (me) that when the delegation of the tribe of ''Abdul Qais came to the Prophet, the Prophet (ﷺ) asked them, "Who are the people (i.e. you)? (Or) who are the delegate?" They replied, "We are from the tribe of Rabi''a." Then the Prophet (ﷺ) said to them, "Welcome! O people (or O delegation of ''Abdul Qais)! Neither will you have disgrace nor will you regret." They said, "O Allah''s Messenger (ﷺ)! We cannot come to you except in the sacred month and there is the infidel tribe of Mudar intervening between you and us. So please order us to do something good (religious deeds) so that we may inform our people whom we have left behind (at home), and that we may enter Paradise (by acting on them)." Then they asked about drinks (what is legal and what is illegal). The Prophet (ﷺ) ordered them to do four things and forbade them from four things. He ordered them to believe in Allah Alone and asked them, "Do you know what is meant by believing in Allah Alone?" They replied, "Allah and His Apostle know better." Thereupon the Prophet (ﷺ) said, "It means: 1. To testify that none has the right to be worshipped but Allah and Muhammad is Allah''s Messenger (ﷺ). 2. To offer prayers perfectly 3. To pay the Zakat (obligatory charity) 4. To observe fast during the month of Ramadan. 5. And to pay Al-Khumus (one fifth of the booty to be given in Allah''s Cause). Then he forbade them four things, namely, Hantam, Dubba,'' Naqir Ann Muzaffat or Muqaiyar; (These were the names of pots in which Alcoholic drinks were prepared) (The Prophet (ﷺ) mentioned the container of wine and he meant the wine itself). The Prophet (ﷺ) further said (to them): "Memorize them (these instructions) and convey them to the people whom you have left behind', NULL, 'f33f73f862ed830e24680d62538742f8c955f3a89231276548f6de8979555556', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (54, 'bukhari', 3, 54, 'Book 2, Hadith 47', 54, NULL, NULL, 'حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ، قَالَ أَخْبَرَنَا مَالِكٌ، عَنْ يَحْيَى بْنِ سَعِيدٍ، عَنْ مُحَمَّدِ بْنِ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ بْنِ وَقَّاصٍ، عَنْ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏', '"‏ الأَعْمَالُ بِالنِّيَّةِ، وَلِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ، فَهِجْرَتُهُ إِلَى اللَّهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا، أَوِ امْرَأَةٍ يَتَزَوَّجُهَا، فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ ‏"‏‏.‏', '"‏ الاعمال بالنيه، ولكل امرئ ما نوي، فمن كانت هجرته الي الله ورسوله، فهجرته الي الله ورسوله، ومن كانت هجرته لدنيا يصيبها، او امراه يتزوجها، فهجرته الي ما هاجر اليه ‏"‏‏.‏', 'Narrated ''Umar bin Al-Khattab: Allah''s Messenger (ﷺ) said, "The reward of deeds depends upon the intention and every person will get the reward according to what he has intended. So whoever emigrated for Allah and His Apostle, then his emigration was for Allah and His Apostle. And whoever emigrated for worldly benefits or for a woman to marry, his emigration was for what he emigrated for', NULL, 'f9ab6a965e14a05a19f06d20719d64e0632b5801ac47c9755f5c78f1927e2c1f', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (55, 'bukhari', 3, 55, 'Book 2, Hadith 48', 55, NULL, NULL, 'حَدَّثَنَا حَجَّاجُ بْنُ مِنْهَالٍ، قَالَ حَدَّثَنَا شُعْبَةُ، قَالَ أَخْبَرَنِي عَدِيُّ بْنُ ثَابِتٍ، قَالَ سَمِعْتُ عَبْدَ اللَّهِ بْنَ يَزِيدَ، عَنْ أَبِي مَسْعُودٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ إِذَا أَنْفَقَ الرَّجُلُ عَلَى أَهْلِهِ يَحْتَسِبُهَا فَهُوَ لَهُ صَدَقَةٌ ‏"‏‏.‏', '"‏ اذا انفق الرجل علي اهله يحتسبها فهو له صدقه ‏"‏‏.‏', 'Narrated Abu Mas''ud: The Prophet (ﷺ) said, "If a man spends on his family (with the intention of having a reward from Allah) sincerely for Allah''s sake then it is a (kind of) alms-giving in reward for him', NULL, '677e36d1412dfd876f80e4078ea1baa8eacde5370d301a3a38b9b2fa75c9ea47', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (56, 'bukhari', 3, 56, 'Book 2, Hadith 49', 56, NULL, NULL, 'حَدَّثَنَا الْحَكَمُ بْنُ نَافِعٍ قَالَ أَخْبَرَنَا شُعَيْبٌ عَنْ الزُّهْرِيِّ قَالَ حَدَّثَنِي عَامِرُ بْنُ سَعْدٍ عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ أَنَّهُ أَخْبَرَهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ "', 'إِنَّكَ لَنْ تُنْفِقَ نَفَقَةً تَبْتَغِي بِهَا وَجْهَ اللَّهِ إِلَّا أُجِرْتَ عَلَيْهَا حَتَّى مَا تَجْعَلُ فِي فَمِ امْرَأَتِكَ', 'انك لن تنفق نفقه تبتغي بها وجه الله الا اجرت عليها حتي ما تجعل في فم امراتك', 'Narrated Sa''d bin Abi Waqqas: Allah''s Messenger (ﷺ) said, "You will be rewarded for whatever you spend for Allah''s sake even if it were a morsel which you put in your wife''s mouth', NULL, '7a6110b6fef41a7a914737389e027fc513836844911a90607d55aacb6699dbc9', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (57, 'bukhari', 3, 57, 'Book 2, Hadith 50', 57, NULL, NULL, 'حَدَّثَنَا مُسَدَّدٌ، قَالَ حَدَّثَنَا يَحْيَى، عَنْ إِسْمَاعِيلَ، قَالَ حَدَّثَنِي قَيْسُ بْنُ أَبِي حَازِمٍ، عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ، قَالَ بَايَعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم عَلَى إِقَامِ الصَّلاَةِ، وَإِيتَاءِ الزَّكَاةِ، وَالنُّصْحِ لِكُلِّ مُسْلِمٍ', '.', '.', 'Narrated Jarir bin Abdullah: I gave the pledge of allegiance to Allah''s Messenger (ﷺ) for the following: 1. offer prayers perfectly 2. pay the Zakat (obligatory charity) 3. and be sincere and true to every Muslim', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (58, 'bukhari', 3, 58, 'Book 2, Hadith 51', 58, NULL, NULL, 'حَدَّثَنَا أَبُو النُّعْمَانِ، قَالَ حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ زِيَادِ بْنِ عِلاَقَةَ، قَالَ سَمِعْتُ جَرِيرَ بْنَ عَبْدِ اللَّهِ، يَقُولُ يَوْمَ مَاتَ الْمُغِيرَةُ بْنُ شُعْبَةَ قَامَ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ وَقَالَ عَلَيْكُمْ بِاتِّقَاءِ اللَّهِ وَحْدَهُ لاَ شَرِيكَ لَهُ، وَالْوَقَارِ وَالسَّكِينَةِ حَتَّى يَأْتِيَكُمْ أَمِيرٌ، فَإِنَّمَا يَأْتِيكُمُ الآنَ، ثُمَّ قَالَ اسْتَعْفُوا لأَمِيرِكُمْ، فَإِنَّهُ كَانَ يُحِبُّ الْعَفْوَ', '. ثُمَّ قَالَ أَمَّا بَعْدُ، فَإِنِّي أَتَيْتُ النَّبِيَّ صلى الله عليه وسلم قُلْتُ أُبَايِعُكَ عَلَى الإِسْلاَمِ. فَشَرَطَ عَلَىَّ وَالنُّصْحِ لِكُلِّ مُسْلِمٍ. فَبَايَعْتُهُ عَلَى هَذَا، وَرَبِّ هَذَا الْمَسْجِدِ إِنِّي لَنَاصِحٌ لَكُمْ. ثُمَّ اسْتَغْفَرَ وَنَزَلَ.', '. ثم قال اما بعد، فاني اتيت النبي صلي الله عليه وسلم قلت ابايعك علي الاسلام. فشرط علي والنصح لكل مسلم. فبايعته علي هذا، ورب هذا المسجد اني لناصح لكم. ثم استغفر ونزل.', 'Narrated Ziyad bin''Ilaqa: I heard Jarir bin ''Abdullah (Praising Allah). On the day when Al-Mughira bin Shu''ba died, he (Jarir) got up (on the pulpit) and thanked and praised Allah and said, "Be afraid of Allah alone Who has none along with Him to be worshipped.(You should) be calm and quiet till the (new) chief comes to you and he will come to you soon. Ask Allah''s forgiveness for your (late) chief because he himself loved to forgive others." Jarir added, "Amma badu (now then), I went to the Prophet and said, ''I give my pledge of allegiance to you for Islam." The Prophet (ﷺ) conditioned (my pledge) for me to be sincere and true to every Muslim so I gave my pledge to him for this. By the Lord of this mosque! I am sincere and true to you (Muslims). Then Jarir asked for Allah''s forgiveness and came down (from the pulpit)', NULL, '36513ee65a7be7eba24b08f4e40ca08c9c132457c5a8aa5c370907945d6a7a54', 'BUKHARI Darussalam Reference Edition', 1, TRUE, 'published'),
  (59, 'muslim', 100, 93, 'Book 1, Hadith 1', 8, NULL, NULL, 'حَدَّثَنِي أَبُو خَيْثَمَةَ، زُهَيْرُ بْنُ حَرْبٍ حَدَّثَنَا وَكِيعٌ، عَنْ كَهْمَسٍ، عَنْ عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ، عَنْ يَحْيَى بْنِ يَعْمَرَ، ح وَحَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ الْعَنْبَرِيُّ، - وَهَذَا حَدِيثُهُ - حَدَّثَنَا أَبِي، حَدَّثَنَا كَهْمَسٌ، عَنِ ابْنِ بُرَيْدَةَ، عَنْ يَحْيَى بْنِ يَعْمَرَ، قَالَ كَانَ أَوَّلَ مَنْ قَالَ فِي الْقَدَرِ بِالْبَصْرَةِ مَعْبَدٌ الْجُهَنِيُّ فَانْطَلَقْتُ أَنَا وَحُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ الْحِمْيَرِيُّ حَاجَّيْنِ أَوْ مُعْتَمِرَيْنِ فَقُلْنَا لَوْ لَقِينَا أَحَدًا مِنْ أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم فَسَأَلْنَاهُ عَمَّا يَقُولُ هَؤُلاَءِ فِي الْقَدَرِ فَوُفِّقَ لَنَا عَبْدُ اللَّهِ بْنُ عُمَرَ بْنِ الْخَطَّابِ دَاخِلاً الْمَسْجِدَ فَاكْتَنَفْتُهُ أَنَا وَصَاحِبِي أَحَدُنَا عَنْ يَمِينِهِ وَالآخَرُ عَنْ شِمَالِهِ فَظَنَنْتُ أَنَّ صَاحِبِي سَيَكِلُ الْكَلاَمَ إِلَىَّ فَقُلْتُ أَبَا عَبْدِ الرَّحْمَنِ إِنَّهُ قَدْ ظَهَرَ قِبَلَنَا نَاسٌ يَقْرَءُونَ الْقُرْآنَ وَيَتَقَفَّرُونَ الْعِلْمَ - وَذَكَرَ مِنْ شَأْنِهِمْ - وَأَنَّهُمْ يَزْعُمُونَ أَنْ لاَ قَدَرَ وَأَنَّ الأَمْرَ أُنُفٌ ‏.‏ قَالَ فَإِذَا لَقِيتَ أُولَئِكَ فَأَخْبِرْهُمْ أَنِّي بَرِيءٌ مِنْهُمْ وَأَنَّهُمْ بُرَآءُ مِنِّي وَالَّذِي يَحْلِفُ بِهِ عَبْدُ اللَّهِ بْنُ عُمَرَ لَوْ أَنَّ لأَحَدِهِمْ مِثْلَ أُحُدٍ ذَهَبًا فَأَنْفَقَهُ مَا قَبِلَ اللَّهُ مِنْهُ حَتَّى يُؤْمِنَ بِالْقَدَرِ ثُمَّ قَالَ حَدَّثَنِي أَبِي عُمَرُ بْنُ الْخَطَّابِ قَالَ بَيْنَمَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم ذَاتَ يَوْمٍ إِذْ طَلَعَ عَلَيْنَا رَجُلٌ شَدِيدُ بَيَاضِ الثِّيَابِ شَدِيدُ سَوَادِ الشَّعَرِ لاَ يُرَى عَلَيْهِ أَثَرُ السَّفَرِ وَلاَ يَعْرِفُهُ مِنَّا أَحَدٌ حَتَّى جَلَسَ إِلَى النَّبِيِّ صلى الله عليه وسلم فَأَسْنَدَ رُكْبَتَيْهِ إِلَى رُكْبَتَيْهِ وَوَضَعَ كَفَّيْهِ عَلَى فَخِذَيْهِ وَقَالَ يَا مُحَمَّدُ أَخْبِرْنِي عَنِ الإِسْلاَمِ ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏', 'الإِسْلاَمُ أَنْ تَشْهَدَ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ وَتُقِيمَ الصَّلاَةَ وَتُؤْتِيَ الزَّكَاةَ وَتَصُومَ رَمَضَانَ وَتَحُجَّ الْبَيْتَ إِنِ اسْتَطَعْتَ إِلَيْهِ سَبِيلاً ‏.‏ قَالَ صَدَقْتَ ‏.‏ قَالَ فَعَجِبْنَا لَهُ يَسْأَلُهُ وَيُصَدِّقُهُ ‏.‏ قَالَ فَأَخْبِرْنِي عَنِ الإِيمَانِ ‏.‏ قَالَ ‏"‏ أَنْ تُؤْمِنَ بِاللَّهِ وَمَلاَئِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الآخِرِ وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ ‏"‏ ‏.‏ قَالَ صَدَقْتَ ‏.‏ قَالَ فَأَخْبِرْنِي عَنِ الإِحْسَانِ ‏.‏ قَالَ ‏"‏ أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ ‏"‏ ‏.‏ قَالَ فَأَخْبِرْنِي عَنِ السَّاعَةِ ‏.‏ قَالَ ‏"‏ مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِلِ ‏"‏ ‏.‏ قَالَ فَأَخْبِرْنِي عَنْ أَمَارَتِهَا ‏.‏ قَالَ ‏"‏ أَنْ تَلِدَ الأَمَةُ رَبَّتَهَا وَأَنْ تَرَى الْحُفَاةَ الْعُرَاةَ الْعَالَةَ رِعَاءَ الشَّاءِ يَتَطَاوَلُونَ فِي الْبُنْيَانِ ‏"‏ ‏.‏ قَالَ ثُمَّ انْطَلَقَ فَلَبِثْتُ مَلِيًّا ثُمَّ قَالَ لِي ‏"‏ يَا عُمَرُ أَتَدْرِي مَنِ السَّائِلُ ‏"‏ ‏.‏ قُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ ‏.‏ قَالَ ‏"‏ فَإِنَّهُ جِبْرِيلُ أَتَاكُمْ يُعَلِّمُكُمْ دِينَكُمْ ‏"‏ ‏.‏', 'الاسلام ان تشهد ان لا اله الا الله وان محمدا رسول الله وتقيم الصلاه وتؤتي الزكاه وتصوم رمضان وتحج البيت ان استطعت اليه سبيلا ‏.‏ قال صدقت ‏.‏ قال فعجبنا له يساله ويصدقه ‏.‏ قال فاخبرني عن الايمان ‏.‏ قال ‏"‏ ان تؤمن بالله وملائكته وكتبه ورسله واليوم الاخر وتؤمن بالقدر خيره وشره ‏"‏ ‏.‏ قال صدقت ‏.‏ قال فاخبرني عن الاحسان ‏.‏ قال ‏"‏ ان تعبد الله كانك تراه فان لم تكن تراه فانه يراك ‏"‏ ‏.‏ قال فاخبرني عن الساعه ‏.‏ قال ‏"‏ ما المسئول عنها باعلم من السائل ‏"‏ ‏.‏ قال فاخبرني عن امارتها ‏.‏ قال ‏"‏ ان تلد الامه ربتها وان تري الحفاه العراه العاله رعاء الشاء يتطاولون في البنيان ‏"‏ ‏.‏ قال ثم انطلق فلبثت مليا ثم قال لي ‏"‏ يا عمر اتدري من السائل ‏"‏ ‏.‏ قلت الله ورسوله اعلم ‏.‏ قال ‏"‏ فانه جبريل اتاكم يعلمكم دينكم ‏"‏ ‏.‏', 'It is narrated on the authority of Yahya b. Ya''mur that the first man who discussed qadr (Divine Decree) in Basra was Ma''bad al-Juhani. I along with Humaid b. ''Abdur-Rahman Himyari set out for pilgrimage or for ''Umrah and said:Should it so happen that we come into contact with one of the Companions of the Messenger of Allah (peace be upon him) we shall ask him about what is talked about taqdir (Divine Decree). Accidentally we came across Abdullah ibn Umar ibn al-Khattab, while he was entering the mosque. My companion and I surrounded him. One of us (stood) on his right and the other stood on his left. I expected that my companion would authorize me to speak. I therefore said: Abu Abdur Rahman! There have appeared some people in our land who recite the Qur''an and pursue knowledge. And then after talking about their affairs, added: They (such people) claim that there is no such thing as Divine Decree and events are not predestined. He (Abdullah ibn Umar) said: When you happen to meet such people tell them that I have nothing to do with them and they have nothing to do with me. And verily they are in no way responsible for my (belief). Abdullah ibn Umar swore by Him (the Lord) (and said): If any one of them (who does not believe in the Divine Decree) had with him gold equal to the bulk of (the mountain) Uhud and spent it (in the way of Allah), Allah would not accept it unless he affirmed his faith in Divine Decree. He further said: My father, Umar ibn al-Khattab, told me: One day we were sitting in the company of Allah''s Apostle (peace be upon him) when there appeared before us a man dressed in pure white clothes, his hair extraordinarily black. There were no signs of travel on him. None amongst us recognized him. At last he sat with the Apostle (peace be upon him) He knelt before him placed his palms on his thighs and said: Muhammad, inform me about al-Islam. The Messenger of Allah (peace be upon him) said: Al-Islam implies that you testify that there is no god but Allah and that Muhammad is the messenger of Allah, and you establish prayer, pay Zakat, observe the fast of Ramadan, and perform pilgrimage to the (House) if you are solvent enough (to bear the expense of) the journey. He (the inquirer) said: You have told the truth. He (Umar ibn al-Khattab) said: It amazed us that he would put the question and then he would himself verify the truth. He (the inquirer) said: Inform me about Iman (faith). He (the Holy Prophet) replied: That you affirm your faith in Allah, in His angels, in His Books, in His Apostles, in the Day of Judgment, and you affirm your faith in the Divine Decree about good and evil. He (the inquirer) said: You have told the truth. He (the inquirer) again said: Inform me about al-Ihsan (performance of good deeds). He (the Holy Prophet) said: That you worship Allah as if you are seeing Him, for though you don''t see Him, He, verily, sees you. He (the enquirer) again said: Inform me about the hour (of the Doom). He (the Holy Prophet) remarked: One who is asked knows no more than the one who is inquiring (about it). He (the inquirer) said: Tell me some of its indications. He (the Holy Prophet) said: That the slave-girl will give birth to her mistress and master, that you will find barefooted, destitute goat-herds vying with one another in the construction of magnificent buildings. He (the narrator, Umar ibn al-Khattab) said: Then he (the inquirer) went on his way but I stayed with him (the Holy Prophet) for a long while. He then, said to me: Umar, do you know who this inquirer was? I replied: Allah and His Apostle knows best. He (the Holy Prophet) remarked: He was Gabriel (the angel). He came to you in order to instruct you in matters of religion', NULL, '393e05b776d6a20386d0cdfefc761fc90994514071eb7fd014f29d57bffc4055', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (60, 'muslim', 100, 94, 'Book 1, Hadith 2', 8, NULL, NULL, NULL, 'حَدَّثَنِي مُحَمَّدُ بْنُ عُبَيْدٍ الْغُبَرِيُّ، وَأَبُو كَامِلٍ الْجَحْدَرِيُّ وَأَحْمَدُ بْنُ عَبْدَةَ قَالُوا حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ مَطَرٍ الْوَرَّاقِ، عَنْ عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ، عَنْ يَحْيَى بْنِ يَعْمَرَ، قَالَ لَمَّا تَكَلَّمَ مَعْبَدٌ بِمَا تَكَلَّمَ بِهِ فِي شَأْنِ الْقَدَرِ أَنْكَرْنَا ذَلِكَ ‏.‏ قَالَ فَحَجَجْتُ أَنَا وَحُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ الْحِمْيَرِيُّ حِجَّةً ‏.‏ وَسَاقُوا الْحَدِيثَ بِمَعْنَى حَدِيثِ كَهْمَسٍ وَإِسْنَادِهِ ‏.‏ وَفِيهِ بَعْضُ زِيَادَةٍ وَنُقْصَانُ أَحْرُفٍ ‏.‏', 'حدثني محمد بن عبيد الغبري، وابو كامل الجحدري واحمد بن عبده قالوا حدثنا حماد بن زيد، عن مطر الوراق، عن عبد الله بن بريده، عن يحيي بن يعمر، قال لما تكلم معبد بما تكلم به في شان القدر انكرنا ذلك ‏.‏ قال فحججت انا وحميد بن عبد الرحمن الحميري حجه ‏.‏ وساقوا الحديث بمعني حديث كهمس واسناده ‏.‏ وفيه بعض زياده ونقصان احرف ‏.‏', 'It is narrated on the authority of Yahya b. Ya''mur that when Ma''bad discussed the problem pertaining to Divine Decree, we refuted that. He (the narrator) said:I and Humaid b. Abdur-Rahman Himyari argued. And they carried on the conversation about the purport of the hadith related by Kahmas and its chain of transmission too, and there is some variation of words', NULL, '4114741d0e16c9920dda3a11187a22829285ef2a647fc0f08ffe6bfeb42bf5ee', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (61, 'muslim', 100, 95, 'Book 1, Hadith 3', 8, NULL, NULL, 'وَحَدَّثَنِي مُحَمَّدُ بْنُ حَاتِمٍ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ، حَدَّثَنَا عُثْمَانُ بْنُ غِيَاثٍ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ بُرَيْدَةَ، عَنْ يَحْيَى بْنِ يَعْمَرَ، وَحُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ، قَالاَ لَقِينَا عَبْدَ اللَّهِ بْنَ عُمَرَ فَذَكَرْنَا الْقَدَرَ وَمَا يَقُولُونَ فِيهِ ‏.‏ فَاقْتَصَّ الْحَدِيثَ كَنَحْوِ حَدِيثِهِمْ عَنْ عُمَرَ - رضى الله عنه - عَنِ النَّبِيِّ صلى الله عليه وسلم', 'وَفِيهِ شَىْءٌ مِنْ زِيَادَةٍ وَقَدْ نَقَصَ مِنْهُ شَيْئًا ‏.‏', 'وفيه شيء من زياده وقد نقص منه شيئا ‏.‏', 'It is narrated on the authority of Yahya b. Ya''mur and Humaid b. ''Abdur-Rahman that they said:We met Abdullah b. ''Umar and we discussed about the Divine Decree, and what they talked about it and he narrated the hadith that has been transmitted by ''Umar (may Allah be pleased with him) from the Apostle (ﷺ). There is a slight variation in that', NULL, 'ee7ad97edee910e4086fbe4e2915b59f7ab5fb36c3cf4879fc99b25212137061', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (62, 'muslim', 100, 96, 'Book 1, Hadith 4', 8, NULL, NULL, 'وَحَدَّثَنِي حَجَّاجُ بْنُ الشَّاعِرِ، حَدَّثَنَا يُونُسُ بْنُ مُحَمَّدٍ، حَدَّثَنَا الْمُعْتَمِرُ، عَنْ أَبِيهِ، عَنْ يَحْيَى بْنِ يَعْمَرَ، عَنِ ابْنِ عُمَرَ، عَنْ عُمَرَ، عَنِ النَّبِيِّ صلى الله عليه وسلم', 'بِنَحْوِ حَدِيثِهِمْ ‏.‏', 'بنحو حديثهم ‏.‏', 'The same hadith is mentioned through a different chain', NULL, '30aaed6cd5fb6964f53c2e3a03881bba871b6c6f8f38dcee26adff78f0aae286', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (63, 'muslim', 100, 97, 'Book 1, Hadith 5', 8, NULL, NULL, 'وَحَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَزُهَيْرُ بْنُ حَرْبٍ، جَمِيعًا عَنِ ابْنِ عُلَيَّةَ، قَالَ زُهَيْرٌ حَدَّثَنَا إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ، عَنْ أَبِي حَيَّانَ، عَنْ أَبِي زُرْعَةَ بْنِ عَمْرِو بْنِ جَرِيرٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَوْمًا بَارِزًا لِلنَّاسِ فَأَتَاهُ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ مَا الإِيمَانُ قَالَ ‏"‏ أَنْ تُؤْمِنَ بِاللَّهِ وَمَلاَئِكَتِهِ وَكِتَابِهِ وَلِقَائِهِ وَرُسُلِهِ وَتُؤْمِنَ بِالْبَعْثِ الآخِرِ ‏"‏ ‏.‏ قَالَ يَا رَسُولَ اللَّهِ مَا الإِسْلاَمُ قَالَ ‏"‏ الإِسْلاَمُ أَنْ تَعْبُدَ اللَّهَ وَلاَ تُشْرِكَ بِهِ شَيْئًا وَتُقِيمَ الصَّلاَةَ الْمَكْتُوبَةَ وَتُؤَدِّيَ الزَّكَاةَ الْمَفْرُوضَةَ وَتَصُومَ رَمَضَانَ ‏"‏ ‏.‏ قَالَ يَا رَسُولَ اللَّهِ مَا الإِحْسَانُ قَالَ ‏"‏ أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ فَإِنَّكَ إِنْ لاَ تَرَاهُ فَإِنَّهُ يَرَاكَ ‏"‏ ‏.‏ قَالَ يَا رَسُولَ اللَّهِ مَتَى السَّاعَةُ قَالَ ‏"‏ مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِلِ وَلَكِنْ سَأُحَدِّثُكَ عَنْ أَشْرَاطِهَا إِذَا وَلَدَتِ الأَمَةُ رَبَّهَا فَذَاكَ مِنْ أَشْرَاطِهَا وَإِذَا كَانَتِ الْعُرَاةُ الْحُفَاةُ رُءُوسَ النَّاسِ فَذَاكَ مِنْ أَشْرَاطِهَا وَإِذَا تَطَاوَلَ رِعَاءُ الْبَهْمِ فِي الْبُنْيَانِ فَذَاكَ مِنْ أَشْرَاطِهَا فِي خَمْسٍ لاَ يَعْلَمُهُنَّ إِلاَّ اللَّهُ ‏"‏ ‏.‏ ثُمَّ تَلاَ صلى الله عليه وسلم ‏{‏ إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ الْغَيْثَ وَيَعْلَمُ مَا فِي الأَرْحَامِ وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا وَمَا تَدْرِي نَفْسٌ بِأَىِّ أَرْضٍ تَمُوتُ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ‏}‏ ‏"‏ ‏.‏ قَالَ ثُمَّ أَدْبَرَ الرَّجُلُ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏', 'رُدُّوا عَلَىَّ الرَّجُلَ ‏"‏ ‏.‏ فَأَخَذُوا لِيَرُدُّوهُ فَلَمْ يَرَوْا شَيْئًا ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏ هَذَا جِبْرِيلُ جَاءَ لِيُعَلِّمَ النَّاسَ دِينَهُمْ ‏"‏ ‏.‏', 'ردوا علي الرجل ‏"‏ ‏.‏ فاخذوا ليردوه فلم يروا شيئا ‏.‏ فقال رسول الله صلي الله عليه وسلم ‏"‏ هذا جبريل جاء ليعلم الناس دينهم ‏"‏ ‏.‏', 'Abu Huraira reported:One day the Messenger of Allah (ﷺ) appeared before the public so a man came to him and then said: Prophet of Allah, what is Iman? Upon this he (the Holy Prophet) replied: That you affirm your faith in Allah, His angels, His Books, His meeting, His Messengers and that you affirm your faith in the Resurrection hereafter. He said: Messenger of Allah, what is al-Islam? He replied: Al-Islam is that you worship Allah and do not associate anything with Him and you establish obligatory prayer and you pay the obligatory alms (Zakat) and you observe the fast of Ramadan. He said: Messenger of Allah, what is al-Ihsan? He replied: That you worship Allah as if you are seeing Him, and for if you fail to see Him. He said: Messenger of Allah, when is the Hour (of Doom)? He replied: The one who is asked about it is no better informed than the inquirer, however I will narrate some of its signs to you. When the slave-girl will give birth to her master, then that is from its signs. When the naked, barefooted would become the chiefs of the people, then that is from its signs. When the shepherds of the black (camels) would exult themselves in buildings, then that is from its signs. (The Hour is) Among one of the five which no one knows but Allah. Then he recited (the verse): "Verily Allah! with Him alone is the knowledge of the Hour and He it is Who sends down the rain and knows that which is in the wombs. And no soul knows what it shall earn tomorrow, and a soul knows not in what land it shall die. Verily Allah is Knowing, Aware." He (Abu Huraira) said: Then the person turned back and went away. The Messenger of Allah (ﷺ) said: Bring that man back to me. They went to bring him back, but they saw nothing there. Upon this the Messenger of Allah remarked: he was Gabriel, who came to teach the people their religion', NULL, '4746a3e190e03671f4257ff03ec64785b84622d16959379b26dfb2d4e7f797cd', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (64, 'muslim', 100, 98, 'Book 1, Hadith 6', 9, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ، حَدَّثَنَا مُحَمَّدُ بْنُ بِشْرٍ، حَدَّثَنَا أَبُو حَيَّانَ التَّيْمِيُّ، بِهَذَا الإِسْنَادِ مِثْلَهُ غَيْرَ أَنَّ فِي رِوَايَتِهِ', 'إِذَا وَلَدَتِ الأَمَةُ بَعْلَهَا  يَعْنِي السَّرَارِيَّ .', 'اذا ولدت الامه بعلها يعني السراري .', 'This hadith is narrated to us on the authority of Muhammad b. ''Abdullah b. Numair, on the authority of Muhammad b. Bishr, on the authority of Abd Hayyan al-Taymi with the exception that in this narration (instead of the words (Iza Waladat al''amah rabbaha), the words are (Iza Waladat al''amah Ba''laha), i, e, when slave-girl gives birth to her master', NULL, '0b01c0e5e014952d7a4e09773a20036df4d7fb8a15f802b3d0af4c363bb108e8', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (65, 'muslim', 100, 99, 'Book 1, Hadith 7', 10, NULL, NULL, 'حَدَّثَنِي زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا جَرِيرٌ، عَنْ عُمَارَةَ، - وَهُوَ ابْنُ الْقَعْقَاعِ - عَنْ أَبِي زُرْعَةَ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏', 'سَلُونِي ‏"‏ فَهَابُوهُ أَنْ يَسْأَلُوهُ ‏.‏ فَجَاءَ رَجُلٌ فَجَلَسَ عِنْدَ رُكْبَتَيْهِ ‏.‏ فَقَالَ يَا رَسُولَ اللَّهِ مَا الإِسْلاَمُ قَالَ ‏"‏ لاَ تُشْرِكُ بِاللَّهِ شَيْئًا وَتُقِيمُ الصَّلاَةَ وَتُؤْتِي الزَّكَاةَ وَتَصُومُ رَمَضَانَ ‏"‏ ‏.‏ قَالَ صَدَقْتَ ‏.‏ قَالَ يَا رَسُولَ اللَّهِ مَا الإِيمَانُ قَالَ ‏"‏ أَنْ تُؤْمِنَ بِاللَّهِ وَمَلاَئِكَتِهِ وَكِتَابِهِ وَلِقَائِهِ وَرُسُلِهِ وَتُؤْمِنَ بِالْبَعْثِ وَتُؤْمِنَ بِالْقَدَرِ كُلِّهِ ‏"‏ ‏.‏ قَالَ صَدَقْتَ ‏.‏ قَالَ يَا رَسُولَ اللَّهِ مَا الإِحْسَانُ قَالَ ‏"‏ أَنْ تَخْشَى اللَّهَ كَأَنَّكَ تَرَاهُ فَإِنَّكَ إِنْ لاَ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ ‏"‏ ‏.‏ قَالَ صَدَقْتَ ‏.‏ قَالَ يَا رَسُولَ اللَّهِ مَتَى تَقُومُ السَّاعَةُ قَالَ ‏"‏ مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِلِ وَسَأُحَدِّثُكَ عَنْ أَشْرَاطِهَا إِذَا رَأَيْتَ الْمَرْأَةَ تَلِدُ رَبَّهَا فَذَاكَ مِنْ أَشْرَاطِهَا وَإِذَا رَأَيْتَ الْحُفَاةَ الْعُرَاةَ الصُّمَّ الْبُكْمَ مُلُوكَ الأَرْضِ فَذَاكَ مِنْ أَشْرَاطهَا وَإِذَا رَأَيْتَ رِعَاءَ الْبَهْمِ يَتَطَاوَلُونَ فِي الْبُنْيَانِ فَذَاكَ مِنْ أَشْرَاطِهَا فِي خَمْسٍ مِنَ الْغَيْبِ لاَ يَعْلَمُهُنَّ إِلاَّ اللَّهُ ‏"‏ ‏.‏ ثُمَّ قَرَأَ ‏{‏ إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ الْغَيْثَ وَيَعْلَمُ مَا فِي الأَرْحَامِ وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا وَمَا تَدْرِي نَفْسٌ بِأَىِّ أَرْضٍ تَمُوتُ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ‏}‏ قَالَ ثُمَّ قَامَ الرَّجُلُ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏ رُدُّوهُ عَلَىَّ ‏"‏ فَالْتُمِسَ فَلَمْ يَجِدُوهُ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏ هَذَا جِبْرِيلُ أَرَادَ أَنْ تَعَلَّمُوا إِذْ لَمْ تَسْأَلُوا ‏"‏ ‏.‏', 'سلوني ‏"‏ فهابوه ان يسالوه ‏.‏ فجاء رجل فجلس عند ركبتيه ‏.‏ فقال يا رسول الله ما الاسلام قال ‏"‏ لا تشرك بالله شيئا وتقيم الصلاه وتؤتي الزكاه وتصوم رمضان ‏"‏ ‏.‏ قال صدقت ‏.‏ قال يا رسول الله ما الايمان قال ‏"‏ ان تؤمن بالله وملائكته وكتابه ولقائه ورسله وتؤمن بالبعث وتؤمن بالقدر كله ‏"‏ ‏.‏ قال صدقت ‏.‏ قال يا رسول الله ما الاحسان قال ‏"‏ ان تخشي الله كانك تراه فانك ان لا تكن تراه فانه يراك ‏"‏ ‏.‏ قال صدقت ‏.‏ قال يا رسول الله متي تقوم الساعه قال ‏"‏ ما المسئول عنها باعلم من السائل وساحدثك عن اشراطها اذا رايت المراه تلد ربها فذاك من اشراطها واذا رايت الحفاه العراه الصم البكم ملوك الارض فذاك من اشراطها واذا رايت رعاء البهم يتطاولون في البنيان فذاك من اشراطها في خمس من الغيب لا يعلمهن الا الله ‏"‏ ‏.‏ ثم قرا ‏{‏ ان الله عنده علم الساعه وينزل الغيث ويعلم ما في الارحام وما تدري نفس ماذا تكسب غدا وما تدري نفس باي ارض تموت ان الله عليم خبير‏}‏ قال ثم قام الرجل فقال رسول الله صلي الله عليه وسلم ‏"‏ ردوه علي ‏"‏ فالتمس فلم يجدوه فقال رسول الله صلي الله عليه وسلم ‏"‏ هذا جبريل اراد ان تعلموا اذ لم تسالوا ‏"‏ ‏.‏', 'It is narrated on the authority of Abu Huraira that the Messenger of Allah (ﷺ) said:Ask me (about religious matters), but they (the Companions) were in awe of asking him. Then came a man, and sat near his knees and said: O Messenger of Allah, what is al-Islam? So he (the Holy Prophet) replied: [That] you do not associate anything with Allah, and establish the prayer, pay the alms (Zakat) and fast Ramadan. He said: You (have) told the truth. He said: Messenger of Allah, what is al-Iman (Faith)? He said: That you affirm your faith in Allah, His angels, His Books, His meeting, His Apostles, and that you believe in Resurrection and that you believe in Qadr (Divine Decree) in all its entirety. He (the inquirer) said: You have told the truth. He said: Messenger of Allah, what is al-Ihsan? Upon this he said: that you fear Allah as if you are seeing Him, and though you see Him not, verily He is seeing you. He (the inquirer) said: You (have) told the truth. He (the inquirer) said: When will the Hour (of Doom) occur? He said: The one who is being asked about it is no better informed than the inquirer and I will narrate some of its signs to you. When you see a [slave] woman giving birth to her master - then that is [one] of its signs. And when you see barefooted, naked, deaf and dumb (ignorant and foolish persons) as the rulers of the earth - then that is [one] of its signs. And when you see the shepherds of black (camels) exult in buildings - then that is [one] of its signs. The (Hour) is one of the five things of the unseen. No one knows them except Allah. Then (the Holy Prophet) recited (the folowing verse):" Verily Allah! with Him alone is the knowledge of the Hour and He it is Who sends down the rain and knows that which is in the wombs. And no soul knows what it shall earn on the morrow and a soul knows not in what land it shall die. Verily Allah is Knowing, Aware." He (Abu Huraira) said: Then the person stood up (and made his way). Then the Messenger of Allah (ﷺ) said: Bring him back to me. He was searched for, but they could not find him. The Messenger of Allah (ﷺ) thereupon said: He was Gabriel and he wanted to teach you when you did not ask', NULL, 'f59c9c7f66bce292eb923474b99e5c20c151e2740a47a5f843b36dc0c17f0824', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (66, 'muslim', 100, 100, 'Book 1, Hadith 8', 11, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدِ بْنِ جَمِيلِ بْنِ طَرِيفِ بْنِ عَبْدِ اللَّهِ الثَّقَفِيُّ، عَنْ مَالِكِ بْنِ أَنَسٍ، - فِيمَا قُرِئَ عَلَيْهِ - عَنْ أَبِي سُهَيْلٍ، عَنْ أَبِيهِ، أَنَّهُ سَمِعَ طَلْحَةَ بْنَ عُبَيْدِ اللَّهِ، يَقُولُ جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم مِنْ أَهْلِ نَجْدٍ ثَائِرُ الرَّأْسِ نَسْمَعُ دَوِيَّ صَوْتِهِ وَلاَ نَفْقَهُ مَا يَقُولُ حَتَّى دَنَا مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم فَإِذَا هُوَ يَسْأَلُ عَنِ الإِسْلاَمِ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏', 'خَمْسُ صَلَوَاتٍ فِي الْيَوْمِ وَاللَّيْلَةِ ‏"‏ ‏.‏ فَقَالَ هَلْ عَلَىَّ غَيْرُهُنَّ قَالَ ‏"‏ لاَ ‏.‏ إِلاَّ أَنْ تَطَّوَّعَ وَصِيَامُ شَهْرِ رَمَضَانَ ‏"‏ ‏.‏ فَقَالَ هَلْ عَلَىَّ غَيْرُهُ فَقَالَ ‏"‏ لاَ ‏.‏ إِلاَّ أَنْ تَطَّوَّعَ ‏"‏ ‏.‏ وَذَكَرَ لَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم الزَّكَاةَ فَقَالَ هَلْ عَلَىَّ غَيْرُهَا قَالَ ‏"‏ لاَ ‏.‏ إِلاَّ أَنْ تَطَّوَّعَ ‏"‏ قَالَ فَأَدْبَرَ الرَّجُلُ وَهُوَ يَقُولُ وَاللَّهِ لاَ أَزِيدُ عَلَى هَذَا وَلاَ أَنْقُصُ مِنْهُ ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏ أَفْلَحَ إِنْ صَدَقَ ‏"‏ ‏.‏', 'خمس صلوات في اليوم والليله ‏"‏ ‏.‏ فقال هل علي غيرهن قال ‏"‏ لا ‏.‏ الا ان تطوع وصيام شهر رمضان ‏"‏ ‏.‏ فقال هل علي غيره فقال ‏"‏ لا ‏.‏ الا ان تطوع ‏"‏ ‏.‏ وذكر له رسول الله صلي الله عليه وسلم الزكاه فقال هل علي غيرها قال ‏"‏ لا ‏.‏ الا ان تطوع ‏"‏ قال فادبر الرجل وهو يقول والله لا ازيد علي هذا ولا انقص منه ‏.‏ فقال رسول الله صلي الله عليه وسلم ‏"‏ افلح ان صدق ‏"‏ ‏.‏', 'It is reported on the authority of Talha b. ''Ubaidullah that a person with dishevelled hair, one of the people of Nejd, came to the Messenger of Allah (ﷺ). We heard the humming of his voice but could not fully discern what he had been saying, till he came nigh to the Messenger of Allah (ﷺ). It was then (disclosed to us) that he was asking questions pertaining to Islam. The Messenger of Allah (ﷺ) said:Five prayers during the day and the night. (Upon this he said: Am I obliged to say any other (prayer) besides these? He (the Holy Prophet, ) said: No, but whatever you observe voluntarily, out of your own free will, and the fasts of Ramadan. The inquirer said: Am I obliged to do anything else besides this? He (the Holy Prophet) said: No, but whatever you do out of your own free will. And the Messenger of Allah told him about the Zakat (poor-rate). The inquirer said: Am I obliged to pay anything else besides this? He (the Holy Prophet) said: No, but whatever you pay voluntarily out of your own free will. The man turned back and was saying: I would neither make any addition to this, nor will decrease anything out of it. The Prophet remarked: He is successful, if he is true to what he affirms', NULL, 'df59b77bc04504e95c9d3e862632f23b836c7dbb9f52f6fa92378d153289b989', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (67, 'muslim', 100, 101, 'Book 1, Hadith 9', 11, NULL, NULL, 'حَدَّثَنِي يَحْيَى بْنُ أَيُّوبَ، وَقُتَيْبَةُ بْنُ سَعِيدٍ، جَمِيعًا عَنْ إِسْمَاعِيلَ بْنِ جَعْفَرٍ، عَنْ أَبِي سُهَيْلٍ، عَنْ أَبِيهِ، عَنْ طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِهَذَا الْحَدِيثِ نَحْوَ حَدِيثِ مَالِكٍ غَيْرَ أَنَّهُ قَالَ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏', 'أَفْلَحَ وَأَبِيهِ إِنْ صَدَقَ ‏"‏ ‏.‏ أَوْ ‏"‏ دَخَلَ الْجَنَّةَ وَأَبِيهِ إِنْ صَدَقَ ‏"‏ ‏.‏', 'افلح وابيه ان صدق ‏"‏ ‏.‏ او ‏"‏ دخل الجنه وابيه ان صدق ‏"‏ ‏.‏', 'Another hadith, the like of which has been narrated by Malik (b. Anas) (and mentioned above) is also reported by Talha b. ''Ubaidullah, with the only variation that the Prophet remarked:By his father, he shall succeed if he were true (to what he professed), or: By his father, he would enter heaven if he were true (to what he professed)', NULL, '268c229498bead8e5d26b8cea7fbabdf02d2b57de48c849eaafc7ed54e1c2ad6', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (68, 'muslim', 100, 102, 'Book 1, Hadith 10', 12, NULL, NULL, NULL, 'حَدَّثَنِي عَمْرُو بْنُ مُحَمَّدِ بْنِ بُكَيْرٍ النَّاقِدُ، حَدَّثَنَا هَاشِمُ بْنُ الْقَاسِمِ أَبُو النَّضْرِ، حَدَّثَنَا سُلَيْمَانُ بْنُ الْمُغِيرَةِ، عَنْ ثَابِتٍ، عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ نُهِينَا أَنْ نَسْأَلَ، رَسُولَ اللَّهِ صلى الله عليه وسلم عَنْ شَىْءٍ فَكَانَ يُعْجِبُنَا أَنْ يَجِيءَ الرَّجُلُ مِنْ أَهْلِ الْبَادِيَةِ الْعَاقِلُ فَيَسْأَلَهُ وَنَحْنُ نَسْمَعُ فَجَاءَ رَجُلٌ مِنْ أَهْلِ الْبَادِيَةِ فَقَالَ يَا مُحَمَّدُ أَتَانَا رَسُولُكَ فَزَعَمَ لَنَا أَنَّكَ تَزْعُمُ أَنَّ اللَّهَ أَرْسَلَكَ قَالَ ‏"‏ صَدَقَ ‏"‏ ‏.‏ قَالَ فَمَنْ خَلَقَ السَّمَاءَ قَالَ ‏"‏ اللَّهُ ‏"‏ ‏.‏ قَالَ فَمَنْ خَلَقَ الأَرْضَ قَالَ ‏"‏ اللَّهُ ‏"‏ ‏.‏ قَالَ فَمَنْ نَصَبَ هَذِهِ الْجِبَالَ وَجَعَلَ فِيهَا مَا جَعَلَ ‏.‏ قَالَ ‏"‏ اللَّهُ ‏"‏ ‏.‏ قَالَ فَبِالَّذِي خَلَقَ السَّمَاءَ وَخَلَقَ الأَرْضَ وَنَصَبَ هَذِهِ الْجِبَالَ آللَّهُ أَرْسَلَكَ قَالَ ‏"‏ نَعَمْ ‏"‏ ‏.‏ قَالَ وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا خَمْسَ صَلَوَاتٍ فِي يَوْمِنَا وَلَيْلَتِنَا ‏.‏ قَالَ ‏"‏ صَدَقَ ‏"‏ ‏.‏ قَالَ فَبِالَّذِي أَرْسَلَكَ آللَّهُ أَمْرَكَ بِهَذَا قَالَ ‏"‏ نَعَمْ ‏"‏ ‏.‏ قَالَ وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا زَكَاةً فِي أَمْوَالِنَا ‏.‏ قَالَ ‏"‏ صَدَقَ ‏"‏ ‏.‏ قَالَ فَبِالَّذِي أَرْسَلَكَ آللَّهُ أَمْرَكَ بِهَذَا قَالَ ‏"‏ نَعَمْ ‏"‏ ‏.‏ قَالَ وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا صَوْمَ شَهْرِ رَمَضَانَ فِي سَنَتِنَا ‏.‏ قَالَ ‏"‏ صَدَقَ ‏"‏ ‏.‏ قَالَ فَبِالَّذِي أَرْسَلَكَ آللَّهُ أَمَرَكَ بِهَذَا قَالَ ‏"‏ نَعَمْ ‏"‏ ‏.‏ قَالَ وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا حَجَّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلاً ‏.‏ قَالَ ‏"‏ صَدَقَ ‏"‏ ‏.‏ قَالَ ثُمَّ وَلَّى ‏.‏ قَالَ وَالَّذِي بَعَثَكَ بِالْحَقِّ لاَ أَزِيدُ عَلَيْهِنَّ وَلاَ أَنْقُصُ مِنْهُنَّ ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏"‏ لَئِنْ صَدَقَ لَيَدْخُلَنَّ الْجَنَّةَ ‏"‏ ‏.‏', 'حدثني عمرو بن محمد بن بكير الناقد، حدثنا هاشم بن القاسم ابو النضر، حدثنا سليمان بن المغيره، عن ثابت، عن انس بن مالك، قال نهينا ان نسال، رسول الله صلي الله عليه وسلم عن شيء فكان يعجبنا ان يجيء الرجل من اهل الباديه العاقل فيساله ونحن نسمع فجاء رجل من اهل الباديه فقال يا محمد اتانا رسولك فزعم لنا انك تزعم ان الله ارسلك قال ‏"‏ صدق ‏"‏ ‏.‏ قال فمن خلق السماء قال ‏"‏ الله ‏"‏ ‏.‏ قال فمن خلق الارض قال ‏"‏ الله ‏"‏ ‏.‏ قال فمن نصب هذه الجبال وجعل فيها ما جعل ‏.‏ قال ‏"‏ الله ‏"‏ ‏.‏ قال فبالذي خلق السماء وخلق الارض ونصب هذه الجبال الله ارسلك قال ‏"‏ نعم ‏"‏ ‏.‏ قال وزعم رسولك ان علينا خمس صلوات في يومنا وليلتنا ‏.‏ قال ‏"‏ صدق ‏"‏ ‏.‏ قال فبالذي ارسلك الله امرك بهذا قال ‏"‏ نعم ‏"‏ ‏.‏ قال وزعم رسولك ان علينا زكاه في اموالنا ‏.‏ قال ‏"‏ صدق ‏"‏ ‏.‏ قال فبالذي ارسلك الله امرك بهذا قال ‏"‏ نعم ‏"‏ ‏.‏ قال وزعم رسولك ان علينا صوم شهر رمضان في سنتنا ‏.‏ قال ‏"‏ صدق ‏"‏ ‏.‏ قال فبالذي ارسلك الله امرك بهذا قال ‏"‏ نعم ‏"‏ ‏.‏ قال وزعم رسولك ان علينا حج البيت من استطاع اليه سبيلا ‏.‏ قال ‏"‏ صدق ‏"‏ ‏.‏ قال ثم ولي ‏.‏ قال والذي بعثك بالحق لا ازيد عليهن ولا انقص منهن ‏.‏ فقال النبي صلي الله عليه وسلم ‏"‏ لئن صدق ليدخلن الجنه ‏"‏ ‏.‏', 'It is reported on the authority of Anas b. Malik that he said:We were forbidden that we should ask anything (without the genuine need) from the Holy Prophet. It, therefore, pleased us that an intelligent person from the dwellers of the desert should come and asked him (the Holy Prophet) and we should listen to it. A man from the dwellers of the desert came (to the Holy Prophet) and said: Muhammad, your messenger came to us and told us your assertion that verily Allah had sent you (as a prophet). He (the Holy Prophet) remarked: He told the truth. He (the bedouin) said: Who created the heaven? He (the Holy Prophet) replied: Allah. He (the bedouin again) said: Who created the earth? He (the Holy Prophet) replied: Allah. He (the bedouin again) said: Who raised these mountains and who created in them whatever is created there? He (the Holy Prophet) replied: Allah. Upon this he (the bedouin) remarked: By Him Who created the heaven and created the earth and raised mountains thereupon, has Allah (in fact) sent you? He (the Holy Prophet) said: Yes. He (the bedouin) said: Your messenger also told us that five prayers (had been made) obligatory for us during the day and the night. He (the Holy Prophet) remarked: He told you the truth. He (the bedouin) said: By Him Who sent you, is it Allah Who ordered you about this (i. e. prayers)? He (the Holy Prophet) said: Yes. He (the bedouin) said: Your messenger told us that Zakat had been made obligatory in our riches. He (the Holy Prophet) said. He has told the truth. He (the bedouin) said: By Him Who sent you (as a prophet), is it Allah Who ordered you about it (Zakat)? He (the Holy Prophet) said: Yes. He (the bedouin) said: Your messenger told us that it had been made obligatory for us to fast every year during the month of Ramadan. He (the Holy Prophet) said: He has told the truth. He (the bedouin) said: By Him Who sent you (as a prophet), is it Allah Who ordered you about it (the fasts of Ramadan)? He (the Holy Prophet) said: Yes. He (the bedouin) said: Your messenger also told us that pilgrimage (Hajj) to the House (of Ka''bah) had been made obligatory for him who is able to undertake the journey to it. He (the Holy Prophet) said: Yes. The narrator said that he (the bedouin) set off (at the conclusion of this answer, but at the time of his departure) remarked: ''By Him Who sent you with the Truth, I would neither make any addition to them nor would I diminish anything out of them. Upon this the Prophet remarked: If he were true (to what he said) he must enter Paradise', NULL, 'fa0eec045efe1c8c7d88a6e082e709e39db8d6dd7f7f12b48df6182175a22304', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (69, 'muslim', 100, 103, 'Book 1, Hadith 11', 12, NULL, NULL, NULL, 'حَدَّثَنِي عَبْدُ اللَّهِ بْنُ هَاشِمٍ الْعَبْدِيُّ، حَدَّثَنَا بَهْزٌ، حَدَّثَنَا سُلَيْمَانُ بْنُ الْمُغِيرَةِ، عَنْ ثَابِتٍ، قَالَ قَالَ أَنَسٌ كُنَّا نُهِينَا فِي الْقُرْآنِ أَنْ نَسْأَلَ رَسُولَ اللَّهِ صلى الله عليه وسلم عَنْ شَىْءٍ ‏.‏ وَسَاقَ الْحَدِيثَ بِمِثْلِهِ ‏.‏', 'حدثني عبد الله بن هاشم العبدي، حدثنا بهز، حدثنا سليمان بن المغيره، عن ثابت، قال قال انس كنا نهينا في القران ان نسال رسول الله صلي الله عليه وسلم عن شيء ‏.‏ وساق الحديث بمثله ‏.‏', 'It is narrated on the authority of Thabit that Anas said:We were forbidden in the Holy Qur''an that we should ask about anything from the Messenger of Allah (ﷺ) and then Anas reported the hadith in similar words', NULL, '76954a9c2976862c3ab120321e624d2215cd945842786eeb034c904fdd653ce6', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (70, 'muslim', 100, 104, 'Book 1, Hadith 12', 13, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا عَمْرُو بْنُ عُثْمَانَ، حَدَّثَنَا مُوسَى بْنُ طَلْحَةَ، قَالَ حَدَّثَنِي أَبُو أَيُّوبَ، أَنَّ أَعْرَابِيًّا، عَرَضَ لِرَسُولِ اللَّهِ صلى الله عليه وسلم وَهُوَ فِي سَفَرٍ', '. فَأَخَذَ بِخِطَامِ نَاقَتِهِ أَوْ بِزِمَامِهَا ثُمَّ قَالَ يَا رَسُولَ اللَّهِ - أَوْ يَا مُحَمَّدُ - أَخْبِرْنِي بِمَا يُقَرِّبُنِي مِنَ الْجَنَّةِ وَمَا يُبَاعِدُنِي مِنَ النَّارِ . قَالَ فَكَفَّ النَّبِيُّ صلى الله عليه وسلم ثُمَّ نَظَرَ فِي أَصْحَابِهِ ثُمَّ قَالَ  لَقَدْ وُفِّقَ - أَوْ لَقَدْ هُدِيَ - قَالَ كَيْفَ قُلْتَ  . قَالَ فَأَعَادَ . فَقَالَ النَّبِيُّ صلى الله عليه وسلم  تَعْبُدُ اللَّهَ لاَ تُشْرِكُ بِهِ شَيْئًا وَتُقِيمُ الصَّلاَةَ وَتُؤْتِي الزَّكَاةَ وَتَصِلُ الرَّحِمَ دَعِ النَّاقَةَ  .', '. فاخذ بخطام ناقته او بزمامها ثم قال يا رسول الله - او يا محمد - اخبرني بما يقربني من الجنه وما يباعدني من النار . قال فكف النبي صلي الله عليه وسلم ثم نظر في اصحابه ثم قال لقد وفق - او لقد هدي - قال كيف قلت . قال فاعاد . فقال النبي صلي الله عليه وسلم تعبد الله لا تشرك به شيئا وتقيم الصلاه وتؤتي الزكاه وتصل الرحم دع الناقه .', 'It is narrated on the authority of Abu Ayyub Ansari that once during the journey of the Prophet (may peace of Allah be upon him) a bedouin appeared before him and caught hold of the nosestring of his she-camel and then said, Messenger of Allah (or Muhammad), inform me about that which takes me near to Paradise and draws me away from the Fire (of Hell). He (the narrator) said:The Prophet (ﷺ) stopped for a while and cast a glance upon his companions and then said: He was afforded a good opportunity (or he had been guided well). He (the Holy Prophet) addressing the bedouin said: (Repeat) whatever you have uttered. He (the bedouin) repeated that. Upon this the Apostle (ﷺ) remarked: The deed which can draw you near to Paradise and take you away from Hell is, that you worship Allah and associate none with Him, and you establish prayer and pay Zakat, and do good to your kin. After having uttered these words, the Prophet asked the bedouin to release the nosestring of his she-camel', NULL, '2db52b146351f1140794a1878c223627d3888bbe64025f42f789869e71d53c8c', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (71, 'muslim', 100, 105, 'Book 1, Hadith 13', 13, NULL, NULL, 'وَحَدَّثَنِي مُحَمَّدُ بْنُ حَاتِمٍ، وَعَبْدُ الرَّحْمَنِ بْنُ بِشْرٍ، قَالاَ حَدَّثَنَا بَهْزٌ، حَدَّثَنَا شُعْبَةُ، حَدَّثَنَا مُحَمَّدُ بْنُ عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ، وَأَبُوهُ، عُثْمَانُ أَنَّهُمَا سَمِعَا مُوسَى بْنَ طَلْحَةَ، يُحَدِّثُ عَنْ أَبِي أَيُّوبَ، عَنِ النَّبِيِّ صلى الله عليه وسلم', 'بِمِثْلِ هَذَا الْحَدِيثِ ‏.‏', 'بمثل هذا الحديث ‏.‏', 'This hadith is transmitted by Muhammad b. Hatim on the authority of Abu Ayyub Ansari', NULL, '2a01eceb18d98603235d020602a57e77c7b2029e226fa72540092a919a2c3ff2', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (72, 'muslim', 100, 106, 'Book 1, Hadith 14', 14, NULL, NULL, 'حَدَّثَنَا يَحْيَى بْنُ يَحْيَى التَّمِيمِيُّ، أَخْبَرَنَا أَبُو الأَحْوَصِ، ح وَحَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو الأَحْوَصِ، عَنْ أَبِي إِسْحَاقَ، عَنْ مُوسَى بْنِ طَلْحَةَ، عَنْ أَبِي أَيُّوبَ، قَالَ جَاءَ رَجُلٌ إِلَى النَّبِيِّ صلى الله عليه وسلم فَقَالَ دُلَّنِي عَلَى عَمَلٍ أَعْمَلُهُ يُدْنِينِي مِنَ الْجَنَّةِ وَيُبَاعِدُنِي مِنَ النَّارِ ‏.‏ قَالَ ‏"‏ تَعْبُدُ اللَّهَ لاَ تُشْرِكُ بِهِ شَيْئًا وَتُقِيمُ الصَّلاَةَ وَتُؤْتِي الزَّكَاةَ وَتَصِلُ ذَا رَحِمِكَ ‏"‏ فَلَمَّا أَدْبَرَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏', 'إِنْ تَمَسَّكَ بِمَا أُمِرَ بِهِ دَخَلَ الْجَنَّةَ ‏"‏ ‏.‏ وَفِي رِوَايَةِ ابْنِ أَبِي شَيْبَةَ ‏"‏ إِنْ تَمَسَّكَ بِهِ ‏"‏ ‏.‏', 'ان تمسك بما امر به دخل الجنه ‏"‏ ‏.‏ وفي روايه ابن ابي شيبه ‏"‏ ان تمسك به ‏"‏ ‏.‏', 'It is narrated on the authority of Abu Ayyub that a man came to the Prophet (ﷺ) and said:Direct me to a deed which draws me near to Paradise and takes me away from the Fire (of Hell). Upon this he (the Holy Prophet) said: You worship Allah and never associate anything with Him, establish prayer, and pay Zakat, and do good to your kin. When he turned his back, the Messenger of Allah (ﷺ) remarked: If he adheres to what he has been ordered to do, he would enter Paradise', NULL, 'fed4338e0455d8a0ddceb1d9d4edffc251700890fd60859481b059a6e9abe0c9', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (73, 'muslim', 100, 107, 'Book 1, Hadith 15', 14, NULL, NULL, 'وَحَدَّثَنِي أَبُو بَكْرِ بْنُ إِسْحَاقَ، حَدَّثَنَا عَفَّانُ، حَدَّثَنَا وُهَيْبٌ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، عَنْ أَبِي زُرْعَةَ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ أَعْرَابِيًّا، جَاءَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ', 'يَا رَسُولَ اللَّهِ دُلَّنِي عَلَى عَمَلٍ إِذَا عَمِلْتُهُ دَخَلْتُ الْجَنَّةَ ‏.‏ قَالَ ‏"‏ تَعْبُدُ اللَّهَ لاَ تُشْرِكُ بِهِ شَيْئًا وَتُقِيمُ الصَّلاَةَ الْمَكْتُوبَةَ وَتُؤَدِّي الزَّكَاةَ الْمَفْرُوضَةَ وَتَصُومُ رَمَضَانَ ‏"‏ ‏.‏ قَالَ وَالَّذِي نَفْسِي بِيَدِهِ لاَ أَزِيدُ عَلَى هَذَا شَيْئًا أَبَدًا وَلاَ أَنْقُصُ مِنْهُ ‏.‏ فَلَمَّا وَلَّى قَالَ النَّبِيُّ صلى الله عليه وسلم ‏"‏ مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى رَجُلٍ مِنْ أَهْلِ الْجَنَّةِ فَلْيَنْظُرْ إِلَى هَذَا ‏"‏ ‏.‏', 'يا رسول الله دلني علي عمل اذا عملته دخلت الجنه ‏.‏ قال ‏"‏ تعبد الله لا تشرك به شيئا وتقيم الصلاه المكتوبه وتؤدي الزكاه المفروضه وتصوم رمضان ‏"‏ ‏.‏ قال والذي نفسي بيده لا ازيد علي هذا شيئا ابدا ولا انقص منه ‏.‏ فلما ولي قال النبي صلي الله عليه وسلم ‏"‏ من سره ان ينظر الي رجل من اهل الجنه فلينظر الي هذا ‏"‏ ‏.‏', 'It is reported on the authority of Abu Huraira that a bedouin came to the Messenger of Allah (ﷺ) and said:Messenger of Allah, direct me to a deed by which I may be entitled to enter Paradise. Upon this he (the Holy Prophet) remarked: You worship Allah and never associate anything with Him, establish the obligatory prayer, and pay the Zakat which is incumbent upon you, and observe the fast of Ramadan. He (the bedouin) said: By Him in Whose hand is my life, I will never add anything to it, nor will I diminish anything from it. When he (the bedouin) turned his back, the Prophet (ﷺ) said: He who is pleased to see a man from the dwellers of Paradise should catch a glimpse of him', NULL, '0179ba1728df9b95c6afa25c5a7db88bb34486def2c33dcbe2a7972bb5afb0d6', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (74, 'muslim', 100, 108, 'Book 1, Hadith 16', 15, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَأَبُو كُرَيْبٍ - وَاللَّفْظُ لأَبِي كُرَيْبٍ - قَالاَ حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ أَبِي سُفْيَانَ، عَنْ جَابِرٍ، قَالَ أَتَى النَّبِيَّ صلى الله عليه وسلم النُّعْمَانُ بْنُ قَوْقَلٍ فَقَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ إِذَا صَلَّيْتُ الْمَكْتُوبَةَ وَحَرَّمْتُ الْحَرَامَ وَأَحْلَلْتُ الْحَلاَلَ أَأَدْخُلُ الْجَنَّةَ فَقَالَ النَّبِيُّ صلى الله عليه وسلم', 'نَعَمْ  .', 'نعم .', 'It is narrated on the authority of Jabir that Nu''man b. Qaufal came to the Prophet (ﷺ) and said:Would I enter Paradise if I say the obligatory prayers and deny myself that which is forbidden and treat that as lawful what has been made permissible (by the Shari''ah)? The Prophet (ﷺ) replied in the affirmative', NULL, 'cc80d0e187463ee7ec6bed584771ab7f7002c9d6aca15ad1bc52a27a1758fe03', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (75, 'muslim', 100, 109, 'Book 1, Hadith 17', 15, NULL, NULL, NULL, 'وَحَدَّثَنِي حَجَّاجُ بْنُ الشَّاعِرِ، وَالْقَاسِمُ بْنُ زَكَرِيَّاءَ، قَالاَ حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُوسَى، عَنْ شَيْبَانَ، عَنِ الأَعْمَشِ، عَنْ أَبِي صَالِحٍ، وَأَبِي، سُفْيَانَ عَنْ جَابِرٍ، قَالَ قَالَ النُّعْمَانُ بْنُ قَوْقَلٍ يَا رَسُولَ اللَّهِ ‏.‏ بِمِثْلِهِ ‏.‏ وَزَادَ فِيهِ وَلَمْ أَزِدْ عَلَى ذَلِكَ شَيْئًا ‏.‏', 'وحدثني حجاج بن الشاعر، والقاسم بن زكرياء، قالا حدثنا عبيد الله بن موسي، عن شيبان، عن الاعمش، عن ابي صالح، وابي، سفيان عن جابر، قال قال النعمان بن قوقل يا رسول الله ‏.‏ بمثله ‏.‏ وزاد فيه ولم ازد علي ذلك شيئا ‏.‏', 'A similar hadith is narrated on Jabir''s authority in which the following words are added:I will do nothing more', NULL, '4f49f444ca9926c6027e8081debed5387f77a47f81201686bc77e36dd7ba8def', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (76, 'muslim', 100, 110, 'Book 1, Hadith 18', 15, NULL, NULL, 'وَحَدَّثَنِي سَلَمَةُ بْنُ شَبِيبٍ، حَدَّثَنَا الْحَسَنُ بْنُ أَعْيَنَ، حَدَّثَنَا مَعْقِلٌ، - وَهُوَ ابْنُ عُبَيْدِ اللَّهِ - عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرٍ، أَنَّ رَجُلاً، سَأَلَ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقَالَ', 'أَرَأَيْتَ إِذَا صَلَّيْتُ الصَّلَوَاتِ الْمَكْتُوبَاتِ وَصُمْتُ رَمَضَانَ وَأَحْلَلْتُ الْحَلاَلَ وَحََّمْتُ الْحَرَامَ وَلَمْ أَزِدْ عَلَى ذَلِكَ شَيْئًا أَأَدْخُلُ الْجَنَّةَ قَالَ ‏ "‏ نَعَمْ ‏"‏ ‏.‏ قَالَ وَاللَّهِ لاَ أَزِيدُ عَلَى ذَلِكَ شَيْئًا ‏.‏', 'ارايت اذا صليت الصلوات المكتوبات وصمت رمضان واحللت الحلال وحمت الحرام ولم ازد علي ذلك شيئا اادخل الجنه قال ‏ "‏ نعم ‏"‏ ‏.‏ قال والله لا ازيد علي ذلك شيئا ‏.‏', 'It is narrated on the authority of Jabir that a man once said to the Messenger of Allah (ﷺ):Shall I enter Paradise in case I say the obligatory prayers, observe the (fasts) of Ramadan and treat that as lawful which has been made permissible (by the Shari''ah) and deny myself that what is forbidden, and make no addition to it? He (the Holy Prophet) replied in the affirmative. He (the inquirer) said: By Allah, I would add nothing to it', NULL, 'bf7b306aff84e5811b7bf09cdf5529e8249c1aa4d177c1344ca9af55b5d20f60', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (77, 'muslim', 100, 111, 'Book 1, Hadith 19', 16, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ الْهَمْدَانِيُّ، حَدَّثَنَا أَبُو خَالِدٍ، - يَعْنِي سُلَيْمَانَ بْنَ حَيَّانَ الأَحْمَرَ - عَنْ أَبِي مَالِكٍ الأَشْجَعِيِّ، عَنْ سَعْدِ بْنِ عُبَيْدَةَ، عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ بُنِيَ الإِسْلاَمُ عَلَى خَمْسَةٍ عَلَى أَنْ يُوَحَّدَ اللَّهُ وَإِقَامِ الصَّلاَةِ وَإِيتَاءِ الزَّكَاةِ وَصِيَامِ رَمَضَانَ وَالْحَجِّ ‏"‏ ‏.‏ فَقَالَ رَجُلٌ الْحَجِّ وَصِيَامِ رَمَضَانَ قَالَ لاَ ‏.‏ صِيَامِ رَمَضَانَ وَالْحَجِّ ‏.‏ هَكَذَا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم ‏.‏', '"‏ بني الاسلام علي خمسه علي ان يوحد الله واقام الصلاه وايتاء الزكاه وصيام رمضان والحج ‏"‏ ‏.‏ فقال رجل الحج وصيام رمضان قال لا ‏.‏ صيام رمضان والحج ‏.‏ هكذا سمعته من رسول الله صلي الله عليه وسلم ‏.‏', 'It is narrated on the authority of (''Abdullah) son of Umar (may Allah be pleased with them) that the Prophet (may peace of Allah be upon him) said:(The superstructure of) al-Islam is raised on five (pillars), i. e. the oneness of Allah, the establishment of prayer, payment of Zakat, the, fast of Ramadan, Pilgrimage (to Mecca). A person said (to ''Abdullah b. Umar the narrator): Which of the two precedes the other-Pilgrimage or the fasts of Rarnadan? Upon this he (the narrator) replied: No (it is not the Pilgrimage first) but the fasts of Ramadan precede the Pilgrimage', NULL, '8537e1592ea5c54c17017686fe47953fca249103e9721d793e0cd1138bc0c2f3', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (78, 'muslim', 100, 112, 'Book 1, Hadith 20', 16, NULL, NULL, 'وَحَدَّثَنَا سَهْلُ بْنُ عُثْمَانَ الْعَسْكَرِيُّ، حَدَّثَنَا يَحْيَى بْنُ زَكَرِيَّاءَ، حَدَّثَنَا سَعْدُ بْنُ طَارِقٍ، قَالَ حَدَّثَنِي سَعْدُ بْنُ عُبَيْدَةَ السُّلَمِيُّ، عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ عَلَى أَنْ يُعْبَدَ اللَّهُ وَيُكْفَرَ بِمَا دُونَهُ وَإِقَامِ الصَّلاَةِ وَإِيتَاءِ الزَّكَاةِ وَحَجِّ الْبَيْتِ وَصَوْمِ رَمَضَانَ ‏"‏ ‏.‏', '"‏ بني الاسلام علي خمس علي ان يعبد الله ويكفر بما دونه واقام الصلاه وايتاء الزكاه وحج البيت وصوم رمضان ‏"‏ ‏.‏', 'It is narrated on the authority of (''Abdullah) son of ''Umar, that the Prophet (may peace of Allah be upon him) said:(The superstructure of) al-Islam is raised on five (pillars), i. e. Allah (alone) should be worshipped, and (all other gods) beside Him should be (categorically) denied. Establishment of prayer, the payment of Zakat, Pilgrimage to the House, and the fast of Ramadan (are the other obligatory acts besides the belief in the oneness of Allah and denial of all other gods)', NULL, '058bc21f0a6a65833b40feff67e0b3215f5c5b792d436a523ac855297e136041', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (79, 'muslim', 100, 113, 'Book 1, Hadith 21', 16, NULL, NULL, 'حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا عَاصِمٌ، - وَهُوَ ابْنُ مُحَمَّدِ بْنِ زَيْدِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ - عَنْ أَبِيهِ، قَالَ قَالَ عَبْدُ اللَّهِ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ وَإِقَامِ الصَّلاَةِ وَإِيتَاءِ الزَّكَاةِ وَحَجِّ الْبَيْتِ وَصَوْمِ رَمَضَانَ ‏"‏ ‏.‏', '"‏ بني الاسلام علي خمس شهاده ان لا اله الا الله وان محمدا عبده ورسوله واقام الصلاه وايتاء الزكاه وحج البيت وصوم رمضان ‏"‏ ‏.‏', 'It is narrated on the authority of ''Abdullah son of ''Umar that the Messenger of Allah (ﷺ) said:(The superstructure of) al-Islam is raised on five (pillars), testifying (the fact) that there is no god but Allah, that Muhammad is His bondsman and messenger, and the establishment of prayer, payment of Zakat, Pilgrimage to the House (Ka''ba) and the fast of Ramadan', NULL, '0337462d5dffe3dd21c679207d64a7a75688ad3aca718aad2009e1ba4fcf1450', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (80, 'muslim', 100, 114, 'Book 1, Hadith 22', 16, NULL, NULL, 'وَحَدَّثَنِي ابْنُ نُمَيْرٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا حَنْظَلَةُ، قَالَ سَمِعْتُ عِكْرِمَةَ بْنَ خَالِدٍ، يُحَدِّثُ طَاوُسًا أَنَّ رَجُلاً، قَالَ لِعَبْدِ اللَّهِ بْنِ عُمَرَ أَلاَ تَغْزُو فَقَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏', '"‏ إِنَّ الإِسْلاَمَ بُنِيَ عَلَى خَمْسٍ شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَإِقَامِ الصَّلاَةِ وَإِيتَاءِ الزَّكَاةِ وَصِيَامِ رَمَضَانَ وَحَجِّ الْبَيْتِ ‏"‏ ‏.‏', '"‏ ان الاسلام بني علي خمس شهاده ان لا اله الا الله واقام الصلاه وايتاء الزكاه وصيام رمضان وحج البيت ‏"‏ ‏.‏', 'It is reported on the authority of Ta''us that a man said to ''Abdullah son of ''Umar (may Allah be pleased with him). Why don''t you carry out a military expedition? Upon which he replied:I heard the messenger of Allah (ﷺ) say: Verily, al-Islam is founded on five (pillars): testifying the fact that there is no god but Allah, establishment of prayer, payment of Zakat, fast of Ramadan and Pilgrimage to the House', NULL, '98f09a5cd09c37a5fe67f71602848b321d4265c7eedf333d6508a8ee41c27414', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (81, 'muslim', 100, 115, 'Book 1, Hadith 23', 17, NULL, NULL, 'حَدَّثَنَا خَلَفُ بْنُ هِشَامٍ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ أَبِي جَمْرَةَ، قَالَ سَمِعْتُ ابْنَ عَبَّاسٍ، ح وَحَدَّثَنَا يَحْيَى بْنُ يَحْيَى، - وَاللَّفْظُ لَهُ - أَخْبَرَنَا عَبَّادُ بْنُ عَبَّادٍ، عَنْ أَبِي جَمْرَةَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ قَدِمَ وَفْدُ عَبْدِ الْقَيْسِ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّا هَذَا الْحَىَّ مِنْ رَبِيعَةَ وَقَدْ حَالَتْ بَيْنَنَا وَبَيْنَكَ كُفَّارُ مُضَرَ فَلاَ نَخْلُصُ إِلَيْكَ إِلاَّ فِي شَهْرِ الْحَرَامِ فَمُرْنَا بِأَمْرٍ نَعْمَلُ بِهِ وَنَدْعُو إِلَيْهِ مَنْ وَرَاءَنَا', '. قَالَ  آمُرُكُمْ بِأَرْبَعٍ وَأَنْهَاكُمْ عَنْ أَرْبَعٍ الإِيمَانِ بِاللَّهِ - ثُمَّ فَسَّرَهَا لَهُمْ فَقَالَ - شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ وَإِقَامِ الصَّلاَةِ وَإِيتَاءِ الزَّكَاةِ وَأَنْ تُؤَدُّوا خُمُسَ مَا غَنِمْتُمْ وَأَنْهَاكُمْ عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالنَّقِيرِ وَالْمُقَيَّرِ  . زَادَ خَلَفٌ فِي رِوَايَتِهِ  شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ  . وَعَقَدَ وَاحِدَةً .', '. قال امركم باربع وانهاكم عن اربع الايمان بالله - ثم فسرها لهم فقال - شهاده ان لا اله الا الله وان محمدا رسول الله واقام الصلاه وايتاء الزكاه وان تؤدوا خمس ما غنمتم وانهاكم عن الدباء والحنتم والنقير والمقير . زاد خلف في روايته شهاده ان لا اله الا الله . وعقد واحده .', 'It is narrated on the authority of Ibn ''Abbas that a delegation of Abdul Qais came to the Messenger of Allah (ﷺ) and said:Messenger of Allah, verily ours is a tribe of Rabi''a and there stand between you and us the unbelievers of Mudar and we find no freedom to come to you except in the sacred month. Direct us to an act which we should ourselves perform and invite those who live beside us. Upon this the Prophet remarked: I command you to do four things and prohibit you against four acts. (The four deeds which you are commanded to do are): Faith in Allah, and then he explained it for them and said: Testifying the fact. that there is no god but Allah, that Muhammad is the messenger of Allah, performance of prayer, payment of Zakat, that you pay Khums (one-fifth) of the booty fallen to your lot, and I prohibit you to use round gourd, wine jars, wooden pots or skins for wine. Khalaf b. Hisham has made this addition in his narration: Testifying the fact that there is no god but Allah, and then he with his finger pointed out the oneness of the Lord', NULL, 'e939e046388a03d5b1c1a761497d7de68f24e4cfab803d617b14363589fda2ed', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (82, 'muslim', 100, 116, 'Book 1, Hadith 24', 17, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَمُحَمَّدُ بْنُ الْمُثَنَّى، وَمُحَمَّدُ بْنُ بَشَّارٍ، وَأَلْفَاظُهُمْ، مُتَقَارِبَةٌ - قَالَ أَبُو بَكْرٍ حَدَّثَنَا غُنْدَرٌ، عَنْ شُعْبَةَ، وَقَالَ الآخَرَانِ، حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، حَدَّثَنَا شُعْبَةُ، - عَنْ أَبِي جَمْرَةَ، قَالَ كُنْتُ أُتَرْجِمُ بَيْنَ يَدَىِ ابْنِ عَبَّاسٍ وَبَيْنَ النَّاسِ فَأَتَتْهُ امْرَأَةٌ تَسْأَلُهُ عَنْ نَبِيذِ الْجَرِّ، فَقَالَ إِنَّ وَفْدَ عَبْدِ الْقَيْسِ أَتَوْا رَسُولَ اللَّهِ صلى الله عليه وسلم فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏', 'مَنِ الْوَفْدُ أَوْ مَنِ الْقَوْمُ ‏"‏ ‏.‏ قَالُوا رَبِيعَةُ ‏.‏ قَالَ ‏"‏ مَرْحَبًا بِالْقَوْمِ أَوْ بِالْوَفْدِ غَيْرَ خَزَايَا وَلاَ النَّدَامَى ‏"‏ ‏.‏ قَالَ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّا نَأْتِيكَ مِنْ شُقَّةٍ بَعِيدَةٍ وَإِنَّ بَيْنَنَا وَبَيْنَكَ هَذَا الْحَىَّ مِنْ كُفَّارِ مُضَرَ وَإِنَّا لاَ نَسْتَطِيعُ أَنْ نَأْتِيَكَ إِلاَّ فِي شَهْرِ الْحَرَامِ فَمُرْنَا بِأَمْرٍ فَصْلٍ نُخْبِرْ بِهِ مَنْ وَرَاءَنَا نَدْخُلُ بِهِ الْجَنَّةَ ‏.‏ قَالَ فَأَمَرَهُمْ بِأَرْبَعٍ وَنَهَاهُمْ عَنْ أَرْبَعٍ ‏.‏ قَالَ أَمَرَهُمْ بِالإِيمَانِ بِاللَّهِ وَحْدَهُ ‏.‏ وَقَالَ ‏"‏ هَلْ تَدْرُونَ مَا الإِيمَانُ بِاللَّهِ ‏"‏ ‏.‏ قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ ‏.‏ قَالَ ‏"‏ شَهَادَةُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ وَإِقَامُ الصَّلاَةِ وَإِيتَاءُ الزَّكَاةِ وَصَوْمُ رَمَضَانَ وَأَنْ تُؤَدُّوا خُمُسًا مِنَ الْمَغْنَمِ ‏"‏ ‏.‏ وَنَهَاهُمْ عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالْمُزَفَّتِ ‏.‏ قَالَ شُعْبَةُ وَرُبَّمَا قَالَ النَّقِيرِ ‏.‏ قَالَ شُعْبَةُ وَرُبَّمَا قَالَ الْمُقَيَّرِ ‏.‏ وَقَالَ ‏"‏ احْفَظُوهُ وَأَخْبِرُوا بِهِ مِنْ وَرَائِكُمْ ‏"‏ ‏.‏ وَقَالَ أَبُو بَكْرٍ فِي رِوَايَتِهِ ‏"‏ مَنْ وَرَاءَكُمْ ‏"‏ وَلَيْسَ فِي رِوَايَتِهِ الْمُقَيَّرِ ‏.‏', 'من الوفد او من القوم ‏"‏ ‏.‏ قالوا ربيعه ‏.‏ قال ‏"‏ مرحبا بالقوم او بالوفد غير خزايا ولا الندامي ‏"‏ ‏.‏ قال فقالوا يا رسول الله انا ناتيك من شقه بعيده وان بيننا وبينك هذا الحي من كفار مضر وانا لا نستطيع ان ناتيك الا في شهر الحرام فمرنا بامر فصل نخبر به من وراءنا ندخل به الجنه ‏.‏ قال فامرهم باربع ونهاهم عن اربع ‏.‏ قال امرهم بالايمان بالله وحده ‏.‏ وقال ‏"‏ هل تدرون ما الايمان بالله ‏"‏ ‏.‏ قالوا الله ورسوله اعلم ‏.‏ قال ‏"‏ شهاده ان لا اله الا الله وان محمدا رسول الله واقام الصلاه وايتاء الزكاه وصوم رمضان وان تؤدوا خمسا من المغنم ‏"‏ ‏.‏ ونهاهم عن الدباء والحنتم والمزفت ‏.‏ قال شعبه وربما قال النقير ‏.‏ قال شعبه وربما قال المقير ‏.‏ وقال ‏"‏ احفظوه واخبروا به من ورائكم ‏"‏ ‏.‏ وقال ابو بكر في روايته ‏"‏ من وراءكم ‏"‏ وليس في روايته المقير ‏.‏', 'Abu Jamra reported:I was an interpreter between Ibn Abbas and the people, that a woman happened to come there and asked about nabidh or the pitcher of wine. He replied: A delegation of the people of ''Abdul-Qais came to the Messenger of Allah (ﷺ). He (the Holy Prophet) asked the delegation or the people (of the delegation about their identity). They replied that they belonged to the tribe of Rabi''a. He (the Holy Prophet) welcomed the people or the delegation which were neither humiliated nor put to shame. They (the members of the delegation) said: Messenger of Allah, we come to you from a far-off distance and there lives between you and us a tribe of the unbelievers of Mudar and, therefore, it is not possible for us to come to you except in the sacred months. Thus direct us to a clear command, about which we should inform people beside us and by which we may enter heaven. He (the Holy Prophet) replied: I command you to do four deeds and forbid you to do four (acts), and added: I direct you to affirm belief in Allah alone, and then asked them: Do you know what belief in Allah really implies? They said: Allah and His Messenger know best. The Prophet said: It implies testimony to the fact that there is no god but Allah, and that Muhammad is the messenger of Allah, establishment of prayer, payment of Zakat, fast of Ramadan, that you pay one-fifth of the booty (fallen to your lot) and I forbid you to use gourd, wine jar, or a receptacle for wine. Shu''ba sometimes narrated the word naqir (wooden pot) and sometimes narrated it as muqayyar. The Prophet also said: Keep it in your mind and inform those who have been left behind', NULL, 'fe74e41ccd66574a7366494fbf5dd131714bf00e23ab046eeead6d256230f85a', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (83, 'muslim', 100, 117, 'Book 1, Hadith 25', 17, NULL, NULL, 'وَحَدَّثَنِي عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ، حَدَّثَنَا أَبِي ح، وَحَدَّثَنَا نَصْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ، قَالَ أَخْبَرَنِي أَبِي قَالاَ، جَمِيعًا حَدَّثَنَا قُرَّةُ بْنُ خَالِدٍ، عَنْ أَبِي جَمْرَةَ، عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِهَذَا الْحَدِيثِ نَحْوَ حَدِيثِ شُعْبَةَ ‏.‏ وَقَالَ ‏"‏ أَنْهَاكُمْ عَمَّا يُنْبَذُ فِي الدُّبَّاءِ وَالنَّقِيرِ وَالْحَنْتَمِ وَالْمُزَفَّتِ ‏"‏ ‏.‏ وَزَادَ ابْنُ مُعَاذٍ فِي حَدِيثِهِ عَنْ أَبِيهِ قَالَ وَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم', 'لِلأَشَجِّ أَشَجِّ عَبْدِ الْقَيْسِ ‏"‏ إِنَّ فِيكَ خَصْلَتَيْنِ يُحِبُّهُمَا اللَّهُ الْحِلْمُ وَالأَنَاةُ ‏"‏ ‏.‏', 'للاشج اشج عبد القيس ‏"‏ ان فيك خصلتين يحبهما الله الحلم والاناه ‏"‏ ‏.‏', 'There is another hadith narrated on the authority of Ibn Abbas (the contents of which are similar to the one) narrated by Shu''ba in which the Prophet (ﷺ) said:I forbid you to prepare nabidh in a gourd, hollowed block of wood, a varnished jar or receptacle. Ibn Mu''adh made this addition on the authority of his father that the Messenger of Allah said to Ashajj, of the tribe of ''Abdul-Qais: You possess two qualities which are liked by Allah: insight and deliberateness', NULL, 'be11939778986d82268dfb28defd6a26e4d8a451b259460873056beed2e1f405', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (84, 'muslim', 100, 118, 'Book 1, Hadith 26', 18, NULL, NULL, 'حَدَّثَنَا يَحْيَى بْنُ أَيُّوبَ، حَدَّثَنَا ابْنُ عُلَيَّةَ، حَدَّثَنَا سَعِيدُ بْنُ أَبِي عَرُوبَةَ، عَنْ قَتَادَةَ، قَالَ حَدَّثَنَا مَنْ، لَقِيَ الْوَفْدَ الَّذِينَ قَدِمُوا عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم مِنْ عَبْدِ الْقَيْسِ ‏.‏ قَالَ سَعِيدٌ وَذَكَرَ قَتَادَةُ أَبَا نَضْرَةَ عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ فِي حَدِيثِهِ هَذَا ‏.‏ أَنَّ أُنَاسًا مِنْ عَبْدِ الْقَيْسِ قَدِمُوا عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالُوا يَا نَبِيَّ اللَّهِ إِنَّا حَىٌّ مِنْ رَبِيعَةَ وَبَيْنَنَا وَبَيْنَكَ كُفَّارُ مُضَرَ وَلاَ نَقْدِرُ عَلَيْكَ إِلاَّ فِي أَشْهُرِ الْحُرُمِ فَمُرْنَا بِأَمْرٍ نَأْمُرُ بِهِ مَنْ وَرَاءَنَا وَنَدْخُلُ بِهِ الْجَنَّةَ إِذَا نَحْنُ أَخَذْنَا بِهِ ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏', 'آمُرُكُمْ بِأَرْبَعٍ وَأَنْهَاكُمْ عَنْ أَرْبَعٍ اعْبُدُوا اللَّهَ وَلاَ تُشْرِكُوا بِهِ شَيْئًا وَأَقِيمُوا الصَّلاَةَ وَآتُوا الزَّكَاةَ وَصُومُوا رَمَضَانَ وَأَعْطُوا الْخُمُسَ مِنَ الْغَنَائِمِ وَأَنْهَاكُمْ عَنْ أَرْبَعٍ عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالْمُزَفَّتِ وَالنَّقِيرِ ‏"‏ ‏.‏ قَالُوا يَا نَبِيَّ اللَّهِ مَا عِلْمُكَ بِالنَّقِيرِ قَالَ ‏"‏ بَلَى جِذْعٌ تَنْقُرُونَهُ فَتَقْذِفُونَ فِيهِ مِنَ الْقُطَيْعَاءِ - قَالَ سَعِيدٌ أَوْ قَالَ مِنَ التَّمْرِ - ثُمَّ تَصُبُّونَ فِيهِ مِنَ الْمَاءِ حَتَّى إِذَا سَكَنَ غَلَيَانُهُ شَرِبْتُمُوهُ حَتَّى إِنَّ أَحَدَكُمْ - أَوْ إِنَّ أَحَدَهُمْ - لَيَضْرِبُ ابْنَ عَمِّهِ بِالسَّيْفِ ‏"‏ ‏.‏ قَالَ وَفِي الْقَوْمِ رَجُلٌ أَصَابَتْهُ جِرَاحَةٌ كَذَلِكَ ‏.‏ قَالَ وَكُنْتُ أَخْبَأُهَا حَيَاءً مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم فَقُلْتُ فَفِيمَ نَشْرَبُ يَا رَسُولَ اللَّهِ قَالَ ‏"‏ فِي أَسْقِيَةِ الأَدَمِ الَّتِي يُلاَثُ عَلَى أَفْوَاهِهَا ‏"‏ ‏.‏ قَالُوا يَا رَسُولَ اللَّهِ إِنَّ أَرْضَنَا كَثِيرَةُ الْجِرْذَانِ وَلاَ تَبْقَى بِهَا أَسْقِيَةُ الأَدَمِ ‏.‏ فَقَالَ نَبِيُّ اللَّهِ صلى الله عليه وسلم ‏"‏ وَإِنْ أَكَلَتْهَا الْجِرْذَانُ وَإِنْ أَكَلَتْهَا الْجِرْذَانُ وَإِنْ أَكَلَتْهَا الْجِرْذَانُ ‏"‏ ‏.‏ قَالَ وَقَالَ نَبِيُّ اللَّهِ صلى الله عليه وسلم لأَشَجِّ عَبْدِ الْقَيْسِ ‏"‏ إِنَّ فِيكَ لَخَصْلَتَيْنِ يُحِبُّهُمَا اللَّهُ الْحِلْمُ وَالأَنَاةُ ‏"‏ ‏.‏', 'امركم باربع وانهاكم عن اربع اعبدوا الله ولا تشركوا به شيئا واقيموا الصلاه واتوا الزكاه وصوموا رمضان واعطوا الخمس من الغنائم وانهاكم عن اربع عن الدباء والحنتم والمزفت والنقير ‏"‏ ‏.‏ قالوا يا نبي الله ما علمك بالنقير قال ‏"‏ بلي جذع تنقرونه فتقذفون فيه من القطيعاء - قال سعيد او قال من التمر - ثم تصبون فيه من الماء حتي اذا سكن غليانه شربتموه حتي ان احدكم - او ان احدهم - ليضرب ابن عمه بالسيف ‏"‏ ‏.‏ قال وفي القوم رجل اصابته جراحه كذلك ‏.‏ قال وكنت اخباها حياء من رسول الله صلي الله عليه وسلم فقلت ففيم نشرب يا رسول الله قال ‏"‏ في اسقيه الادم التي يلاث علي افواهها ‏"‏ ‏.‏ قالوا يا رسول الله ان ارضنا كثيره الجرذان ولا تبقي بها اسقيه الادم ‏.‏ فقال نبي الله صلي الله عليه وسلم ‏"‏ وان اكلتها الجرذان وان اكلتها الجرذان وان اكلتها الجرذان ‏"‏ ‏.‏ قال وقال نبي الله صلي الله عليه وسلم لاشج عبد القيس ‏"‏ ان فيك لخصلتين يحبهما الله الحلم والاناه ‏"‏ ‏.‏', 'It is reported on the authority of Qatada that one among the delegates of the ''Abdul-Qais tribe narrated this tradition to him. Sa''id said that Qatada had mentioned the name of Abu Nadra on the authority of Abu Sa''id Khudri who narrated this tradition:That people from the- tribe of ''Abdul-Qais came to the Messenger of Allah (ﷺ) and said: Messenger of Allah, we belong to the tribe of Rabi''a and there live between you and us the unbelievers of the Mudar tribe and we find it impossible to come to you except in the sacred months; direct us to a deed which we must communicate to those who have been left behind us and by doing which we may enter heaven. Upon this the Messenger of Allah (ﷺ) said: I enjoin upon you four (things) and forbid you to do four (things): worship Allah and associate none with Him, establish prayer, pay Zakat, and observe the fast of Ramadan, and pay the fifth part out of the booty. And I prohibit you from four (things): dry gourds, green-coloured jars, hollowed stumps of palm-trees, and receptacles. They (the members of the delegation) said: Do you know what al-naqir is? He replied: Yes, it is a stump which you hollow out and in which you throw small dates. Sa''id said: He (the Holy Prophet) used the word tamar (dates). (The Prophet then added): Then you sprinkle water over it and when its ebullition subsides, you drink it (and you are so intoxicated) that one amongst you, or one amongst them (the other members of your tribe, who were not present there) strikes his cousin with the sword. He (the narrator) said: There was a man amongst us who had sustained injury on this very account due to (intoxication), and he told that he tried to conceal it out of shame from the Messenger of Allah (ﷺ). I, however, inquired from the Messenger of Allah (it we discard those utensils which you have forbidden us to use), then what type of vessels should be used for drink? He (the Holy Prophet) replied: In the waterskin the mouths of which are tied (with a string). They (again) said: Prophet of Allah, our land abounds in rats and water-skins cannot remain preserved. The holy Prophet of Allah (ﷺ) said: (Drink in water-skins) even if these arenibbled by rats. And then (addressing) al-Ashajj of ''Abdul-Qais he said: Verily, you possess two such qualities which Allah loves: insight and deliberateness', NULL, 'ec03f65b123c1c8cb825bc13d59c295e560cd80a444c9d92d8c6fc449e17ab6c', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (85, 'muslim', 100, 119, 'Book 1, Hadith 27', 18, NULL, NULL, NULL, 'حَدَّثَنِي مُحَمَّدُ بْنُ الْمُثَنَّى، وَابْنُ، بَشَّارٍ قَالاَ حَدَّثَنَا ابْنُ أَبِي عَدِيٍّ، عَنْ سَعِيدٍ، عَنْ قَتَادَةَ، قَالَ حَدَّثَنِي غَيْرُ، وَاحِدٍ، لَقِيَ ذَاكَ الْوَفْدَ ‏.‏ وَذَكَرَ أَبَا نَضْرَةَ عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ وَفْدَ عَبْدِ الْقَيْسِ، لَمَّا قَدِمُوا عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم بِمِثْلِ حَدِيثِ ابْنِ عُلَيَّةَ غَيْرَ أَنَّ فِيهِ ‏ "‏ وَتَذِيفُونَ فِيهِ مِنَ الْقُطَيْعَاءِ أَوِ التَّمْرِ وَالْمَاءِ ‏"‏ ‏.‏ وَلَمْ يَقُلْ قَالَ سَعِيدٌ أَوْ قَالَ مِنَ التَّْرِ ‏.‏', 'حدثني محمد بن المثني، وابن، بشار قالا حدثنا ابن ابي عدي، عن سعيد، عن قتاده، قال حدثني غير، واحد، لقي ذاك الوفد ‏.‏ وذكر ابا نضره عن ابي سعيد الخدري، ان وفد عبد القيس، لما قدموا علي رسول الله صلي الله عليه وسلم بمثل حديث ابن عليه غير ان فيه ‏ "‏ وتذيفون فيه من القطيعاء او التمر والماء ‏"‏ ‏.‏ ولم يقل قال سعيد او قال من التر ‏.‏', 'The above hadith has been mentioned with a different chain and slightly different wording', NULL, '5a20eb547f81f6eb4ee8c6e1c2bf856e31739f72b5d1ec736c2a12551a54b014', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (86, 'muslim', 100, 120, 'Book 1, Hadith 28', 18, NULL, NULL, NULL, 'حَدَّثَنِي مُحَمَّدُ بْنُ بَكَّارٍ الْبَصْرِيُّ، حَدَّثَنَا أَبُو عَاصِمٍ، عَنِ ابْنِ جُرَيْجٍ، ح وَحَدَّثَنِي مُحَمَّدُ بْنُ رَافِعٍ، - وَاللَّفْظُ لَهُ - حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا ابْنُ جُرَيْجٍ، قَالَ أَخْبَرَنِي أَبُو قَزَعَةَ، أَنَّ أَبَا نَضْرَةَ، أَخْبَرَهُ وَحَسَنًا، أَخْبَرَهُمَا أَنَّ أَبَا سَعِيدٍ الْخُدْرِيَّ أَخْبَرَهُ أَنَّ وَفْدَ عَبْدِ الْقَيْسِ لَمَّا أَتَوْا نَبِيَّ اللَّهِ صلى الله عليه وسلم قَالُوا يَا نَبِيَّ اللَّهِ جَعَلَنَا اللَّهُ فِدَاءَكَ مَاذَا يَصْلُحُ لَنَا مِنَ الأَشْرِبَةِ فَقَالَ ‏"‏ لاَ تَشْرَبُوا فِي النَّقِيرِ ‏"‏ ‏.‏ قَالُوا يَا نَبِيَّ اللَّهِ جَعَلَنَا اللَّهُ فِدَاءَكَ أَوَتَدْرِي مَا النَّقِيرُ قَالَ ‏"‏ نَعَمِ الْجِذْعُ يُنْقَرُ وَسَطُهُ وَلاَ فِي الدُّبَّاءِ وَلاَ فِي الْحَنْتَمَةِ وَعَلَيْكُمْ بِالْمُوكَى ‏"‏ ‏.‏', 'حدثني محمد بن بكار البصري، حدثنا ابو عاصم، عن ابن جريج، ح وحدثني محمد بن رافع، - واللفظ له - حدثنا عبد الرزاق، اخبرنا ابن جريج، قال اخبرني ابو قزعه، ان ابا نضره، اخبره وحسنا، اخبرهما ان ابا سعيد الخدري اخبره ان وفد عبد القيس لما اتوا نبي الله صلي الله عليه وسلم قالوا يا نبي الله جعلنا الله فداءك ماذا يصلح لنا من الاشربه فقال ‏"‏ لا تشربوا في النقير ‏"‏ ‏.‏ قالوا يا نبي الله جعلنا الله فداءك اوتدري ما النقير قال ‏"‏ نعم الجذع ينقر وسطه ولا في الدباء ولا في الحنتمه وعليكم بالموكي ‏"‏ ‏.‏', 'It is narrated on the authority of Abu Said al-Khudri that when the delegation of the tribe of Abdul-Qais came to the Prophet of Allah (ﷺ), (its members) said:Apostle of Allah, may God enable us to lay down our lives for you, which beverage is good for us? He (the Prophet) said: (Not to speak of beverages, I would lay stress) that you should not drink in the wine jars. They said: Apostle of Allah, may God enable us to lay down our lives for you, do you know what al-naqir is? He (the Holy Prophet) replied: Yes, it is a stump which you hollow out in the middle, and added: Do not use gourd or receptacle (for drink). Use water-skin the mouth of which is tied with a thong (for this purpose)', NULL, 'd6ad609a8417d1dfb06140a8a262e402bfc8949dd671768187203f5f44c287d8', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (87, 'muslim', 100, 121, 'Book 1, Hadith 29', 19, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَأَبُو كُرَيْبٍ وَإِسْحَاقُ بْنُ إِبْرَاهِيمَ جَمِيعًا عَنْ وَكِيعٍ، - قَالَ أَبُو بَكْرٍ حَدَّثَنَا وَكِيعٌ، - عَنْ زَكَرِيَّاءَ بْنِ إِسْحَاقَ، قَالَ حَدَّثَنِي يَحْيَى بْنُ عَبْدِ اللَّهِ بْنِ صَيْفِيٍّ، عَنْ أَبِي مَعْبَدٍ، عَنِ ابْنِ عَبَّاسٍ، عَنْ مُعَاذِ بْنِ جَبَلٍ، - قَالَ أَبُو بَكْرٍ رُبَّمَا قَالَ وَكِيعٌ عَنِ ابْنِ عَبَّاسٍ، أَنَّ مُعَاذًا، - قَالَ بَعَثَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم قَالَ ‏', '"‏ إِنَّكَ تَأْتِي قَوْمًا مِنْ أَهْلِ الْكِتَابِ ‏.‏ فَادْعُهُمْ إِلَى شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنِّي رَسُولُ اللَّهِ فَإِنْ هُمْ أَطَاعُوا لِذَلِكَ فَأَعْلِمْهُمْ أَنَّ اللَّهَ افْتَرَضَ عَلَيْهِمْ خَمْسَ صَلَوَاتٍ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ فَإِنْ هُمْ أَطَاعُوا لِذَلِكَ فَأَعْلِمْهُمْ أَنَّ اللَّهَ افْتَرَضَ عَلَيْهِمْ صَدَقَةً تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ فَتُرَدُّ فِي فُقَرَائِهِمْ فَإِنْ هُمْ أَطَاعُوا لِذَلِكَ فَإِيَّاكَ وَكَرَائِمَ أَمْوَالِهِمْ وَاتَّقِ دَعْوَةَ الْمَظْلُومِ فَإِنَّهُ لَيْسَ بَيْنَهَا وَبَيْنَ اللَّهِ حِجَابٌ ‏"‏ ‏.‏', '"‏ انك تاتي قوما من اهل الكتاب ‏.‏ فادعهم الي شهاده ان لا اله الا الله واني رسول الله فان هم اطاعوا لذلك فاعلمهم ان الله افترض عليهم خمس صلوات في كل يوم وليله فان هم اطاعوا لذلك فاعلمهم ان الله افترض عليهم صدقه تؤخذ من اغنيائهم فترد في فقرائهم فان هم اطاعوا لذلك فاياك وكرائم اموالهم واتق دعوه المظلوم فانه ليس بينها وبين الله حجاب ‏"‏ ‏.‏', 'It is reported on the authority of Ibn ''Abbas that Mu''adh said:The Messenger of Allah sent me (as a governor of Yemen) and (at the time of departure) instructed me thus: You will soon find yourself in a community one among the people of the Book, so first call them to testify that there is no god but Allah, that I (Muhammad) am the messenger of Allah, and if they accept this, then tell them Allah has enjoined upon them five prayers during the day and the night and if they accept it, then tell them that Allah has made Zakat obligatory for them that it should be collected from the rich and distributed among the poor, and if they agree to it don''t pick up (as a share of Zakat) the best of their wealths. Beware of the supplication of the oppressed for there is no barrier between him and Allah', NULL, '45bdca5cb9176c2a0628761ca51b1f7b057670d579f6a8c4af9446996802b845', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (88, 'muslim', 100, 122, 'Book 1, Hadith 30', 19, NULL, NULL, 'حَدَّثَنَا ابْنُ أَبِي عُمَرَ، حَدَّثَنَا بِشْرُ بْنُ السَّرِيِّ، حَدَّثَنَا زَكَرِيَّاءُ بْنُ إِسْحَاقَ، ح وَحَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا أَبُو عَاصِمٍ، عَنْ زَكَرِيَّاءَ بْنِ إِسْحَاقَ، عَنْ يَحْيَى بْنِ عَبْدِ اللَّهِ بْنِ صَيْفِيٍّ، عَنْ أَبِي مَعْبَدٍ، عَنِ ابْنِ عَبَّاسٍ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'بَعَثَ مُعَاذًا إِلَى الْيَمَنِ فَقَالَ ‏ "‏ إِنَّكَ سَتَأْتِي قَوْمًا ‏"‏ بِمِثْلِ حَدِيثِ وَكِيعٍ ‏.‏', 'بعث معاذا الي اليمن فقال ‏ "‏ انك ستاتي قوما ‏"‏ بمثل حديث وكيع ‏.‏', 'The above hadith has been mentioned with a different chain with a slightly different wording at the beginning, then follows the same', NULL, '023793e35105f3567c2e3d18fe2ba223431e8370bc4b3fba07d8c11120f7d1c6', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (89, 'muslim', 100, 123, 'Book 1, Hadith 31', 19, NULL, NULL, 'حَدَّثَنَا أُمَيَّةُ بْنُ بِسْطَامَ الْعَيْشِيُّ، حَدَّثَنَا يَزِيدُ بْنُ زُرَيْعٍ، حَدَّثَنَا رَوْحٌ، - وَهُوَ ابْنُ الْقَاسِمِ - عَنْ إِسْمَاعِيلَ بْنِ أُمَيَّةَ، عَنْ يَحْيَى بْنِ عَبْدِ اللَّهِ بْنِ صَيْفِيٍّ، عَنْ أَبِي مَعْبَدٍ، عَنِ ابْنِ عَبَّاسٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم', 'لَمَّا بَعَثَ مُعَاذًا إِلَى الْيَمَنِ قَالَ ‏ "‏ إِنَّكَ تَقْدَمُ عَلَى قَوْمٍ أَهْلِ كِتَابٍ فَلْيَكُنْ أَوَّلَ مَا تَدْعُوهُمْ إِلَيْهِ عِبَادَةُ اللَّهِ عَزَّ وَجَلَّ فَإِذَا عَرَفُوا اللَّهَ فَأَخْبِرْهُمْ أَنَّ اللَّهَ فَرَضَ عَلَيْهِمْ خَمْسَ صَلَوَاتٍ فِي يَوْمِهِمْ وَلَيْلَتِهِمْ فَإِذَا فَعَلُوا فَأَخْبِرْهُمْ أَنَّ اللَّهَ قَدْ فَرَضَ عَلَيْهِمْ زَكَاةً تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ فَتُرَدُّ عَلَى فُقَرَائِهِمْ فَإِذَا أَطَاعُوا بِهَا فَخُذْ مِنْهُمْ وَتَوَقَّ كَرَائِمَ أَمْوَالِهِمْ ‏"‏ ‏.‏', 'لما بعث معاذا الي اليمن قال ‏ "‏ انك تقدم علي قوم اهل كتاب فليكن اول ما تدعوهم اليه عباده الله عز وجل فاذا عرفوا الله فاخبرهم ان الله فرض عليهم خمس صلوات في يومهم وليلتهم فاذا فعلوا فاخبرهم ان الله قد فرض عليهم زكاه تؤخذ من اغنيائهم فترد علي فقرائهم فاذا اطاعوا بها فخذ منهم وتوق كرائم اموالهم ‏"‏ ‏.‏', 'It is narrated on the authority of Ibn ''Abbas that when the Messenger of Allah (ﷺ) sent Mu''adh towards Yemen (as governor) he said to him:Verily you would reach a community of the people of the Book, the very first thing to which you should call them is the worship of Allah, may His Glory be Magnificent, and when they become fully aware of Allah, instruct them that He has enjoined five prayers on them during the day and the night, and when they begin observing it, then instruct them that verily Allah has made Zakat obligatory for them which would be collected from the wealthy amongst them and distributed to their needy ones, and when they submit to it, then collect it from them and avoid (the temptation) of selecting the best (items) of their riches', NULL, '61caa8e4a4982dbe45d8993dae032f4f3988f1878245efbed864b95eee85eed7', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (90, 'muslim', 100, 124, 'Book 1, Hadith 32', 20, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا لَيْثُ بْنُ سَعْدٍ، عَنْ عُقَيْلٍ، عَنِ الزُّهْرِيِّ، قَالَ أَخْبَرَنِي عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ لَمَّا تُوُفِّيَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَاسْتُخْلِفَ أَبُو بَكْرٍ بَعْدَهُ وَكَفَرَ مَنْ كَفَرَ مِنَ الْعَرَبِ قَالَ عُمَرُ بْنُ الْخَطَّابِ لأَبِي بَكْرٍ كَيْفَ تُقَاتِلُ النَّاسَ وَقَدْ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لاَ إِلَهَ إِلاَّ اللَّهُ فَمَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ فَقَدْ عَصَمَ مِنِّي مَالَهُ وَنَفْسَهُ إِلاَّ بِحَقِّهِ وَحِسَابُهُ عَلَى اللَّهِ ‏"‏ ‏.‏ فَقَالَ أَبُو بَكْرٍ وَاللَّهِ لأُقَاتِلَنَّ مَنْ فَرَّقَ بَيْنَ الصَّلاَةِ وَالزَّكَاةِ فَإِنَّ الزَّكَاةَ حَقُّ الْمَالِ وَاللَّهِ لَوْ مَنَعُونِي عِقَالاً كَانُوا يُؤَدُّونَهُ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم لَقَاتَلْتُهُمْ عَلَى مَنْعِهِ ‏.‏ فَقَالَ عُمَرُ بْنُ الْخَطَّابِ فَوَاللَّهِ مَا هُوَ إِلاَّ أَنْ رَأَيْتُ اللَّهَ عَزَّ وَجَلَّ قَدْ شَرَحَ صَدْرَ أَبِي بَكْرٍ لِلْقِتَالِ فَعَرَفْتُ أَنَّهُ الْحَقُّ ‏.‏', '"‏ امرت ان اقاتل الناس حتي يقولوا لا اله الا الله فمن قال لا اله الا الله فقد عصم مني ماله ونفسه الا بحقه وحسابه علي الله ‏"‏ ‏.‏ فقال ابو بكر والله لاقاتلن من فرق بين الصلاه والزكاه فان الزكاه حق المال والله لو منعوني عقالا كانوا يؤدونه الي رسول الله صلي الله عليه وسلم لقاتلتهم علي منعه ‏.‏ فقال عمر بن الخطاب فوالله ما هو الا ان رايت الله عز وجل قد شرح صدر ابي بكر للقتال فعرفت انه الحق ‏.‏', 'It is narrated on the authority of Abu Huraira that when the Messenger of Allah (ﷺ) breathed his last and Abu Bakr was appointed as his successor (Caliph), those amongst the Arabs who wanted to become apostates became apostates. ''Umar b. Khattab said to Abu Bakr:Why would you fight against the people, when the Messenger of Allah declared: I have been directed to fight against people so long as they do not say: There is no god but Allah, and he who professed it was granted full protection of his property and life on my behalf except for a right? His (other) affairs rest with Allah. Upon this Abu Bakr said: By Allah, I would definitely fight against him who severed prayer from Zakat, for it is the obligation upon the rich. By Allah, I would fight against them even to secure the cord (used for hobbling the feet of a camel) which they used to give to the Messenger of Allah (as zakat) but now they have withheld it. Umar b. Khattab remarked: By Allah, I found nothing but the fact that Allah had opened the heart of Abu Bakr for (perceiving the justification of) fighting (against those who refused to pay Zakat) and I fully recognized that the (stand of Abu Bakr) was right', NULL, '3274d2c9e91c7365249e817d31cf99059101e4c13666dc5cac611f22c16c804a', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (91, 'muslim', 100, 125, 'Book 1, Hadith 33', 21, NULL, NULL, 'وَحَدَّثَنَا أَبُو الطَّاهِرِ، وَحَرْمَلَةُ بْنُ يَحْيَى، وَأَحْمَدُ بْنُ عِيسَى، قَالَ أَحْمَدُ حَدَّثَنَا وَقَالَ الآخَرَانِ، أَخْبَرَنَا ابْنُ وَهْبٍ، قَالَ أَخْبَرَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، قَالَ حَدَّثَنِي سَعِيدُ بْنُ الْمُسَيَّبِ، أَنَّ أَبَا هُرَيْرَةَ، أَخْبَرَهُ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏', '"‏ أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لاَ إِلَهَ إِلاَّ اللَّهُ فَمَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ عَصَمَ مِنِّي مَالَهُ وَنَفْسَهُ إِلاَّ بِحَقِّهِ وَحِسَابُهُ عَلَى اللَّهِ ‏"‏ ‏.‏', '"‏ امرت ان اقاتل الناس حتي يقولوا لا اله الا الله فمن قال لا اله الا الله عصم مني ماله ونفسه الا بحقه وحسابه علي الله ‏"‏ ‏.‏', 'It is reported on the authority of Abu Huraira that the Messenger of Allah said:I have been commanded to fight against people so long as they do not declare that there is no god but Allah, and he who professed it was guaranteed the protection of his property and life on my behalf except for the right affairs rest with Allah', NULL, 'cf8910ab76c7500aa10ee3724bf2144e65e582e03d0e556320c2b0b9eb3694d9', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (92, 'muslim', 100, 126, 'Book 1, Hadith 34', 21, NULL, NULL, 'حَدَّثَنَا أَحْمَدُ بْنُ عَبْدَةَ الضَّبِّيُّ، أَخْبَرَنَا عَبْدُ الْعَزِيزِ، - يَعْنِي الدَّرَاوَرْدِيَّ - عَنِ الْعَلاَءِ، ح وَحَدَّثَنَا أُمَيَّةُ بْنُ بِسْطَامَ، - وَاللَّفْظُ لَهُ - حَدَّثَنَا يَزِيدُ بْنُ زُرَيْعٍ، حَدَّثَنَا رَوْحٌ، عَنِ الْعَلاَءِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم قَالَ ‏', '"‏ أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَيُؤْمِنُوا بِي وَبِمَا جِئْتُ بِهِ فَإِذَا فَعَلُوا ذَلِكَ عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلاَّ بِحَقِّهَا وَحِسَابُهُمْ عَلَى اللَّهِ ‏"‏ ‏.‏', '"‏ امرت ان اقاتل الناس حتي يشهدوا ان لا اله الا الله ويؤمنوا بي وبما جئت به فاذا فعلوا ذلك عصموا مني دماءهم واموالهم الا بحقها وحسابهم علي الله ‏"‏ ‏.‏', 'It is reported on the authority of Abu Huraira that he heard the Messenger of Allah say:I have been commanded to fight against people, till they testify to the fact that there is no god but Allah, and believe in me (that) I am the messenger (from the Lord) and in all that I have brought. And when they do it, their blood and riches are guaranteed protection on my behalf except where it is justified by law, and their affairs rest with Allah', NULL, '50a1873b8f45f2351048f325e084f2db9d28630af0ba8b874e6bef9c7fadb0f1', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (93, 'muslim', 100, 127, 'Book 1, Hadith 35', 21, NULL, NULL, 'وَحَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا حَفْصُ بْنُ غِيَاثٍ، عَنِ الأَعْمَشِ، عَنْ أَبِي سُفْيَانَ، عَنْ جَابِرٍ، وَعَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ، قَالاَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏', 'أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ ‏"‏ ‏.‏ بِمِثْلِ حَدِيثِ ابْنِ الْمُسَيَّبِ عَنْ أَبِي هُرَيْرَةَ ح وَحَدَّثَنِي أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا وَكِيعٌ، ح وَحَدَّثَنِي مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا عَبْدُ الرَّحْمَنِ، - يَعْنِي ابْنَ مَهْدِيٍّ - قَالاَ جَمِيعًا حَدَّثَنَا سُفْيَانُ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏ أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لاَ إِلَهَ إِلاَّ اللَّهُ فَإِذَا قَالُوا لاَ إِلَهَ إِلاَّ اللَّهُ عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلاَّ بِحَقِّهَا وَحِسَابُهُمْ عَلَى اللَّهِ ‏"‏ ‏.‏ ثُمَّ قَرَأَ ‏{‏ إِنَّمَا أَنْتَ مُذَكِّرٌ * لَسْتَ عَلَيْهِمْ بِمُسَيْطِرٍ‏}‏', 'امرت ان اقاتل الناس ‏"‏ ‏.‏ بمثل حديث ابن المسيب عن ابي هريره ح وحدثني ابو بكر بن ابي شيبه، حدثنا وكيع، ح وحدثني محمد بن المثني، حدثنا عبد الرحمن، - يعني ابن مهدي - قالا جميعا حدثنا سفيان، عن ابي الزبير، عن جابر، قال قال رسول الله صلي الله عليه وسلم ‏"‏ امرت ان اقاتل الناس حتي يقولوا لا اله الا الله فاذا قالوا لا اله الا الله عصموا مني دماءهم واموالهم الا بحقها وحسابهم علي الله ‏"‏ ‏.‏ ثم قرا ‏{‏ انما انت مذكر * لست عليهم بمسيطر‏}‏', 'It is narrated on the authority of Jabir that the Messenger of Allah said:I have been commanded that I should fight against people till they declare that there is no god but Allah, and when they profess it that there is no god but Allah, their blood and riches are guaranteed protection on my behalf except where it is justified by law, and their affairs rest with Allah, and then he (the Holy Prophet) recited (this verse of the Holy Qur''an):" Thou art not over them a warden" (lxxxviii)', NULL, 'f033a97b986d34f702a69d8868bff9463cd90cc6938125109e3741ea203117e3', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (94, 'muslim', 100, 129, 'Book 1, Hadith 36', 22, NULL, NULL, 'حَدَّثَنَا أَبُو غَسَّانَ الْمِسْمَعِيُّ، مَالِكُ بْنُ عَبْدِ الْوَاحِدِ حَدَّثَنَا عَبْدُ الْمَلِكِ بْنُ الصَّبَّاحِ، عَنْ شُعْبَةَ، عَنْ وَاقِدِ بْنِ مُحَمَّدِ بْنِ زَيْدِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ، عَنْ أَبِيهِ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ وَيُقِيمُوا الصَّلاَةَ وَيُؤْتُوا الزَّكَاةَ فَإِذَا فَعَلُوا عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلاَّ بِحَقِّهَا وَحِسَابُهُمْ عَلَى اللَّهِ ‏"‏ ‏.‏', '"‏ امرت ان اقاتل الناس حتي يشهدوا ان لا اله الا الله وان محمدا رسول الله ويقيموا الصلاه ويؤتوا الزكاه فاذا فعلوا عصموا مني دماءهم واموالهم الا بحقها وحسابهم علي الله ‏"‏ ‏.‏', 'It has been narrated on the authority of Abdullah b. ''Umar that the Messenger of Allah said:I have been commanded to fight against people till they testify that there is no god but Allah, that Muhammad is the messenger of Allah, and they establish prayer, and pay Zakat and if they do it, their blood and property are guaranteed protection on my behalf except when justified by law, and their affairs rest with Allah', NULL, 'f787bf63a395bd2bd2ef628fc53bf94c02a08b110a5b49a000d19bc82dbd3f7c', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (95, 'muslim', 100, 130, 'Book 1, Hadith 37', 23, NULL, NULL, 'وَحَدَّثَنَا سُوَيْدُ بْنُ سَعِيدٍ، وَابْنُ أَبِي عُمَرَ، قَالاَ حَدَّثَنَا مَرْوَانُ، - يَعْنِيَانِ الْفَزَارِيَّ - عَنْ أَبِي مَالِكٍ، عَنْ أَبِيهِ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏', '"‏ مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ وَكَفَرَ بِمَا يُعْبَدُ مِنْ دُونِ اللَّهِ حَرُمَ مَالُهُ وَدَمُهُ وَحِسَابُهُ عَلَى اللَّهِ ‏"‏ ‏.‏', '"‏ من قال لا اله الا الله وكفر بما يعبد من دون الله حرم ماله ودمه وحسابه علي الله ‏"‏ ‏.‏', 'It Is narrated on the authority of Abu Malik:I heard the Messenger of Allah (ﷺ) say: He who professed that there is no god but Allah and made a denial of everything which the people worship beside Allah, his property and blood became inviolable, an their affairs rest with Allah', NULL, '436ef2e84b9cbdd0e44d393aec6080bfb49473de469084a831952a7655f19f34', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (96, 'muslim', 100, 131, 'Book 1, Hadith 38', 23, NULL, NULL, 'وَحَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو خَالِدٍ الأَحْمَرُ، ح وَحَدَّثَنِيهِ زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا يَزِيدُ بْنُ هَارُونَ، كِلاَهُمَا عَنْ أَبِي مَالِكٍ، عَنْ أَبِيهِ، أَنَّهُ سَمِعَ النَّبِيَّ صلى الله عليه وسلم يَقُولُ ‏', '"‏ مَنْ وَحَّدَ اللَّهَ ‏"‏ ثُمَّ ذَكَرَ بِمِثْلِهِ ‏.‏', '"‏ من وحد الله ‏"‏ ثم ذكر بمثله ‏.‏', 'Abu Malik narrated on the authority of his father that he heard the Apostle (ﷺ) say:He who held belief in the unity of Allah, and then narrated what has been stated above', NULL, '7a72a4c859b48849d7eadda4853819f64d4766804783467cb8d11bf3cf0aca31', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (97, 'muslim', 100, 132, 'Book 1, Hadith 39', 24, NULL, NULL, 'وَحَدَّثَنِي حَرْمَلَةُ بْنُ يَحْيَى التُّجِيبِيُّ، أَخْبَرَنَا عَبْدُ اللَّهِ بْنُ وَهْبٍ، قَالَ أَخْبَرَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، قَالَ أَخْبَرَنِي سَعِيدُ بْنُ الْمُسَيَّبِ، عَنْ أَبِيهِ، قَالَ لَمَّا حَضَرَتْ أَبَا طَالِبٍ الْوَفَاةُ جَاءَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم فَوَجَدَ عِنْدَهُ أَبَا جَهْلٍ وَعَبْدَ اللَّهِ بْنَ أَبِي أُمَيَّةَ بْنِ الْمُغِيرَةِ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏', 'يَا عَمِّ قُلْ لاَ إِلَهَ إِلاَّ اللَّهُ ‏.‏ كَلِمَةً أَشْهَدُ لَكَ بِهَا عِنْدَ اللَّهِ ‏"‏ ‏.‏ فَقَالَ أَبُو جَهْلٍ وَعَبْدُ اللَّهِ بْنُ أَبِي أُمَيَّةَ يَا أَبَا طَالِبٍ أَتَرْغَبُ عَنْ مِلَّةِ عَبْدِ الْمُطَّلِبِ ‏.‏ فَلَمْ يَزَلْ رَسُولُ اللَّهِ صلى الله عليه وسلم يَعْرِضُهَا عَلَيْهِ وَيُعِيدُ لَهُ تِلْكَ الْمَقَالَةَ حَتَّى قَالَ أَبُو طَالِبٍ آخِرَ مَا كَلَّمَهُمْ هُوَ عَلَى مِلَّةِ عَبْدِ الْمُطَّلِبِ ‏.‏ وَأَبَى أَنْ يَقُولَ لاَ إِلَهَ إِلاَّ اللَّهُ ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏ أَمَا وَاللَّهِ لأَسْتَغْفِرَنَّ لَكَ مَا لَمْ أُنْهَ عَنْكَ ‏"‏ ‏.‏ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ‏}‏ ‏.‏ وَأَنْزَلَ اللَّهُ تَعَالَى فِي أَبِي طَالِبٍ فَقَالَ لِرَسُولِ اللَّهِ صلى الله عليه وسلم ‏{‏ إِنَّكَ لاَ تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ‏}‏‏.‏', 'يا عم قل لا اله الا الله ‏.‏ كلمه اشهد لك بها عند الله ‏"‏ ‏.‏ فقال ابو جهل وعبد الله بن ابي اميه يا ابا طالب اترغب عن مله عبد المطلب ‏.‏ فلم يزل رسول الله صلي الله عليه وسلم يعرضها عليه ويعيد له تلك المقاله حتي قال ابو طالب اخر ما كلمهم هو علي مله عبد المطلب ‏.‏ وابي ان يقول لا اله الا الله ‏.‏ فقال رسول الله صلي الله عليه وسلم ‏"‏ اما والله لاستغفرن لك ما لم انه عنك ‏"‏ ‏.‏ فانزل الله عز وجل ‏{‏ ما كان للنبي والذين امنوا ان يستغفروا للمشركين ولو كانوا اولي قربي من بعد ما تبين لهم انهم اصحاب الجحيم‏}‏ ‏.‏ وانزل الله تعالي في ابي طالب فقال لرسول الله صلي الله عليه وسلم ‏{‏ انك لا تهدي من احببت ولكن الله يهدي من يشاء وهو اعلم بالمهتدين‏}‏‏.‏', 'It is reported by Sa''id b. Musayyib who narrated it on the authority of his father (Musayyib b. Hazm) that when Abu Talib was about to die, the Messenger of Allah (ﷺ) came to him and found with him Abu Jahl (''Amr b. Hisham) and ''Abdullah b. Abi Umayya ibn al-Mughirah. The Messenger of Allah (ﷺ) said:My uncle, you just make a profession that there is no god but Allah, and I will bear testimony before Allah (of your being a believer), Abu Jahl and ''Abdullah b. Abi Umayya addressing him said: Abu Talib, would you abandon the religion of ''Abdul-Muttalib? The Messenger of Allah (ﷺ) constantly requested him (to accept his offer), and (on the other hand) was repeated the same statement (of Abu Jahl and ''Abdullah b. Abi Umayya) till Abu Talib gave his final decision and be stuck to the religion of ''Abdul-Muttalib and refused to profess that there is no god but Allah. Upon this the Messenger of Allah remarked: By Allah, I will persistently beg pardon for you till I am forbidden to do so (by God), It was then that Allah, the Magnificent and the Glorious, revealed this verse: " It is not meet for the Prophet and for those who believe that they should beg pardon for the polytheists, even though they were their kith and kin, after it had been made known to them that they were the denizens of Hell" (ix. 113) And it was said to the Messenger of Allah (ﷺ): " Verily thou canst not guide to the right path whom thou lovest. And it is Allah Who guideth whom He will, and He knoweth best who are the guided" (xxviii)', NULL, '491cad8443a73328cc2b2198d8425e73fbbabf7acf71c73410b1e95d4af9ab87', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (98, 'muslim', 100, 133, 'Book 1, Hadith 40', 24, NULL, NULL, NULL, 'وَحَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، وَعَبْدُ بْنُ حُمَيْدٍ، قَالاَ أَخْبَرَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، ح وَحَدَّثَنَا حَسَنٌ الْحُلْوَانِيُّ، وَعَبْدُ بْنُ حُمَيْدٍ، قَالاَ حَدَّثَنَا يَعْقُوبُ، - وَهُوَ ابْنُ إِبْرَاهِيمَ بْنِ سَعْدٍ - قَالَ حَدَّثَنِي أَبِي، عَنْ صَالِحٍ، كِلاَهُمَا عَنِ الزُّهْرِيِّ، بِهَذَا الإِسْنَادِ مِثْلَهُ غَيْرَ أَنَّ حَدِيثَ صَالِحٍ انْتَهَى عِنْدَ قَوْلِهِ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ فِيهِ ‏.‏ وَلَمْ يَذْكُرِ الآيَتَيْنِ ‏.‏ وَقَالَ فِي حَدِيثِهِ وَيَعُودَانِ فِي تِلْكَ الْمَقَالَةِ ‏.‏ وَفِي حَدِيثِ مَعْمَرٍ مَكَانَ هَذِهِ الْكَلِمَةِ فَلَمْ يَزَالاَ بِهِ ‏.‏', 'وحدثنا اسحاق بن ابراهيم، وعبد بن حميد، قالا اخبرنا عبد الرزاق، اخبرنا معمر، ح وحدثنا حسن الحلواني، وعبد بن حميد، قالا حدثنا يعقوب، - وهو ابن ابراهيم بن سعد - قال حدثني ابي، عن صالح، كلاهما عن الزهري، بهذا الاسناد مثله غير ان حديث صالح انتهي عند قوله فانزل الله عز وجل فيه ‏.‏ ولم يذكر الايتين ‏.‏ وقال في حديثه ويعودان في تلك المقاله ‏.‏ وفي حديث معمر مكان هذه الكلمه فلم يزالا به ‏.‏', 'The same hadith is mentioned through a different chain except it ends where it mentions that Allah revealed the verses and it does not mention the verses. There is also a slight variation in words', NULL, 'c3e65309b80080ed58acaa720565a44360025a7c40e5d13d8fe5605ccc29e759', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (99, 'muslim', 100, 134, 'Book 1, Hadith 41', 25, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ عَبَّادٍ، وَابْنُ أَبِي عُمَرَ، قَالاَ حَدَّثَنَا مَرْوَانُ، عَنْ يَزِيدَ، - وَهُوَ ابْنُ كَيْسَانَ - عَنْ أَبِي حَازِمٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم', 'لِعَمِّهِ عِنْدَ الْمَوْتِ ‏"‏ قُلْ لاَ إِلَهَ إِلاَّ اللَّهُ أَشْهَدُ لَكَ بِهَا يَوْمَ الْقِيَامَةِ ‏"‏ ‏.‏ فَأَبَى فَأَنْزَلَ اللَّهُ ‏{‏ إِنَّكَ لاَ تَهْدِي مَنْ أَحْبَبْتَ‏}‏ الآيَةَ ‏.‏', 'لعمه عند الموت ‏"‏ قل لا اله الا الله اشهد لك بها يوم القيامه ‏"‏ ‏.‏ فابي فانزل الله ‏{‏ انك لا تهدي من احببت‏}‏ الايه ‏.‏', 'It is narrated on the authority of Abu Huraira that the Messenger of Allah said to his uncle at the time of his death:Make a profession of it that there is no god but Allah and I will bear testimony (of your being a Muslim) on the Day of judgment. But he (Abu Talib) refused to do so. Then Allah revealed this verse: " Verily thou canst not guide to the right path whom thou lovest. And it is Allah Who guideth whom He will and He knoweth best who are the guided" (xxviii)', NULL, 'e9138c7dbb85a9cf4ba37c22d97682302915eb1ea8b7e507fc9a53ae3d17d21d', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (100, 'muslim', 100, 135, 'Book 1, Hadith 42', 25, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ حَاتِمِ بْنِ مَيْمُونٍ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، حَدَّثَنَا يَزِيدُ بْنُ كَيْسَانَ، عَنْ أَبِي حَازِمٍ الأَشْجَعِيِّ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم', 'لِعَمِّهِ ‏"‏ قُلْ لاَ إِلَهَ إِلاَّ اللَّهُ أَشْهَدُ لَكَ بِهَا يَوْمَ الْقِيَامَةِ ‏"‏ ‏.‏ قَالَ لَوْلاَ أَنْ تُعَيِّرَنِي قُرَيْشٌ يَقُولُونَ إِنَّمَا حَمَلَهُ عَلَى ذَلِكَ الْجَزَعُ لأَقْرَرْتُ بِهَا عَيْنَكَ فَأَنْزَلَ اللَّهُ ‏{‏ إِنَّكَ لاَ تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللَّهَ يَهْدِي مَنْ يَشَاءُ‏}‏', 'لعمه ‏"‏ قل لا اله الا الله اشهد لك بها يوم القيامه ‏"‏ ‏.‏ قال لولا ان تعيرني قريش يقولون انما حمله علي ذلك الجزع لاقررت بها عينك فانزل الله ‏{‏ انك لا تهدي من احببت ولكن الله يهدي من يشاء‏}‏', 'It is narrated on the authority of Abu Huraira that the Messenger of Allah said to his uncle (at the time of his death):Make a profession of it that there is no god but Allah and I will bear testimony (of your being a Muslim) on the Day of judgment. He (Abu Talib) said: Were it not the fear of the Quraysh blaming me (and) saying that it was the fear of (approaching death) that induced me to do so, I would have certainly delighted your eyes. It was then that Allah revealed: " Verily thou canst not guide to the right path whom thou lovest. And it is Allah Who guideth whom He will and He knoweth best who are the guided" (xxviii)', NULL, '9529c473f7ca8ede7e0057d7aea4682b4814ee770615ea3ea4f8dee4fbb574a9', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published')
INSERT INTO public.hadith_narrations (id, collection_id, book_id, hadith_number, in_book_reference, international_number, chapter_title_arabic, chapter_title_english, sanad_arabic, matn_arabic, matn_clean, translation_english, translation_urdu, text_checksum, source_edition, version_number, is_current, status) VALUES
  (101, 'muslim', 100, 136, 'Book 1, Hadith 43', 26, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَزُهَيْرُ بْنُ حَرْبٍ، كِلاَهُمَا عَنْ إِسْمَاعِيلَ بْنِ إِبْرَاهِيمَ، - قَالَ أَبُو بَكْرٍ حَدَّثَنَا ابْنُ عُلَيَّةَ، - عَنْ خَالِدٍ، قَالَ حَدَّثَنِي الْوَلِيدُ بْنُ مُسْلِمٍ، عَنْ حُمْرَانَ، عَنْ عُثْمَانَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ مَنْ مَاتَ وَهُوَ يَعْلَمُ أَنَّهُ لاَ إِلَهَ إِلاَّ اللَّهُ دَخَلَ الْجَنَّةَ ‏"‏ ‏.‏', '"‏ من مات وهو يعلم انه لا اله الا الله دخل الجنه ‏"‏ ‏.‏', 'It is narrated on the authority of ''Uthman that the Messenger of Allah (ﷺ) said. He who died knowing (fully well) that there is no god but Allah entered Paradise', NULL, '8b498d3e11b7fca53804e601d45af2d6347905e6ddd74c6e987b46ea1ce02659', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (102, 'muslim', 100, 137, 'Book 1, Hadith 44', 26, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ، حَدَّثَنَا بِشْرُ بْنُ الْمُفَضَّلِ، حَدَّثَنَا خَالِدٌ الْحَذَّاءُ، عَنِ الْوَلِيدِ أَبِي بِشْرٍ، قَالَ سَمِعْتُ حُمْرَانَ، يَقُولُ سَمِعْتُ عُثْمَانَ، يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ', 'مِثْلَهُ سَوَاءً ‏.‏', 'مثله سواء ‏.‏', 'It is narrated on the authority of Humran that he heard Uthman saying this:I heard the Messenger of Allah (ﷺ) uttering these words (as stated above)', NULL, 'b8fa828b0b62142b542d4d010c5c4e98a2c34b6c3336a5a48c84c4749aec4250', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (103, 'muslim', 100, 138, 'Book 1, Hadith 45', 27, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ النَّضْرِ بْنِ أَبِي النَّضْرِ، قَالَ حَدَّثَنِي أَبُو النَّضْرِ، هَاشِمُ بْنُ الْقَاسِمِ حَدَّثَنَا عُبَيْدُ اللَّهِ الأَشْجَعِيُّ، عَنْ مَالِكِ بْنِ مِغْوَلٍ، عَنْ طَلْحَةَ بْنِ مُصَرِّفٍ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ كُنَّا مَعَ النَّبِيِّ صلى الله عليه وسلم فِي مَسِيرٍ - قَالَ - فَنَفِدَتْ أَزْوَادُ الْقَوْمِ قَالَ حَتَّى هَمَّ بِنَحْرِ بَعْضِ حَمَائِلِهِمْ - قَالَ - فَقَالَ عُمَرُ يَا رَسُولَ اللَّهِ لَوْ جَمَعْتَ مَا بَقِيَ مِنْ أَزْوَادِ الْقَوْمِ فَدَعَوْتَ اللَّهَ عَلَيْهَا', '. قَالَ فَفَعَلَ - قَالَ - فَجَاءَ ذُو الْبُرِّ بِبُرِّهِ وَذُو التَّمْرِ بِتَمْرِهِ - قَالَ وَقَالَ مُجَاهِدٌ وَذُو النَّوَاةِ بِنَوَاهُ - قُلْتُ وَمَا كَانُوا يَصْنَعُونَ بِالنَّوَى قَالَ كَانُوا يَمُصُّونَهُ وَيَشْرَبُونَ عَلَيْهِ الْمَاءَ . قَالَ فَدَعَا عَلَيْهَا - قَالَ - حَتَّى مَلأَ الْقَوْمُ أَزْوِدَتَهُمْ - قَالَ - فَقَالَ عِنْدَ ذَلِكَ   أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنِّي رَسُولُ اللَّهِ لاَ يَلْقَى اللَّهَ بِهِمَا عَبْدٌ غَيْرَ شَاكٍّ فِيهِمَا إِلاَّ دَخَلَ الْجَنَّةَ  .', '. قال ففعل - قال - فجاء ذو البر ببره وذو التمر بتمره - قال وقال مجاهد وذو النواه بنواه - قلت وما كانوا يصنعون بالنوي قال كانوا يمصونه ويشربون عليه الماء . قال فدعا عليها - قال - حتي ملا القوم ازودتهم - قال - فقال عند ذلك اشهد ان لا اله الا الله واني رسول الله لا يلقي الله بهما عبد غير شاك فيهما الا دخل الجنه .', 'It is narrated on the authority of Abu Huraira:We were accompanying the Apostle (ﷺ) in a march (towards Tabuk). He (the narrator) said: The provisions with the people were almost depleted. He (the narrator) said: (And the situation became so critical) that they (the men of the army) decided to slaughter some of their camels. He (the narrator) said: Upon this Umar said: Messenger of Allah, I wish that you should pool together what has been left out of the provisions with the people and then invoke (the blessings of) Allah upon it. He (the narrator) said: He (the Holy Prophet) did it accordingly. He (the narrator) said: The one who had wheat in his possession came there with wheat. He who had dates with him came there with dates. And Mujahid said: He who possessed stones of dates came there with stones. I (the narrator) said: What did they do with the date-stones. They said: They (the people) sucked them and then drank water over them. He (the narrator said): He (the Holy Prophet) invoked the blessings (of Allah) upon them (provisions). He (the narrator) said: (And there was such a miraculous increase in the stocks) that the people replenished their provisions fully. He (the narrator) said: At that time he (the Holy Prophet) said: I bear testimony to the fact that there is no god but Allah, and I am His messenger. The bondsman who would meet Allah without entertaining any doubt about these (two fundamentals) would enter heaven', NULL, '8d3e72510151f517f8fac61ad2a3731763078302b2e1d3a3c77363e2fceb5570', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (104, 'muslim', 100, 139, 'Book 1, Hadith 46', 27, NULL, NULL, 'حَدَّثَنَا سَهْلُ بْنُ عُثْمَانَ، وَأَبُو كُرَيْبٍ مُحَمَّدُ بْنُ الْعَلاَءِ جَمِيعًا عَنْ أَبِي مُعَاوِيَةَ، - قَالَ أَبُو كُرَيْبٍ حَدَّثَنَا أَبُو مُعَاوِيَةَ، - عَنِ الأَعْمَشِ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ، أَوْ عَنْ أَبِي سَعِيدٍ، - شَكَّ الأَعْمَشُ - قَالَ لَمَّا كَانَ غَزْوَةُ تَبُوكَ أَصَابَ النَّاسَ مَجَاعَةٌ ‏.‏ قَالُوا يَا رَسُولَ اللَّهِ لَوْ أَذِنْتَ لَنَا فَنَحَرْنَا نَوَاضِحَنَا فَأَكَلْنَا وَادَّهَنَّا ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏', 'افْعَلُوا ‏"‏ ‏.‏ قَالَ فَجَاءَ عُمَرُ فَقَالَ يَا رَسُولَ اللَّهِ إِنْ فَعَلْتَ قَلَّ الظَّهْرُ وَلَكِنِ ادْعُهُمْ بِفَضْلِ أَزْوَادِهِمْ ثُمَّ ادْعُ اللَّهَ لَهُمْ عَلَيْهَا بِالْبَرَكَةِ لَعَلَّ اللَّهَ أَنْ يَجْعَلَ فِي ذَلِكَ ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏ نَعَمْ ‏"‏ ‏.‏ قَالَ فَدَعَا بِنِطَعٍ فَبَسَطَهُ ثُمَّ دَعَا بِفَضْلِ أَزْوَادِهِمْ - قَالَ - فَجَعَلَ الرَّجُلُ يَجِيءُ بِكَفِّ ذُرَةٍ - قَالَ - وَيَجِيءُ الآخَرُ بَكَفِّ تَمْرٍ - قَالَ - وَيَجِيءُ الآخَرُ بِكِسْرَةٍ حَتَّى اجْتَمَعَ عَلَى النِّطَعِ مِنْ ذَلِكَ شَىْءٌ يَسِيرٌ - قَالَ - فَدَعَا رَسُولُ اللَّهِ صلى الله عليه وسلم عَلَيْهِ بِالْبَرَكَةِ ثُمَّ قَالَ ‏"‏ خُذُوا فِي أَوْعِيَتِكُمْ ‏"‏ ‏.‏ قَالَ فَأَخَذُوا فِي أَوْعِيَتِهِمْ حَتَّى مَا تَرَكُوا فِي الْعَسْكَرِ وِعَاءً إِلاَّ مَلأُوهُ - قَالَ - فَأَكَلُوا حَتَّى شَبِعُوا وَفَضِلَتْ فَضْلَةٌ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنِّي رَسُولُ اللَّهِ لاَ يَلْقَى اللَّهَ بِهِمَا عَبْدٌ غَيْرَ شَاكٍّ فَيُحْجَبَ عَنِ الْجَنَّةِ ‏"‏ ‏.‏', 'افعلوا ‏"‏ ‏.‏ قال فجاء عمر فقال يا رسول الله ان فعلت قل الظهر ولكن ادعهم بفضل ازوادهم ثم ادع الله لهم عليها بالبركه لعل الله ان يجعل في ذلك ‏.‏ فقال رسول الله صلي الله عليه وسلم ‏"‏ نعم ‏"‏ ‏.‏ قال فدعا بنطع فبسطه ثم دعا بفضل ازوادهم - قال - فجعل الرجل يجيء بكف ذره - قال - ويجيء الاخر بكف تمر - قال - ويجيء الاخر بكسره حتي اجتمع علي النطع من ذلك شيء يسير - قال - فدعا رسول الله صلي الله عليه وسلم عليه بالبركه ثم قال ‏"‏ خذوا في اوعيتكم ‏"‏ ‏.‏ قال فاخذوا في اوعيتهم حتي ما تركوا في العسكر وعاء الا ملاوه - قال - فاكلوا حتي شبعوا وفضلت فضله فقال رسول الله صلي الله عليه وسلم ‏"‏ اشهد ان لا اله الا الله واني رسول الله لا يلقي الله بهما عبد غير شاك فيحجب عن الجنه ‏"‏ ‏.‏', 'It is narrated either on the authority of Abu Huraira or that of Abu Sa''id Khudri. The narrator A''mash has narrated this hadith with a little bit of doubt (about the name of the very first narrator who was in direct contact with the Holy Prophet. He was either Abu Huraira or Abu Sa''id Khudri. Both are equally reliable transmitters of the traditions). He (the narrator) said:During the time of Tabuk expedition, the (provisions) ran short and the men (of the army) suffered starvation; they said: Messenger of Allah, would you permit us to slay our camels? We would eat them and use their fat. The Messenger of Allah (ﷺ) said: Do as you please. He (the narrator) said: Then ''Umar came there and said: Messenger of Allah, if you do that (if you give your consent and the men begin to slay their camels), the riding animals would become short. But (I would suggest you to) summon them along with the provisions left with them Then invoke Allah''s blessings on them (different items of the provisions) It is hoped Allah shall bless them. The Messenger of Allah replied in the affirmative. (the narrator) said: He called for a leather mat to be used as a table cloth and spread it out. Then he called people along with the remaining portions of their provisions. He (the narrator) said: Someone was coming with handful of mote, another was coming with a handful of dates, still another was coming with a portion of bread, till small quantities of these things were collected on the table cloth. He (the narrator said): Then the messenger of Allah invoked blessing (on them) and said: Fill your utensils with these provisions. He (the narrator) said: They filled their vessel to the brim with them, and no one amongst the army (which comprised of 30,000 persons) was left even with a single empty vessel. He (the narrator) aid: They ate to their fill, and there was still a surplus. Upon this the Messenger of Allah (ﷺ) remarked: I bear testimony that there is no god but Allah and I am the messenger of Allah. The man who meets his Lord without harboring any doubt about these two (truths) would never be kept away from Paradise', NULL, '9f680044d4e5317770853a6324d478061ac6bb61f495219d1130a4beeab5686e', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (105, 'muslim', 100, 140, 'Book 1, Hadith 47', 28, NULL, NULL, 'حَدَّثَنَا دَاوُدُ بْنُ رُشَيْدٍ، حَدَّثَنَا الْوَلِيدُ، - يَعْنِي ابْنَ مُسْلِمٍ - عَنِ ابْنِ جَابِرٍ، قَالَ حَدَّثَنِي عُمَيْرُ بْنُ هَانِئٍ، قَالَ حَدَّثَنِي جُنَادَةُ بْنُ أَبِي أُمَيَّةَ، حَدَّثَنَا عُبَادَةُ بْنُ الصَّامِتِ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ مَنْ قَالَ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ وَأَنَّ عِيسَى عَبْدُ اللَّهِ وَابْنُ أَمَتِهِ وَكَلِمَتُهُ أَلْقَاهَا إِلَى مَرْيَمَ وَرُوحٌ مِنْهُ وَأَنَّ الْجَنَّةَ حَقٌّ وَأَنَّ النَّارَ حَقٌّ أَدْخَلَهُ اللَّهُ مِنْ أَىِّ أَبْوَابِ الْجَنَّةِ الثَّمَانِيَةِ شَاءَ ‏"‏ ‏.‏', '"‏ من قال اشهد ان لا اله الا الله وحده لا شريك له وان محمدا عبده ورسوله وان عيسي عبد الله وابن امته وكلمته القاها الي مريم وروح منه وان الجنه حق وان النار حق ادخله الله من اي ابواب الجنه الثمانيه شاء ‏"‏ ‏.‏', 'It is narrated on the authority of Ubadah b. Samit that the messenger of Allah (ﷺ) observed:He who said:" There is no god but Allah, He is One and there is no associate with Him, that Muhammad is his servant and His messenger, that Christ is servant and the son of His slave-girl and he (Christ) His word which He communicated to Mary and is His Spirit, that Paradise is a fact and Hell is a fact," Allah would make him (he who affirms these truths enter Paradise through any one of its eight doors which he would like)', NULL, '7a6cd4814bfb3b484469c73a6b9f1846f0c4b97dd780907d7d0676ef395ed20f', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (106, 'muslim', 100, 141, 'Book 1, Hadith 48', 28, NULL, NULL, NULL, 'وَحَدَّثَنِي أَحْمَدُ بْنُ إِبْرَاهِيمَ الدَّوْرَقِيُّ، حَدَّثَنَا مُبَشِّرُ بْنُ إِسْمَاعِيلَ، عَنِ الأَوْزَاعِيِّ، عَنْ عُمَيْرِ بْنِ هَانِئٍ، فِي هَذَا الإِسْنَادِ بِمِثْلِهِ غَيْرَ أَنَّهُ قَالَ ‏"‏ أَدْخَلَهُ اللَّهُ الْجَنَّةَ عَلَى مَا كَانَ مِنْ عَمَلٍ ‏"‏ ‏.‏ وَلَمْ يَذْكُرْ ‏"‏ مِنْ أَىِّ أَبْوَابِ الْجَنَّةِ الثَّمَانِيَةِ شَاءَ ‏"‏ ‏.‏', 'وحدثني احمد بن ابراهيم الدورقي، حدثنا مبشر بن اسماعيل، عن الاوزاعي، عن عمير بن هانئ، في هذا الاسناد بمثله غير انه قال ‏"‏ ادخله الله الجنه علي ما كان من عمل ‏"‏ ‏.‏ ولم يذكر ‏"‏ من اي ابواب الجنه الثمانيه شاء ‏"‏ ‏.‏', 'It is narrated on the authority of Umar b. Hani with the same chain of transmitters with the exception of these words:Allah would make him (he who affirms these truths) enter Paradise through one of the eight doors which he would like', NULL, '3e136d1328e7704237b6814e0eaeec42af1228a4cf996cb88da57434e2d44228', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (107, 'muslim', 100, 142, 'Book 1, Hadith 49', 29, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا لَيْثٌ، عَنِ ابْنِ عَجْلاَنَ، عَنْ مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ، عَنِ ابْنِ مُحَيْرِيزٍ، عَنِ الصُّنَابِحِيِّ، عَنْ عُبَادَةَ بْنِ الصَّامِتِ، أَنَّهُ قَالَ دَخَلْتُ عَلَيْهِ وَهُوَ فِي الْمَوْتِ فَبَكَيْتُ فَقَالَ مَهْلاً لِمَ تَبْكِي فَوَاللَّهِ لَئِنِ اسْتُشْهِدْتُ لأَشْهَدَنَّ لَكَ وَلَئِنْ شُفِّعْتُ لأَشْفَعَنَّ لَكَ وَلَئِنِ اسْتَطَعْتُ لأَنْفَعَنَّكَ ثُمَّ قَالَ وَاللَّهِ مَا مِنْ حَدِيثٍ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم لَكُمْ فِيهِ خَيْرٌ إِلاَّ حَدَّثْتُكُمُوهُ إِلاَّ حَدِيثًا وَاحِدًا وَسَوْفَ أُحَدِّثُكُمُوهُ الْيَوْمَ وَقَدْ أُحِيطَ بِنَفْسِي سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏', '"‏ مَنْ شَهِدَ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ حَرَّمَ اللَّهُ عَلَيْهِ النَّارَ ‏"‏ ‏.‏', '"‏ من شهد ان لا اله الا الله وان محمدا رسول الله حرم الله عليه النار ‏"‏ ‏.‏', 'It is narrated on the authority of Sunabihi that he went to Ubada b. Samit when he was about to die. I burst into tears. Upon this he said to me:Allow me some time (so that I may talk with you). Why do you weep? By Allah, if I am asked to bear witness, I would certainly testify for you (that you are a believer). Should I be asked to intercede, I would certainly intercede for you, and if I have the power, I would certainly do good to you, and then observed: By Allah, never did I hear anything from the Messenger of Allah (ﷺ) which could have been a source of benefit to you and then not conveyed it to you except this single hadith. That I intend to narrate to you today, since I am going to breathe my last. I heard the Messenger of Allah (ﷺ) say: He who testifies that there is no god but Allah and that Muhammad is the messenger of Allah, Allah would prohibit the fire of Hell for him', NULL, 'caf6773228d497a7b04af2ce7b55ca0a36a9e0456a9a404e29fc3145dc2cc152', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (108, 'muslim', 100, 143, 'Book 1, Hadith 50', 30, NULL, NULL, 'حَدَّثَنَا هَدَّابُ بْنُ خَالِدٍ الأَزْدِيُّ، حَدَّثَنَا هَمَّامٌ، حَدَّثَنَا قَتَادَةُ، حَدَّثَنَا أَنَسُ بْنُ مَالِكٍ، عَنْ مُعَاذِ بِْ جَبَلٍ، قَالَ كُنْتُ رِدْفَ النَّبِيِّ صلى الله عليه وسلم لَيْسَ بَيْنِي وَبَيْنَهُ إِلاَّ مُؤْخِرَةُ الرَّحْلِ فَقَالَ', 'يَا مُعَاذَ بْنَ جَبَلٍ  . قُلْتُ لَبَّيْكَ رَسُولَ اللَّهِ وَسَعْدَيْكَ . ثُمَّ سَارَ سَاعَةً ثُمَّ قَالَ  يَا مُعَاذَ بْنَ جَبَلٍ  . قُلْتُ لَبَّيْكَ رَسُولَ اللَّهِ وَسَعْدَيْكَ . ثُمَّ سَارَ سَاعَةَ ثُمَّ قَالَ  يَا مُعَاذَ بْنَ جَبَلٍ  . قُلْتُ لَبَّيْكَ رَسُولَ اللَّهِ وَسَعْدَيْكَ . قَالَ  هَلْ تَدْرِي مَا حَقُّ اللَّهِ عَلَى الْعِبَادِ  . قَالَ قُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ . قَالَ  فَإِنَّ حَقَّ اللَّهِ عَلَى الْعِبَادِ أَنْ يَعْبُدُوهُ وَلاَ يُشْرِكُوا بِهِ شَيْئًا  . ثُمَّ سَارَ سَاعَةً ثُمَّ قَالَ  يَا مُعَاذَ بْنَ جَبَلٍ  . قُلْتُ لَبَّيْكَ رَسُولَ اللَّهِ وَسَعْدَيْكَ . قَالَ  هَلْ تَدْرِي مَا حَقُّ الْعِبَادِ عَلَى اللَّهِ إِذَا فَعَلُوا ذَلِكَ  . قَالَ قُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ . قَالَ  أَنْ لاَ يُعَذِّبَهُمْ  .', 'يا معاذ بن جبل . قلت لبيك رسول الله وسعديك . ثم سار ساعه ثم قال يا معاذ بن جبل . قلت لبيك رسول الله وسعديك . ثم سار ساعه ثم قال يا معاذ بن جبل . قلت لبيك رسول الله وسعديك . قال هل تدري ما حق الله علي العباد . قال قلت الله ورسوله اعلم . قال فان حق الله علي العباد ان يعبدوه ولا يشركوا به شيئا . ثم سار ساعه ثم قال يا معاذ بن جبل . قلت لبيك رسول الله وسعديك . قال هل تدري ما حق العباد علي الله اذا فعلوا ذلك . قال قلت الله ورسوله اعلم . قال ان لا يعذبهم .', 'It is narrated on the authority of Mu''adh b. Jabal:I was riding behind the Prophet (ﷺ) and there was nothing between him and me but the rear part of the saddle, when he said: Mu''adh b. Jabal: To which I replied: At your beck and call, and at your pleasure, Messenger of Allah! He moved along for a few minutes, when again he said: Mu''adh b. Jabal: To which I replied: At your beck and call, and at your pleasure, Messenger of Allah! He then again moved along for a few minutes and said: Mu''adh b. Jabal: To which I replied. At your beck and call, and at your pleasure. Messenger of Allah He, (the Holy Prophet) said: Do you know what right has Allah upon His servants? I said: Allah and His Messenger know best. He (the Holy Prophet) said: Verily the right of Allah over His servants is that they should worship Him, not associating anything with Him. He (the Holy Prophet) with Mu''adh behind him, moved along for a few minutes and said: Mu''adh b. Jabal: To which I replied: At your beck and call, and at your pleasure, Messenger of Allah! He (the Holy Prophet) said: Do you know what rights have servants upon Allah in case they do it (i. e. they worship Allah without associating anything with Him)? I (Mu''adh b. Jabal) replied: Allah and His Messenger know best. (Upon this) he (the Holy Prophet) remarked: That He would not torment them (with the fire of Hell)', NULL, 'f137b8463275c70d209eadf9f5adc8806924d3d86de61725bf350193287c6190', 'MUSLIM Darussalam Reference Edition', 1, TRUE, 'published'),
  (109, 'tirmidhi', 157, 1, 'Book 1, Hadith 1', 1, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ سِمَاكِ بْنِ حَرْبٍ، ح وَحَدَّثَنَا هَنَّادٌ، حَدَّثَنَا وَكِيعٌ، عَنْ إِسْرَائِيلَ، عَنْ سِمَاكٍ، عَنْ مُصْعَبِ بْنِ سَعْدٍ، عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏"‏', 'لاَ تُقْبَلُ صَلاَةٌ بِغَيْرِ طُهُورٍ وَلاَ صَدَقَةٌ مِنْ غُلُولٍ ‏"‏ ‏.‏ قَالَ هَنَّادٌ فِي حَدِيثِهِ ‏"‏ إِلاَّ بِطُهُورٍ ‏"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا الْحَدِيثُ أَصَحُّ شَيْءٍ فِي هَذَا الْبَابِ وَأَحْسَنُ ‏.‏ وَفِي الْبَابِ عَنْ أَبِي الْمَلِيحِ عَنْ أَبِيهِ وَأَبِي هُرَيْرَةَ وَأَنَسٍ ‏.‏ وَأَبُو الْمَلِيحِ بْنُ أُسَامَةَ اسْمُهُ عَامِرٌ وَيُقَالُ زَيْدُ بْنُ أُسَامَةَ بْنِ عُمَيْرٍ الْهُذَلِيُّ ‏.‏', 'لا تقبل صلاه بغير طهور ولا صدقه من غلول ‏"‏ ‏.‏ قال هناد في حديثه ‏"‏ الا بطهور ‏"‏ ‏.‏ قال ابو عيسي هذا الحديث اصح شيء في هذا الباب واحسن ‏.‏ وفي الباب عن ابي المليح عن ابيه وابي هريره وانس ‏.‏ وابو المليح بن اسامه اسمه عامر ويقال زيد بن اسامه بن عمير الهذلي ‏.‏', 'Ibn `Umar narrated that:the Prophet said: "Salat will not be accepted without purification, nor Charity from Ghulul." Hannad said in his narration, "except with purification" [Abu `Eisa said: This Hadith is the most correct thing on this topic, and the best. There are also narrations on this topic from Abu Al-Malih, from his father; and Abu Hurairah and Anas. And Abu Al-Malih bin Usamah''s name is `Amir, and they also say it was Zaid bin Usamah bin `Umair Al-Hudhali]', NULL, '9ea9460d521e4a3edcbbb71f5beef9d9ae73d475a286ee801bef5b28dd9bcb0b', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (110, 'tirmidhi', 157, 2, 'Book 1, Hadith 2', 2, NULL, NULL, 'حَدَّثَنَا إِسْحَاقُ بْنُ مُوسَى الأَنْصَارِيُّ، حَدَّثَنَا مَعْنُ بْنُ عِيسَى الْقَزَّازُ، حَدَّثَنَا مَالِكُ بْنُ أَنَسٍ، ح وَحَدَّثَنَا قُتَيْبَةُ، عَنْ مَالِكٍ، عَنْ سُهَيْلِ بْنِ أَبِي صَالِحٍ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏', 'إِذَا تَوَضَّأَ الْعَبْدُ الْمُسْلِمُ أَوِ الْمُؤْمِنُ فَغَسَلَ وَجْهَهُ خَرَجَتْ مِنْ وَجْهِهِ كُلُّ خَطِيئَةٍ نَظَرَ إِلَيْهَا بِعَيْنَيْهِ مَعَ الْمَاءِ أَوْ مَعَ آخِرِ قَطْرِ الْمَاءِ أَوْ نَحْوِ هَذَا وَإِذَا غَسَلَ يَدَيْهِ خَرَجَتْ مِنْ يَدَيْهِ كُلُّ خَطِيئَةٍ بَطَشَتْهَا يَدَاهُ مَعَ الْمَاءِ أَوْ مَعَ آخِرِ قَطْرِ الْمَاءِ حَتَّى يَخْرُجَ نَقِيًّا مِنَ الذُّنُوبِ ‏"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ وَهُوَ حَدِيثُ مَالِكٍ عَنْ سُهَيْلٍ عَنْ أَبِيهِ عَنْ أَبِي هُرَيْرَةَ ‏.‏ وَأَبُو صَالِحٍ وَالِدُ سُهَيْلٍ هُوَ أَبُو صَالِحٍ السَّمَّانُ وَاسْمُهُ ذَكْوَانُ ‏.‏ وَأَبُو هُرَيْرَةَ اخْتُلِفَ فِي اسْمِهِ فَقَالُوا عَبْدُ شَمْسٍ وَقَالُوا عَبْدُ اللَّهِ بْنُ عَمْرٍو وَهَكَذَا قَالَ مُحَمَّدُ بْنُ إِسْمَاعِيلَ وَهُوَ الأَصَحُّ ‏.‏ قَالَ أَبُو عِيسَى وَفِي الْبَابِ عَنْ عُثْمَانَ بْنِ عَفَّانَ وَثَوْبَانَ وَالصُّنَابِحِيِّ وَعَمْرِو بْنِ عَبَسَةَ وَسَلْمَانَ وَعَبْدِ اللَّهِ بْنِ عَمْرٍو ‏.‏ وَالصُّنَابِحِيُّ الَّذِي رَوَى عَنْ أَبِي بَكْرٍ الصِّدِّيقِ لَيْسَ لَهُ سَمَاعٌ مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم وَاسْمُهُ عَبْدُ الرَّحْمَنِ بْنُ عُسَيْلَةَ وَيُكْنَى أَبَا عَبْدِ اللَّهِ رَحَلَ إِلَى النَّبِيِّ صلى الله عليه وسلم فَقُبِضَ النَّبِيُّ صلى الله عليه وسلم وَهُوَ فِي الطَّرِيقِ وَقَدْ رَوَى عَنِ النَّبِيِّ صلى الله عليه وسلم أَحَادِيثَ ‏.‏ وَالصُّنَابِحُ بْنُ الأَعْسَرِ الأَحْمَسِيُّ صَاحِبُ النَّبِيِّ صلى الله عليه وسلم يُقَالُ لَهُ الصُّنَابِحِيُّ أَيْضًا وَإِنَّمَا حَدِيثُهُ قَالَ سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَقُولُ ‏"‏ إِنِّي مُكَاثِرٌ بِكُمُ الأُمَمَ فَلاَ تَقْتَتِلُنَّ بَعْدِي ‏"‏ ‏.‏', 'اذا توضا العبد المسلم او المؤمن فغسل وجهه خرجت من وجهه كل خطيئه نظر اليها بعينيه مع الماء او مع اخر قطر الماء او نحو هذا واذا غسل يديه خرجت من يديه كل خطيئه بطشتها يداه مع الماء او مع اخر قطر الماء حتي يخرج نقيا من الذنوب ‏"‏ ‏.‏ قال ابو عيسي هذا حديث حسن صحيح وهو حديث مالك عن سهيل عن ابيه عن ابي هريره ‏.‏ وابو صالح والد سهيل هو ابو صالح السمان واسمه ذكوان ‏.‏ وابو هريره اختلف في اسمه فقالوا عبد شمس وقالوا عبد الله بن عمرو وهكذا قال محمد بن اسماعيل وهو الاصح ‏.‏ قال ابو عيسي وفي الباب عن عثمان بن عفان وثوبان والصنابحي وعمرو بن عبسه وسلمان وعبد الله بن عمرو ‏.‏ والصنابحي الذي روي عن ابي بكر الصديق ليس له سماع من رسول الله صلي الله عليه وسلم واسمه عبد الرحمن بن عسيله ويكني ابا عبد الله رحل الي النبي صلي الله عليه وسلم فقبض النبي صلي الله عليه وسلم وهو في الطريق وقد روي عن النبي صلي الله عليه وسلم احاديث ‏.‏ والصنابح بن الاعسر الاحمسي صاحب النبي صلي الله عليه وسلم يقال له الصنابحي ايضا وانما حديثه قال سمعت النبي صلي الله عليه وسلم يقول ‏"‏ اني مكاثر بكم الامم فلا تقتتلن بعدي ‏"‏ ‏.‏', 'Abu Hurairah narrated that :Allah''s Messenger said: "When a Muslim, or believer, performs Wudu'', washing his face, every evil that he looked at with his eyes leaves with the water - or with the last drop of water, or an expression similar to that - and when he washes his hands, every evil he did with his hands leaves with the water - or with the last drop of water - until he becomes free of sin', NULL, 'ee7f66fe333f127814bd4f08e3a567b9f090d8b846b0e893db11eb32493ddcf9', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (111, 'tirmidhi', 157, 3, 'Book 1, Hadith 3', 3, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ، وَهَنَّادٌ، وَمَحْمُودُ بْنُ غَيْلاَنَ، قَالُوا حَدَّثَنَا وَكِيعٌ، عَنْ سُفْيَانَ، ح وَحَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ، حَدَّثَنَا سُفْيَانُ، عَنْ عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ، عَنْ مُحَمَّدِ ابْنِ الْحَنَفِيَّةِ، عَنْ عَلِيٍّ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ مِفْتَاحُ الصَّلاَةِ الطُّهُورُ وَتَحْرِيمُهَا التَّكْبِيرُ وَتَحْلِيلُهَا التَّسْلِيمُ ‏"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا الْحَدِيثُ أَصَحُّ شَيْءٍ فِي هَذَا الْبَابِ وَأَحْسَنُ ‏.‏ وَعَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلٍ هُوَ صَدُوقٌ وَقَدْ تَكَلَّمَ فِيهِ بَعْضُ أَهْلِ الْعِلْمِ مِنْ قِبَلِ حِفْظِهِ ‏.‏ قَالَ أَبُو عِيسَى وَسَمِعْتُ مُحَمَّدَ بْنَ إِسْمَاعِيلَ يَقُولُ كَانَ أَحْمَدُ بْنُ حَنْبَلٍ وَإِسْحَاقُ بْنُ إِبْرَاهِيمَ وَالْحُمَيْدِيُّ يَحْتَجُّونَ بِحَدِيثِ عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏.‏ قَالَ مُحَمَّدٌ وَهُوَ مُقَارِبُ الْحَدِيثِ ‏.‏ قَالَ أَبُو عِيسَى وَفِي الْبَابِ عَنْ جَابِرٍ وَأَبِي سَعِيدٍ ‏.‏', '"‏ مفتاح الصلاه الطهور وتحريمها التكبير وتحليلها التسليم ‏"‏ ‏.‏ قال ابو عيسي هذا الحديث اصح شيء في هذا الباب واحسن ‏.‏ وعبد الله بن محمد بن عقيل هو صدوق وقد تكلم فيه بعض اهل العلم من قبل حفظه ‏.‏ قال ابو عيسي وسمعت محمد بن اسماعيل يقول كان احمد بن حنبل واسحاق بن ابراهيم والحميدي يحتجون بحديث عبد الله بن محمد بن عقيل ‏.‏ قال محمد وهو مقارب الحديث ‏.‏ قال ابو عيسي وفي الباب عن جابر وابي سعيد ‏.‏', 'Ali narrated that :the Prophet, said: "The key to Salat is the purification, its Tahrlm is the Takblr, and its Tahlil is the Taslim', NULL, '8ca9231aa2653456b0cd22f7cb23e6a32e96cceae61fdd40bcd85b97da322ca9', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (112, 'tirmidhi', 157, 4, 'Book 1, Hadith 4', 4, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرٍ، مُحَمَّدُ بْنُ زَنْجَوَيْهِ الْبَغْدَادِيُّ وَغَيْرُ وَاحِدٍ قَالَ حَدَّثَنَا الْحُسَيْنُ بْنُ مُحَمَّدٍ، حَدَّثَنَا سُلَيْمَانُ بْنُ قَرْمٍ، عَنْ أَبِي يَحْيَى الْقَتَّاتِ، عَنْ مُجَاهِدٍ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، رضى الله عنهما قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ مِفْتَاحُ الْجَنَّةِ الصَّلاَةُ وَمِفْتَاحُ الصَّلاَةِ الْوُضُوءُ ‏"‏ ‏.‏', '"‏ مفتاح الجنه الصلاه ومفتاح الصلاه الوضوء ‏"‏ ‏.‏', 'Jabir bin ''Abdullah, may Allah be pleased with them, narrated that :Allah''s Messenger said: "The key to Paradise is Salat, and the key to Salat is Wudu', NULL, 'd4df4ef281daec8a01f3dedbd12b0a85e05bc09f586d6c23e85f7484a4dfd421', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (113, 'tirmidhi', 157, 5, 'Book 1, Hadith 5', 5, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ، وَهَنَّادٌ، قَالاَ حَدَّثَنَا وَكِيعٌ، عَنْ شُعْبَةَ، عَنْ عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ، عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا دَخَلَ الْخَلاَءَ قَالَ ‏ "‏ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ قَالَ شُعْبَةُ وَقَدْ قَالَ مَرَّةً أُخْرَى أَعُوذُ بِكَ مِنَ الْخُبْثِ وَالْخَبِيثِ أَوِ الْخُبُثِ وَالْخَبَائِثِ ‏"‏ ‏.‏ قَالَ أَبُو عِيسَى وَفِي الْبَابِ عَنْ عَلِيٍّ وَزَيْدِ بْنِ أَرْقَمَ وَجَابِرٍ وَابْنِ مَسْعُودٍ ‏.‏ قَالَ أَبُو عِيسَى حَدِيثُ أَنَسٍ أَصَحُّ شَيْءٍ فِي هَذَا الْبَابِ وَأَحْسَنُ ‏.‏ وَحَدِيثُ زَيْدِ بْنِ أَرْقَمَ فِي إِسْنَادِهِ اضْطِرَابٌ رَوَى هِشَامٌ الدَّسْتَوَائِيُّ وَسَعِيدُ بْنُ أَبِي عَرُوبَةَ عَنْ قَتَادَةَ فَقَالَ سَعِيدٌ عَنِ الْقَاسِمِ بْنِ عَوْفٍ الشَّيْبَانِيِّ عَنْ زَيْدِ بْنِ أَرْقَمَ ‏.‏ وَقَالَ هِشَامٌ الدَّسْتَوَائِيُّ عَنْ قَتَادَةَ عَنْ زَيْدِ بْنِ أَرْقَمَ ‏.‏ وَرَوَاهُ شُعْبَةُ وَمَعْمَرٌ عَنْ قَتَادَةَ عَنِ النَّضْرِ بْنِ أَنَسٍ فَقَالَ شُعْبَةُ عَنْ زَيْدِ بْنِ أَرْقَمَ ‏.‏ وَقَالَ مَعْمَرٌ عَنِ النَّضْرِ بْنِ أَنَسٍ عَنْ أَبِيهِ عَنِ النَّبِيِّ صلى الله عليه وسلم ‏', '.‏ قَالَ أَبُو عِيسَى سَأَلْتُ مُحَمَّدًا عَنْ هَذَا فَقَالَ يُحْتَمَلُ أَنْ يَكُونَ قَتَادَةُ رَوَى عَنْهُمَا جَمِيعًا ‏.‏', '.‏ قال ابو عيسي سالت محمدا عن هذا فقال يحتمل ان يكون قتاده روي عنهما جميعا ‏.‏', 'Anas bin Malik said:"When the Prophet entered the toilet he would say: ''O Allah Indeed I seek refuge in You.''" Shu''bah (one of the narrators) said: "Another time he said: ''I seek refuge in You from AI-Khubthi and al-Khablth.'' Or: ''Al-Khubthi and Al-Khaba''ith', NULL, 'c4600497f5bc8664c967cba646105aabc1430f316d306c718501e032e00ca2fd', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (114, 'tirmidhi', 157, 6, 'Book 1, Hadith 6', 6, NULL, NULL, 'أَخْبَرَنَا أَحْمَدُ بْنُ عَبْدَةَ الضَّبِّيُّ الْبَصْرِيُّ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ، عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'كَانَ إِذَا دَخَلَ الْخَلاَءَ قَالَ ‏ "‏ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبْثِ وَالْخَبَائِثِ ‏"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏', 'كان اذا دخل الخلاء قال ‏ "‏ اللهم اني اعوذ بك من الخبث والخبائث ‏"‏ ‏.‏ قال ابو عيسي هذا حديث حسن صحيح ‏.‏', 'Anas bin Malik said:"When the Prophet would enter the toilet ''He said: "O Allah! Indeed I seek refuge in You from Al-Khubith and Al- Khaba''ith', NULL, 'c65aa162e37ea4e211c362d2cc5d30e599f6cfc498a30e332205429168cfa4df', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (115, 'tirmidhi', 157, 7, 'Book 1, Hadith 7', 7, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ إِسْمَاعِيلَ، حَدَّثَنَا مَالِكُ بْنُ إِسْمَاعِيلَ، عَنْ إِسْرَائِيلَ بْنِ يُونُسَ، عَنْ يُوسُفَ بْنِ أَبِي بُرْدَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، رضى الله عنها قَالَتْ كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا خَرَجَ مِنَ الْخَلاَءِ قَالَ ‏ "‏ غُفْرَانَكَ ‏"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ لاَ نَعْرِفُهُ إِلاَّ مِنْ حَدِيثِ إِسْرَائِيلَ عَنْ يُوسُفَ بْنِ أَبِي بُرْدَةَ ‏.‏ وَأَبُو بُرْدَةَ بْنُ أَبِي مُوسَى اسْمُهُ عَامِرُ بْنُ عَبْدِ اللَّهِ بْنِ قَيْسٍ الأَشْعَرِيُّ ‏.‏ وَلاَ نَعْرِفُ فِي هَذَا الْبَابِ إِلاَّ حَدِيثَ عَائِشَةَ رضى الله عنها عَنِ النَّبِيِّ صلى الله عليه وسلم ‏', '.‏', '.‏', 'Aishah, [may Allah be pleased with her] said:"When the Prophet would exit the toilet he would say: ''Ghufranak', NULL, 'deb1860477f9d3decf01edc0cfbecd57dbb43c8f35e8be68cc55d4bcf9bf9441', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (116, 'tirmidhi', 157, 8, 'Book 1, Hadith 8', 8, NULL, NULL, 'حَدَّثَنَا سَعِيدُ بْنُ عَبْدِ الرَّحْمَنِ الْمَخْزُومِيُّ، حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنِ الزُّهْرِيِّ، عَنْ عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ، عَنْ أَبِي أَيُّوبَ الأَنْصَارِيِّ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏', 'إِذَا أَتَيْتُمُ الْغَائِطَ فَلاَ تَسْتَقْبِلُوا الْقِبْلَةَ بِغَائِطٍ وَلاَ بَوْلٍ وَلاَ تَسْتَدْبِرُوهَا وَلَكِنْ شَرِّقُوا أَوْ غَرِّبُوا ‏"‏ ‏.‏ فَقَالَ أَبُو أَيُّوبَ َقَدِمْنَا الشَّأْمَ فَوَجَدْنَا مَرَاحِيضَ قَدْ بُنِيَتْ مُسْتَقْبَلَ الْقِبْلَةِ فَنَنْحَرِفُ عَنْهَا وَنَسْتَغْفِرُ اللَّهَ ‏.‏ قَالَ أَبُو عِيسَى وَفِي الْبَابِ عَنْ عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ جَزْءٍ الزُّبَيْدِيِّ وَمَعْقِلِ بْنِ أَبِي الْهَيْثَمِ وَيُقَالُ مَعْقِلُ بْنُ أَبِي مَعْقِلٍ وَأَبِي أُمَامَةَ وَأَبِي هُرَيْرَةَ وَسَهْلِ بْنِ حُنَيْفٍ ‏.‏ قَالَ أَبُو عِيسَى حَدِيثُ أَبِي أَيُّوبَ أَحْسَنُ شَيْءٍ فِي هَذَا الْبَابِ وَأَصَحُّ ‏.‏ وَأَبُو أَيُّوبَ اسْمُهُ خَالِدُ بْنُ زَيْدٍ ‏.‏ وَالزُّهْرِيُّ اسْمُهُ مُحَمَّدُ بْنُ مُسْلِمِ بْنِ عُبَيْدِ اللَّهِ بْنِ شِهَابٍ الزُّهْرِيُّ وَكُنْيَتُهُ أَبُو بَكْرٍ ‏.‏ قَالَ أَبُو الْوَلِيدِ الْمَكِّيُّ قَالَ أَبُو عَبْدِ اللَّهِ مُحَمَّدُ بْنُ إِدْرِيسَ الشَّافِعِيُّ إِنَّمَا مَعْنَى قَوْلِ النَّبِيِّ صلى الله عليه وسلم ‏"‏ لاَ تَسْتَقْبِلُوا الْقِبْلَةَ بِغَائِطٍ وَلاَ بِبَوْلٍ وَلاَ تَسْتَدْبِرُوهَا ‏"‏ ‏.‏ إِنَّمَا هَذَا فِي الْفَيَافِي وَأَمَّا فِي الْكُنُفِ الْمَبْنِيَّةِ لَهُ رُخْصَةٌ فِي أَنْ يَسْتَقْبِلَهَا ‏.‏ وَهَكَذَا قَالَ إِسْحَاقُ بْنُ إِبْرَاهِيمَ ‏.‏ وَقَالَ أَحْمَدُ بْنُ حَنْبَلٍ رَحِمَهُ اللَّهُ إِنَّمَا الرُّخْصَةُ مِنَ النَّبِيِّ صلى الله عليه وسلم فِي اسْتِدْبَارِ الْقِبْلَةِ بِغَائِطٍ أَوْ بَوْلٍ وَأَمَّا اسْتِقْبَالُ الْقِبْلَةِ فَلاَ يَسْتَقْبِلُهَا ‏.‏ كَأَنَّهُ لَمْ يَرَ فِي الصَّحْرَاءِ وَلاَ فِي الْكُنُفِ أَنْ يَسْتَقْبِلَ الْقِبْلَةَ ‏.‏', 'اذا اتيتم الغائط فلا تستقبلوا القبله بغائط ولا بول ولا تستدبروها ولكن شرقوا او غربوا ‏"‏ ‏.‏ فقال ابو ايوب قدمنا الشام فوجدنا مراحيض قد بنيت مستقبل القبله فننحرف عنها ونستغفر الله ‏.‏ قال ابو عيسي وفي الباب عن عبد الله بن الحارث بن جزء الزبيدي ومعقل بن ابي الهيثم ويقال معقل بن ابي معقل وابي امامه وابي هريره وسهل بن حنيف ‏.‏ قال ابو عيسي حديث ابي ايوب احسن شيء في هذا الباب واصح ‏.‏ وابو ايوب اسمه خالد بن زيد ‏.‏ والزهري اسمه محمد بن مسلم بن عبيد الله بن شهاب الزهري وكنيته ابو بكر ‏.‏ قال ابو الوليد المكي قال ابو عبد الله محمد بن ادريس الشافعي انما معني قول النبي صلي الله عليه وسلم ‏"‏ لا تستقبلوا القبله بغائط ولا ببول ولا تستدبروها ‏"‏ ‏.‏ انما هذا في الفيافي واما في الكنف المبنيه له رخصه في ان يستقبلها ‏.‏ وهكذا قال اسحاق بن ابراهيم ‏.‏ وقال احمد بن حنبل رحمه الله انما الرخصه من النبي صلي الله عليه وسلم في استدبار القبله بغائط او بول واما استقبال القبله فلا يستقبلها ‏.‏ كانه لم ير في الصحراء ولا في الكنف ان يستقبل القبله ‏.‏', 'Abu Ayyub Al-Ansari narrated that :Allah''s Messenger said: "When one of you arrives to defecate, then let none of you face the Qiblah while defecating, nor while urinating. And do not have your back towards it, but have it east of you or west of you', NULL, '8bb603060ea20068f5535e7cebc525d7a873da3fc0350b4c49654c32b9dbf143', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (117, 'tirmidhi', 157, 9, 'Book 1, Hadith 9', 9, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، وَمُحَمَّدُ بْنُ الْمُثَنَّى، قَالاَ حَدَّثَنَا وَهْبُ بْنُ جَرِيرٍ، حَدَّثَنَا أَبِي، عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ، عَنْ أَبَانَ بْنِ صَالِحٍ، عَنْ مُجَاهِدٍ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ نَهَى النَّبِيُّ صلى الله عليه وسلم أَنْ نَسْتَقْبِلَ الْقِبْلَةَ بِبَوْلٍ فَرَأَيْتُهُ قَبْلَ أَنْ يُقْبَضَ بِعَامٍ يَسْتَقْبِلُهَا', '. وَفِي الْبَابِ عَنْ أَبِي قَتَادَةَ وَعَائِشَةَ وَعَمَّارِ بْنِ يَاسِرٍ . قَالَ أَبُو عِيسَى حَدِيثُ جَابِرٍ فِي هَذَا الْبَابِ حَدِيثٌ حَسَنٌ غَرِيبٌ .', '. وفي الباب عن ابي قتاده وعائشه وعمار بن ياسر . قال ابو عيسي حديث جابر في هذا الباب حديث حسن غريب .', 'Jabir bin Abdullah said:"The Prophet prohibited us from facing the Qiblah while urinating. Then i saw him facing it a year before he died', NULL, '7cccfb36521503e5d5e4593836fa431bac2bfd5f2f10c02bb838671a1fe11ba3', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (118, 'tirmidhi', 157, 10, 'Book 1, Hadith 10', 10, NULL, NULL, 'وَقَدْ رَوَى هَذَا الْحَدِيثَ ابْنُ لَهِيعَةَ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرٍ، عَنْ أَبِي قَتَادَةَ، أَنَّهُ رَأَى النَّبِيَّ صلى الله عليه وسلم يَبُولُ مُسْتَقْبِلَ الْقِبْلَةِ ‏.‏ حَدَّثَنَا بِذَلِكَ قُتَيْبَةُ حَدَّثَنَا ابْنُ لَهِيعَةَ ‏.‏ وَحَدِيثُ جَابِرٍ عَنِ النَّبِيِّ صلى الله عليه وسلم', 'أَصَحُّ مِنْ حَدِيثِ ابْنِ لَهِيعَةَ ‏.‏ وَابْنُ لَهِيعَةَ ضَعِيفٌ عِنْدَ أَهْلِ الْحَدِيثِ ضَعَّفَهُ يَحْيَى بْنُ سَعِيدٍ الْقَطَّانُ وَغَيْرُهُ مِنْ قِبَلِ حِفْظِهِ ‏.‏', 'اصح من حديث ابن لهيعه ‏.‏ وابن لهيعه ضعيف عند اهل الحديث ضعفه يحيي بن سعيد القطان وغيره من قبل حفظه ‏.‏', 'Abu Qatadah narrated that :he saw the Prophet urinating while facing the Qiblah. Qutaibah narrated that to us, he said: "Ibn Lahi''ah informed us." Jabir''s Hadlth about the Prophet is more correct than the Hadith of Ibn Lahi''ah. Ibn Lahi''ah is weak according to the scholars of Hadith. He was graded weak by Yahya bin Sa''eed Al-Qattan, and others, [due to his memorization]', NULL, '6942b95c97e1b0d5e99d3eec2170f58fe5fe619a496535802ef8cf1e95ad3313', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (119, 'tirmidhi', 157, 11, 'Book 1, Hadith 11', 11, NULL, NULL, 'حَدَّثَنَا هَنَّادٌ، حَدَّثَنَا عَبْدَةُ بْنُ سُلَيْمَانَ، عَنْ عُبَيْدِ اللَّهِ بْنِ عُمَرَ، عَنْ مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ، عَنْ عَمِّهِ، وَاسِعِ بْنِ حَبَّانَ، عَنِ ابْنِ عُمَرَ، قَالَ رَقِيتُ يَوْمًا عَلَى بَيْتِ حَفْصَةَ فَرَأَيْتُ النَّبِيَّ صلى الله عليه وسلم عَلَى حَاجَتِهِ مُسْتَقْبِلَ الشَّأْمِ مُسْتَدْبِرَ الْكَعْبَةِ', '. قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ .', '. قال ابو عيسي هذا حديث حسن صحيح .', 'Ibn ''Umar said:"One day I climbed on Hafsah''s house, and I saw the Prophet relieving himself while facing Ash-Sham, with his back toward the Ka''bah', NULL, '084499abaff4aa3cd6baed42037f7c58e8c1ca7b38e405a3b541278f02233b7a', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (120, 'tirmidhi', 157, 12, 'Book 1, Hadith 12', 12, NULL, NULL, 'حَدَّثَنَا عَلِيُّ بْنُ حُجْرٍ، أَخْبَرَنَا شَرِيكٌ، عَنِ الْمِقْدَامِ بْنِ شُرَيْحٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ مَنْ حَدَّثَكُمْ أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'كَانَ يَبُولُ قَائِمًا فَلاَ تُصَدِّقُوهُ مَا كَانَ يَبُولُ إِلاَّ قَاعِدًا ‏.‏ قَالَ وَفِي الْبَابِ عَنْ عُمَرَ وَبُرَيْدَةَ وَعَبْدِ الرَّحْمَنِ بْنِ حَسَنَةَ ‏.‏ قَالَ أَبُو عِيسَى حَدِيثُ عَائِشَةَ أَحْسَنُ شَيْءٍ فِي هَذَا الْبَابِ وَأَصَحُّ ‏.‏ وَحَدِيثُ عُمَرَ إِنَّمَا رُوِيَ مِنْ حَدِيثِ عَبْدِ الْكَرِيمِ بْنِ أَبِي الْمُخَارِقِ عَنْ نَافِعٍ عَنِ ابْنِ عُمَرَ عَنْ عُمَرَ قَالَ رَآنِي النَّبِيُّ صلى الله عليه وسلم وَأَنَا أَبُولُ قَائِمًا فَقَالَ ‏ "‏ يَا عُمَرُ لاَ تَبُلْ قَائِمًا ‏"‏ ‏.‏ فَمَا بُلْتُ قَائِمًا بَعْدُ ‏.‏ قَالَ أَبُو عِيسَى وَإِنَّمَا رَفَعَ هَذَا الْحَدِيثَ عَبْدُ الْكَرِيمِ بْنُ أَبِي الْمُخَارِقِ وَهُوَ ضَعِيفٌ عِنْدَ أَهْلِ الْحَدِيثِ ضَعَّفَهُ أَيُّوبُ السَّخْتِيَانِيُّ وَتَكَلَّمَ فِيهِ ‏.‏ وَرَوَى عُبَيْدُ اللَّهِ عَنْ نَافِعٍ عَنِ ابْنِ عُمَرَ قَالَ قَالَ عُمَرُ رضى الله عنه مَا بُلْتُ قَائِمًا مُنْذُ أَسْلَمْتُ ‏.‏ وَهَذَا أَصَحُّ مِنْ حَدِيثِ عَبْدِ الْكَرِيمِ وَحَدِيثُ بُرَيْدَةَ فِي هَذَا غَيْرُ مَحْفُوظٍ ‏.‏ وَمَعْنَى النَّهْىِ عَنِ الْبَوْلِ قَائِمًا عَلَى التَّأْدِيبِ لاَ عَلَى التَّحْرِيمِ ‏.‏ وَقَدْ رُوِيَ عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ إِنَّ مِنَ الْجَفَاءِ أَنْ تَبُولَ وَأَنْتَ قَائِمٌ ‏.‏', 'كان يبول قائما فلا تصدقوه ما كان يبول الا قاعدا ‏.‏ قال وفي الباب عن عمر وبريده وعبد الرحمن بن حسنه ‏.‏ قال ابو عيسي حديث عائشه احسن شيء في هذا الباب واصح ‏.‏ وحديث عمر انما روي من حديث عبد الكريم بن ابي المخارق عن نافع عن ابن عمر عن عمر قال راني النبي صلي الله عليه وسلم وانا ابول قائما فقال ‏ "‏ يا عمر لا تبل قائما ‏"‏ ‏.‏ فما بلت قائما بعد ‏.‏ قال ابو عيسي وانما رفع هذا الحديث عبد الكريم بن ابي المخارق وهو ضعيف عند اهل الحديث ضعفه ايوب السختياني وتكلم فيه ‏.‏ وروي عبيد الله عن نافع عن ابن عمر قال قال عمر رضي الله عنه ما بلت قائما منذ اسلمت ‏.‏ وهذا اصح من حديث عبد الكريم وحديث بريده في هذا غير محفوظ ‏.‏ ومعني النهي عن البول قائما علي التاديب لا علي التحريم ‏.‏ وقد روي عن عبد الله بن مسعود قال ان من الجفاء ان تبول وانت قائم ‏.‏', 'Aishah said:"Whoever narrated to you that the Prophet would urinate while standing; then do not believe him. He would not urinate except while squatting." [He said:] There are narrations on this topic from Umar, Buraidah, [and Abdur-Rahman bin Hasanah]', NULL, 'cedd07aa9db5706fe1e7bd7e2c97e1d24f05c6109ae370e5ed6ca580c18e2231', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (121, 'tirmidhi', 157, 13, 'Book 1, Hadith 13', 13, NULL, NULL, 'حَدَّثَنَا هَنَّادٌ، حَدَّثَنَا وَكِيعٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي وَائِلٍ، عَنْ حُذَيْفَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم أَتَى سُبَاطَةَ قَوْمٍ فَبَالَ عَلَيْهَا قَائِمًا فَأَتَيْتُهُ بِوَضُوءٍ فَذَهَبْتُ لأَتَأَخَّرَ عَنْهُ فَدَعَانِي حَتَّى كُنْتُ عِنْدَ عَقِبَيْهِ فَتَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ ‏.‏ قَالَ أَبُو عِيسَى وَسَمِعْتُ الْجَارُودَ يَقُولُ سَمِعْتُ وَكِيعًا يُحَدِّثُ بِهَذَا الْحَدِيثِ عَنِ الأَعْمَشِ ‏.‏ ثُمَّ قَالَ وَكِيعٌ هَذَا أَصَحُّ حَدِيثٍ رُوِيَ عَنِ النَّبِيِّ صلى الله عليه وسلم', 'فِي الْمَسْحِ ‏.‏ وَسَمِعْتُ أَبَا عَمَّارٍ الْحُسَيْنَ بْنَ حُرَيْثٍ يَقُولُ سَمِعْتُ وَكِيعًا فَذَكَرَ نَحْوَهُ ‏.‏ قَالَ أَبُو عِيسَى وَهَكَذَا رَوَى مَنْصُورٌ وَعُبَيْدَةُ الضَّبِّيُّ عَنْ أَبِي وَائِلٍ عَنْ حُذَيْفَةَ مِثْلَ رِوَايَةِ الأَعْمَشِ ‏.‏ وَرَوَى حَمَّادُ بْنُ أَبِي سُلَيْمَانَ وَعَاصِمُ بْنُ بَهْدَلَةَ عَنْ أَبِي وَائِلٍ عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ عَنِ النَّبِيِّ صلى الله عليه وسلم وَحَدِيثُ أَبِي وَائِلٍ عَنْ حُذَيْفَةَ أَصَحُّ ‏.‏ وَقَدْ رَخَّصَ قَوْمٌ مِنْ أَهْلِ الْعِلْمِ فِي الْبَوْلِ قَائِمًا ‏.‏ قَالَ أَبُو عِيسَى وَعَبِيدَةُ بْنُ عَمْرٍو السَّلْمَانِيُّ رَوَى عَنْهُ إِبْرَاهِيمُ النَّخَعِيُّ ‏.‏ وَعَبِيدَةُ مِنْ كِبَارِ التَّابِعِينَ يُرْوَى عَنْ عَبِيدَةَ أَنَّهُ قَالَ أَسْلَمْتُ قَبْلَ وَفَاةِ النَّبِيِّ صلى الله عليه وسلم بِسَنَتَيْنِ ‏.‏ وَعُبَيْدَةُ الضَّبِّيُّ صَاحِبُ إِبْرَاهِيمَ هُوَ عُبَيْدَةُ بْنُ مُعَتِّبٍ الضَّبِّيُّ وَيُكْنَى أَبَا عَبْدِ الْكَرِيمِ ‏.‏', 'في المسح ‏.‏ وسمعت ابا عمار الحسين بن حريث يقول سمعت وكيعا فذكر نحوه ‏.‏ قال ابو عيسي وهكذا روي منصور وعبيده الضبي عن ابي وائل عن حذيفه مثل روايه الاعمش ‏.‏ وروي حماد بن ابي سليمان وعاصم بن بهدله عن ابي وائل عن المغيره بن شعبه عن النبي صلي الله عليه وسلم وحديث ابي وائل عن حذيفه اصح ‏.‏ وقد رخص قوم من اهل العلم في البول قائما ‏.‏ قال ابو عيسي وعبيده بن عمرو السلماني روي عنه ابراهيم النخعي ‏.‏ وعبيده من كبار التابعين يروي عن عبيده انه قال اسلمت قبل وفاه النبي صلي الله عليه وسلم بسنتين ‏.‏ وعبيده الضبي صاحب ابراهيم هو عبيده بن معتب الضبي ويكني ابا عبد الكريم ‏.‏', 'Hudhaifah narrated:"Allah''s Messenger came to a waste area used by people, so he urinated on it while standing. I brought him the (water for) Wudu. Then I left to be away from him, but he called me until I was behind him. So he performed Wudu and wiped (Masaba) over his Khuff', NULL, 'fd4b42a13c91396119a88c4de3240a844a022ceb47a0286579abf1c07ef03ee1', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (122, 'tirmidhi', 157, 14, 'Book 1, Hadith 14', 14, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا عَبْدُ السَّلاَمِ بْنُ حَرْبٍ الْمُلاَئِيُّ، عَنِ الأَعْمَشِ، عَنْ أَنَسٍ، قَالَ كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا أَرَادَ الْحَاجَةَ لَمْ يَرْفَعْ ثَوْبَهُ حَتَّى يَدْنُوَ مِنَ الأَرْضِ', '. قَالَ أَبُو عِيسَى هَكَذَا رَوَى مُحَمَّدُ بْنُ رَبِيعَةَ عَنِ الأَعْمَشِ عَنْ أَنَسٍ هَذَا الْحَدِيثَ . وَرَوَى وَكِيعٌ وَأَبُو يَحْيَى الْحِمَّانِيُّ عَنِ الأَعْمَشِ قَالَ قَالَ ابْنُ عُمَرَ كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا أَرَادَ الْحَاجَةَ لَمْ يَرْفَعْ ثَوْبَهُ حَتَّى يَدْنُوَ مِنَ الأَرْضِ . وَكِلاَ الْحَدِيثَيْنِ مُرْسَلٌ . وَيُقَالُ لَمْ يَسْمَعِ الأَعْمَشُ مِنْ أَنَسٍ وَلاَ مِنْ أَحَدٍ مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم وَقَدْ نَظَرَ إِلَى أَنَسِ بْنِ مَالِكٍ قَالَ رَأَيْتُهُ يُصَلِّي . فَذَكَرَ عَنْهُ حِكَايَةً فِي الصَّلاَةِ . وَالأَعْمَشُ اسْمُهُ سُلَيْمَانُ بْنُ مِهْرَانَ أَبُو مُحَمَّدٍ الْكَاهِلِيُّ وَهُوَ مَوْلًى لَهُمْ . قَالَ الأَعْمَشُ كَانَ أَبِي حَمِيلاً فَوَرَّثَهُ مَسْرُوقٌ .', '. قال ابو عيسي هكذا روي محمد بن ربيعه عن الاعمش عن انس هذا الحديث . وروي وكيع وابو يحيي الحماني عن الاعمش قال قال ابن عمر كان النبي صلي الله عليه وسلم اذا اراد الحاجه لم يرفع ثوبه حتي يدنو من الارض . وكلا الحديثين مرسل . ويقال لم يسمع الاعمش من انس ولا من احد من اصحاب النبي صلي الله عليه وسلم وقد نظر الي انس بن مالك قال رايته يصلي . فذكر عنه حكايه في الصلاه . والاعمش اسمه سليمان بن مهران ابو محمد الكاهلي وهو مولي لهم . قال الاعمش كان ابي حميلا فورثه مسروق .', 'Anas, may Allah Most High be pleased with him, said:"When the Prophet wanted to relieve himself, he would not raise his garment until he was close to the ground', NULL, '172922aa7d088c49b0beea8ad93c8bedc406211d0ae7a6fdc90bd9c9504e2e09', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (123, 'tirmidhi', 157, 15, 'Book 1, Hadith 15', 15, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ أَبِي عُمَرَ الْمَكِّيُّ، حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنْ مَعْمَرٍ، عَنْ يَحْيَى بْنِ أَبِي كَثِيرٍ، عَنْ عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ، عَنْ أَبِيهِ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'نَهَى أَنْ يَمَسَّ الرَّجُلُ ذَكَرَهُ بِيَمِينِهِ ‏.‏ وَفِي هَذَا الْبَابِ عَنْ عَائِشَةَ وَسَلْمَانَ وَأَبِي هُرَيْرَةَ وَسَهْلِ بْنِ حُنَيْفٍ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَأَبُو قَتَادَةَ الأَنْصَارِيُّ اسْمُهُ الْحَارِثُ بْنُ رِبْعِيٍّ ‏.‏ وَالْعَمَلُ عَلَى هَذَا عِنْدَ عَامَّةِ أَهْلِ الْعِلْمِ كَرِهُوا الاِسْتِنْجَاءَ بِالْيَمِينِ ‏.‏', 'نهي ان يمس الرجل ذكره بيمينه ‏.‏ وفي هذا الباب عن عائشه وسلمان وابي هريره وسهل بن حنيف ‏.‏ قال ابو عيسي هذا حديث حسن صحيح ‏.‏ وابو قتاده الانصاري اسمه الحارث بن ربعي ‏.‏ والعمل علي هذا عند عامه اهل العلم كرهوا الاستنجاء باليمين ‏.‏', 'Abdullah bin Abu Qatadah narrated from his father:"The Prophet prohibited that a man should touch his penis with his right hand', NULL, '9553142b3d456d48022066f28e90a6872d789b70b800428b23fd86d367768e6b', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (124, 'tirmidhi', 157, 16, 'Book 1, Hadith 16', 16, NULL, NULL, 'حَدَّثَنَا هَنَّادٌ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ، قَالَ قِيلَ لِسَلْمَانَ قَدْ عَلَّمَكُمْ نَبِيُّكُمْ صلى الله عليه وسلم كُلَّ شَيْءٍ حَتَّى الْخِرَاءَةَ فَقَالَ سَلْمَانُ أَجَلْ نَهَانَا أَنْ نَسْتَقْبِلَ الْقِبْلَةَ بِغَائِطٍ أَوْ بَوْلٍ وَأَنْ نَسْتَنْجِيَ بِالْيَمِينِ أَوْ أَنْ يَسْتَنْجِيَ أَحَدُنَا بِأَقَلَّ مِنْ ثَلاَثَةِ أَحْجَارٍ أَوْ أَنْ نَسْتَنْجِيَ بِرَجِيعٍ أَوْ بِعَظْمٍ', '. قَالَ أَبُو عِيسَى وَفِي الْبَابِ عَنْ عَائِشَةَ وَخُزَيْمَةَ بْنِ ثَابِتٍ وَجَابِرٍ وَخَلاَّدِ بْنِ السَّائِبِ عَنْ أَبِيهِ . قَالَ أَبُو عِيسَى وَحَدِيثُ سَلْمَانَ فِي هَذَا الْبَابِ حَدِيثٌ حَسَنٌ صَحِيحٌ . وَهُوَ قَوْلُ أَكْثَرِ أَهْلِ الْعِلْمِ مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم وَمَنْ بَعْدَهُمْ رَأَوْا أَنَّ الاِسْتِنْجَاءَ بِالْحِجَارَةِ يُجْزِئُ وَإِنْ لَمْ يَسْتَنْجِ بِالْمَاءِ إِذَا أَنْقَى أَثَرَ الْغَائِطِ وَالْبَوْلِ وَبِهِ يَقُولُ الثَّوْرِيُّ وَابْنُ الْمُبَارَكِ وَالشَّافِعِيُّ وَأَحْمَدُ وَإِسْحَاقُ .', '. قال ابو عيسي وفي الباب عن عائشه وخزيمه بن ثابت وجابر وخلاد بن السائب عن ابيه . قال ابو عيسي وحديث سلمان في هذا الباب حديث حسن صحيح . وهو قول اكثر اهل العلم من اصحاب النبي صلي الله عليه وسلم ومن بعدهم راوا ان الاستنجاء بالحجاره يجزئ وان لم يستنج بالماء اذا انقي اثر الغائط والبول وبه يقول الثوري وابن المبارك والشافعي واحمد واسحاق .', 'Abdur-Rahman bin Yazld said, :"They said to Salman, ''Your Prophet taught you about everything, even defecating?'' So Salman said, ''Yes. He prohibited us from facing the Qiblah when defecating and urinating, performing Istinja with the right hand, using less than three stones for Istinja, and using dung or bones for Istinja', NULL, '6fa79ed2e1df264591400134a5928d768d44bb14f535242f94c2205ff6b35e8e', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (125, 'tirmidhi', 157, 17, 'Book 1, Hadith 17', 17, NULL, NULL, 'حَدَّثَنَا هَنَّادٌ، وَقُتَيْبَةُ، قَالاَ حَدَّثَنَا وَكِيعٌ، عَنْ إِسْرَائِيلَ، عَنْ أَبِي إِسْحَاقَ، عَنْ أَبِي عُبَيْدَةَ، عَنْ عَبْدِ اللَّهِ، قَالَ خَرَجَ النَّبِيُّ صلى الله عليه وسلم لِحَاجَتِهِ فَقَالَ', 'الْتَمِسْ لِي ثَلاَثَةَ أَحْجَارٍ  . قَالَ فَأَتَيْتُهُ بِحَجَرَيْنِ وَرَوْثَةٍ فَأَخَذَ الْحَجَرَيْنِ وَأَلْقَى الرَّوْثَةَ وَقَالَ  إِنَّهَا رِكْسٌ  . قَالَ أَبُو عِيسَى وَهَكَذَا رَوَى قَيْسُ بْنُ الرَّبِيعِ هَذَا الْحَدِيثَ عَنْ أَبِي إِسْحَاقَ عَنْ أَبِي عُبَيْدَةَ عَنْ عَبْدِ اللَّهِ نَحْوَ حَدِيثِ إِسْرَائِيلَ . وَرَوَى مَعْمَرٌ وَعَمَّارُ بْنُ رُزَيْقٍ عَنْ أَبِي إِسْحَاقَ عَنْ عَلْقَمَةَ عَنْ عَبْدِ اللَّهِ . وَرَوَى زُهَيْرٌ عَنْ أَبِي إِسْحَاقَ عَنْ عَبْدِ الرَّحْمَنِ بْنِ الأَسْوَدِ عَنْ أَبِيهِ الأَسْوَدِ بْنِ يَزِيدَ عَنْ عَبْدِ اللَّهِ . وَرَوَى زَكَرِيَّا بْنُ أَبِي زَائِدَةَ عَنْ أَبِي إِسْحَاقَ عَنْ عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ عَنِ الأَسْوَدِ بْنِ يَزِيدَ عَنْ عَبْدِ اللَّهِ . وَهَذَا حَدِيثٌ فِيهِ اضْطِرَابٌ . حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ الْعَبْدِيُّ حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ حَدَّثَنَا شُعْبَةُ عَنْ عَمْرِو بْنِ مُرَّةَ قَالَ سَأَلْتُ أَبَا عُبَيْدَةَ بْنَ عَبْدِ اللَّهِ هَلْ تَذْكُرُ مِنْ عَبْدِ اللَّهِ شَيْئًا قَالَ لاَ .', 'التمس لي ثلاثه احجار . قال فاتيته بحجرين وروثه فاخذ الحجرين والقي الروثه وقال انها ركس . قال ابو عيسي وهكذا روي قيس بن الربيع هذا الحديث عن ابي اسحاق عن ابي عبيده عن عبد الله نحو حديث اسرائيل . وروي معمر وعمار بن رزيق عن ابي اسحاق عن علقمه عن عبد الله . وروي زهير عن ابي اسحاق عن عبد الرحمن بن الاسود عن ابيه الاسود بن يزيد عن عبد الله . وروي زكريا بن ابي زائده عن ابي اسحاق عن عبد الرحمن بن يزيد عن الاسود بن يزيد عن عبد الله . وهذا حديث فيه اضطراب . حدثنا محمد بن بشار العبدي حدثنا محمد بن جعفر حدثنا شعبه عن عمرو بن مره قال سالت ابا عبيده بن عبد الله هل تذكر من عبد الله شيئا قال لا .', 'Abdullah said:"Allah''s Messenger went out to relieve himself. So he said: ''Bring me tree stones.''" He said, "So I came with two stones and a piece of dung. So he took the two stones, and left the dung. He said: ''It is Riks (a degenerative or filthy thing)', NULL, 'a20451018d11988a9f61b82b75e8a1e499819146f0a5a62cab0840656f094f1b', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (126, 'tirmidhi', 157, 18, 'Book 1, Hadith 18', 18, NULL, NULL, 'حَدَّثَنَا هَنَّادٌ، حَدَّثَنَا حَفْصُ بْنُ غِيَاثٍ، عَنْ دَاوُدَ بْنِ أَبِي هِنْدٍ، عَنِ الشَّعْبِيِّ، عَنْ عَلْقَمَةَ، عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏', 'لاَ تَسْتَنْجُوا بِالرَّوْثِ وَلاَ بِالْعِظَامِ فَإِنَّهُ زَادُ إِخْوَانِكُمْ مِنَ الْجِنِّ ‏"‏ ‏.‏ وَفِي الْبَابِ عَنْ أَبِي هُرَيْرَةَ وَسَلْمَانَ وَجَابِرٍ وَابْنِ عُمَرَ ‏.‏ قَالَ أَبُو عِيسَى وَقَدْ رَوَى هَذَا الْحَدِيثَ إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ وَغَيْرُهُ عَنْ دَاوُدَ بْنِ أَبِي هِنْدٍ عَنِ الشَّعْبِيِّ عَنْ عَلْقَمَةَ عَنْ عَبْدِ اللَّهِ أَنَّهُ كَانَ مَعَ النَّبِيِّ صلى الله عليه وسلم لَيْلَةَ الْجِنِّ - الْحَدِيثَ بِطُولِهِ - فَقَالَ الشَّعْبِيُّ إِنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏"‏ لاَ تَسْتَنْجُوا بِالرَّوْثِ وَلاَ بِالْعِظَامِ فَإِنَّهُ زَادُ إِخْوَانِكُمْ مِنَ الْجِنِّ ‏"‏ ‏.‏ وَكَأَنَّ رِوَايَةَ إِسْمَاعِيلَ أَصَحُّ مِنْ رِوَايَةِ حَفْصِ بْنِ غِيَاثٍ ‏.‏ وَالْعَمَلُ عَلَى هَذَا الْحَدِيثِ عِنْدَ أَهْلِ الْعِلْمِ ‏.‏ وَفِي الْبَابِ عَنْ جَابِرٍ وَابْنِ عُمَرَ رضى الله عنهما ‏.‏', 'لا تستنجوا بالروث ولا بالعظام فانه زاد اخوانكم من الجن ‏"‏ ‏.‏ وفي الباب عن ابي هريره وسلمان وجابر وابن عمر ‏.‏ قال ابو عيسي وقد روي هذا الحديث اسماعيل بن ابراهيم وغيره عن داود بن ابي هند عن الشعبي عن علقمه عن عبد الله انه كان مع النبي صلي الله عليه وسلم ليله الجن - الحديث بطوله - فقال الشعبي ان النبي صلي الله عليه وسلم قال ‏"‏ لا تستنجوا بالروث ولا بالعظام فانه زاد اخوانكم من الجن ‏"‏ ‏.‏ وكان روايه اسماعيل اصح من روايه حفص بن غياث ‏.‏ والعمل علي هذا الحديث عند اهل العلم ‏.‏ وفي الباب عن جابر وابن عمر رضي الله عنهما ‏.‏', 'Abdullah bin Mas''ud narrated that :Allah''s Messenger said: "Do not perform Istinja, with dung, nor with bones. For indeed it is provisions for your brothers among the Jinn', NULL, 'b478f26af6016124e0e98e96d42c448450259b0bfffa319cc324df211a40c418', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (127, 'tirmidhi', 157, 19, 'Book 1, Hadith 19', 19, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ، وَمُحَمَّدُ بْنُ عَبْدِ الْمَلِكِ بْنِ أَبِي الشَّوَارِبِ الْبَصْرِيُّ، قَالاَ حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ قَتَادَةَ، عَنْ مُعَاذَةَ، عَنْ عَائِشَةَ، قَالَتْ مُرْنَ أَزْوَاجَكُنَّ أَنْ يَسْتَطِيبُوا، بِالْمَاءِ فَإِنِّي أَسْتَحْيِيهِمْ فَإِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ يَفْعَلُهُ', '. وَفِي الْبَابِ عَنْ جَرِيرِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ وَأَنَسٍ وَأَبِي هُرَيْرَةَ . قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ . وَعَلَيْهِ الْعَمَلُ عِنْدَ أَهْلِ الْعِلْمِ يَخْتَارُونَ الاِسْتِنْجَاءَ بِالْمَاءِ وَإِنْ كَانَ الاِسْتِنْجَاءُ بِالْحِجَارَةِ يُجْزِئُ عِنْدَهُمْ فَإِنَّهُمُ اسْتَحَبُّوا الاِسْتِنْجَاءَ بِالْمَاءِ وَرَأَوْهُ أَفْضَلَ . وَبِهِ يَقُولُ سُفْيَانُ الثَّوْرِيُّ وَابْنُ الْمُبَارَكِ وَالشَّافِعِيُّ وَأَحْمَدُ وَإِسْحَاقُ .', '. وفي الباب عن جرير بن عبد الله البجلي وانس وابي هريره . قال ابو عيسي هذا حديث حسن صحيح . وعليه العمل عند اهل العلم يختارون الاستنجاء بالماء وان كان الاستنجاء بالحجاره يجزئ عندهم فانهم استحبوا الاستنجاء بالماء وراوه افضل . وبه يقول سفيان الثوري وابن المبارك والشافعي واحمد واسحاق .', 'Aishah said:"Encourage your Husbands to clean themselves with water, for I am too shy of them, and Allah''s Messenger would do that', NULL, 'b3dceb46dc462c154d36478246dc4293edf3fd6a3a8b89f29d554b66130c7d20', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (128, 'tirmidhi', 157, 20, 'Book 1, Hadith 20', 20, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا عَبْدُ الْوَهَّابِ الثَّقَفِيُّ، عَنْ مُحَمَّدِ بْنِ عَمْرٍو، عَنْ أَبِي سَلَمَةَ، عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، قَالَ كُنْتُ مَعَ النَّبِيِّ صلى الله عليه وسلم فِي سَفَرٍ فَأَتَى النَّبِيُّ صلى الله عليه وسلم حَاجَتَهُ فَأَبْعَدَ فِي الْمَذْهَبِ ‏.‏ قَالَ وَفِي الْبَابِ عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي قُرَادٍ وَأَبِي قَتَادَةَ وَجَابِرٍ وَيَحْيَى بْنِ عُبَيْدٍ عَنْ أَبِيهِ وَأَبِي مُوسَى وَابْنِ عَبَّاسٍ وَبِلاَلِ بْنِ الْحَارِثِ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَيُرْوَى عَنِ النَّبِيِّ صلى الله عليه وسلم', 'أَنَّهُ كَانَ يَرْتَادُ لِبَوْلِهِ مَكَانًا كَمَا يَرْتَادُ مَنْزِلاً ‏.‏ وَأَبُو سَلَمَةَ اسْمُهُ عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ الزُّهْرِيُّ ‏.‏', 'انه كان يرتاد لبوله مكانا كما يرتاد منزلا ‏.‏ وابو سلمه اسمه عبد الله بن عبد الرحمن بن عوف الزهري ‏.‏', 'Al-Mughirah bin Shu''bah said:I was with the Prophet on a journey. The Prophet had to relieve himself, so he went far away', NULL, '0bb03d03d2aa2158397db0c46d0fd7e0e252aa1ddcdb9e8e5a8c77d58c7605d7', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (129, 'tirmidhi', 157, 21, 'Book 1, Hadith 21', 21, NULL, NULL, 'حَدَّثَنَا عَلِيُّ بْنُ حُجْرٍ، وَأَحْمَدُ بْنُ مُحَمَّدِ بْنِ مُوسَى، مَرْدَوَيْهِ قَالاَ أَخْبَرَنَا عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ، عَنْ مَعْمَرٍ، عَنْ أَشْعَثَ بْنِ عَبْدِ اللَّهِ، عَنِ الْحَسَنِ، عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'نَهَى أَنْ يَبُولَ الرَّجُلُ فِي مُسْتَحَمِّهِ ‏.‏ وَقَالَ ‏ "‏ إِنَّ عَامَّةَ الْوَسْوَاسِ مِنْهُ ‏"‏ ‏.‏ قَالَ وَفِي الْبَابِ عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْرِفُهُ مَرْفُوعًا إِلاَّ مِنْ حَدِيثِ أَشْعَثَ بْنِ عَبْدِ اللَّهِ وَيُقَالُ لَهُ أَشْعَثُ الأَعْمَى ‏.‏ وَقَدْ كَرِهَ قَوْمٌ مِنْ أَهْلِ الْعِلْمِ الْبَوْلَ فِي الْمُغْتَسَلِ وَقَالُوا عَامَّةُ الْوَسْوَاسِ مِنْهُ ‏.‏ وَرَخَّصَ فِيهِ بَعْضُ أَهْلِ الْعِلْمِ مِنْهُمُ ابْنُ سِيرِينَ وَقِيلَ لَهُ إِنَّهُ يُقَالُ إِنَّ عَامَّةَ الْوَسْوَاسِ مِنْهُ فَقَالَ رَبُّنَا اللَّهُ لاَ شَرِيكَ لَهُ ‏.‏ وَقَالَ ابْنُ الْمُبَارَكِ قَدْ وُسِّعَ فِي الْبَوْلِ فِي الْمُغْتَسَلِ إِذَا جَرَى فِيهِ الْمَاءُ ‏.‏ قَالَ أَبُو عِيسَى حَدَّثَنَا بِذَلِكَ أَحْمَدُ بْنُ عَبْدَةَ الآمُلِيُّ عَنْ حِبَّانَ عَنْ عَبْدِ اللَّهِ بْنِ الْمُبَارَكِ ‏.‏', 'نهي ان يبول الرجل في مستحمه ‏.‏ وقال ‏ "‏ ان عامه الوسواس منه ‏"‏ ‏.‏ قال وفي الباب عن رجل من اصحاب النبي صلي الله عليه وسلم ‏.‏ قال ابو عيسي هذا حديث غريب لا نعرفه مرفوعا الا من حديث اشعث بن عبد الله ويقال له اشعث الاعمي ‏.‏ وقد كره قوم من اهل العلم البول في المغتسل وقالوا عامه الوسواس منه ‏.‏ ورخص فيه بعض اهل العلم منهم ابن سيرين وقيل له انه يقال ان عامه الوسواس منه فقال ربنا الله لا شريك له ‏.‏ وقال ابن المبارك قد وسع في البول في المغتسل اذا جري فيه الماء ‏.‏ قال ابو عيسي حدثنا بذلك احمد بن عبده الاملي عن حبان عن عبد الله بن المبارك ‏.‏', 'Abdullah bin Mughaffal narrated that :the Prophet prohibited that a man should urinate in his bathing area. And he said: "It will only cause misgivings." [He said:] There are narrations on This topic from "a man from among the Companions of the Prophet', NULL, '8591040367d06cede30adf1900d4bd4e7ba1062674133a87cbfd4f926a27a328', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (130, 'tirmidhi', 157, 22, 'Book 1, Hadith 22', 22, NULL, NULL, 'حَدَّثَنَا أَبُو كُرَيْبٍ، حَدَّثَنَا عَبْدَةُ بْنُ سُلَيْمَانَ، عَنْ مُحَمَّدِ بْنِ عَمْرٍو، عَنْ أَبِي سَلَمَةَ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ لَوْلاَ أَنْ أَشُقَّ عَلَى أُمَّتِي لأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلاَةٍ ‏"‏ ‏.‏ قَالَ أَبُو عِيسَى وَقَدْ رَوَى هَذَا الْحَدِيثَ مُحَمَّدُ بْنُ إِسْحَاقَ عَنْ مُحَمَّدِ بْنِ إِبْرَاهِيمَ عَنْ أَبِي سَلَمَةَ عَنْ زَيْدِ بْنِ خَالِدٍ عَنِ النَّبِيِّ صلى الله عليه وسلم ‏.‏ وَحَدِيثُ أَبِي سَلَمَةَ عَنْ أَبِي هُرَيْرَةَ وَزَيْدِ بْنِ خَالِدٍ عَنِ النَّبِيِّ صلى الله عليه وسلم كِلاَهُمَا عِنْدِي صَحِيحٌ لأَنَّهُ قَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صلى الله عليه وسلم هَذَا الْحَدِيثُ ‏.‏ وَحَدِيثُ أَبِي هُرَيْرَةَ إِنَّمَا صَحَّ لأَنَّهُ قَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ ‏.‏ وَأَمَّا مُحَمَّدُ بْنُ إِسْمَاعِيلَ فَزَعَمَ أَنَّ حَدِيثَ أَبِي سَلَمَةَ عَنْ زَيْدِ بْنِ خَالِدٍ أَصَحُّ ‏.‏ قَالَ أَبُو عِيسَى وَفِي الْبَابِ عَنْ أَبِي بَكْرٍ الصِّدِّيقِ وَعَلِيٍّ وَعَائِشَةَ وَابْنِ عَبَّاسٍ وَحُذَيْفَةَ وَزَيْدِ بْنِ خَالِدٍ وَأَنَسٍ وَعَبْدِ اللَّهِ بْنِ عَمْرٍو وَابْنِ عُمَرَ وَأُمِّ حَبِيبَةَ وَأَبِي أُمَامَةَ وَأَبِي أَيُّوبَ وَتَمَّامِ بْنِ عَبَّاسٍ وَعَبْدِ اللَّهِ بْنِ حَنْظَلَةَ وَأُمِّ سَلَمَةَ وَوَاثِلَةَ بْنِ الأَسْقَعِ وَأَبِي مُوسَى ‏.‏', '"‏ لولا ان اشق علي امتي لامرتهم بالسواك عند كل صلاه ‏"‏ ‏.‏ قال ابو عيسي وقد روي هذا الحديث محمد بن اسحاق عن محمد بن ابراهيم عن ابي سلمه عن زيد بن خالد عن النبي صلي الله عليه وسلم ‏.‏ وحديث ابي سلمه عن ابي هريره وزيد بن خالد عن النبي صلي الله عليه وسلم كلاهما عندي صحيح لانه قد روي من غير وجه عن ابي هريره عن النبي صلي الله عليه وسلم هذا الحديث ‏.‏ وحديث ابي هريره انما صح لانه قد روي من غير وجه ‏.‏ واما محمد بن اسماعيل فزعم ان حديث ابي سلمه عن زيد بن خالد اصح ‏.‏ قال ابو عيسي وفي الباب عن ابي بكر الصديق وعلي وعائشه وابن عباس وحذيفه وزيد بن خالد وانس وعبد الله بن عمرو وابن عمر وام حبيبه وابي امامه وابي ايوب وتمام بن عباس وعبد الله بن حنظله وام سلمه وواثله بن الاسقع وابي موسي ‏.‏', 'Abu Hurairah narrated that :Allah''s Messenger said: "If it were not that it would be difficult on my nation, then I would have ordered them to use the Siwak for each prayer', NULL, '8aff6af0bb0ee74a3404cf580086d58a37604ea0d5e608e836b17acfc8d5712d', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (131, 'tirmidhi', 157, 23, 'Book 1, Hadith 23', 23, NULL, NULL, 'حَدَّثَنَا هَنَّادٌ، حَدَّثَنَا عَبْدَةُ بْنُ سُلَيْمَانَ، عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ، عَنْ مُحَمَّدِ بْنِ إِبْرَاهِيمَ، عَنْ أَبِي سَلَمَةَ، عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏"‏', 'لَوْلاَ أَنْ أَشُقَّ عَلَى أُمَّتِي لأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلاَةٍ وَلأَخَّرْتُ صَلاَةَ الْعِشَاءِ إِلَى ثُلُثِ اللَّيْلِ ‏"‏ ‏.‏ قَالَ فَكَانَ زَيْدُ بْنُ خَالِدٍ يَشْهَدُ الصَّلَوَاتِ فِي الْمَسْجِدِ وَسِوَاكُهُ عَلَى أُذُنِهِ مَوْضِعَ الْقَلَمِ مِنْ أُذُنِ الْكَاتِبِ لاَ يَقُومُ إِلَى الصَّلاَةِ إِلاَّ اسْتَنَّ ثُمَّ رَدَّهُ إِلَى مَوْضِعِهِ ‏"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏', 'لولا ان اشق علي امتي لامرتهم بالسواك عند كل صلاه ولاخرت صلاه العشاء الي ثلث الليل ‏"‏ ‏.‏ قال فكان زيد بن خالد يشهد الصلوات في المسجد وسواكه علي اذنه موضع القلم من اذن الكاتب لا يقوم الي الصلاه الا استن ثم رده الي موضعه ‏"‏ ‏.‏ قال ابو عيسي هذا حديث حسن صحيح ‏.‏', 'Zaid bin Khalid Al-Juhani said :''I heard Allah''s Messenger saying: ''If it were not that it would be difficult on my nation then, I would have ordered them to use the Siwak for each prayer and to delay the Isha prayer until the third of the night.''"He [Abu Salamah, one of the narrators] said: Zaid bin Khalid wouId attend the prayer in the Masjid and his Siwak would be on his ear in the location of the pen on the ear of a writer. He would not get up to pray without cleaning his teeth, then returning it to its location', NULL, '2c415e7889c6a7896a317e38a8e7dcc848c85d87cd160df268322b7b5b5959ba', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (132, 'tirmidhi', 157, 24, 'Book 1, Hadith 24', 24, NULL, NULL, 'حَدَّثَنَا أَبُو الْوَلِيدِ، أَحْمَدُ بْنُ بَكَّارٍ الدِّمَشْقِيُّ - يُقَالُ هُوَ مِنْ وَلَدِ بُسْرِ بْنِ أَرْطَاةَ صَاحِبِ النَّبِيِّ صلى الله عليه وسلم حَدَّثَنَا الْوَلِيدُ بْنُ مُسْلِمٍ عَنِ الأَوْزَاعِيِّ عَنِ الزُّهْرِيِّ عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ وَأَبِي سَلَمَةَ عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنَ اللَّيْلِ فَلاَ يُدْخِلْ يَدَهُ فِي الإِنَاءِ حَتَّى يُفْرِغَ عَلَيْهَا مَرَّتَيْنِ أَوْ ثَلاَثًا فَإِنَّهُ لاَ يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏"‏ ‏.‏ وَفِي الْبَابِ عَنِ ابْنِ عُمَرَ وَجَابِرٍ وَعَائِشَةَ ‏.‏ قَالَ أَبُو عِيسَى وَهَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ قَالَ الشَّافِعِيُّ وَأُحِبُّ لِكُلِّ مَنِ اسْتَيْقَظَ مِنَ النَّوْمِ قَائِلَةً كَانَتْ أَوْ غَيْرَهَا أَنْ لاَ يُدْخِلَ يَدَهُ فِي وَضُوئِهِ حَتَّى يَغْسِلَهَا فَإِنْ أَدْخَلَ يَدَهُ قَبْلَ أَنْ يَغْسِلَهَا كَرِهْتُ ذَلِكَ لَهُ وَلَمْ يُفْسِدْ ذَلِكَ الْمَاءَ إِذَا لَمْ يَكُنْ عَلَى يَدِهِ نَجَاسَةٌ ‏.‏ وَقَالَ أَحْمَدُ بْنُ حَنْبَلٍ إِذَا اسْتَيْقَظَ مِنَ النَّوْمِ مِنَ اللَّيْلِ فَأَدْخَلَ يَدَهُ فِي وَضُوئِهِ قَبْلَ أَنْ يَغْسِلَهَا فَأَعْجَبُ إِلَىَّ أَنْ يُهَرِيقَ الْمَاءَ ‏.‏ وَقَالَ إِسْحَاقُ إِذَا اسْتَيْقَظَ مِنَ النَّوْمِ بِاللَّيْلِ أَوْ بِالنَّهَارِ فَلاَ يُدْخِلْ يَدَهُ فِي وَضُوئِهِ حَتَّى يَغْسِلَهَا ‏.‏', '"‏ اذا استيقظ احدكم من الليل فلا يدخل يده في الاناء حتي يفرغ عليها مرتين او ثلاثا فانه لا يدري اين باتت يده ‏"‏ ‏.‏ وفي الباب عن ابن عمر وجابر وعائشه ‏.‏ قال ابو عيسي وهذا حديث حسن صحيح ‏.‏ قال الشافعي واحب لكل من استيقظ من النوم قائله كانت او غيرها ان لا يدخل يده في وضوئه حتي يغسلها فان ادخل يده قبل ان يغسلها كرهت ذلك له ولم يفسد ذلك الماء اذا لم يكن علي يده نجاسه ‏.‏ وقال احمد بن حنبل اذا استيقظ من النوم من الليل فادخل يده في وضوئه قبل ان يغسلها فاعجب الي ان يهريق الماء ‏.‏ وقال اسحاق اذا استيقظ من النوم بالليل او بالنهار فلا يدخل يده في وضوئه حتي يغسلها ‏.‏', 'Abu Hurairah reported that the :Prophet said: "When on of you awakens in the night, then let him not put his hand into the vessel until he has poured water on two times, or three times, for indeed he does not know where his hand has spent the night', NULL, '258568497a09c230a78a7fb7836ccecc8107d9040ccc5c72d48453dabe97e093', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (133, 'tirmidhi', 157, 25, 'Book 1, Hadith 25', 25, NULL, NULL, 'حَدَّثَنَا نَصْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ، وَبِشْرُ بْنُ مُعَاذٍ الْعَقَدِيُّ، قَالاَ حَدَّثَنَا بِشْرُ بْنُ الْمُفَضَّلِ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ حَرْمَلَةَ، عَنْ أَبِي ثِفَالٍ الْمُرِّيِّ، عَنْ رَبَاحِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي سُفْيَانَ بْنِ حُوَيْطِبٍ، عَنْ جَدَّتِهِ، عَنْ أَبِيهَا، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏', '"‏ لاَ وُضُوءَ لِمَنْ لَمْ يَذْكُرِ اسْمَ اللَّهِ عَلَيْهِ ‏"‏ ‏.‏ قَالَ وَفِي الْبَابِ عَنْ عَائِشَةَ وَأَبِي سَعِيدٍ وَأَبِي هُرَيْرَةَ وَسَهْلِ بْنِ سَعْدٍ وَأَنَسٍ ‏.‏ قَالَ أَبُو عِيسَى قَالَ أَحْمَدُ بْنُ حَنْبَلٍ لاَ أَعْلَمُ فِي هَذَا الْبَابِ حَدِيثًا لَهُ إِسْنَادٌ جَيِّدٌ ‏.‏ وَقَالَ إِسْحَاقُ إِنْ تَرَكَ التَّسْمِيَةَ عَامِدًا أَعَادَ الْوُضُوءَ وَإِنْ كَانَ نَاسِيًا أَوْ مُتَأَوِّلاً أَجْزَأَهُ ‏.‏ قَالَ مُحَمَّدُ بْنُ إِسْمَاعِيلَ أَحْسَنُ شَيْءٍ فِي هَذَا الْبَابِ حَدِيثُ رَبَاحِ بْنِ عَبْدِ الرَّحْمَنِ ‏.‏ قَالَ أَبُو عِيسَى وَرَبَاحُ بْنُ عَبْدِ الرَّحْمَنِ عَنْ جَدَّتِهِ عَنْ أَبِيهَا ‏.‏ وَأَبُوهَا سَعِيدُ بْنُ زَيْدِ بْنِ عَمْرِو بْنِ نُفَيْلٍ ‏.‏ وَأَبُو ثِفَالٍ الْمُرِّيُّ اسْمُهُ ثُمَامَةُ بْنُ حُصَيْنٍ ‏.‏ وَرَبَاحُ بْنُ عَبْدِ الرَّحْمَنِ هُوَ أَبُو بَكْرِ بْنُ حُوَيْطِبٍ ‏.‏ مِنْهُمْ مَنْ رَوَى هَذَا الْحَدِيثَ فَقَالَ عَنْ أَبِي بَكْرِ بْنِ حُوَيْطِبٍ فَنَسَبَهُ إِلَى جَدِّهِ ‏.‏', '"‏ لا وضوء لمن لم يذكر اسم الله عليه ‏"‏ ‏.‏ قال وفي الباب عن عائشه وابي سعيد وابي هريره وسهل بن سعد وانس ‏.‏ قال ابو عيسي قال احمد بن حنبل لا اعلم في هذا الباب حديثا له اسناد جيد ‏.‏ وقال اسحاق ان ترك التسميه عامدا اعاد الوضوء وان كان ناسيا او متاولا اجزاه ‏.‏ قال محمد بن اسماعيل احسن شيء في هذا الباب حديث رباح بن عبد الرحمن ‏.‏ قال ابو عيسي ورباح بن عبد الرحمن عن جدته عن ابيها ‏.‏ وابوها سعيد بن زيد بن عمرو بن نفيل ‏.‏ وابو ثفال المري اسمه ثمامه بن حصين ‏.‏ ورباح بن عبد الرحمن هو ابو بكر بن حويطب ‏.‏ منهم من روي هذا الحديث فقال عن ابي بكر بن حويطب فنسبه الي جده ‏.‏', 'Rabah bin Abdur-Rahman bin Abi Sufyan bin Huwaitib narrated from his grandmother, from her father; she said (that he said):"I heard Allah''s Messenger saying: there is no Wudu for one who does not mention Allah''s Name over it', NULL, '0dc930477b844c673cc80f04a226813898257c100fe6e910d0821240ec0192b4', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (134, 'tirmidhi', 157, 26, 'Book 1, Hadith 26', 26, NULL, NULL, 'حَدَّثَنَا الْحَسَنُ بْنُ عَلِيٍّ الْحُلْوَانِيُّ، حَدَّثَنَا يَزِيدُ بْنُ هَارُونَ، عَنْ يَزِيدَ بْنِ عِيَاضٍ، عَنْ أَبِي ثِفَالٍ الْمُرِّيِّ، عَنْ رَبَاحِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي سُفْيَانَ بْنِ حُوَيْطِبٍ، عَنْ جَدَّتِهِ بِنْتِ سَعِيدِ بْنِ زَيْدٍ، عَنْ أَبِيهَا، عَنِ النَّبِيِّ صلى الله عليه وسلم', 'مِثْلَهُ ‏.‏', 'مثله ‏.‏', 'Rabah Bin Abdur-Rahman bin Abu Sufyan bin Huwaitib narrated :the same from his grandmother the daughter of Sa''eed bin Zaid, from her father, from the Prophet', NULL, 'a85ef776def7f28c368b983f35c1b775f318921ceca93e4801b4aac759910369', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (135, 'tirmidhi', 157, 27, 'Book 1, Hadith 27', 27, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، وَجَرِيرٌ، عَنْ مَنْصُورٍ، عَنْ هِلاَلِ بْنِ يِسَافٍ، عَنْ سَلَمَةَ بْنِ قَيْسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ إِذَا تَوَضَّأْتَ فَانْتَثِرْ وَإِذَا اسْتَجْمَرْتَ فَأَوْتِرْ ‏"‏ ‏.‏ قَالَ وَفِي الْبَابِ عَنْ عُثْمَانَ وَلَقِيطِ بْنِ صَبِرَةَ وَابْنِ عَبَّاسٍ وَالْمِقْدَامِ بْنِ مَعْدِيكَرِبَ وَوَائِلِ بْنِ حُجْرٍ وَأَبِي هُرَيْرَةَ ‏.‏ قَالَ أَبُو عِيسَى حَدِيثُ سَلَمَةَ بْنِ قَيْسٍ حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَاخْتَلَفَ أَهْلُ الْعِلْمِ فِيمَنْ تَرَكَ الْمَضْمَضَةَ وَالاِسْتِنْشَاقَ فَقَالَتْ طَائِفَةٌ مِنْهُمْ إِذَا تَرَكَهُمَا فِي الْوُضُوءِ حَتَّى صَلَّى أَعَادَ الصَّلاَةَ وَرَأَوْا ذَلِكَ فِي الْوُضُوءِ وَالْجَنَابَةِ سَوَاءً ‏.‏ وَبِهِ يَقُولُ ابْنُ أَبِي لَيْلَى وَعَبْدُ اللَّهِ بْنُ الْمُبَارَكِ وَأَحْمَدُ وَإِسْحَاقُ ‏.‏ وَقَالَ أَحْمَدُ الاِسْتِنْشَاقُ أَوْكَدُ مِنَ الْمَضْمَضَةِ ‏.‏ قَالَ أَبُو عِيسَى وَقَالَتْ طَائِفَةٌ مِنْ أَهْلِ الْعِلْمِ يُعِيدُ فِي الْجَنَابَةِ وَلاَ يُعِيدُ فِي الْوُضُوءِ وَهُوَ قَوْلُ سُفْيَانَ الثَّوْرِيِّ وَبَعْضِ أَهْلِ الْكُوفَةِ ‏.‏ وَقَالَتْ طَائِفَةٌ لاَ يُعِيدُ فِي الْوُضُوءِ وَلاَ فِي الْجَنَابَةِ لأَنَّهُمَا سُنَّةٌ مِنَ النَّبِيِّ صلى الله عليه وسلم فَلاَ تَجِبُ الإِعَادَةُ عَلَى مَنْ تَرَكَهُمَا فِي الْوُضُوءِ وَلاَ فِي الْجَنَابَةِ ‏.‏ وَهُوَ قَوْلُ مَالِكٍ وَالشَّافِعِيِّ فِي آخِرَةٍ ‏.‏', '"‏ اذا توضات فانتثر واذا استجمرت فاوتر ‏"‏ ‏.‏ قال وفي الباب عن عثمان ولقيط بن صبره وابن عباس والمقدام بن معديكرب ووائل بن حجر وابي هريره ‏.‏ قال ابو عيسي حديث سلمه بن قيس حديث حسن صحيح ‏.‏ واختلف اهل العلم فيمن ترك المضمضه والاستنشاق فقالت طائفه منهم اذا تركهما في الوضوء حتي صلي اعاد الصلاه وراوا ذلك في الوضوء والجنابه سواء ‏.‏ وبه يقول ابن ابي ليلي وعبد الله بن المبارك واحمد واسحاق ‏.‏ وقال احمد الاستنشاق اوكد من المضمضه ‏.‏ قال ابو عيسي وقالت طائفه من اهل العلم يعيد في الجنابه ولا يعيد في الوضوء وهو قول سفيان الثوري وبعض اهل الكوفه ‏.‏ وقالت طائفه لا يعيد في الوضوء ولا في الجنابه لانهما سنه من النبي صلي الله عليه وسلم فلا تجب الاعاده علي من تركهما في الوضوء ولا في الجنابه ‏.‏ وهو قول مالك والشافعي في اخره ‏.‏', 'Salamah bin Qais narrated that :Allah''s Messenger said: "When you perform Wudu then sniff water in the nose and blow it out, and when you use small stones (to remove filth) then make it odd (numbered)', NULL, '8f3437c7423956d43d1218ea5936177841ff1f23bc772b12c4869cd2bd31e9d4', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (136, 'tirmidhi', 157, 28, 'Book 1, Hadith 28', 28, NULL, NULL, 'حَدَّثَنَا يَحْيَى بْنُ مُوسَى، حَدَّثَنَا إِبْرَاهِيمُ بْنُ مُوسَى الرَّازِيُّ، حَدَّثَنَا خَالِدُ بْنُ عَبْدِ اللَّهِ، عَنْ عَمْرِو بْنِ يَحْيَى، عَنْ أَبِيهِ، عَنْ عَبْدِ اللَّهِ بْنِ زَيْدٍ، قَالَ رَأَيْتُ النَّبِيَّ صلى الله عليه وسلم مَضْمَضَ وَاسْتَنْشَقَ مِنْ كَفٍّ وَاحِدٍ فَعَلَ ذَلِكَ ثَلاَثًا ‏.‏ قَالَ أَبُو عِيسَى وَفِي الْبَابِ عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏.‏ قَالَ أَبُو عِيسَى وَحَدِيثُ عَبْدِ اللَّهِ بْنِ زَيْدٍ حَسَنٌ غَرِيبٌ ‏.‏ وَقَدْ رَوَى مَالِكٌ وَابْنُ عُيَيْنَةَ وَغَيْرُ وَاحِدٍ هَذَا الْحَدِيثَ عَنْ عَمْرِو بْنِ يَحْيَى وَلَمْ يَذْكُرُوا هَذَا الْحَرْفَ أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'مَضْمَضَ وَاسْتَنْشَقَ مِنْ كَفٍّ وَاحِدٍ ‏.‏ وَإِنَّمَا ذَكَرَهُ خَالِدُ بْنُ عَبْدِ اللَّهِ ‏.‏ وَخَالِدُ بْنُ عَبْدِ اللَّهِ ثِقَةٌ حَافِظٌ عِنْدَ أَهْلِ الْحَدِيثِ ‏.‏ وَقَالَ بَعْضُ أَهْلِ الْعِلْمِ الْمَضْمَضَةُ وَالاِسْتِنْشَاقُ مِنْ كَفٍّ وَاحِدٍ يُجْزِئُ وَقَالَ بَعْضُهُمْ تَفْرِيقُهُمَا أَحَبُّ إِلَيْنَا ‏.‏ وَقَالَ الشَّافِعِيُّ إِنْ جَمَعَهُمَا فِي كَفٍّ وَاحِدٍ فَهُوَ جَائِزٌ وَإِنْ فَرَّقَهُمَا فَهُوَ أَحَبُّ إِلَيْنَا ‏.‏', 'مضمض واستنشق من كف واحد ‏.‏ وانما ذكره خالد بن عبد الله ‏.‏ وخالد بن عبد الله ثقه حافظ عند اهل الحديث ‏.‏ وقال بعض اهل العلم المضمضه والاستنشاق من كف واحد يجزئ وقال بعضهم تفريقهما احب الينا ‏.‏ وقال الشافعي ان جمعهما في كف واحد فهو جائز وان فرقهما فهو احب الينا ‏.‏', 'Abdullah bin Zaid said:"1 saw the Prophet rinse his mouth and sniff water in his nose using one hand, he did that thrice', NULL, '7895e457cdcfee6eaa4c5ca3a83a9ca92f0c59ff99d31f08972c04b8bddf9f54', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (137, 'tirmidhi', 157, 29, 'Book 1, Hadith 29', 29, NULL, NULL, 'حَدَّثَنَا ابْنُ أَبِي عُمَرَ، حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنْ عَبْدِ الْكَرِيمِ بْنِ أَبِي الْمُخَارِقِ أَبِي أُمَيَّةَ، عَنْ حَسَّانَ بْنِ بِلاَلٍ، قَالَ رَأَيْتُ عَمَّارَ بْنَ يَاسِرٍ تَوَضَّأَ فَخَلَّلَ لِحْيَتَهُ فَقِيلَ لَهُ أَوْ قَالَ فَقُلْتُ لَهُ أَتُخَلِّلُ لِحْيَتَكَ قَالَ وَمَا يَمْنَعُنِي وَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يُخَلِّلُ لِحْيَتَهُ', '.', '.', 'Hassan bin Bilal said:"1 saw Ammar bin Yasir performing Wudu, so he went through his beard (with his hand). It was said to him" - or he said - "1 said: ''You go through your beard?'' He said: ''And what is there to prevent me? Indeed I saw Allah''s Messenger going through his beard', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (138, 'tirmidhi', 157, 30, 'Book 1, Hadith 30', 30, NULL, NULL, 'حَدَّثَنَا ابْنُ أَبِي عُمَرَ، حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنْ سَعِيدِ بْنِ أَبِي عَرُوبَةَ، عَنْ قَتَادَةَ، عَنْ حَسَّانَ بْنِ بِلاَلٍ، عَنْ عَمَّارٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم', 'مِثْلَهُ ‏.‏ قَالَ أَبُو عِيسَى وَفِي الْبَابِ عَنْ عُثْمَانَ وَعَائِشَةَ وَأُمِّ سَلَمَةَ وَأَنَسٍ وَابْنِ أَبِي أَوْفَى وَأَبِي أَيُّوبَ ‏.‏ قَالَ أَبُو عِيسَى وَسَمِعْتُ إِسْحَاقَ بْنَ مَنْصُورٍ يَقُولُ قَالَ أَحْمَدُ بْنُ حَنْبَلٍ قَالَ ابْنُ عُيَيْنَةَ لَمْ يَسْمَعْ عَبْدُ الْكَرِيمِ مِنْ حَسَّانَ بْنِ بِلاَلٍ حَدِيثَ التَّخْلِيلِ ‏.‏ وَقَالَ مُحَمَّدُ بْنُ إِسْمَاعِيلَ أَصَحُّ شَيْءٍ فِي هَذَا الْبَابِ حَدِيثُ عَامِرِ بْنِ شَقِيقٍ عَنْ أَبِي وَائِلٍ عَنْ عُثْمَانَ ‏.‏ قَالَ أَبُو عِيسَى وَقَالَ بِهَذَا أَكْثَرُ أَهْلِ الْعِلْمِ مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم وَمَنْ بَعْدَهُمْ رَأَوْا تَخْلِيلَ اللِّحْيَةِ ‏.‏ وَبِهِ يَقُولُ الشَّافِعِيُّ ‏.‏ وَقَالَ أَحْمَدُ إِنْ سَهَا عَنْ تَخْلِيلِ اللِّحْيَةِ فَهُوَ جَائِزٌ ‏.‏ وَقَالَ إِسْحَاقُ إِنْ تَرَكَهُ نَاسِيًا أَوْ مُتَأَوِّلاً أَجْزَأَهُ وَإِنْ تَرَكَهُ عَامِدًا أَعَادَ ‏.‏', 'مثله ‏.‏ قال ابو عيسي وفي الباب عن عثمان وعائشه وام سلمه وانس وابن ابي اوفي وابي ايوب ‏.‏ قال ابو عيسي وسمعت اسحاق بن منصور يقول قال احمد بن حنبل قال ابن عيينه لم يسمع عبد الكريم من حسان بن بلال حديث التخليل ‏.‏ وقال محمد بن اسماعيل اصح شيء في هذا الباب حديث عامر بن شقيق عن ابي وائل عن عثمان ‏.‏ قال ابو عيسي وقال بهذا اكثر اهل العلم من اصحاب النبي صلي الله عليه وسلم ومن بعدهم راوا تخليل اللحيه ‏.‏ وبه يقول الشافعي ‏.‏ وقال احمد ان سها عن تخليل اللحيه فهو جائز ‏.‏ وقال اسحاق ان تركه ناسيا او متاولا اجزاه وان تركه عامدا اعاد ‏.‏', '(In another narration) Ammar narrated :the same from the Prophet', NULL, '95d94efb39bb2135d2064c41434ce8d067618a7657af73f7591739d13c333381', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (139, 'tirmidhi', 157, 31, 'Book 1, Hadith 31', 31, NULL, NULL, 'حَدَّثَنَا يَحْيَى بْنُ مُوسَى، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، عَنْ إِسْرَائِيلَ، عَنْ عَامِرِ بْنِ شَقِيقٍ، عَنْ أَبِي وَائِلٍ، عَنْ عُثْمَانَ بْنِ عَفَّانَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'كَانَ يُخَلِّلُ لِحْيَتَهُ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏', 'كان يخلل لحيته ‏.‏ قال ابو عيسي هذا حديث حسن صحيح ‏.‏', 'Uthman bin Affan narrated that :the Prophet would go through his beard', NULL, 'bbac5bf7982fee8f2561ac93b495b2d07d6b6549f29f8e2722a79ddec886b3cc', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (140, 'tirmidhi', 157, 32, 'Book 1, Hadith 32', 32, NULL, NULL, 'حَدَّثَنَا إِسْحَاقُ بْنُ مُوسَى الأَنْصَارِيُّ، حَدَّثَنَا مَعْنُ بْنُ عِيسَى الْقَزَّازُ، حَدَّثَنَا مَالِكُ بْنُ أَنَسٍ، عَنْ عَمْرِو بْنِ يَحْيَى، عَنْ أَبِيهِ، عَنْ عَبْدِ اللَّهِ بْنِ زَيْدٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم', 'مَسَحَ رَأْسَهُ بِيَدَيْهِ فَأَقْبَلَ بِهِمَا وَأَدْبَرَ بَدَأَ بِمُقَدَّمِ رَأْسِهِ ثُمَّ ذَهَبَ بِهِمَا إِلَى قَفَاهُ ثُمَّ رَدَّهُمَا حَتَّى رَجَعَ إِلَى الْمَكَانِ الَّذِي بَدَأَ مِنْهُ ثُمَّ غَسَلَ رِجْلَيْهِ ‏.‏ قَالَ أَبُو عِيسَى وَفِي الْبَابِ عَنْ مُعَاوِيَةَ وَالْمِقْدَامِ بْنِ مَعْدِيكَرِبَ وَعَائِشَةَ ‏.‏ قَالَ أَبُو عِيسَى حَدِيثُ عَبْدِ اللَّهِ بْنِ زَيْدٍ أَصَحُّ شَيْءٍ فِي هَذَا الْبَابِ وَأَحْسَنُ وَبِهِ يَقُولُ الشَّافِعِيُّ وَأَحْمَدُ وَإِسْحَاقُ ‏.‏', 'مسح راسه بيديه فاقبل بهما وادبر بدا بمقدم راسه ثم ذهب بهما الي قفاه ثم ردهما حتي رجع الي المكان الذي بدا منه ثم غسل رجليه ‏.‏ قال ابو عيسي وفي الباب عن معاويه والمقدام بن معديكرب وعائشه ‏.‏ قال ابو عيسي حديث عبد الله بن زيد اصح شيء في هذا الباب واحسن وبه يقول الشافعي واحمد واسحاق ‏.‏', 'Abdullah bin Zaid narrated that:"Allah''s Messenger wiped over his head with his hands, going over the front with them and the rear. He began with the front of his head until they went to the nape of his neck. Then he brought them back again to the place where he began. Then he washed his feet', NULL, '6881f8a5d9a785eee851bb9fbd90591580b738655a40760adb8fe46892b828ec', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (141, 'tirmidhi', 157, 33, 'Book 1, Hadith 33', 33, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا بِشْرُ بْنُ الْمُفَضَّلِ، عَنْ عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ، عَنِ الرُّبَيِّعِ بِنْتِ مُعَوِّذِ بْنِ عَفْرَاءَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'مَسَحَ بِرَأْسِهِ مَرَّتَيْنِ بَدَأَ بِمُؤَخَّرِ رَأْسِهِ ثُمَّ بِمُقَدَّمِهِ وَبِأُذُنَيْهِ كِلْتَيْهِمَا ظُهُورِهِمَا وَبُطُونِهِمَا ‏"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ وَحَدِيثُ عَبْدِ اللَّهِ بْنِ زَيْدٍ أَصَحُّ مِنْ هَذَا وَأَجْوَدُ إِسْنَادًا ‏.‏ وَقَدْ ذَهَبَ بَعْضُ أَهْلِ الْكُوفَةِ إِلَى هَذَا الْحَدِيثِ مِنْهُمْ وَكِيعُ بْنُ الْجَرَّاحِ ‏.‏', 'مسح براسه مرتين بدا بمؤخر راسه ثم بمقدمه وباذنيه كلتيهما ظهورهما وبطونهما ‏"‏ ‏.‏ قال ابو عيسي هذا حديث حسن وحديث عبد الله بن زيد اصح من هذا واجود اسنادا ‏.‏ وقد ذهب بعض اهل الكوفه الي هذا الحديث منهم وكيع بن الجراح ‏.‏', 'Ar-Rubay'' bint Mu''awwidh bin Afra'' narrated:"The Prophet wiped his head two times: He began with the rear of his head, then with the front of his head and with both of his ears, outside and Inside of them', NULL, 'ed1599aeff55835854c4fbd1da55197759bc7a00cdd64b7424703ffab66baf19', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (142, 'tirmidhi', 157, 34, 'Book 1, Hadith 34', 34, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا بَكْرُ بْنُ مُضَرَ، عَنِ ابْنِ عَجْلاَنَ، عَنْ عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ، عَنِ الرُّبَيِّعِ بِنْتِ مُعَوِّذِ بْنِ عَفْرَاءَ، أَنَّهَا رَأَتِ النَّبِيَّ صلى الله عليه وسلم يَتَوَضَّأُ قَالَتْ مَسَحَ رَأْسَهُ وَمَسَحَ مَا أَقْبَلَ مِنْهُ وَمَا أَدْبَرَ وَصُدْغَيْهِ وَأُذُنَيْهِ مَرَّةً وَاحِدَةً ‏"‏ ‏.‏ قَالَ وَفِي الْبَابِ عَنْ عَلِيٍّ وَجَدِّ طَلْحَةَ بْنِ مُصَرِّفِ بْنِ عَمْرٍو ‏.‏ قَالَ أَبُو عِيسَى وَحَدِيثُ الرُّبَيِّعِ حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَقَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ عَنِ النَّبِيِّ صلى الله عليه وسلم', 'أَنَّهُ مَسَحَ بِرَأْسِهِ مَرَّةً ‏.‏ وَالْعَمَلُ عَلَى هَذَا عِنْدَ أَكْثَرِ أَهْلِ الْعِلْمِ مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم وَمَنْ بَعْدَهُمْ ‏.‏ وَبِهِ يَقُولُ جَعْفَرُ بْنُ مُحَمَّدٍ وَسُفْيَانُ الثَّوْرِيُّ وَابْنُ الْمُبَارَكِ وَالشَّافِعِيُّ وَأَحْمَدُ وَإِسْحَاقُ رَأَوْا مَسْحَ الرَّأْسِ مَرَّةً وَاحِدَةً ‏.‏ حَدَّثَنَا مُحَمَّدُ بْنُ مَنْصُورٍ الْمَكِّيُّ قَالَ سَمِعْتُ سُفْيَانَ بْنَ عُيَيْنَةَ يَقُولُ سَأَلْتُ جَعْفَرَ بْنَ مُحَمَّدٍ عَنْ مَسْحِ الرَّأْسِ أَيُجْزِئُ مَرَّةً فَقَالَ إِي وَاللَّهِ ‏.‏', 'انه مسح براسه مره ‏.‏ والعمل علي هذا عند اكثر اهل العلم من اصحاب النبي صلي الله عليه وسلم ومن بعدهم ‏.‏ وبه يقول جعفر بن محمد وسفيان الثوري وابن المبارك والشافعي واحمد واسحاق راوا مسح الراس مره واحده ‏.‏ حدثنا محمد بن منصور المكي قال سمعت سفيان بن عيينه يقول سالت جعفر بن محمد عن مسح الراس ايجزئ مره فقال اي والله ‏.‏', 'Ar-Rubayy bint Mu''awidh bin Afra narrated that :she saw the Prophet performing Wudu. She said: "He wiped his head, and what is in the front of it and what is in its rear, and his temples and his ears one time', NULL, '2283fbd423d4d2c514a2b32f692d4d3524a71a1be5e204075ee153c2676481d7', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (143, 'tirmidhi', 157, 35, 'Book 1, Hadith 35', 35, NULL, NULL, 'حَدَّثَنَا عَلِيُّ بْنُ خَشْرَمٍ، أَخْبَرَنَا عَبْدُ اللَّهِ بْنُ وَهْبٍ، حَدَّثَنَا عَمْرُو بْنُ الْحَارِثِ، عَنْ حَبَّانَ بْنِ وَاسِعٍ، عَنْ أَبِيهِ، عَنْ عَبْدِ اللَّهِ بْنِ زَيْدٍ، أَنَّهُ رَأَى النَّبِيَّ صلى الله عليه وسلم تَوَضَّأَ وَأَنَّهُ مَسَحَ رَأْسَهُ بِمَاءٍ غَيْرِ فَضْلِ يَدَيْهِ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَرَوَى ابْنُ لَهِيعَةَ هَذَا الْحَدِيثَ عَنْ حَبَّانَ بْنِ وَاسِعٍ عَنْ أَبِيهِ عَنْ عَبْدِ اللَّهِ بْنِ زَيْدٍ أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'تَوَضَّأَ وَأَنَّهُ مَسَحَ رَأْسَهُ بِمَاءٍ غَبَرَ مِنْ فَضْلِ يَدَيْهِ ‏"‏ ‏.‏ وَرِوَايَةُ عَمْرِو بْنِ الْحَارِثِ عَنْ حَبَّانَ أَصَحُّ لأَنَّهُ قَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ هَذَا الْحَدِيثُ عَنْ عَبْدِ اللَّهِ بْنِ زَيْدٍ وَغَيْرِهِ أَنَّ النَّبِيَّ صلى الله عليه وسلم أَخَذَ لِرَأْسِهِ مَاءً جَدِيدًا ‏.‏ وَالْعَمَلُ عَلَى هَذَا عِنْدَ أَكْثَرِ أَهْلِ الْعِلْمِ رَأَوْا أَنْ يَأْخُذَ لِرَأْسِهِ مَاءً جَدِيدًا ‏.‏', 'توضا وانه مسح راسه بماء غبر من فضل يديه ‏"‏ ‏.‏ وروايه عمرو بن الحارث عن حبان اصح لانه قد روي من غير وجه هذا الحديث عن عبد الله بن زيد وغيره ان النبي صلي الله عليه وسلم اخذ لراسه ماء جديدا ‏.‏ والعمل علي هذا عند اكثر اهل العلم راوا ان ياخذ لراسه ماء جديدا ‏.‏', 'Abdullah bin Zaid narrated that :he saw the Prophet performing Wudu, and that he wiped his head with water that was not left over from his hands', NULL, '658ebb623a77cefb22a94e29df00978b27fc337f697d75170b48fad4bceea444', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (144, 'tirmidhi', 157, 36, 'Book 1, Hadith 36', 36, NULL, NULL, 'حَدَّثَنَا هَنَّادٌ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ إِدْرِيسَ، عَنْ مُحَمَّدِ بْنِ عَجْلاَنَ، عَنْ زَيْدِ بْنِ أَسْلَمَ، عَنْ عَطَاءِ بْنِ يَسَارٍ، عَنِ ابْنِ عَبَّاسٍ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'مَسَحَ بِرَأْسِهِ وَأُذُنَيْهِ ظَاهِرِهِمَا وَبَاطِنِهِمَا ‏.‏ قَالَ أَبُو عِيسَى وَفِي الْبَابِ عَنِ الرُّبَيِّعِ ‏.‏ قَالَ أَبُو عِيسَى وَحَدِيثُ ابْنِ عَبَّاسٍ حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَالْعَمَلُ عَلَى هَذَا عِنْدَ أَكْثَرِ أَهْلِ الْعِلْمِ يَرَوْنَ مَسْحَ الأُذُنَيْنِ ظُهُورِهِمَا وَبُطُونِهِمَا ‏.‏', 'مسح براسه واذنيه ظاهرهما وباطنهما ‏.‏ قال ابو عيسي وفي الباب عن الربيع ‏.‏ قال ابو عيسي وحديث ابن عباس حديث حسن صحيح ‏.‏ والعمل علي هذا عند اكثر اهل العلم يرون مسح الاذنين ظهورهما وبطونهما ‏.‏', 'Ibn ''Abbas narrated:"The Prophet wiped his head and his ears: the outside and the inside of them." ($ahih)', NULL, 'b45a7222b3da4263bc6ec0a884cdf65d03d2d4324d80ab7c19d9a52fff9b4cbc', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (145, 'tirmidhi', 157, 37, 'Book 1, Hadith 37', 37, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ سِنَانِ بْنِ رَبِيعَةَ، عَنْ شَهْرِ بْنِ حَوْشَبٍ، عَنْ أَبِي أُمَامَةَ، قَالَ تَوَضَّأَ النَّبِيُّ صلى الله عليه وسلم فَغَسَلَ وَجْهَهُ ثَلاَثًا وَيَدَيْهِ ثَلاَثًا وَمَسَحَ بِرَأْسِهِ وَقَالَ', 'الأُذُنَانِ مِنَ الرَّأْسِ  . قَالَ أَبُو عِيسَى قَالَ قُتَيْبَةُ قَالَ حَمَّادٌ لاَ أَدْرِي هَذَا مِنْ قَوْلِ النَّبِيِّ صلى الله عليه وسلم أَوْ مِنْ قَوْلِ أَبِي أُمَامَةَ . قَالَ وَفِي الْبَابِ عَنْ أَنَسٍ . قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ لَيْسَ إِسْنَادُهُ بِذَاكَ الْقَائِمِ . وَالْعَمَلُ عَلَى هَذَا عِنْدَ أَكْثَرِ أَهْلِ الْعِلْمِ مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم وَمَنْ بَعْدَهُمْ أَنَّ الأُذُنَيْنِ مِنَ الرَّأْسِ . وَبِهِ يَقُولُ سُفْيَانُ الثَّوْرِيُّ وَابْنُ الْمُبَارَكِ وَالشَّافِعِيُّ وَأَحْمَدُ وَإِسْحَاقُ . وَقَالَ بَعْضُ أَهْلِ الْعِلْمِ مَا أَقْبَلَ مِنَ الأُذُنَيْنِ فَمِنَ الْوَجْهِ وَمَا أَدْبَرَ فَمِنَ الرَّأْسِ . قَالَ إِسْحَاقُ وَأَخْتَارُ أَنْ يَمْسَحَ مُقَدَّمَهُمَا مَعَ الْوَجْهِ وَمُؤَخَّرَهُمَا مَعَ رَأْسِهِ . وَقَالَ الشَّافِعِيُّ هُمَا سُنَّةٌ عَلَى حِيَالِهِمَا يَمْسَحُهُمَا بِمَاءٍ جَدِيدٍ .', 'الاذنان من الراس . قال ابو عيسي قال قتيبه قال حماد لا ادري هذا من قول النبي صلي الله عليه وسلم او من قول ابي امامه . قال وفي الباب عن انس . قال ابو عيسي هذا حديث حسن ليس اسناده بذاك القائم . والعمل علي هذا عند اكثر اهل العلم من اصحاب النبي صلي الله عليه وسلم ومن بعدهم ان الاذنين من الراس . وبه يقول سفيان الثوري وابن المبارك والشافعي واحمد واسحاق . وقال بعض اهل العلم ما اقبل من الاذنين فمن الوجه وما ادبر فمن الراس . قال اسحاق واختار ان يمسح مقدمهما مع الوجه ومؤخرهما مع راسه . وقال الشافعي هما سنه علي حيالهما يمسحهما بماء جديد .', 'Abu Umamah narrated:"The Prophet performed Wudu; so he washed his face three times, and his hands three times, and wiped his head, and he said: "The ears are part of the head', NULL, '919dc0ae8b665248001d31711a27e1dff147b74a77850fcc56bd9012e30dfb08', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (146, 'tirmidhi', 157, 38, 'Book 1, Hadith 38', 38, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ، وَهَنَّادٌ، قَالاَ حَدَّثَنَا وَكِيعٌ، عَنْ سُفْيَانَ، عَنْ أَبِي هَاشِمٍ، عَنْ عَاصِمِ بْنِ لَقِيطِ بْنِ صَبِرَةَ، عَنْ أَبِيهِ، قَالَ قَالَ النَّبِيُّ صلى الله عليه وسلم', 'إِذَا تَوَضَّأْتَ فَخَلِّلِ الأَصَابِعَ  . قَالَ وَفِي الْبَابِ عَنِ ابْنِ عَبَّاسٍ وَالْمُسْتَوْرِدِ وَهُوَ ابْنُ شَدَّادٍ الْفِهْرِيُّ وَأَبِي أَيُّوبَ الأَنْصَارِيِّ . قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ . وَالْعَمَلُ عَلَى هَذَا عِنْدَ أَهْلِ الْعِلْمِ أَنَّهُ يُخَلِّلُ أَصَابِعَ رِجْلَيْهِ فِي الْوُضُوءِ . وَبِهِ يَقُولُ أَحْمَدُ وَإِسْحَاقُ . وَقَالَ إِسْحَاقُ يُخَلِّلُ أَصَابِعَ يَدَيْهِ وَرِجْلَيْهِ فِي الْوُضُوءِ . وَأَبُو هَاشِمٍ اسْمُهُ إِسْمَاعِيلُ بْنُ كَثِيرٍ الْمَكِّيُّ .', 'اذا توضات فخلل الاصابع . قال وفي الباب عن ابن عباس والمستورد وهو ابن شداد الفهري وابي ايوب الانصاري . قال ابو عيسي هذا حديث حسن صحيح . والعمل علي هذا عند اهل العلم انه يخلل اصابع رجليه في الوضوء . وبه يقول احمد واسحاق . وقال اسحاق يخلل اصابع يديه ورجليه في الوضوء . وابو هاشم اسمه اسماعيل بن كثير المكي .', 'Asim bin Laqit bin Sabirah narrated from his father that :the Prophet Muhammad said: "When performing Wudu go between the fingers', NULL, '859f6e7d07db9c77eb2f9de446f6fe4b61bc044ef1b10c92ff21ae3161b20077', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (147, 'tirmidhi', 157, 39, 'Book 1, Hadith 39', 39, NULL, NULL, 'حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعِيدٍ، هُوَ الْجَوْهَرِيُّ حَدَّثَنَا سَعْدُ بْنُ عَبْدِ الْحَمِيدِ بْنِ جَعْفَرٍ، حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ، عَنْ مُوسَى بْنِ عُقْبَةَ، عَنْ صَالِحٍ، مَوْلَى التَّوْأَمَةِ عَنِ ابْنِ عَبَّاسٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏', '"‏ إِذَا تَوَضَّأْتَ فَخَلِّلْ بَيْنَ أَصَابِعِ يَدَيْكَ وَرِجْلَيْكَ ‏"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ ‏.‏', '"‏ اذا توضات فخلل بين اصابع يديك ورجليك ‏"‏ ‏.‏ قال ابو عيسي هذا حديث حسن غريب ‏.‏', 'Ibn Abbas narrated that :Allah''s Messenger said: "When performing Wudu go between the fingers of your hands and (toes of) your feet', NULL, '5fb7da9af0947926b0a9fd54704783ed760eef14e4241db8b849440d6fba413b', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (148, 'tirmidhi', 157, 40, 'Book 1, Hadith 40', 40, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا ابْنُ لَهِيعَةَ، عَنْ يَزِيدَ بْنِ عَمْرٍو، عَنْ أَبِي عَبْدِ الرَّحْمَنِ الْحُبُلِيِّ، عَنِ الْمُسْتَوْرِدِ بْنِ شَدَّادٍ الْفِهْرِيِّ، قَالَ رَأَيْتُ النَّبِيَّ صلى الله عليه وسلم إِذَا تَوَضَّأَ دَلَكَ أَصَابِعَ رِجْلَيْهِ بِخِنْصَرِهِ', '. قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ لاَ نَعْرِفُهُ إِلاَّ مِنْ حَدِيثِ ابْنِ لَهِيعَةَ .', '. قال ابو عيسي هذا حديث حسن غريب لا نعرفه الا من حديث ابن لهيعه .', 'Al-Mustawrid bin Shaddad Al-Fihri said :"I saw the Prophet when he was performing Wudu doing that to the toes on his feet with his pinky', NULL, '2d80d34cfaec155b753f39042d02871759efcb9bc26cb72343281ec184daf1d6', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (149, 'tirmidhi', 157, 41, 'Book 1, Hadith 41', 41, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ، قَالَ حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ، عَنْ سُهَيْلِ بْنِ أَبِي صَالِحٍ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏"‏ وَيْلٌ لِلأَعْقَابِ مِنَ النَّارِ ‏"‏ ‏.‏ قَالَ وَفِي الْبَابِ عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو وَعَائِشَةَ وَجَابِرٍ وَعَبْدِ اللَّهِ بْنِ الْحَارِثِ هُوَ ابْنُ جَزْءٍ الزُّبَيْدِيُّ وَمُعَيْقِيبٍ وَخَالِدِ بْنِ الْوَلِيدِ وَشُرَحْبِيلَ بْنِ حَسَنَةَ وَعَمْرِو بْنِ الْعَاصِ وَيَزِيدَ بْنِ أَبِي سُفْيَانَ ‏.‏ قَالَ أَبُو عِيسَى حَدِيثُ أَبِي هُرَيْرَةَ حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَقَدْ رُوِيَ عَنِ النَّبِيِّ صلى الله عليه وسلم', 'أَنَّهُ قَالَ ‏"‏ وَيْلٌ لِلأَعْقَابِ وَبُطُونِ الأَقْدَامِ مِنَ النَّارِ ‏"‏ ‏.‏ قَالَ وَفِقْهُ هَذَا الْحَدِيثِ أَنَّهُ لاَ يَجُوزُ الْمَسْحُ عَلَى الْقَدَمَيْنِ إِذَا لَمْ يَكُنْ عَلَيْهِمَا خُفَّانِ أَوْ جَوْرَبَانِ ‏.‏', 'انه قال ‏"‏ ويل للاعقاب وبطون الاقدام من النار ‏"‏ ‏.‏ قال وفقه هذا الحديث انه لا يجوز المسح علي القدمين اذا لم يكن عليهما خفان او جوربان ‏.‏', 'Abu Hurairah narrated that :the Prophet said: "Protect the heels from the Fire', NULL, '01a94686333bdb776ab84e94f2adeec5ef1904cd600fa75a1fb21eed17d09afa', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (150, 'tirmidhi', 157, 42, 'Book 1, Hadith 42', 42, NULL, NULL, 'حَدَّثَنَا أَبُو كُرَيْبٍ، وَهَنَّادٌ، وَقُتَيْبَةُ، قَالُوا حَدَّثَنَا وِكِيعٌ، عَنْ سُفْيَانَ، ح قَالَ وَحَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، قَالَ حَدَّثَنَا سُفْيَانُ، عَنْ زَيْدِ بْنِ أَسْلَمَ، عَنْ عَطَاءِ بْنِ يَسَارٍ، عَنِ ابْنِ عَبَّاسٍ، أَنَّ النَّبِيَّ صلى الله عليه وسلم تَوَضَّأَ مَرَّةً مَرَّةً ‏.‏ قَالَ أَبُو عِيسَى وَفِي الْبَابِ عَنْ عُمَرَ وَجَابِرٍ وَبُرَيْدَةَ وَأَبِي رَافِعٍ وَابْنِ الْفَاكِهِ ‏.‏ قَالَ أَبُو عِيسَى وَحَدِيثُ ابْنِ عَبَّاسٍ أَحْسَنُ شَيْءٍ فِي هَذَا الْبَابِ وَأَصَحُّ ‏.‏ وَرَوَى رِشْدِينُ بْنُ سَعْدٍ وَغَيْرُهُ هَذَا الْحَدِيثَ عَنِ الضَّحَّاكِ بْنِ شُرَحْبِيلَ عَنْ زَيْدِ بْنِ أَسْلَمَ عَنْ أَبِيهِ عَنْ عُمَرَ بْنِ الْخَطَّابِ أَنَّ النَّبِيَّ صلى الله عليه وسلم تَوَضَّأَ مَرَّةً مَرَّةً ‏.‏ قَالَ وَلَيْسَ هَذَا بِشَيْءٍ وَالصَّحِيحُ مَا رَوَى ابْنُ عَجْلاَنَ وَهِشَامُ بْنُ سَعْدٍ وَسُفْيَانُ الثَّوْرِيُّ وَعَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ عَنْ زَيْدِ بْنِ أَسْلَمَ عَنْ عَطَاءِ بْنِ يَسَارٍ عَنِ ابْنِ عَبَّاسٍ عَنِ النَّبِيِّ صلى الله عليه وسلم ‏', '.‏', '.‏', 'Ibn Abbas narrated:"The Prophet performed Wudu one time (for each limb)', NULL, 'deb1860477f9d3decf01edc0cfbecd57dbb43c8f35e8be68cc55d4bcf9bf9441', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published')
INSERT INTO public.hadith_narrations (id, collection_id, book_id, hadith_number, in_book_reference, international_number, chapter_title_arabic, chapter_title_english, sanad_arabic, matn_arabic, matn_clean, translation_english, translation_urdu, text_checksum, source_edition, version_number, is_current, status) VALUES
  (151, 'tirmidhi', 157, 43, 'Book 1, Hadith 43', 43, NULL, NULL, 'حَدَّثَنَا أَبُو كُرَيْبٍ، وَمُحَمَّدُ بْنُ رَافِعٍ، قَالاَ حَدَّثَنَا زَيْدُ بْنُ حُبَابٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ ثَابِتِ بْنِ ثَوْبَانَ، قَالَ حَدَّثَنِي عَبْدُ اللَّهِ بْنُ الْفَضْلِ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ هُرْمُزَ، هُوَ الأَعْرَجُ عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'تَوَضَّأَ مَرَّتَيْنِ مَرَّتَيْنِ ‏.‏ قَالَ أَبُو عِيسَى وَفِي الْبَابِ عَنْ جَابِرٍ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ لاَ نَعْرِفُهُ إِلاَّ مِنْ حَدِيثِ ابْنِ ثَوْبَانَ عَنْ عَبْدِ اللَّهِ بْنِ الْفَضْلِ وَهُوَ إِسْنَادٌ حَسَنٌ صَحِيحٌ ‏.‏ قَالَ أَبُو عِيسَى وَقَدْ رَوَى هَمَّامٌ عَنْ عَامِرٍ الأَحْوَلِ عَنْ عَطَاءٍ عَنْ أَبِي هُرَيْرَةَ أَنَّ النَّبِيَّ صلى الله عليه وسلم تَوَضَّأَ ثَلاَثًا ثَلاَثًا ‏"‏ ‏.‏', 'توضا مرتين مرتين ‏.‏ قال ابو عيسي وفي الباب عن جابر ‏.‏ قال ابو عيسي هذا حديث حسن غريب لا نعرفه الا من حديث ابن ثوبان عن عبد الله بن الفضل وهو اسناد حسن صحيح ‏.‏ قال ابو عيسي وقد روي همام عن عامر الاحول عن عطاء عن ابي هريره ان النبي صلي الله عليه وسلم توضا ثلاثا ثلاثا ‏"‏ ‏.‏', 'Abu Hurairah narrated:"The Prophet performed Wudu two time (for each limb)', NULL, '2876e160c63f74c283edd0c51e201a9e6f29c0d56483b8bd98f081e489863618', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (152, 'tirmidhi', 157, 44, 'Book 1, Hadith 44', 44, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ، عَنْ سُفْيَانَ، عَنْ أَبِي إِسْحَاقَ، عَنْ أَبِي حَيَّةَ، عَنْ عَلِيٍّ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'تَوَضَّأَ ثَلاَثًا ثَلاَثًا ‏.‏ قَالَ أَبُو عِيسَى وَفِي الْبَابِ عَنْ عُثْمَانَ وَعَائِشَةَ وَالرُّبَيِّعِ وَابْنِ عُمَرَ وَأَبِي أُمَامَةَ وَأَبِي رَافِعٍ وَعَبْدِ اللَّهِ بْنِ عَمْرٍو وَمُعَاوِيَةَ وَأَبِي هُرَيْرَةَ وَجَابِرٍ وَعَبْدِ اللَّهِ بْنِ زَيْدٍ وَأُبَىِّ بْنِ كَعْبٍ ‏.‏ قَالَ أَبُو عِيسَى حَدِيثُ عَلِيٍّ أَحْسَنُ شَيْءٍ فِي هَذَا الْبَابِ وَأَصَحُّ لأَنَّهُ قَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ عَنْ عَلِيٍّ رِضْوَانُ اللَّهِ عَلَيْهِ ‏.‏ وَالْعَمَلُ عَلَى هَذَا عِنْدَ عَامَّةِ أَهْلِ الْعِلْمِ أَنَّ الْوُضُوءَ يُجْزِئُ مَرَّةً مَرَّةً وَمَرَّتَيْنِ أَفْضَلُ وَأَفْضَلُهُ ثَلاَثٌ وَلَيْسَ بَعْدَهُ شَيْءٌ ‏.‏ وَقَالَ ابْنُ الْمُبَارَكِ لاَ آمَنُ إِذَا زَادَ فِي الْوُضُوءِ عَلَى الثَّلاَثِ أَنْ يَأْثَمَ ‏.‏ وَقَالَ أَحْمَدُ وَإِسْحَاقُ لاَ يَزِيدُ عَلَى الثَّلاَثِ إِلاَّ رَجُلٌ مُبْتَلًى ‏.‏', 'توضا ثلاثا ثلاثا ‏.‏ قال ابو عيسي وفي الباب عن عثمان وعائشه والربيع وابن عمر وابي امامه وابي رافع وعبد الله بن عمرو ومعاويه وابي هريره وجابر وعبد الله بن زيد وابي بن كعب ‏.‏ قال ابو عيسي حديث علي احسن شيء في هذا الباب واصح لانه قد روي من غير وجه عن علي رضوان الله عليه ‏.‏ والعمل علي هذا عند عامه اهل العلم ان الوضوء يجزئ مره مره ومرتين افضل وافضله ثلاث وليس بعده شيء ‏.‏ وقال ابن المبارك لا امن اذا زاد في الوضوء علي الثلاث ان ياثم ‏.‏ وقال احمد واسحاق لا يزيد علي الثلاث الا رجل مبتلي ‏.‏', 'Ali narrated that:"The Prophet performed Wudu three times (for each limb)', NULL, '350bc37163e479102eb633e49d4132acc5efd1895da2ebe408119c34269678b1', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (153, 'tirmidhi', 157, 45, 'Book 1, Hadith 45', 45, NULL, NULL, 'حَدَّثَنَا إِسْمَاعِيلُ بْنُ مُوسَى الْفَزَارِيُّ، حَدَّثَنَا شَرِيكٌ، عَنْ ثَابِتِ بْنِ أَبِي صَفِيَّةَ، قَالَ قُلْتُ لأَبِي جَعْفَرٍ حَدَّثَكَ جَابِرٌ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'تَوَضَّأَ مَرَّةً مَرَّةً وَمَرَّتَيْنِ مَرَّتَيْنِ وَثَلاَثًا ثَلاَثًا قَالَ نَعَمْ ‏.‏', 'توضا مره مره ومرتين مرتين وثلاثا ثلاثا قال نعم ‏.‏', 'Thabit bin Abi Safiyyah said, :"I asked Abu Ja''far: ''Did Jabir narrate to you that: "The Prophet performed Wudu one time each, and two times, and three times?" He said: "Yes', NULL, '66ccc2c7f51b336aab9d7928f14bdc8d65df664c363e5c478749b09af12bc5ee', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (154, 'tirmidhi', 157, 46, 'Book 1, Hadith 46', 46, NULL, NULL, 'قَالَ أَبُو عِيسَى وَرَوَى وَكِيعٌ، هَذَا الْحَدِيثَ عَنْ ثَابِتِ بْنِ أَبِي صَفِيَّةَ، قَالَ قُلْتُ لأَبِي جَعْفَرٍ حَدَّثَكَ جَابِرٌ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'تَوَضَّأَ مَرَّةً مَرَّةً قَالَ نَعَمْ ‏.‏ حَدَّثَنَا بِذَلِكَ هَنَّادٌ وَقُتَيْبَةُ قَالاَ حَدَّثَنَا وَكِيعٌ عَنْ ثَابِتِ بْنِ أَبِي صَفِيَّةَ ‏.‏ قَالَ أَبُو عِيسَى وَهَذَا أَصَحُّ مِنْ حَدِيثِ شَرِيكٍ لأَنَّهُ قَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ هَذَا عَنْ ثَابِتٍ نَحْوَ رِوَايَةِ وَكِيعٍ ‏.‏ وَشَرِيكٌ كَثِيرُ الْغَلَطِ وَثَابِتُ بْنُ أَبِي صَفِيَّةَ هُوَ أَبُو حَمْزَةَ الثُّمَالِيُّ ‏.‏', 'توضا مره مره قال نعم ‏.‏ حدثنا بذلك هناد وقتيبه قالا حدثنا وكيع عن ثابت بن ابي صفيه ‏.‏ قال ابو عيسي وهذا اصح من حديث شريك لانه قد روي من غير وجه هذا عن ثابت نحو روايه وكيع ‏.‏ وشريك كثير الغلط وثابت بن ابي صفيه هو ابو حمزه الثمالي ‏.‏', 'Thabit bin Abi Safiyyah said, :"1 asked Abu Ja''far: ''Did Jabir narrate to you that: "The Prophet performed Wudu one time each?" He said: "Yes', NULL, 'beaf29245d8e879f8f320276b68dddab9e5b51718ef5aefbcae792cb4625a8bd', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (155, 'tirmidhi', 157, 47, 'Book 1, Hadith 47', 47, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ أَبِي عُمَرَ، حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، عَنْ عَمْرِو بْنِ يَحْيَى، عَنْ أَبِيهِ، عَنْ عَبْدِ اللَّهِ بْنِ زَيْدٍ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'تَوَضَّأَ فَغَسَلَ وَجْهَهُ ثَلاَثًا وَغَسَلَ يَدَيْهِ مَرَّتَيْنِ مَرَّتَيْنِ وَمَسَحَ بِرَأْسِهِ وَغَسَلَ رِجْلَيْهِ مَرَّتَيْنِ ‏.‏ قَالَ أَبُو عِيسَى وَهَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَقَدْ ذُكِرَ فِي غَيْرِ حَدِيثٍ أَنَّ النَّبِيَّ صلى الله عليه وسلم تَوَضَّأَ بَعْضَ وُضُوئِهِ مَرَّةً وَبَعْضَهُ ثَلاَثًا ‏.‏ وَقَدْ رَخَّصَ بَعْضُ أَهْلِ الْعِلْمِ فِي ذَلِكَ لَمْ يَرَوْا بَأْسًا أَنْ يَتَوَضَّأَ الرَّجْلُ بَعْضَ وُضُوئِهِ ثَلاَثًا وَبَعْضَهُ مَرَّتَيْنِ أَوْ مَرَّةً ‏.‏', 'توضا فغسل وجهه ثلاثا وغسل يديه مرتين مرتين ومسح براسه وغسل رجليه مرتين ‏.‏ قال ابو عيسي وهذا حديث حسن صحيح ‏.‏ وقد ذكر في غير حديث ان النبي صلي الله عليه وسلم توضا بعض وضوئه مره وبعضه ثلاثا ‏.‏ وقد رخص بعض اهل العلم في ذلك لم يروا باسا ان يتوضا الرجل بعض وضوئه ثلاثا وبعضه مرتين او مره ‏.‏', 'Abdullah bin Zaid narrated that:"The Prophet performed Wudu. So he washed his face three times, and washed his hands two times each, and wiped his head, and washed his feet [two times]', NULL, '10bd99739a2afc29a61b7499f46860a6222421674ffdb24c5342510717412ab1', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (156, 'tirmidhi', 157, 48, 'Book 1, Hadith 48', 48, NULL, NULL, 'حَدَّثَنَا هَنَّادٌ، وَقُتَيْبَةُ، قَالاَ حَدَّثَنَا أَبُو الأَحْوَصِ، عَنْ أَبِي إِسْحَاقَ، عَنْ أَبِي حَيَّةَ، قَالَ رَأَيْتُ عَلِيًّا تَوَضَّأَ فَغَسَلَ كَفَّيْهِ حَتَّى أَنْقَاهُمَا ثُمَّ مَضْمَضَ ثَلاَثًا وَاسْتَنْشَقَ ثَلاَثًا وَغَسَلَ وَجْهَهُ ثَلاَثًا وَذِرَاعَيْهِ ثَلاَثًا وَمَسَحَ بِرَأْسِهِ مَرَّةً ثُمَّ غَسَلَ قَدَمَيْهِ إِلَى الْكَعْبَيْنِ ثُمَّ قَامَ فَأَخَذَ فَضْلَ طَهُورِهِ فَشَرِبَهُ وَهُوَ قَائِمٌ ثُمَّ قَالَ أَحْبَبْتُ أَنْ أُرِيَكُمْ كَيْفَ كَانَ طُهُورُ رَسُولِ اللَّهِ صلى الله عليه وسلم', '. قَالَ أَبُو عِيسَى وَفِي الْبَابِ عَنْ عُثْمَانَ وَعَبْدِ اللَّهِ بْنِ زَيْدٍ وَابْنِ عَبَّاسٍ وَعَبْدِ اللَّهِ بْنِ عَمْرٍو وَالرُّبَيِّعِ وَعَبْدِ اللَّهِ بْنِ أُنَيْسٍ وَعَائِشَةَ رِضْوَانُ اللَّهِ عَلَيْهِمْ .', '. قال ابو عيسي وفي الباب عن عثمان وعبد الله بن زيد وابن عباس وعبد الله بن عمرو والربيع وعبد الله بن انيس وعائشه رضوان الله عليهم .', 'Abu Hayyah narrated:"I saw Ali performing Wudu. He washed his hands until he cleaned them, then he rinsed out his mouth three times, sniffed water into his nose and blew it out three times, washed his face three times, and his forearms three times. He wiped his head once, then he washed his feet up to the ankles. Then he stood up, taking what was left over from his purification (water) and drank it while he was standing. Then he said, ''I wanted to show you how Allah''s Messenger purified himself', NULL, '6a15ee4a3268439f5860ad0815b09748052b743c49d33795711caf1b4cf31080', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (157, 'tirmidhi', 157, 49, 'Book 1, Hadith 49', 49, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ، وَهَنَّادٌ، قَالاَ حَدَّثَنَا أَبُو الأَحْوَصِ، عَنْ أَبِي إِسْحَاقَ، عَنْ عَبْدِ خَيْرٍ، ذَكَرَ عَنْ عَلِيٍّ، مِثْلَ حَدِيثِ أَبِي حَيَّةَ إِلاَّ أَنَّ عَبْدَ خَيْرٍ، قَالَ كَانَ إِذَا فَرَغَ مِنْ طُهُورِهِ أَخَذَ مِنْ فَضْلِ طَهُورِهِ بِكَفِّهِ فَشَرِبَهُ', '. قَالَ أَبُو عِيسَى حَدِيثُ عَلِيٍّ رَوَاهُ أَبُو إِسْحَاقَ الْهَمْدَانِيُّ عَنْ أَبِي حَيَّةَ وَعَبْدِ خَيْرٍ وَالْحَارِثِ عَنْ عَلِيٍّ وَقَدْ رَوَى زَائِدَةُ بْنُ قُدَامَةَ وَغَيْرُ وَاحِدٍ عَنْ خَالِدِ بْنِ عَلْقَمَةَ عَنْ عَبْدِ خَيْرٍ عَنْ عَلِيٍّ رضى الله عنه حَدِيثَ الْوُضُوءِ بِطُولِهِ . وَهَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ . قَالَ وَرَوَى شُعْبَةُ هَذَا الْحَدِيثَ عَنْ خَالِدِ بْنِ عَلْقَمَةَ فَأَخْطَأَ فِي اسْمِهِ وَاسْمِ أَبِيهِ فَقَالَ مَالِكُ بْنُ عُرْفُطَةَ عَنْ عَبْدِ خَيْرٍ عَنْ عَلِيٍّ . قَالَ وَرُوِيَ عَنْ أَبِي عَوَانَةَ عَنْ خَالِدِ بْنِ عَلْقَمَةَ عَنْ عَبْدِ خَيْرٍ عَنْ عَلِيٍّ . قَالَ وَرُوِيَ عَنْهُ عَنْ مَالِكِ بْنِ عُرْفُطَةَ مِثْلَ رِوَايَةِ شُعْبَةَ وَالصَّحِيحُ خَالِدُ بْنُ عَلْقَمَةَ .', '. قال ابو عيسي حديث علي رواه ابو اسحاق الهمداني عن ابي حيه وعبد خير والحارث عن علي وقد روي زائده بن قدامه وغير واحد عن خالد بن علقمه عن عبد خير عن علي رضي الله عنه حديث الوضوء بطوله . وهذا حديث حسن صحيح . قال وروي شعبه هذا الحديث عن خالد بن علقمه فاخطا في اسمه واسم ابيه فقال مالك بن عرفطه عن عبد خير عن علي . قال وروي عن ابي عوانه عن خالد بن علقمه عن عبد خير عن علي . قال وروي عنه عن مالك بن عرفطه مثل روايه شعبه والصحيح خالد بن علقمه .', 'Abd Khair related a narration similar to that of Abu Hayyah, :from Ali (no. 48). Except that Abd Khair''s version includes the following additions: "When he was finished from his purification, he would take what was left over from his purification with his hand to drink it', NULL, 'f618543491faa9f49d95ff56f34cc2e7aeab80fb6bbacc34d6705bb246d3f682', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (158, 'tirmidhi', 157, 50, 'Book 1, Hadith 50', 50, NULL, NULL, 'حَدَّثَنَا نَصْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ، وَأَحْمَدُ بْنُ أَبِي عُبَيْدِ اللَّهِ السَّلِيمِيُّ الْبَصْرِيُّ، قَالاَ حَدَّثَنَا أَبُو قُتَيْبَةَ، سَلْمُ بْنُ قُتَيْبَةَ عَنِ الْحَسَنِ بْنِ عَلِيٍّ الْهَاشِمِيِّ، عَنْ عَبْدِ الرَّحْمَنِ الأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏', '"‏ جَاءَنِي جِبْرِيلُ فَقَالَ يَا مُحَمَّدُ إِذَا تَوَضَّأْتَ فَانْتَضِحْ ‏"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ ‏.‏ قَالَ وَسَمِعْتُ مُحَمَّدًا يَقُولُ الْحَسَنُ بْنُ عَلِيٍّ الْهَاشِمِيُّ مُنْكَرُ الْحَدِيثِ ‏.‏ قَالَ وَفِي الْبَابِ عَنْ أَبِي الْحَكَمِ بْنِ سُفْيَانَ وَابْنِ عَبَّاسٍ وَزَيْدِ بْنِ حَارِثَةَ وَأَبِي سَعِيدٍ الْخُدْرِيِّ ‏.‏ وَقَالَ بَعْضُهُمْ سُفْيَانُ بْنُ الْحَكَمِ أَوِ الْحَكَمُ بْنُ سُفْيَانَ وَاضْطَرَبُوا فِي هَذَا الْحَدِيثِ ‏.‏', '"‏ جاءني جبريل فقال يا محمد اذا توضات فانتضح ‏"‏ ‏.‏ قال ابو عيسي هذا حديث غريب ‏.‏ قال وسمعت محمدا يقول الحسن بن علي الهاشمي منكر الحديث ‏.‏ قال وفي الباب عن ابي الحكم بن سفيان وابن عباس وزيد بن حارثه وابي سعيد الخدري ‏.‏ وقال بعضهم سفيان بن الحكم او الحكم بن سفيان واضطربوا في هذا الحديث ‏.‏', 'Abu Hurairah narrated that :the Prophet said: "Jibril came to me and he said: ''O Muhammad! When you perform wudu then perform Nadh', NULL, 'b8790d55f999017a00ea0d91e8fc80b6082098698aa044eba0ba3fac2125bb25', 'TIRMIDHI Darussalam Reference Edition', 1, TRUE, 'published'),
  (159, 'abudawud', 207, 1, 'Book 1, Hadith 1', 1, NULL, NULL, 'حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ بْنِ قَعْنَبٍ الْقَعْنَبِيُّ، حَدَّثَنَا عَبْدُ الْعَزِيزِ، - يَعْنِي ابْنَ مُحَمَّدٍ - عَنْ مُحَمَّدٍ، - يَعْنِي ابْنَ عَمْرٍو - عَنْ أَبِي سَلَمَةَ، عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'كَانَ إِذَا ذَهَبَ الْمَذْهَبَ أَبْعَدَ ‏.‏', 'كان اذا ذهب المذهب ابعد ‏.‏', 'Narrated Mughirah ibn Shu''bah: When the Prophet (ﷺ) went (outside) to relieve himself, he went to a far-off place', NULL, '8017dd6c84dd3c9b9a388b79c12903c2d2293bf7db3f3d6fe3e520dfdfd64824', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (160, 'abudawud', 207, 2, 'Book 1, Hadith 2', 2, NULL, NULL, 'حَدَّثَنَا مُسَدَّدُ بْنُ مُسَرْهَدٍ، حَدَّثَنَا عِيسَى بْنُ يُونُسَ، أَخْبَرَنَا إِسْمَاعِيلُ بْنُ عَبْدِ الْمَلِكِ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'كَانَ إِذَا أَرَادَ الْبَرَازَ انْطَلَقَ حَتَّى لاَ يَرَاهُ أَحَدٌ ‏.‏', 'كان اذا اراد البراز انطلق حتي لا يراه احد ‏.‏', 'Narrated Jabir ibn Abdullah: When the Prophet (ﷺ) felt the need of relieving himself, he went far off where no one could see him', NULL, '189d6d067bbf9ca0e0984a618986e573423e184546acdde1b23b737c471ab4b8', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (161, 'abudawud', 207, 3, 'Book 1, Hadith 3', 3, NULL, NULL, 'حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا حَمَّادٌ، أَخْبَرَنَا أَبُو التَّيَّاحِ، حَدَّثَنِي شَيْخٌ، قَالَ لَمَّا قَدِمَ عَبْدُ اللَّهِ بْنُ عَبَّاسٍ الْبَصْرَةَ فَكَانَ يُحَدَّثُ عَنْ أَبِي مُوسَى، فَكَتَبَ عَبْدُ اللَّهِ إِلَى أَبِي مُوسَى يَسْأَلُهُ عَنْ أَشْيَاءَ، فَكَتَبَ إِلَيْهِ أَبُو مُوسَى إِنِّي كُنْتُ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم ذَاتَ يَوْمٍ فَأَرَادَ أَنْ يَبُولَ فَأَتَى دَمِثًا فِي أَصْلِ جِدَارٍ فَبَالَ ثُمَّ قَالَ صلى الله عليه وسلم', 'إِذَا أَرَادَ أَحَدُكُمْ أَنْ يَبُولَ فَلْيَرْتَدْ لِبَوْلِهِ مَوْضِعًا  .', 'اذا اراد احدكم ان يبول فليرتد لبوله موضعا .', 'Abu al-Tayyah reported on the authority of a shaykh (an old man):When Abdullah ibn Abbas came to Basrah, people narrated to him traditions from AbuMusa. Therefore Ibn Abbas wrote to him asking him about certain things. In reply AbuMusa wrote to him saying: One day I was in the company of the Messenger of Allah (ﷺ). He wanted to urinate. Then he came to a soft ground at the foot of a wall and urinated. He (the Prophet) then said: If any of you wants to urinate, he should look for a place (like this) for his urination', NULL, '8a50f2a22c6eea604f07af5a26e74129962d4f3a1d2ba1a15919b95f1226b666', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (162, 'abudawud', 207, 4, 'Book 1, Hadith 4', 4, NULL, NULL, NULL, 'حَدَّثَنَا مُسَدَّدُ بْنُ مُسَرْهَدٍ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، وَعَبْدُ الْوَارِثِ، عَنْ عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ، عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِذَا دَخَلَ الْخَلاَءَ - قَالَ عَنْ حَمَّادٍ قَالَ ‏"‏ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ ‏"‏ ‏.‏ وَقَالَ عَنْ عَبْدِ الْوَارِثِ - قَالَ ‏"‏ أَعُوذُ بِاللَّهِ مِنَ الْخُبُثِ وَالْخَبَائِثِ ‏"‏ ‏.‏ قَالَ أَبُو دَاوُد رَوَاهُ شُعْبَةُ عَنْ عَبْدِ الْعَزِيزِ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ وَقَالَ مَرَّةً أَعُوذُ بِاللَّهِ و قَالَ وُهَيْبٌ فَلْيَتَعَوَّذْ بِاللَّهِ', 'حدثنا مسدد بن مسرهد، حدثنا حماد بن زيد، وعبد الوارث، عن عبد العزيز بن صهيب، عن انس بن مالك، قال كان رسول الله صلي الله عليه وسلم اذا دخل الخلاء - قال عن حماد قال ‏"‏ اللهم اني اعوذ بك ‏"‏ ‏.‏ وقال عن عبد الوارث - قال ‏"‏ اعوذ بالله من الخبث والخبائث ‏"‏ ‏.‏ قال ابو داود رواه شعبه عن عبد العزيز اللهم اني اعوذ بك وقال مره اعوذ بالله و قال وهيب فليتعوذ بالله', 'Anas b. Malik reported:When the Apostle of Allaah (sal Allahu alayhi wa sallam) entered the toilet, he used to say (before entering): "O Allaah, I seek refuge in Thee." This is according to the version of Hammad. ''Abd al-Warith has another version :"I seek refuge in Allaah from male and female devils', NULL, '2b4e28d407fedadeb27719a5b3ba3b956b8b585685ba3fc1807fa859688bcdc0', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (163, 'abudawud', 207, 5, 'Book 1, Hadith 5', 5, NULL, NULL, NULL, 'حَدَّثَنَا الْحَسَنُ بْنُ عَمْرٍو، - يَعْنِي السَّدُوسِيَّ - حَدَّثَنَا وَكِيعٌ، عَنْ شُعْبَةَ، عَنْ عَبْدِ الْعَزِيزِ، - هُوَ ابْنُ صُهَيْبٍ - عَنْ أَنَسٍ، بِهَذَا الْحَدِيثِ قَالَ ‏"‏ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ ‏"‏ ‏.‏ وَقَالَ شُعْبَةُ وَقَالَ مَرَّةً ‏"‏ أَعُوذُ بِاللَّهِ ‏"‏ ‏.‏', 'حدثنا الحسن بن عمرو، - يعني السدوسي - حدثنا وكيع، عن شعبه، عن عبد العزيز، - هو ابن صهيب - عن انس، بهذا الحديث قال ‏"‏ اللهم اني اعوذ بك ‏"‏ ‏.‏ وقال شعبه وقال مره ‏"‏ اعوذ بالله ‏"‏ ‏.‏', 'Another tradition on the authority of Anas has:" O Allaah, I seek refuge in Thee." Shu''bah said: Anas sometimes reported the words: "I take refuge in Allah', NULL, '51f06db4a8a68683fa24d4ab75089fa3aba7d263104a97b5b4168dcbe831082d', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (164, 'abudawud', 207, 6, 'Book 1, Hadith 6', 6, NULL, NULL, 'حَدَّثَنَا عَمْرُو بْنُ مَرْزُوقٍ، أَخْبَرَنَا شُعْبَةُ، عَنْ قَتَادَةَ، عَنِ النَّضْرِ بْنِ أَنَسٍ، عَنْ زَيْدِ بْنِ أَرْقَمَ، عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم قَالَ ‏', '"‏ إِنَّ هَذِهِ الْحُشُوشَ مُحْتَضَرَةٌ فَإِذَا أَتَى أَحَدُكُمُ الْخَلاَءَ فَلْيَقُلْ أَعُوذُ بِاللَّهِ مِنَ الْخُبُثِ وَالْخَبَائِثِ ‏"‏ ‏.‏', '"‏ ان هذه الحشوش محتضره فاذا اتي احدكم الخلاء فليقل اعوذ بالله من الخبث والخبائث ‏"‏ ‏.‏', 'Narrated Zayd ibn Arqam: The Messenger of Allah (ﷺ) said: These privies are frequented by the jinns and devils. So when anyone amongst you goes there, he should say: "I seek refuge in Allah from male and female devils', NULL, '8e71f74dc0f0fc2a2ade1139c46cab125a9e542c133184ec60c42bedda8a4139', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (165, 'abudawud', 207, 7, 'Book 1, Hadith 7', 7, NULL, NULL, 'حَدَّثَنَا مُسَدَّدُ بْنُ مُسَرْهَدٍ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ، عَنْ سَلْمَانَ، قَالَ قِيلَ لَهُ لَقَدْ عَلَّمَكُمْ نَبِيُّكُمْ كُلَّ شَىْءٍ حَتَّى الْخِرَاءَةَ', '. قَالَ أَجَلْ لَقَدْ نَهَانَا صلى الله عليه وسلم أَنْ نَسْتَقْبِلَ الْقِبْلَةَ بِغَائِطٍ أَوْ بَوْلٍ وَأَنْ لاَ نَسْتَنْجِيَ بِالْيَمِينِ وَأَنْ لاَ يَسْتَنْجِيَ أَحَدُنَا بِأَقَلَّ مِنْ ثَلاَثَةِ أَحْجَارٍ أَوْ يَسْتَنْجِيَ بِرَجِيعٍ أَوْ عَظْمٍ .', '. قال اجل لقد نهانا صلي الله عليه وسلم ان نستقبل القبله بغائط او بول وان لا نستنجي باليمين وان لا يستنجي احدنا باقل من ثلاثه احجار او يستنجي برجيع او عظم .', 'Narrated Salman al-Farsi: It was said to Salman: Your Prophet teaches you everything, even about excrement. He replied: Yes. He has forbidden us to face the qiblah at the time of easing or urinating, and cleansing with right hand, and cleansing with less than three stones, or cleansing with dung or bone', NULL, 'd31e2dd9fca6fd139813f4aea7d904adc5118c496d04238479a292a16f66f4f3', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (166, 'abudawud', 207, 8, 'Book 1, Hadith 8', 8, NULL, NULL, 'حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ النُّفَيْلِيُّ، حَدَّثَنَا ابْنُ الْمُبَارَكِ، عَنْ مُحَمَّدِ بْنِ عَجْلاَنَ، عَنِ الْقَعْقَاعِ بْنِ حَكِيمٍ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ إِنَّمَا أَنَا لَكُمْ بِمَنْزِلَةِ الْوَالِدِ أُعَلِّمُكُمْ فَإِذَا أَتَى أَحَدُكُمُ الْغَائِطَ فَلاَ يَسْتَقْبِلِ الْقِبْلَةَ وَلاَ يَسْتَدْبِرْهَا وَلاَ يَسْتَطِبْ بِيَمِينِهِ ‏"‏ ‏.‏ وَكَانَ يَأْمُرُ بِثَلاَثَةِ أَحْجَارٍ وَيَنْهَى عَنِ الرَّوْثِ وَالرِّمَّةِ ‏.‏', '"‏ انما انا لكم بمنزله الوالد اعلمكم فاذا اتي احدكم الغائط فلا يستقبل القبله ولا يستدبرها ولا يستطب بيمينه ‏"‏ ‏.‏ وكان يامر بثلاثه احجار وينهي عن الروث والرمه ‏.‏', 'Narrated Abu Hurairah:The Apostle of Allaah ( sal Allaahu alayhi wa sallam ) as saying: I am like father to you. When any of you goes to privy, he should not face or turn his back towards the qiblah. He should not cleanse with his right hand. He (the Prophet, sal Allaahu alayhi wa sallam) also commanded the Muslims to use three stones and forbade them to use dung or decayed bone', NULL, '57d9fb0e6053a54ac0223f55c1336b20ef1940e729cc0bc6d56cd2bb419bc33b', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (167, 'abudawud', 207, 9, 'Book 1, Hadith 9', 9, NULL, NULL, 'حَدَّثَنَا مُسَدَّدُ بْنُ مُسَرْهَدٍ، حَدَّثَنَا سُفْيَانُ، عَنِ الزُّهْرِيِّ، عَنْ عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ، عَنْ أَبِي أَيُّوبَ، رِوَايَةً قَالَ', 'إِذَا أَتَيْتُمُ الْغَائِطَ فَلاَ تَسْتَقْبِلُوا الْقِبْلَةَ بِغَائِطٍ وَلاَ بَوْلٍ وَلَكِنْ شَرِّقُوا أَوْ غَرِّبُوا  . فَقَدِمْنَا الشَّامَ فَوَجَدْنَا مَرَاحِيضَ قَدْ بُنِيَتْ قِبَلَ الْقِبْلَةِ فَكُنَّا نَنْحَرِفُ عَنْهَا وَنَسْتَغْفِرُ اللَّهَ .', 'اذا اتيتم الغائط فلا تستقبلوا القبله بغائط ولا بول ولكن شرقوا او غربوا . فقدمنا الشام فوجدنا مراحيض قد بنيت قبل القبله فكنا ننحرف عنها ونستغفر الله .', 'Narrated Abu Ayyub :That he (the Holy Prophet, sal Allahu alayhi wa sallam) said:"When you go to the privy, neither turn your face nor your back towards the qiblah at the time of excretion or urination, but turn towards the east or the west. (Abu Ayyub said): When we came to Syria, we found that the toilets already built there were facing the qiblah, We turned our faces away from them and begged pardon of Allaah', NULL, '694d8c78fc53faa4042852edda008640585007c0bf2e69aa774f90fe81598b14', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (168, 'abudawud', 207, 10, 'Book 1, Hadith 10', 10, NULL, NULL, 'حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا وُهَيْبٌ، حَدَّثَنَا عَمْرُو بْنُ يَحْيَى، عَنْ أَبِي زَيْدٍ، عَنْ مَعْقِلِ بْنِ أَبِي مَعْقِلٍ الأَسَدِيِّ، قَالَ نَهَى رَسُولُ اللَّهِ صلى الله عليه وسلم أَنْ نَسْتَقْبِلَ الْقِبْلَتَيْنِ بِبَوْلٍ أَوْ غَائِطٍ', '. قَالَ أَبُو دَاوُدَ وَأَبُو زَيْدٍ هُوَ مَوْلَى بَنِي ثَعْلَبَةَ .', '. قال ابو داود وابو زيد هو مولي بني ثعلبه .', 'Narrated Ma''qil ibn AbuMa''qil al-Asadi: The Messenger of Allah (ﷺ) has forbidden us to face the two qiblahs at the time of urination or excretion', NULL, '34e93c2f1286de1fb514bd9f36488ebd1efae2969e5139f5e1cd9e88b3819c00', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (169, 'abudawud', 207, 11, 'Book 1, Hadith 11', 11, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى بْنِ فَارِسٍ، حَدَّثَنَا صَفْوَانُ بْنُ عِيسَى، عَنِ الْحَسَنِ بْنِ ذَكْوَانَ، عَنْ مَرْوَانَ الأَصْفَرِ، قَالَ رَأَيْتُ ابْنَ عُمَرَ أَنَاخَ رَاحِلَتَهُ مُسْتَقْبِلَ الْقِبْلَةِ ثُمَّ جَلَسَ يَبُولُ إِلَيْهَا فَقُلْتُ يَا أَبَا عَبْدِ الرَّحْمَنِ أَلَيْسَ قَدْ نُهِيَ عَنْ هَذَا قَالَ بَلَى إِنَّمَا نُهِيَ عَنْ ذَلِكَ فِي الْفَضَاءِ فَإِذَا كَانَ بَيْنَكَ وَبَيْنَ الْقِبْلَةِ شَىْءٌ يَسْتُرُكَ فَلاَ بَأْسَ', '.', '.', 'Marwan al-Asfar said:I saw Ibn Umar make his camel kneel down facing the qiblah, then he sat down urinating in its direction. So I said: AbuAbdurRahman, has this not been forbidden? He replied: Why not, that was forbidden only in open country; but when there is something between you and the qiblah that conceals you , then there is no harm', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (170, 'abudawud', 207, 12, 'Book 1, Hadith 12', 12, NULL, NULL, NULL, 'حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ، عَنْ مَالِكٍ، عَنْ يَحْيَى بْنِ سَعِيدٍ، عَنْ مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ، عَنْ عَمِّهِ، وَاسِعِ بْنِ حَبَّانَ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، قَالَ لَقَدِ ارْتَقَيْتُ عَلَى ظَهْرِ الْبَيْتِ فَرَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم عَلَى لَبِنَتَيْنِ مُسْتَقْبِلَ بَيْتِ الْمَقْدِسِ لِحَاجَتِهِ', 'حدثنا عبد الله بن مسلمه، عن مالك، عن يحيي بن سعيد، عن محمد بن يحيي بن حبان، عن عمه، واسع بن حبان، عن عبد الله بن عمر، قال لقد ارتقيت علي ظهر البيت فرايت رسول الله صلي الله عليه وسلم علي لبنتين مستقبل بيت المقدس لحاجته', 'Narrated ''Abd Allaah b. ''Umar :I ascended the roof of the house and saw the Apostle of Allaah ( sal Allaahu alayhi wa sallam) sitting on two bricks facing Jerusalem (Bait al-Maqdis) for relieving himself', NULL, '2a221c9270fc40d53a4cb8caaed7a4e87e2caae4a43892790e5ca37af7d03d63', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (171, 'abudawud', 207, 13, 'Book 1, Hadith 13', 13, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا وَهْبُ بْنُ جَرِيرٍ، حَدَّثَنَا أَبِي قَالَ، سَمِعْتُ مُحَمَّدَ بْنَ إِسْحَاقَ، يُحَدِّثُ عَنْ أَبَانَ بْنِ صَالِحٍ، عَنْ مُجَاهِدٍ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ نَهَى نَبِيُّ اللَّهِ صلى الله عليه وسلم أَنْ نَسْتَقْبِلَ الْقِبْلَةَ بِبَوْلٍ فَرَأَيْتُهُ قَبْلَ أَنْ يُقْبَضَ بِعَامٍ يَسْتَقْبِلُهَا', '.', '.', 'Narrated Jabir ibn Abdullah: The Prophet of Allah (ﷺ) forbade us to face the qiblah at the time of making water. Then I saw him facing it (qiblah) urinating or easing himself one year before his death', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (172, 'abudawud', 207, 14, 'Book 1, Hadith 14', 14, NULL, NULL, 'حَدَّثَنَا زُهَيْرُ بْنُ حَرْبٍ، حَدَّثَنَا وَكِيعٌ، عَنِ الأَعْمَشِ، عَنْ رَجُلٍ، عَنِ ابْنِ عُمَرَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'كَانَ إِذَا أَرَادَ حَاجَةً لاَ يَرْفَعُ ثَوْبَهُ حَتَّى يَدْنُوَ مِنَ الأَرْضِ ‏.‏ قَالَ أَبُو دَاوُدَ رَوَاهُ عَبْدُ السَّلاَمِ بْنُ حَرْبٍ عَنِ الأَعْمَشِ عَنْ أَنَسِ بْنِ مَالِكٍ وَهُوَ ضَعِيفٌ ‏.‏ قَالَ أَبُو عِيسَى الرَّمْلِيُّ حَدَّثَنَا أَحْمَدُ بْنُ الْوَلِيدِ حَدَّثَنَا عَمْرُو بْنُ عَوْنٍ أَخْبَرَنَا عَبْدُ السَّلاَمِ بِهِ ‏.‏', 'كان اذا اراد حاجه لا يرفع ثوبه حتي يدنو من الارض ‏.‏ قال ابو داود رواه عبد السلام بن حرب عن الاعمش عن انس بن مالك وهو ضعيف ‏.‏ قال ابو عيسي الرملي حدثنا احمد بن الوليد حدثنا عمرو بن عون اخبرنا عبد السلام به ‏.‏', 'Narrated Abdullah ibn Umar: When the Prophet (ﷺ) wanted to relieve himself, he would not raise his garment, until he lowered himself near the ground. Abu DAwud said: This tradition has been transmitted by ''Abd al-Salam b. Harb on the authority of al-A''mash from Anas b. Malik. This chain of narrators is weak (because A''mash''s hearing tradition from Anas b. Malik is not established)', NULL, 'a8f13fdaa609251c4945fa8324c78f823af6fc8bf49ce4c645aba12bd2a638e3', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (173, 'abudawud', 207, 15, 'Book 1, Hadith 15', 15, NULL, NULL, 'حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ عُمَرَ بْنِ مَيْسَرَةَ، حَدَّثَنَا ابْنُ مَهْدِيٍّ، حَدَّثَنَا عِكْرِمَةُ بْنُ عَمَّارٍ، عَنْ يَحْيَى بْنِ أَبِي كَثِيرٍ، عَنْ هِلاَلِ بْنِ عِيَاضٍ، قَالَ حَدَّثَنِي أَبُو سَعِيدٍ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏', '"‏ لاَ يَخْرُجُ الرَّجُلاَنِ يَضْرِبَانِ الْغَائِطَ كَاشِفَيْنِ عَنْ عَوْرَتِهِمَا يَتَحَدَّثَانِ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ يَمْقُتُ عَلَى ذَلِكَ ‏"‏ ‏.‏ قَالَ أَبُو دَاوُدَ هَذَا لَمْ يُسْنِدْهُ إِلاَّ عِكْرِمَةُ بْنُ عَمَّارٍ ‏.‏', '"‏ لا يخرج الرجلان يضربان الغائط كاشفين عن عورتهما يتحدثان فان الله عز وجل يمقت علي ذلك ‏"‏ ‏.‏ قال ابو داود هذا لم يسنده الا عكرمه بن عمار ‏.‏', 'Narrated AbuSa''id al-Khudri: I heard the Messenger of Allah (ﷺ) say: When two persons go together for relieving themselves uncovering their private parts and talking together, Allah, the Great and Majestic, becomes wrathful at this (action). Abu Dawud said: This tradition has been narrated only by ''Ikrimah b. ''Ammar', NULL, '197c794bc905ee45249c7cbbc5e93bdc9c0cc60915076cb7a8c3a04f9fa6030e', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (174, 'abudawud', 207, 16, 'Book 1, Hadith 16', 16, NULL, NULL, 'حَدَّثَنَا عُثْمَانُ، وَأَبُو بَكْرٍ ابْنَا أَبِي شَيْبَةَ قَالاَ حَدَّثَنَا عُمَرُ بْنُ سَعْدٍ، عَنْ سُفْيَانَ، عَنِ الضَّحَّاكِ بْنِ عُثْمَانَ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، قَالَ مَرَّ رَجُلٌ عَلَى النَّبِيِّ صلى الله عليه وسلم وَهُوَ يَبُولُ فَسَلَّمَ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيْهِ ‏.‏ قَالَ أَبُو دَاوُدَ وَرُوِيَ عَنِ ابْنِ عُمَرَ وَغَيْرِهِ أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'تَيَمَّمَ ثُمَّ رَدَّ عَلَى الرَّجُلِ السَّلاَمَ ‏.‏', 'تيمم ثم رد علي الرجل السلام ‏.‏', 'Narrated Ibn ''Umar : A man passed by the Prophet (sal Allaahu alayhi wa sallam ) while he was urinating, and saluted him. The Prophet (sal Allaahu alayhi wa sallam) did not return the salutation to him. Abu Dawud said : It is narrated on the authority of Ibn ''Umar that the Prophet (sal Allaahu alayhi wa sallam) performed tayammum, then he returned the salutation to the man', NULL, '17c629b40e4d597ce2eb3e3726ed032e5fc1909dce30a13b8bb76751c3b72231', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (175, 'abudawud', 207, 17, 'Book 1, Hadith 17', 17, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا عَبْدُ الأَعْلَى، حَدَّثَنَا سَعِيدٌ، عَنْ قَتَادَةَ، عَنِ الْحَسَنِ، عَنْ حُضَيْنِ بْنِ الْمُنْذِرِ أَبِي سَاسَانَ، عَنِ الْمُهَاجِرِ بْنِ قُنْفُذٍ، أَنَّهُ أَتَى النَّبِيَّ صلى الله عليه وسلم وَهُوَ يَبُولُ فَسَلَّمَ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيْهِ حَتَّى تَوَضَّأَ ثُمَّ اعْتَذَرَ إِلَيْهِ فَقَالَ', 'إِنِّي كَرِهْتُ أَنْ أَذْكُرَ اللَّهَ عَزَّ وَجَلَّ إِلاَّ عَلَى طُهْرٍ  . أَوْ قَالَ  عَلَى طَهَارَةٍ  .', 'اني كرهت ان اذكر الله عز وجل الا علي طهر . او قال علي طهاره .', 'Narrated Muhajir ibn Qunfudh: Muhajir came to the Prophet (ﷺ) while he was urinating. He saluted him. The Prophet (ﷺ) did not return the salutation to him until he performed ablution. He then apologised to him, saying: I disliked remembering Allah except in the state of purification', NULL, '7f649a237092cef29ad3937ecaad9a9bb256e9d3c6c484cae47590a427c59da5', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (176, 'abudawud', 207, 18, 'Book 1, Hadith 18', 18, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ الْعَلاَءِ، حَدَّثَنَا ابْنُ أَبِي زَائِدَةَ، عَنْ أَبِيهِ، عَنْ خَالِدِ بْنِ سَلَمَةَ، - يَعْنِي الْفَأْفَاءَ - عَنِ الْبَهِيِّ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ، قَالَتْ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَذْكُرُ اللَّهَ عَزَّ وَجَلَّ عَلَى كُلِّ أَحْيَانِهِ', '.', '.', 'Narrated A''ishah:The Apostle of Allaah ( sal Allaahu alayhi wa sallam ) used to remember Allaah, the Great and Majestic, at all moments', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (177, 'abudawud', 207, 19, 'Book 1, Hadith 19', 19, NULL, NULL, 'حَدَّثَنَا نَصْرُ بْنُ عَلِيٍّ، عَنْ أَبِي عَلِيٍّ الْحَنَفِيِّ، عَنْ هَمَّامٍ، عَنِ ابْنِ جُرَيْجٍ، عَنِ الزُّهْرِيِّ، عَنْ أَنَسٍ، قَالَ كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا دَخَلَ الْخَلاَءَ وَضَعَ خَاتَمَهُ ‏.‏ قَالَ أَبُو دَاوُدَ هَذَا حَدِيثٌ مُنْكَرٌ وَإِنَّمَا يُعْرَفُ عَنِ ابْنِ جُرَيْجٍ عَنْ زِيَادِ بْنِ سَعْدٍ عَنِ الزُّهْرِيِّ عَنْ أَنَسٍ أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'اتَّخَذَ خَاتَمًا مِنْ وَرِقٍ ثُمَّ أَلْقَاهُ ‏.‏ وَالْوَهَمُ فِيهِ مِنْ هَمَّامٍ وَلَمْ يَرْوِهِ إِلاَّ هَمَّامٌ ‏.‏', 'اتخذ خاتما من ورق ثم القاه ‏.‏ والوهم فيه من همام ولم يروه الا همام ‏.‏', 'Narrated Anas ibn Malik: When the Prophet (ﷺ) entered the privy, he removed his ring. Abu Dawud said: This is a munkar tradition, i.e. it contradicts the well-known version reported by reliable narrators. On the authority of Anas the well-known version says: The Prophet (ﷺ) had a silver ring made for him. Then he cast it off. The misunderstanding is on the part of Hammam (who is the narrator of the previous tradition mentioned in the text). This is transmitted only by Hammam', NULL, 'eb42ea7197bcd6160724750ba5ee5ba3b0991fa2ef747b77ddb27264e21071de', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (178, 'abudawud', 207, 20, 'Book 1, Hadith 20', 20, NULL, NULL, 'حَدَّثَنَا زُهَيْرُ بْنُ حَرْبٍ، وَهَنَّادُ بْنُ السَّرِيِّ، قَالاَ حَدَّثَنَا وَكِيعٌ، حَدَّثَنَا الأَعْمَشُ، قَالَ سَمِعْتُ مُجَاهِدًا، يُحَدِّثُ عَنْ طَاوُسٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ مَرَّ رَسُولُ اللَّهِ صلى الله عليه وسلم عَلَى قَبْرَيْنِ فَقَالَ', 'إِنَّهُمَا يُعَذَّبَانِ وَمَا يُعَذَّبَانِ فِي كَبِيرٍ أَمَّا هَذَا فَكَانَ لاَ يَسْتَنْزِهُ مِنَ الْبَوْلِ وَأَمَّا هَذَا فَكَانَ يَمْشِي بِالنَّمِيمَةِ  . ثُمَّ دَعَا بِعَسِيبٍ رَطْبٍ فَشَقَّهُ بِاثْنَيْنِ ثُمَّ غَرَسَ عَلَى هَذَا وَاحِدًا وَعَلَى هَذَا وَاحِدًا وَقَالَ  لَعَلَّهُ يُخَفَّفُ عَنْهُمَا مَا لَمْ يَيْبَسَا  . قَالَ هَنَّادٌ  يَسْتَتِرُ  . مَكَانَ  يَسْتَنْزِهُ  .', 'انهما يعذبان وما يعذبان في كبير اما هذا فكان لا يستنزه من البول واما هذا فكان يمشي بالنميمه . ثم دعا بعسيب رطب فشقه باثنين ثم غرس علي هذا واحدا وعلي هذا واحدا وقال لعله يخفف عنهما ما لم ييبسا . قال هناد يستتر . مكان يستنزه .', 'Narrated Ibn ''Abbas : The Prophet (sal Allaahu alayhi wa sallam ) passed by two graves. He said : Both (the dead) are being punished, but they are not being punished for a major (sin). One did not safeguard himself from urine. The other carried tales. He then called for a fresh twig and split it into two parts and planted one part on each grave and said: Perhaps their punishment may be mitigated as long as the twigs remain fresh. Another version of Hannad has: "One of them did not cover himself while urinating." This version does not have the words: "He did not safeguard himself from urine', NULL, 'f651b15236d8edcfcc18007f81deeaf37d12a9c834379bbc9c11ee3f3385c373', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (179, 'abudawud', 207, 21, 'Book 1, Hadith 21', 21, NULL, NULL, 'حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، عَنْ مُجَاهِدٍ، عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم', 'بِمَعْنَاهُ قَالَ ‏"‏ كَانَ لاَ يَسْتَتِرُ مِنْ بَوْلِهِ ‏"‏ ‏.‏ وَقَالَ أَبُو مُعَاوِيَةَ ‏"‏ يَسْتَنْزِهُ ‏"‏ ‏.‏', 'بمعناه قال ‏"‏ كان لا يستتر من بوله ‏"‏ ‏.‏ وقال ابو معاويه ‏"‏ يستنزه ‏"‏ ‏.‏', 'Narrated Ibn ''Abbas: A tradition from the Prophet (sal Allaahu alayhi wa sallam ) conveying similar meaning. The version of Jarir has the wording : "he did not cover himself while urinating." The version of Abu Mu''awiyah has the wording: "he did not safeguard himself (from urine)', NULL, 'a43449fd750d3275aa361a1e6900f31b73b4193fb46ada7b11e8a8e69fb83720', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (180, 'abudawud', 207, 22, 'Book 1, Hadith 22', 22, NULL, NULL, 'حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ، حَدَّثَنَا الأَعْمَشُ، عَنْ زَيْدِ بْنِ وَهْبٍ، عَنْ عَبْدِ الرَّحْمَنِ ابْنِ حَسَنَةَ، قَالَ انْطَلَقْتُ أَنَا وَعَمْرُو بْنُ الْعَاصِ، إِلَى النَّبِيِّ صلى الله عليه وسلم فَخَرَجَ وَمَعَهُ دَرَقَةٌ ثُمَّ اسْتَتَرَ بِهَا ثُمَّ بَالَ فَقُلْنَا انْظُرُوا إِلَيْهِ يَبُولُ كَمَا تَبُولُ الْمَرْأَةُ ‏.‏ فَسَمِعَ ذَلِكَ فَقَالَ ‏"‏ أَلَمْ تَعْلَمُوا مَا لَقِيَ صَاحِبُ بَنِي إِسْرَائِيلَ كَانُوا إِذَا أَصَابَهُمُ الْبَوْلُ قَطَعُوا مَا أَصَابَهُ الْبَوْلُ مِنْهُمْ فَنَهَاهُمْ فَعُذِّبَ فِي قَبْرِهِ ‏"‏ ‏.‏ قَالَ أَبُو دَاوُدَ قَالَ مَنْصُورٌ عَنْ أَبِي وَائِلٍ عَنْ أَبِي مُوسَى فِي هَذَا الْحَدِيثِ قَالَ ‏"‏ جِلْدَ أَحَدِهِمْ ‏"‏ ‏.‏ وَقَالَ عَاصِمٌ عَنْ أَبِي وَائِلٍ عَنْ أَبِي مُوسَى عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏"‏', 'جَسَدَ أَحَدِهِمْ ‏"‏ ‏.‏', 'جسد احدهم ‏"‏ ‏.‏', 'Narrated Amr ibn al-''As: AbdurRahman ibn Hasanah reported: I and Amr ibn al-''As went to the Prophet (ﷺ). He came out with a leather shield (in his hand). He covered himself with it and urinated. Then we said: Look at him. He is urinating as a woman does. The Prophet (ﷺ), heard this and said: Do you not know what befell a person from amongst Banu Isra''il (the children of Israel)? When urine fell on them, they would cut off the place where the urine fell; but he (that person) forbade them (to do so), and was punished in his grave. Abu Dawud said: One version of Abu Musa has the wording: "he cut off his skin". Another version of Abu Musa goes: "he cut off (part of) his body', NULL, '49b779fdb620fc6cb81a1a1ee97e319f177bc289340dda7b7716e3f2467ea457', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (181, 'abudawud', 207, 23, 'Book 1, Hadith 23', 23, NULL, NULL, 'حَدَّثَنَا حَفْصُ بْنُ عُمَرَ، وَمُسْلِمُ بْنُ إِبْرَاهِيمَ، قَالاَ حَدَّثَنَا شُعْبَةُ، ح وَحَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا أَبُو عَوَانَةَ، - وَهَذَا لَفْظُ حَفْصٍ - عَنْ سُلَيْمَانَ، عَنْ أَبِي وَائِلٍ، عَنْ حُذَيْفَةَ، قَالَ أَتَى رَسُولُ اللَّهِ صلى الله عليه وسلم سُبَاطَةَ قَوْمٍ فَبَالَ قَائِمًا ثُمَّ دَعَا بِمَاءٍ فَمَسَحَ عَلَى خُفَّيْهِ', '. قَالَ أَبُو دَاوُدَ قَالَ مُسَدَّدٌ قَالَ فَذَهَبْتُ أَتَبَاعَدُ فَدَعَانِي حَتَّى كُنْتُ عِنْدَ عَقِبِهِ .', '. قال ابو داود قال مسدد قال فذهبت اتباعد فدعاني حتي كنت عند عقبه .', 'Narrated Hudhaifah : The Apostle of Allaah ( sal Allaahu alayhi wa sallam ) came to a midden of some people and urinated while standing. He then asked for water and wiped his shoes. Abu Dawud said: Musaddad, a narrator, reported: I went far away from him. He then called me and I reached just near his heals', NULL, 'a0775d8a67ee56a9663166331a2a1aa0096ba2405554b6326a8c9f4a3a7f9bdd', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (182, 'abudawud', 207, 24, 'Book 1, Hadith 24', 24, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ عِيسَى، حَدَّثَنَا حَجَّاجٌ، عَنِ ابْنِ جُرَيْجٍ، عَنْ حُكَيْمَةَ بِنْتِ أُمَيْمَةَ بِنْتِ رُقَيْقَةَ، عَنْ أُمِّهَا، أَنَّهَا قَالَتْ كَانَ لِلنَّبِيِّ صلى الله عليه وسلم قَدَحٌ مِنْ عَيْدَانٍ تَحْتَ سَرِيرِهِ يَبُولُ فِيهِ بِاللَّيْلِ', '.', '.', 'Narrated Umaymah daughter of Ruqayqah: The Prophet (ﷺ) had a wooden vessel under his bed in which he would urinate at night', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (183, 'abudawud', 207, 25, 'Book 1, Hadith 25', 25, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا إِسْمَاعِيلُ بْنُ جَعْفَرٍ، عَنِ الْعَلاَءِ بْنِ عَبْدِ الرَّحْمَنِ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏"‏', 'اتَّقُوا اللاَّعِنَيْنِ ‏"‏ ‏.‏ قَالُوا وَمَا اللاَّعِنَانِ يَا رَسُولَ اللَّهِ قَالَ ‏"‏ الَّذِي يَتَخَلَّى فِي طَرِيقِ النَّاسِ أَوْ ظِلِّهِمْ ‏"‏ ‏.‏', 'اتقوا اللاعنين ‏"‏ ‏.‏ قالوا وما اللاعنان يا رسول الله قال ‏"‏ الذي يتخلي في طريق الناس او ظلهم ‏"‏ ‏.‏', 'Narrated Abu Hurairah:The Prophet (sal Allaahu alayhi wa sallam ) as saying : Be on your guard against two things which provoke cursing. They (the hearers) said : Prophet of Allaah ( sal Allaahu alayhi wa sallam), what are these things which provoke cursing: easing in the watering places and on the thoroughfares, and in the shade (of the tree)(where they take shelter and rest)', NULL, 'afb793d73700f327d0cb51c299bace9623737f52286a77b21b939d30efce6902', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (184, 'abudawud', 207, 26, 'Book 1, Hadith 26', 26, NULL, NULL, 'حَدَّثَنَا إِسْحَاقُ بْنُ سُوَيْدٍ الرَّمْلِيُّ، وَعُمَرُ بْنُ الْخَطَّابِ أَبُو حَفْصٍ، وَحَدِيثُهُ، أَتَمُّ أَنَّ سَعِيدَ بْنَ الْحَكَمِ، حَدَّثَهُمْ قَالَ أَخْبَرَنَا نَافِعُ بْنُ يَزِيدَ، حَدَّثَنِي حَيْوَةُ بْنُ شُرَيْحٍ، أَنَّ أَبَا سَعِيدٍ الْحِمْيَرِيَّ، حَدَّثَهُ عَنْ مُعَاذِ بْنِ جَبَلٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ اتَّقُوا الْمَلاَعنَ الثَّلاَثَ الْبَرَازَ فِي الْمَوَارِدِ وَقَارِعَةِ الطَّرِيقِ وَالظِّلِّ ‏"‏ ‏.‏', '"‏ اتقوا الملاعن الثلاث البراز في الموارد وقارعه الطريق والظل ‏"‏ ‏.‏', 'Narrated Mu''adh ibn Jabal: The Messenger of Allah (ﷺ) said: Be on your guard against three things which provoke cursing: easing in the watering places and on the thoroughfares, and in the shade (of the tree)', NULL, '41d062d7ba17fea8123e6215ac708b917d62225e91a1f9bf3159c7910aeedd56', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (185, 'abudawud', 207, 27, 'Book 1, Hadith 27', 27, NULL, NULL, 'حَدَّثَنَا أَحْمَدُ بْنُ مُحَمَّدِ بْنِ حَنْبَلٍ، وَالْحَسَنُ بْنُ عَلِيٍّ، قَالاَ حَدَّثَنَا عَبْدُ الرَّزَّاقِ، قَالَ أَحْمَدُ حَدَّثَنَا مَعْمَرٌ، أَخْبَرَنِي أَشْعَثُ، وَقَالَ الْحَسَنُ، عَنْ أَشْعَثَ بْنِ عَبْدِ اللَّهِ، عَنِ الْحَسَنِ، عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏"‏', 'لاَ يَبُولَنَّ أَحَدُكُمْ فِي مُسْتَحَمِّهِ ثُمَّ يَغْتَسِلُ فِيهِ ‏"‏ ‏.‏ قَالَ أَحْمَدُ ‏"‏ ثُمَّ يَتَوَضَّأُ فِيهِ فَإِنَّ عَامَّةَ الْوَسْوَاسِ مِنْهُ ‏"‏ ‏.‏', 'لا يبولن احدكم في مستحمه ثم يغتسل فيه ‏"‏ ‏.‏ قال احمد ‏"‏ ثم يتوضا فيه فان عامه الوسواس منه ‏"‏ ‏.‏', 'Narrated Abdullah ibn Mughaffal: The Messenger of Allah (ﷺ) said: No one of you should make water in his bath and then wash himself there (after urination). The version of Ahmad has: Then performs ablution there, for evil thoughts come from it', NULL, 'd2bd18fe03313f5a43001cf3e679a9c99032c2a685e02228ada7419b61bf4ea5', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (186, 'abudawud', 207, 28, 'Book 1, Hadith 28', 28, NULL, NULL, 'حَدَّثَنَا أَحْمَدُ بْنُ يُونُسَ، حَدَّثَنَا زُهَيْرٌ، عَنْ دَاوُدَ بْنِ عَبْدِ اللَّهِ، عَنْ حُمَيْدٍ الْحِمْيَرِيِّ، - وَهُوَ ابْنُ عَبْدِ الرَّحْمَنِ - قَالَ لَقِيتُ رَجُلاً صَحِبَ النَّبِيَّ صلى الله عليه وسلم كَمَا صَحِبَهُ أَبُو هُرَيْرَةَ قَالَ نَهَى رَسُولُ اللَّهِ صلى الله عليه وسلم أَنْ يَمْتَشِطَ أَحَدُنَا كُلَّ يَوْمٍ أَوْ يَبُولَ فِي مُغْتَسَلِهِ', '.', '.', 'Narrated A Man from the Companions: Humayd al-Himyari said: I met a man (Companion of the Prophet) who remained in the company of the Prophet (ﷺ) just as AbuHurayrah remained in his company. He then added: The Messenger of Allah (ﷺ) forbade that anyone amongst us should comb (his hair) every day or urinate in the place where he takes a bath', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (187, 'abudawud', 207, 29, 'Book 1, Hadith 29', 29, NULL, NULL, 'حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ عُمَرَ بْنِ مَيْسَرَةَ، حَدَّثَنَا مُعَاذُ بْنُ هِشَامٍ، حَدَّثَنِي أَبِي، عَنْ قَتَادَةَ، عَنْ عَبْدِ اللَّهِ بْنِ سَرْجِسَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم', 'نَهَى أَنْ يُبَالَ فِي الْجُحْرِ ‏.‏ قَالَ قَالُوا لِقَتَادَةَ مَا يُكْرَهُ مِنَ الْبَوْلِ فِي الْجُحْرِ قَالَ كَانَ يُقَالُ إِنَّهَا مَسَاكِنُ الْجِنِّ ‏.‏', 'نهي ان يبال في الجحر ‏.‏ قال قالوا لقتاده ما يكره من البول في الجحر قال كان يقال انها مساكن الجن ‏.‏', 'Narrated Abdullah ibn Sarjis: The Prophet (ﷺ) prohibited to urinate in a hole. Qatadah (a narrator) was asked about the reason for the disapproval of urinating in a hole. He replied: It is said that these (holes) are the habitats of the jinn', NULL, 'e2e13814561d8b96583e5b3d6dcdc73357601afa78a993938a4384c51a64d2d5', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (188, 'abudawud', 207, 30, 'Book 1, Hadith 30', 30, NULL, NULL, 'حَدَّثَنَا عَمْرُو بْنُ مُحَمَّدٍ النَّاقِدُ، حَدَّثَنَا هَاشِمُ بْنُ الْقَاسِمِ، حَدَّثَنَا إِسْرَائِيلُ، عَنْ يُوسُفَ بْنِ أَبِي بُرْدَةَ، عَنْ أَبِيهِ، حَدَّثَتْنِي عَائِشَةُ، رضى الله عنها أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'كَانَ إِذَا خَرَجَ مِنَ الْغَائِطِ قَالَ ‏ "‏ غُفْرَانَكَ ‏"‏ ‏.‏', 'كان اذا خرج من الغائط قال ‏ "‏ غفرانك ‏"‏ ‏.‏', 'Narrated Aisha, Ummul Mu''minin: When the Prophet (ﷺ) came out of the privy, he used to say: "Grant me Thy forgiveness', NULL, 'a6f7cbe8d8e6e3ce299474a53af15c506be0cd2ead23548ec29027beb5f6da21', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (189, 'abudawud', 207, 31, 'Book 1, Hadith 31', 31, NULL, NULL, 'حَدَّثَنَا مُسْلِمُ بْنُ إِبْرَاهِيمَ، وَمُوسَى بْنُ إِسْمَاعِيلَ، قَالاَ حَدَّثَنَا أَبَانُ، حَدَّثَنَا يَحْيَى، عَنْ عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ، عَنْ أَبِيهِ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ إِذَا بَالَ أَحَدُكُمْ فَلاَ يَمَسَّ ذَكَرَهُ بِيَمِينِهِ وَإِذَا أَتَى الْخَلاَءَ فَلاَ يَتَمَسَّحْ بِيَمِينِهِ وَإِذَا شَرِبَ فَلاَ يَشْرَبْ نَفَسًا وَاحِدًا ‏"‏ ‏.‏', '"‏ اذا بال احدكم فلا يمس ذكره بيمينه واذا اتي الخلاء فلا يتمسح بيمينه واذا شرب فلا يشرب نفسا واحدا ‏"‏ ‏.‏', 'Narrated Abu Qatadah:The Prophet (sal Allaahu alayhi wa sallam) said: When any one of you urinates, he must not touch his penis with his right hand, and when he goes to relieve himself he must not wipe himself with his right hand (in the privy), and when he drinks, he must not drink in one breath', NULL, '289c279f9ddc4eaeaabd1f16e48d39a3a47b6ffee6c22bb7e7ecf53fc3e8c379', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (190, 'abudawud', 207, 32, 'Book 1, Hadith 32', 32, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ آدَمَ بْنِ سُلَيْمَانَ الْمِصِّيصِيُّ، حَدَّثَنَا ابْنُ أَبِي زَائِدَةَ، قَالَ حَدَّثَنِي أَبُو أَيُّوبَ، - يَعْنِي الإِفْرِيقِيَّ - عَنْ عَاصِمٍ، عَنِ الْمُسَيَّبِ بْنِ رَافِعٍ، وَمَعْبَدٍ، عَنْ حَارِثَةَ بْنِ وَهْبٍ الْخُزَاعِيِّ، قَالَ حَدَّثَتْنِي حَفْصَةُ، زَوْجُ النَّبِيِّ صلى الله عليه وسلم أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'كَانَ يَجْعَلُ يَمِينَهُ لِطَعَامِهِ وَشَرَابِهِ وَثِيَابِهِ وَيَجْعَلُ شِمَالَهُ لِمَا سِوَى ذَلِكَ ‏.‏', 'كان يجعل يمينه لطعامه وشرابه وثيابه ويجعل شماله لما سوي ذلك ‏.‏', 'Narrated Hafsah, Ummul Mu''minin: The Prophet (ﷺ) used his right hand for taking his food and drink and used his left hand for other purposes', NULL, '4d67a1f19e64f29eba71e1b7ccc4eb8b92b3e5c4ff526f84b89246cd54241e89', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (191, 'abudawud', 207, 33, 'Book 1, Hadith 33', 33, NULL, NULL, 'حَدَّثَنَا أَبُو تَوْبَةَ الرَّبِيعُ بْنُ نَافِعٍ، حَدَّثَنِي عِيسَى بْنُ يُونُسَ، عَنِ ابْنِ أَبِي عَرُوبَةَ، عَنْ أَبِي مَعْشَرٍ، عَنْ إِبْرَاهِيمَ، عَنْ عَائِشَةَ، قَالَتْ كَانَتْ يَدُ رَسُولِ اللَّهِ صلى الله عليه وسلم الْيُمْنَى لِطُهُورِهِ وَطَعَامِهِ وَكَانَتْ يَدُهُ الْيُسْرَى لِخَلاَئِهِ وَمَا كَانَ مِنْ أَذًى', '.', '.', 'Narrated Aisha, Ummul Mu''minin: The Prophet (ﷺ) used his right hand for getting water for ablution and taking food, and his left hand for his evacuation and for anything repugnant', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (192, 'abudawud', 207, 34, 'Book 1, Hadith 34', 34, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ حَاتِمِ بْنِ بَزِيعٍ، حَدَّثَنَا عَبْدُ الْوَهَّابِ بْنُ عَطَاءٍ، عَنْ سَعِيدٍ، عَنْ أَبِي مَعْشَرٍ، عَنْ إِبْرَاهِيمَ، عَنِ الأَسْوَدِ، عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم', 'بِمَعْنَاهُ ‏.‏', 'بمعناه ‏.‏', 'Aishah, also reported a tradition bearing similar meaning through another chain of transmitters', NULL, '24fad38dcc35c962428282a09a4891875502e8e45fd03009c12f1b243d7bb20a', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (193, 'abudawud', 207, 35, 'Book 1, Hadith 35', 35, NULL, NULL, 'حَدَّثَنَا إِبْرَاهِيمُ بْنُ مُوسَى الرَّازِيُّ، أَخْبَرَنَا عِيسَى بْنُ يُونُسَ، عَنْ ثَوْرٍ، عَنِ الْحُصَيْنِ الْحُبْرَانِيِّ، عَنْ أَبِي سَعِيدٍ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ مَنِ اكْتَحَلَ فَلْيُوتِرْ مَنْ فَعَلَ فَقَدْ أَحْسَنَ وَمَنْ لاَ فَلاَ حَرَجَ وَمَنِ اسْتَجْمَرَ فَلْيُوتِرْ مَنْ فَعَلَ فَقَدْ أَحْسَنَ وَمَنْ لاَ فَلاَ حَرَجَ وَمَنْ أَكَلَ فَمَا تَخَلَّلَ فَلْيَلْفِظْ وَمَا لاَكَ بِلِسَانِهِ فَلْيَبْتَلِعْ مَنْ فَعَلَ فَقَدْ أَحْسَنَ وَمَنْ لاَ فَلاَ حَرَجَ وَمَنْ أَتَى الْغَائِطَ فَلْيَسْتَتِرْ فَإِنْ لَمْ يَجِدْ إِلاَّ أَنْ يَجْمَعَ كَثِيبًا مِنْ رَمْلٍ فَلْيَسْتَدْبِرْهُ فَإِنَّ الشَّيْطَانَ يَلْعَبُ بِمَقَاعِدِ بَنِي آدَمَ مَنْ فَعَلَ فَقَدْ أَحْسَنَ وَمَنْ لاَ فَلاَ حَرَجَ ‏"‏ ‏.‏ قَالَ أَبُو دَاوُدَ رَوَاهُ أَبُو عَاصِمٍ عَنْ ثَوْرٍ قَالَ حُصَيْنٌ الْحِمْيَرِيُّ وَرَوَاهُ عَبْدُ الْمَلِكِ بْنُ الصَّبَّاحِ عَنْ ثَوْرٍ فَقَالَ أَبُو سَعِيدٍ الْخَيْرُ ‏.‏ قَالَ أَبُو دَاوُدَ أَبُو سَعِيدٍ الْخَيْرُ هُوَ مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم ‏.‏', '"‏ من اكتحل فليوتر من فعل فقد احسن ومن لا فلا حرج ومن استجمر فليوتر من فعل فقد احسن ومن لا فلا حرج ومن اكل فما تخلل فليلفظ وما لاك بلسانه فليبتلع من فعل فقد احسن ومن لا فلا حرج ومن اتي الغائط فليستتر فان لم يجد الا ان يجمع كثيبا من رمل فليستدبره فان الشيطان يلعب بمقاعد بني ادم من فعل فقد احسن ومن لا فلا حرج ‏"‏ ‏.‏ قال ابو داود رواه ابو عاصم عن ثور قال حصين الحميري ورواه عبد الملك بن الصباح عن ثور فقال ابو سعيد الخير ‏.‏ قال ابو داود ابو سعيد الخير هو من اصحاب النبي صلي الله عليه وسلم ‏.‏', 'Narrated AbuHurayrah: The Prophet (ﷺ) said: If anyone applies collyrium, he should do it an odd number of times. If he does so, he has done well; but if not, there is no harm. If anyone cleanses himself with pebbles, he should use an odd number. If he does so, he has done well; but if not, there is no harm. If anyone eats, he should throw away what he removes with a toothpick and swallow what sticks to his tongue. If he does so, he has done well; if not, there is no harm. If anyone goes to relieve himself, he should conceal himself, and if all he can do is to collect a heap of send, he should sit with his back to it, for the devil makes sport with the posteriors of the children of Adam. If he does so, he has done well; but if not, there is no harm', NULL, 'd1ff20b348cd76604521d6b6182cedee16040a4110e799996225e73bf869322e', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (194, 'abudawud', 207, 36, 'Book 1, Hadith 36', 36, NULL, NULL, 'حَدَّثَنَا يَزِيدُ بْنُ خَالِدِ بْنِ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ الْهَمْدَانِيُّ، حَدَّثَنَا الْمُفَضَّلُ، - يَعْنِي ابْنَ فَضَالَةَ الْمِصْرِيَّ - عَنْ عَيَّاشِ بْنِ عَبَّاسٍ الْقِتْبَانِيِّ، أَنَّ شُيَيْمَ بْنَ بَيْتَانَ، أَخْبَرَهُ عَنْ شَيْبَانَ الْقِتْبَانِيِّ، قَالَ إِنَّ مَسْلَمَةَ بْنَ مُخَلَّدٍ اسْتَعْمَلَ رُوَيْفِعَ بْنَ ثَابِتٍ، عَلَى أَسْفَلِ الأَرْضِ', '. قَالَ شَيْبَانُ فَسِرْنَا مَعَهُ مِنْ كُومِ شَرِيكٍ إِلَى عَلْقَمَاءَ أَوْ مِنْ عَلْقَمَاءَ إِلَى كُومِ شَرِيكٍ - يُرِيدُ عَلْقَامَ - فَقَالَ رُوَيْفِعٌ إِنْ كَانَ أَحَدُنَا فِي زَمَنِ رَسُولِ اللَّهِ صلى الله عليه وسلم لَيَأْخُذُ نِضْوَ أَخِيهِ عَلَى أَنَّ لَهُ النِّصْفَ مِمَّا يَغْنَمُ وَلَنَا النِّصْفُ وَإِنْ كَانَ أَحَدُنَا لَيَطِيرُ لَهُ النَّصْلُ وَالرِّيشُ وَلِلآخَرِ الْقَدَحُ . ثُمَّ قَالَ قَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم   يَا رُوَيْفِعُ لَعَلَّ الْحَيَاةَ سَتَطُولُ بِكَ بَعْدِي فَأَخْبِرِ النَّاسَ أَنَّهُ مَنْ عَقَدَ لِحْيَتَهُ أَوْ تَقَلَّدَ وَتَرًا أَوِ اسْتَنْجَى بِرَجِيعِ دَابَّةٍ أَوْ عَظْمٍ فَإِنَّ مُحَمَّدًا صلى الله عليه وسلم مِنْهُ بَرِيءٌ  .', '. قال شيبان فسرنا معه من كوم شريك الي علقماء او من علقماء الي كوم شريك - يريد علقام - فقال رويفع ان كان احدنا في زمن رسول الله صلي الله عليه وسلم لياخذ نضو اخيه علي ان له النصف مما يغنم ولنا النصف وان كان احدنا ليطير له النصل والريش وللاخر القدح . ثم قال قال لي رسول الله صلي الله عليه وسلم يا رويفع لعل الحياه ستطول بك بعدي فاخبر الناس انه من عقد لحيته او تقلد وترا او استنجي برجيع دابه او عظم فان محمدا صلي الله عليه وسلم منه بريء .', 'Narrated Ruwayfi'' ibn Thabit: Shayban al-Qatbani reported that Maslamah ibn Mukhallad made Ruwayfi'' ibn Thabit the governor of the lower parts (of Egypt). He added: We travelled with him from Kum Sharik to Alqamah or from Alqamah to Kum Sharik (the narrator doubts) for Alqam. Ruwayfi'' said: Any one of us would borrow a camel during the lifetime of the Prophet (ﷺ) from the other, on condition that he would give him half the booty, and the other half he would retain himself. Further, one of us received an arrowhead and a feather, and the other an arrow-shaft as a share from the booty. He then reported: The Messenger of Allah (ﷺ) said: You may live for a long time after I am gone, Ruwayfi'', so, tell people that if anyone ties his beard or wears round his neck a string to ward off the evil eye, or cleanses himself with animal dung or bone, Muhammad has nothing to do with him', NULL, 'aa37d444e0549917424aca5f430ce33616a8f1fc8656e194696a300745b04db3', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (195, 'abudawud', 207, 37, 'Book 1, Hadith 37', 37, NULL, NULL, 'حَدَّثَنَا يَزِيدُ بْنُ خَالِدٍ، حَدَّثَنَا مُفَضَّلٌ، عَنْ عَيَّاشٍ، أَنَّ شُيَيْمَ بْنَ بَيْتَانَ، أَخْبَرَهُ بِهَذَا الْحَدِيثِ، أَيْضًا عَنْ أَبِي سَالِمٍ الْجَيْشَانِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، يَذْكُرُ ذَلِكَ وَهُوَ مَعَهُ مُرَابِطٌ بِحِصْنِ بَابِ أَلْيُونَ', '. قَالَ أَبُو دَاوُدَ حِصْنُ أَلْيُونَ عَلَى جَبَلٍ بِالْفُسْطَاطِ . قَالَ أَبُو دَاوُدَ وَهُوَ شَيْبَانُ بْنُ أُمَيَّةَ يُكْنَى أَبَا حُذَيْفَةَ .', '. قال ابو داود حصن اليون علي جبل بالفسطاط . قال ابو داود وهو شيبان بن اميه يكني ابا حذيفه .', 'This tradition has also been narrated by Abu Salim al-Jaishani on the authority of ''Abd Allaah b. ''Amr. He narrated this tradition at the time when he besieged the fort at the gate of Alyun. Abu Dawud said:The fort of Alyun lies at the mountain in Fustat. Abu Dawud said: The kunyah (surname) of Shaiban b. Umayyah is Abu Hudhaifah', NULL, 'b3c5cc2029dbff397e031c36e61324cc0721a433efb2a46f371664781b2b293b', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (196, 'abudawud', 207, 38, 'Book 1, Hadith 38', 38, NULL, NULL, 'حَدَّثَنَا أَحْمَدُ بْنُ مُحَمَّدِ بْنِ حَنْبَلٍ، حَدَّثَنَا رَوْحُ بْنُ عُبَادَةَ، حَدَّثَنَا زَكَرِيَّا بْنُ إِسْحَاقَ، حَدَّثَنَا أَبُو الزُّبَيْرِ، أَنَّهُ سَمِعَ جَابِرَ بْنَ عَبْدِ اللَّهِ، يَقُولُ نَهَانَا رَسُولُ اللَّهِ صلى الله عليه وسلم أَنْ نَتَمَسَّحَ بِعَظْمٍ أَوْ بَعْرٍ', '.', '.', 'Narrated Jabir b. ''Abd Allaah:The Apostle of Allaah ( sal Allaahu alayhi wa sallam ) forbade us to use a bone or dung for wiping', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (197, 'abudawud', 207, 39, 'Book 1, Hadith 39', 39, NULL, NULL, 'حَدَّثَنَا حَيْوَةُ بْنُ شُرَيْحٍ الْحِمْصِيُّ، حَدَّثَنَا ابْنُ عَيَّاشٍ، عَنْ يَحْيَى بْنِ أَبِي عَمْرٍو السَّيْبَانِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ الدَّيْلَمِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ قَدِمَ وَفْدُ الْجِنِّ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالُوا يَا مُحَمَّدُ انْهَ أُمَّتَكَ أَنْ يَسْتَنْجُوا بِعَظْمٍ أَوْ رَوْثَةٍ أَوْ حُمَمَةٍ فَإِنَّ اللَّهَ تَعَالَى جَعَلَ لَنَا فِيهَا رِزْقًا', '. قَالَ فَنَهَى النَّبِيُّ صلى الله عليه وسلم عَنْ ذَلِكَ .', '. قال فنهي النبي صلي الله عليه وسلم عن ذلك .', 'Narrated Abdullah ibn Mas''ud: A deputation of the jinn came to the Prophet (ﷺ) and said: O Muhammad, forbid your community to cleans themselves with a bone or dung or charcoal, for in them Allah has provided sustenance for us. So the Prophet (ﷺ) forbade them to do so', NULL, 'a3965c7245677c790945ffc46ea2b43d4c75b087be5edef9d59ca532f624f2ca', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (198, 'abudawud', 207, 40, 'Book 1, Hadith 40', 40, NULL, NULL, 'حَدَّثَنَا سَعِيدُ بْنُ مَنْصُورٍ، وَقُتَيْبَةُ بْنُ سَعِيدٍ، قَالاَ حَدَّثَنَا يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ، عَنْ أَبِي حَازِمٍ، عَنْ مُسْلِمِ بْنِ قُرْطٍ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏', '"‏ إِذَا ذَهَبَ أَحَدُكُمْ إِلَى الْغَائِطِ فَلْيَذْهَبْ مَعَهُ بِثَلاَثَةِ أَحْجَارٍ يَسْتَطِيبُ بِهِنَّ فَإِنَّهَا تُجْزِئُ عَنْهُ ‏"‏ ‏.‏', '"‏ اذا ذهب احدكم الي الغائط فليذهب معه بثلاثه احجار يستطيب بهن فانها تجزئ عنه ‏"‏ ‏.‏', 'Narrated Aisha, Ummul Mu''minin: The Messenger of Allah (ﷺ) said: When any of you goes to relieve himself, he should take with him three stones to cleans himself, for they will be enough for him', NULL, 'ea0c38c3e99d2923078c4f6872a4fb26b0ecb4fd1f79831d881d23500b3c7796', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (199, 'abudawud', 207, 41, 'Book 1, Hadith 41', 41, NULL, NULL, 'حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ النُّفَيْلِيُّ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ عَمْرِو بْنِ خُزَيْمَةَ، عَنْ عُمَارَةَ بْنِ خُزَيْمَةَ، عَنْ خُزَيْمَةَ بْنِ ثَابِتٍ، قَالَ سُئِلَ رَسُولُ اللَّهِ صلى الله عليه وسلم عَنْ الاِسْتِطَابَةِ فَقَالَ', 'بِثَلاَثَةِ أَحْجَارٍ لَيْسَ فِيهَا رَجِيعٌ  . قَالَ أَبُو دَاوُدَ كَذَا رَوَاهُ أَبُو أُسَامَةَ وَابْنُ نُمَيْرٍ عَنْ هِشَامٍ يَعْنِي ابْنَ عُرْوَةَ .', 'بثلاثه احجار ليس فيها رجيع . قال ابو داود كذا رواه ابو اسامه وابن نمير عن هشام يعني ابن عروه .', 'Narrated Khuzaymah ibn Thabit: The Prophet (ﷺ) was asked about cleansing (after relieving oneself). He said: (One should cleanse oneself) with three stones which should be free from dung. Abu Dawud said: A similar tradition has been narrated by Abu Usamah and Ibn Numair from Hisham', NULL, '9963b71025203075de5e4ec9399cc6dc4bff2e8c458e9270b71bc18706020f60', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (200, 'abudawud', 207, 42, 'Book 1, Hadith 42', 42, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، وَخَلَفُ بْنُ هِشَامٍ الْمُقْرِئُ، قَالاَ حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يَحْيَى التَّوْأَمُ، ح وَحَدَّثَنَا عَمْرُو بْنُ عَوْنٍ، قَالَ أَخْبَرَنَا أَبُو يَعْقُوبَ التَّوْأَمُ، عَنْ عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ، عَنْ أُمِّهِ، عَنْ عَائِشَةَ، قَالَتْ بَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَقَامَ عُمَرُ خَلْفَهُ بِكُوزٍ مِنْ مَاءٍ فَقَالَ', 'مَا هَذَا يَا عُمَرُ  . فَقَالَ هَذَا مَاءٌ تَتَوَضَّأُ بِهِ . قَالَ  مَا أُمِرْتُ كُلَّمَا بُلْتُ أَنْ أَتَوَضَّأَ وَلَوْ فَعَلْتُ لَكَانَتْ سُنَّةً  .', 'ما هذا يا عمر . فقال هذا ماء تتوضا به . قال ما امرت كلما بلت ان اتوضا ولو فعلت لكانت سنه .', 'Narrated Aisha, Ummul Mu''minin: The Prophet (ﷺ) urinated and Umar was standing behind him with a jug of water. He said: What is this, Umar? He replied: Water for you to perform ablution with. He said: I have not been commanded to perform ablution every time I urinate. If I were to do so, it would become a sunnah', NULL, '3405ac33717ff545574df5cd1f441db246892d7a494d635e1eaa8f4ffc51ae9a', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published')
INSERT INTO public.hadith_narrations (id, collection_id, book_id, hadith_number, in_book_reference, international_number, chapter_title_arabic, chapter_title_english, sanad_arabic, matn_arabic, matn_clean, translation_english, translation_urdu, text_checksum, source_edition, version_number, is_current, status) VALUES
  (201, 'abudawud', 207, 43, 'Book 1, Hadith 43', 43, NULL, NULL, 'حَدَّثَنَا وَهْبُ بْنُ بَقِيَّةَ، عَنْ خَالِدٍ، - يَعْنِي الْوَاسِطِيَّ - عَنْ خَالِدٍ، - يَعْنِي الْحَذَّاءَ - عَنْ عَطَاءِ بْنِ أَبِي مَيْمُونَةَ، عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم', 'دَخَلَ حَائِطًا وَمَعَهُ غُلاَمٌ مَعَهُ مِيضَأَةٌ وَهُوَ أَصْغَرُنَا فَوَضَعَهَا عِنْدَ السِّدْرَةِ فَقَضَى حَاجَتَهُ فَخَرَجَ عَلَيْنَا وَقَدِ اسْتَنْجَى بِالْمَاءِ ‏.‏', 'دخل حائطا ومعه غلام معه ميضاه وهو اصغرنا فوضعها عند السدره فقضي حاجته فخرج علينا وقد استنجي بالماء ‏.‏', 'Narrated Anas b. Malik :The Apostle of Allaah ( sal Allaahu alayhi wa sallam ) entered a park. He was accompanied by a boy who had a jug of water with him. He was the youngest of us. He placed it near the lote-tree. He ( the Prophet, sal Allaahu alayhi wa sallam ) relieved himself. He came to us after he had cleansed himself with water', NULL, '80aad39d33de62d276a6a565d1779c53aa86c7d3cbf129473bf0ab90792e34e5', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (202, 'abudawud', 207, 44, 'Book 1, Hadith 44', 44, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ الْعَلاَءِ، أَخْبَرَنَا مُعَاوِيَةُ بْنُ هِشَامٍ، عَنْ يُونُسَ بْنِ الْحَارِثِ، عَنْ إِبْرَاهِيمَ بْنِ أَبِي مَيْمُونَةَ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏"‏', 'نَزَلَتْ هَذِهِ الآيَةُ فِي أَهْلِ قُبَاءَ ‏{‏ فِيهِ رِجَالٌ يُحِبُّونَ أَنْ يَتَطَهَّرُوا ‏}‏ قَالَ كَانُوا يَسْتَنْجُونَ بِالْمَاءِ فَنَزَلَتْ فِيهِمْ هَذِهِ الآيَةُ ‏.‏', 'نزلت هذه الايه في اهل قباء ‏{‏ فيه رجال يحبون ان يتطهروا ‏}‏ قال كانوا يستنجون بالماء فنزلت فيهم هذه الايه ‏.‏', 'Narrated AbuHurayrah: The Prophet (ﷺ) said: The following verse was revealed in connection with the people of Quba'': "In it are men who love to be purified" (ix.108). He (AbuHurayrah) said: They used to cleanse themselves with water after easing. So the verse was revealed in connection with them', NULL, 'd956e5e2a8945b407e442b72761394fe0b950d341d446c989a25a9e5e90d8ea0', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (203, 'abudawud', 207, 45, 'Book 1, Hadith 45', 45, NULL, NULL, 'حَدَّثَنَا إِبْرَاهِيمُ بْنُ خَالِدٍ، حَدَّثَنَا أَسْوَدُ بْنُ عَامِرٍ، حَدَّثَنَا شَرِيكٌ، وَهَذَا، لَفْظُهُ ح وَحَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ، - يَعْنِي الْمُخَرِّمِيَّ - حَدَّثَنَا وَكِيعٌ، عَنْ شَرِيكٍ، عَنْ إِبْرَاهِيمَ بْنِ جَرِيرٍ، عَنِ الْمُغِيرَةِ، عَنْ أَبِي زُرْعَةَ، عَنْ أَبِي هُرَيْرَةَ، قَالَ كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا أَتَى الْخَلاَءَ أَتَيْتُهُ بِمَاءٍ فِي تَوْرٍ أَوْ رَكْوَةٍ فَاسْتَنْجَى', '. قَالَ أَبُو دَاوُدَ فِي حَدِيثِ وَكِيعٍ ثُمَّ مَسَحَ يَدَهُ عَلَى الأَرْضِ ثُمَّ أَتَيْتُهُ بِإِنَاءٍ آخَرَ فَتَوَضَّأَ . قَالَ أَبُو دَاوُدَ وَحَدِيثُ الأَسْوَدِ بْنِ عَامِرٍ أَتَمُّ .', '. قال ابو داود في حديث وكيع ثم مسح يده علي الارض ثم اتيته باناء اخر فتوضا . قال ابو داود وحديث الاسود بن عامر اتم .', 'Narrated Abu Hurayrah : When the Prophet (sal Allaahu alayhi wa sallam ) went to the privy, I took to him water in a small vessel or a skin, and he cleansed himself. He then wiped his hand on the ground. I then took to him another vessel and he performed ablution. Abu Dawud said : The tradition is transmitted by al-Aswad b. ''Amir is more perfect', NULL, 'fe979bfc56625247459e826052c6060d2a4b21d8ccdd1cb0d9e3c854144e98b1', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (204, 'abudawud', 207, 46, 'Book 1, Hadith 46', 46, NULL, NULL, 'حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، عَنْ سُفْيَانَ، عَنْ أَبِي الزِّنَادِ، عَنِ الأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ، يَرْفَعُهُ قَالَ', 'لَوْلاَ أَنْ أَشُقَّ، عَلَى الْمُؤْمِنِينَ لأَمَرْتُهُمْ بِتَأْخِيرِ الْعِشَاءِ وَبِالسِّوَاكِ عِنْدَ كُلِّ صَلاَةٍ  .', 'لولا ان اشق، علي المؤمنين لامرتهم بتاخير العشاء وبالسواك عند كل صلاه .', 'Narrated Abu Hurayrah :(the Prophet, sal Allaahu alayhi wa sallam ) as saying : Were it not that I might oeverburdern the believers, I would order them to delay the night (''isha ) prayer and use the tooth-stick at the time of every prayer', NULL, '1447d7b79eefe45f110067183f98d22e1bc9128cba2cf357b081dd43786923ee', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (205, 'abudawud', 207, 47, 'Book 1, Hadith 47', 47, NULL, NULL, 'حَدَّثَنَا إِبْرَاهِيمُ بْنُ مُوسَى، أَخْبَرَنَا عِيسَى بْنُ يُونُسَ، حَدَّثَنَا مُحَمَّدُ بْنُ إِسْحَاقَ، عَنْ مُحَمَّدِ بْنِ إِبْرَاهِيمَ التَّيْمِيِّ، عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ، عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏', '"‏ لَوْلاَ أَنْ أَشُقَّ عَلَى أُمَّتِي لأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلاَةٍ ‏"‏ ‏.‏ قَالَ أَبُو سَلَمَةَ فَرَأَيْتُ زَيْدًا يَجْلِسُ فِي الْمَسْجِدِ وَإِنَّ السِّوَاكَ مِنْ أُذُنِهِ مَوْضِعُ الْقَلَمِ مِنْ أُذُنِ الْكَاتِبِ فَكُلَّمَا قَامَ إِلَى الصَّلاَةِ اسْتَاكَ ‏.‏', '"‏ لولا ان اشق علي امتي لامرتهم بالسواك عند كل صلاه ‏"‏ ‏.‏ قال ابو سلمه فرايت زيدا يجلس في المسجد وان السواك من اذنه موضع القلم من اذن الكاتب فكلما قام الي الصلاه استاك ‏.‏', 'Narrated Zayd ibn Khalid al-Juhani: I heard the Messenger of Allah (ﷺ) say: Were it not hard on my ummah, I would order them to use the tooth-stick at the time of every prayer. AbuSalamah said: Zayd ibn Khalid used to attend the prayers in the mosque with his tooth-stick on his ear where a clerk carries a pen, and whenever he got up for prayer he used it', NULL, 'f1b85cc608aec659d770ea8c2123b5aca08aecf99d7332ea62ba8e900eb721fd', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (206, 'abudawud', 207, 48, 'Book 1, Hadith 48', 48, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ عَوْفٍ الطَّائِيُّ، حَدَّثَنَا أَحْمَدُ بْنُ خَالِدٍ، حَدَّثَنَا مُحَمَّدُ بْنُ إِسْحَاقَ، عَنْ مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ، عَنْ عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ، قَالَ قُلْتُ أَرَأَيْتَ تَوَضُّؤَ ابْنِ عُمَرَ لِكُلِّ صَلاَةٍ طَاهِرًا وَغَيْرَ طَاهِرٍ عَمَّ ذَاكَ فَقَالَ حَدَّثَتْنِيهِ أَسْمَاءُ بِنْتُ زَيْدِ بْنِ الْخَطَّابِ أَنَّ عَبْدَ اللَّهِ بْنَ حَنْظَلَةَ بْنِ أَبِي عَامِرٍ حَدَّثَهَا أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم', 'أُمِرَ بِالْوُضُوءِ لِكُلِّ صَلاَةٍ طَاهِرًا وَغَيْرَ طَاهِرٍ فَلَمَّا شَقَّ ذَلِكَ عَلَيْهِ أُمِرَ بِالسِّوَاكِ لِكُلِّ صَلاَةٍ فَكَانَ ابْنُ عُمَرَ يَرَى أَنَّ بِهِ قُوَّةً فَكَانَ لاَ يَدَعُ الْوُضُوءَ لِكُلِّ صَلاَةٍ ‏.‏ قَالَ أَبُو دَاوُدَ إِبْرَاهِيمُ بْنُ سَعْدٍ رَوَاهُ عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ قَالَ عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ ‏.‏', 'امر بالوضوء لكل صلاه طاهرا وغير طاهر فلما شق ذلك عليه امر بالسواك لكل صلاه فكان ابن عمر يري ان به قوه فكان لا يدع الوضوء لكل صلاه ‏.‏ قال ابو داود ابراهيم بن سعد رواه عن محمد بن اسحاق قال عبيد الله بن عبد الله ‏.‏', 'Narrated Abdullah b. ''Abd Allah b. ''Umar: Muhammad ibn Yahya ibn Habban asked Abdullah ibn Abdullah ibn Umar about the reason for Ibn Umar''s performing ablution for every prayer, whether he was with or without ablution. He replied: Asma'', daughter of Zayd ibn al-Khattab, reported to me that Abdullah ibn Hanzalah ibn AbuAmir narrated to her that the Messenger of Allah (ﷺ) was earlier commanded to perform ablution for every prayer whether or not he was with ablution. When it became a burden for him, he was ordered to use tooth-stick for every prayer. As Ibn Umar thought that he had the strength (to perform the ablution for every prayer), he did not give up performing ablution for every prayer. Abu Dawud said: Ibrahim b. Sa''d narrated this tradition on the authority of Muhammad b. Ishaq, and there he mentions the name of ''Ubaid Allah b. ''Abd Allah (instead of ''Abd Allah b. ''Abd Allah b. ''Umar)', NULL, 'e2e33d38bd9f75d002149456553d550eb2f88fa071a84d3b27a8c5a9dc062d7b', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (207, 'abudawud', 207, 49, 'Book 1, Hadith 49', 49, NULL, NULL, 'حَدَّثَنَا مُسَدَّدٌ، وَسُلَيْمَانُ بْنُ دَاوُدَ الْعَتَكِيُّ، قَالاَ حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ غَيْلاَنَ بْنِ جَرِيرٍ، عَنْ أَبِي بُرْدَةَ، عَنْ أَبِيهِ، قَالَ مُسَدَّدٌ قَالَ أَتَيْنَا رَسُولَ اللَّهِ صلى الله عليه وسلم نَسْتَحْمِلُهُ فَرَأَيْتُهُ يَسْتَاكُ عَلَى لِسَانِهِ - قَالَ أَبُو دَاوُدَ وَقَالَ سُلَيْمَانُ قَالَ دَخَلْتُ عَلَى النَّبِيِّ صلى الله عليه وسلم وَهُوَ يَسْتَاكُ وَقَدْ وَضَعَ السِّوَاكَ عَلَى طَرَفِ لِسَانِهِ - وَهُوَ يَقُولُ', 'إِهْ إِهْ  . يَعْنِي يَتَهَوَّعُ . قَالَ أَبُو دَاوُدَ قَالَ مُسَدَّدٌ فَكَانَ حَدِيثًا طَوِيلاً اخْتَصَرْتُهُ .', 'اه اه . يعني يتهوع . قال ابو داود قال مسدد فكان حديثا طويلا اختصرته .', 'Narrated Abu Burdah: On the authority of his father ( Abu Musa al-Ash''ari), reported (according to the version of Musaddad) : We came to the Apostle of Allaah (sal Allaahu alayhi wa sallam) to provide us with a mount, and found him using the tooth-stick, its one end being at his tongue (i.e. he wsa rinsing his mouth). According to the version of Sulaiman it goes : I entered upon the Prophet (sal Allaahu alayhi wa sallam ) who was using the tooth-stick, and had it placed at one side of his tongue, producing a gurgling sound. Abu Dawud said : Musaddad said that the tradition was a lengthy but he shortened it', NULL, 'b599d5dcec5b9afdb8124dc6dedd24019e1a0201d3d23123cf9c0ee29d11943a', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (208, 'abudawud', 207, 50, 'Book 1, Hadith 50', 50, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ عِيسَى، حَدَّثَنَا عَنْبَسَةُ بْنُ عَبْدِ الْوَاحِدِ، عَنْ هِشَامِ بْنِ عُرْوَةَ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَسْتَنُّ وَعِنْدَهُ رَجُلاَنِ أَحَدُهُمَا أَكْبَرُ مِنَ الآخَرِ فَأُوحِيَ إِلَيْهِ فِي فَضْلِ السِّوَاكِ', 'أَنْ كَبِّرْ  . أَعْطِ السِّوَاكَ أَكْبَرَهُمَا . قَالَ أَحْمَدُ - هُوَ ابْنُ حَزْمٍ - قَالَ لَنَا أَبُو سَعِيدٍ هُوَ ابْنُ الأَعْرَابِيِّ هَذَا مِمَّا تَفَرَّدَ بِهِ أَهْلُ الْمَدِينَةِ .', 'ان كبر . اعط السواك اكبرهما . قال احمد - هو ابن حزم - قال لنا ابو سعيد هو ابن الاعرابي هذا مما تفرد به اهل المدينه .', 'Narrated Aisha, Ummul Mu''minin: The Messenger of Allah (ﷺ) was using the tooth-stick, when two men, one older than the other, were with him. A revelation came to him about the merit of using the tooth-stick. He was asked to show proper respect and give it to the elder of the two', NULL, '52a54db816d2aabb491a5fe84a91a8d63d5871abd1d9219ab274bb4b562a1eac', 'ABUDAWUD Darussalam Reference Edition', 1, TRUE, 'published'),
  (209, 'nasai', 251, 1, 'Book 1, Hadith 1', 1, NULL, NULL, 'أَخْبَرَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، قَالَ حَدَّثَنَا سُفْيَانُ، عَنِ الزُّهْرِيِّ، عَنْ أَبِي سَلَمَةَ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏', '"‏ إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ فَلاَ يَغْمِسْ يَدَهُ فِي وَضُوئِهِ حَتَّى يَغْسِلَهَا ثَلاَثًا فَإِنَّ أَحَدَكُمْ لاَ يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏"‏ ‏.‏', '"‏ اذا استيقظ احدكم من نومه فلا يغمس يده في وضوئه حتي يغسلها ثلاثا فان احدكم لا يدري اين باتت يده ‏"‏ ‏.‏', 'It was narrated from Abu Hurairah that the Prophet (ﷺ) said:"When any one of you wakes from sleep, let him not dip his hand in (the water he uses for) his Wudu'' until he has washed it three times, for none of you knows where his hand spent the night', NULL, 'cb82db1dcc12e56cb13a1567eed6e373c73e50a04045b4f8e01cf53b7ac56c73', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (210, 'nasai', 251, 2, 'Book 1, Hadith 2', 2, NULL, NULL, 'أَخْبَرَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، وَقُتَيْبَةُ بْنُ سَعِيدٍ، عَنْ جَرِيرٍ، عَنْ مَنْصُورٍ، عَنْ أَبِي وَائِلٍ، عَنْ حُذَيْفَةَ، قَالَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِذَا قَامَ مِنَ اللَّيْلِ يَشُوصُ فَاهُ بِالسِّوَاكِ', '.', '.', 'It was narrated that Huthaifah said:"When the Messenger of Allah (ﷺ) got up at night, he would brush his mouth with the Siwak', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (211, 'nasai', 251, 3, 'Book 1, Hadith 3', 3, NULL, NULL, 'أَخْبَرَنَا أَحْمَدُ بْنُ عَبْدَةَ، قَالَ حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، قَالَ أَخْبَرَنَا غَيْلاَنُ بْنُ جَرِيرٍ، عَنْ أَبِي بُرْدَةَ، عَنْ أَبِي مُوسَى، قَالَ دَخَلْتُ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم وَهُوَ يَسْتَنُّ وَطَرَفُ السِّوَاكِ عَلَى لِسَانِهِ وَهُوَ يَقُولُ', 'عَأْعَأْ  .', 'عاعا .', 'It was narrated that Abu Musa said:"I came to the Messenger of Allah (ﷺ) when he was using the Siwak, and the end of the Siwak was on his toungue, and he was saying, "''A'',''a', NULL, '3a48380c25a51e6ee47ca0680b2248d8fcb483f03135168cf8a98f697a5dd450', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (212, 'nasai', 251, 4, 'Book 1, Hadith 4', 4, NULL, NULL, 'أَخْبَرَنَا عَمْرُو بْنُ عَلِيٍّ، حَدَّثَنَا يَحْيَى، - وَهُوَ ابْنُ سَعِيدٍ - قَالَ حَدَّثَنَا قُرَّةُ بْنُ خَالِدٍ، قَالَ حَدَّثَنَا حُمَيْدُ بْنُ هِلاَلٍ، قَالَ حَدَّثَنِي أَبُو بُرْدَةَ، عَنْ أَبِي مُوسَى، قَالَ أَقْبَلْتُ إِلَى النَّبِيِّ صلى الله عليه وسلم وَمَعِي رَجُلاَنِ مِنَ الأَشْعَرِيِّينَ أَحَدُهُمَا عَنْ يَمِينِي وَالآخَرُ عَنْ يَسَارِي وَرَسُولُ اللَّهِ صلى الله عليه وسلم يَسْتَاكُ فَكِلاَهُمَا سَأَلَ الْعَمَلَ قُلْتُ وَالَّذِي بَعَثَكَ بِالْحَقِّ نَبِيًّا مَا أَطْلَعَانِي عَلَى مَا فِي أَنْفُسِهِمَا وَمَا شَعَرْتُ أَنَّهُمَا يَطْلُبَانِ الْعَمَلَ فَكَأَنِّي أَنْظُرُ إِلَى سِوَاكِهِ تَحْتَ شَفَتِهِ قَلَصَتْ فَقَالَ', 'إِنَّا لاَ - أَوْ لَنْ - نَسْتَعِينَ عَلَى الْعَمَلِ مَنْ أَرَادَهُ وَلَكِنِ اذْهَبْ أَنْتَ  . فَبَعَثَهُ عَلَى الْيَمَنِ ثُمَّ أَرْدَفَهُ مُعَاذُ بْنُ جَبَلٍ رضى الله عنهما .', 'انا لا - او لن - نستعين علي العمل من اراده ولكن اذهب انت . فبعثه علي اليمن ثم اردفه معاذ بن جبل رضي الله عنهما .', 'It was narrated from Abu Burdah that Abu Musa said:"I came to the Prophet (ﷺ) when he was using the Siwak and with me were two men of the Ash''aris - one on my right and the other on my left - who were seeking to be appointed as officials. I said: ''By the One Who sent you as a Prophet with the truth, they did not tell me why they wanted to come with me and I did not realize that they were seeking to be appointed as officials.'' And I could see his Siwak beneath his lip, then it slipped and he said: ''We do not'' - or; ''We will never appoint as an official anyone who seeks that. Rather you should go.''" So he sent his (Abu Musa) to Yemen, then he sent Mu''adh bin Jabal to go after him - may Allah be pleased with them', NULL, 'b84937f2d7a49c674b702bbd8d8edcf11b52856e3dbf18edc3fe2a7c1ed6be25', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (213, 'nasai', 251, 5, 'Book 1, Hadith 5', 5, NULL, NULL, 'أَخْبَرَنَا حُمَيْدُ بْنُ مَسْعَدَةَ، وَمُحَمَّدُ بْنُ عَبْدِ الأَعْلَى، عَنْ يَزِيدَ، - وَهُوَ ابْنُ زُرَيْعٍ - قَالَ حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبِي عَتِيقٍ، قَالَ حَدَّثَنِي أَبِي قَالَ، سَمِعْتُ عَائِشَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ السِّوَاكُ مَطْهَرَةٌ لِلْفَمِ مَرْضَاةٌ لِلرَّبِّ ‏"‏ ‏.‏', '"‏ السواك مطهره للفم مرضاه للرب ‏"‏ ‏.‏', 'Abdur-Rahman bin Abu ''Atiq said:"My father told me: ''I heard ''Aishah say, (narrating) from the Prophet (ﷺ): "Siwak is a means of purification for the mouth and is pleasing to the Lord', NULL, 'c6a23476787c2dc74710b47aac09d639567e7349d7b8b040982e716e4bc6ef92', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (214, 'nasai', 251, 6, 'Book 1, Hadith 6', 6, NULL, NULL, 'أَخْبَرَنَا حُمَيْدُ بْنُ مَسْعَدَةَ، وَعِمْرَانُ بْنُ مُوسَى، قَالاَ حَدَّثَنَا عَبْدُ الْوَارِثِ، قَالَ حَدَّثَنَا شُعَيْبُ بْنُ الْحَبْحَابِ، عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ قَدْ أَكْثَرْتُ عَلَيْكُمْ فِي السِّوَاكِ ‏"‏ ‏.‏', '"‏ قد اكثرت عليكم في السواك ‏"‏ ‏.‏', 'It was narrated that Anas bin Malik said:"The Messenger of Allah (ﷺ) said: ''I have indeed urged you with regard to the Siwak', NULL, '242b3d8c457a468a7ea26c2d883129f282769fa4372487b8dfe85334929b4d55', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (215, 'nasai', 251, 7, 'Book 1, Hadith 7', 7, NULL, NULL, 'أَخْبَرَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، عَنْ مَالِكٍ، عَنْ أَبِي الزِّنَادِ، عَنِ الأَعْرَجِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏', '"‏ لَوْلاَ أَنْ أَشُقَّ عَلَى أُمَّتِي لأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلاَةٍ ‏"‏ ‏.‏', '"‏ لولا ان اشق علي امتي لامرتهم بالسواك عند كل صلاه ‏"‏ ‏.‏', 'It was narrated from Abu Hurairah that the Messenger of Allah (ﷺ) said:"Were it not that it would be too difficult for my Ummah, I would have commanded them to use the Siwak at (the time of) every Salah', NULL, '4fa7e9c3b6ff90f5fcff1399251f6a2aadb19b3c73f4ed142de9851801c0168d', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (216, 'nasai', 251, 8, 'Book 1, Hadith 8', 8, NULL, NULL, 'أَخْبَرَنَا عَلِيُّ بْنُ خَشْرَمٍ، قَالَ حَدَّثَنَا عِيسَى، - وَهُوَ ابْنُ يُونُسَ - عَنْ مِسْعَرٍ، عَنِ الْمِقْدَامِ، - وَهُوَ ابْنُ شُرَيْحٍ - عَنْ أَبِيهِ، قَالَ قُلْتُ لِعَائِشَةَ بِأَىِّ شَىْءٍ كَانَ يَبْدَأُ النَّبِيُّ صلى الله عليه وسلم إِذَا دَخَلَ بَيْتَهُ قَالَتْ بِالسِّوَاكِ', '.', '.', 'It was narrated from Al-Miqdam - Abu Shuraih - that his father said:"I said to ''Aishah: ''What did the Prophet (ﷺ) start with when he entered his house?'' She said: ''The Siwak', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (217, 'nasai', 251, 9, 'Book 1, Hadith 9', 9, NULL, NULL, 'أَخْبَرَنَا الْحَارِثُ بْنُ مِسْكِينٍ، قِرَاءَةً عَلَيْهِ وَأَنَا أَسْمَعُ، عَنِ ابْنِ وَهْبٍ، عَنْ يُونُسَ، عَنِ ابْنِ شِهَابٍ، عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ، عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم قَالَ ‏', '"‏ الْفِطْرَةُ خَمْسٌ الاِخْتِتَانُ وَالاِسْتِحْدَادُ وَقَصُّ الشَّارِبِ وَتَقْلِيمُ الأَظْفَارِ وَنَتْفُ الإِبْطِ ‏"‏ ‏.‏', '"‏ الفطره خمس الاختتان والاستحداد وقص الشارب وتقليم الاظفار ونتف الابط ‏"‏ ‏.‏', 'It was narrated from Abu Hurairah that the Messenger of Allah (ﷺ) said:"The Fitrah are five: Circumcision, removing the pubes, trimming the mustache, clipping the nails, and plucking the armpit hairs', NULL, 'e6808491a03b01586e8049ddde86a97f4e3f3ae156385b6f05e59b0dfaa35b67', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (218, 'nasai', 251, 10, 'Book 1, Hadith 10', 10, NULL, NULL, 'أَخْبَرَنَا مُحَمَّدُ بْنُ عَبْدِ الأَعْلَى، قَالَ حَدَّثَنَا الْمُعْتَمِرُ، قَالَ سَمِعْتُ مَعْمَرًا، عَنِ الزُّهْرِيِّ، عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ خَمْسٌ مِنَ الْفِطْرَةِ قَصُّ الشَّارِبِ وَنَتْفُ الإِبْطِ وَتَقْلِيمُ الأَظْفَارِ وَالاِسْتِحْدَادُ وَالْخِتَانُ ‏"‏ ‏.‏', '"‏ خمس من الفطره قص الشارب ونتف الابط وتقليم الاظفار والاستحداد والختان ‏"‏ ‏.‏', 'It was narrated that Abu Hurairah said:"The Messenger of Allah (ﷺ) said: ''The Fitrah are five: Trimming the mustache, plucking the armpit hairs, clipping the nails, removing the pubes, and circumcision', NULL, 'd01dd07852c6fa32e3babf80bb6b5b16f97edb8658b75d3bbf48a871b61b7f82', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (219, 'nasai', 251, 11, 'Book 1, Hadith 11', 11, NULL, NULL, 'أَخْبَرَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ يَزِيدَ، قَالَ حَدَّثَنَا سُفْيَانُ، عَنِ الزُّهْرِيِّ، عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ خَمْسٌ مِنَ الْفِطْرَةِ الْخِتَانُ وَحَلْقُ الْعَانَةِ وَنَتْفُ الإِبْطِ وَتَقْلِيمُ الأَظْفَارِ وَأَخْذُ الشَّارِبِ ‏"‏ ‏.‏', '"‏ خمس من الفطره الختان وحلق العانه ونتف الابط وتقليم الاظفار واخذ الشارب ‏"‏ ‏.‏', 'It was narrated from Abu Hurairah that the Prophet (ﷺ) said:"The Fitrah are five: Circumcision, shaving the pubes, plucking the armpit hairs, clipping the nails and taking from the mustache', NULL, '2b1653e7773ab5c2a93249fa448ca466d81bdae81705ca1260b80a3c2ea5bbcc', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (220, 'nasai', 251, 12, 'Book 1, Hadith 12', 12, NULL, NULL, 'أَخْبَرَنَا الْحَارِثُ بْنُ مِسْكِينٍ، قِرَاءَةً عَلَيْهِ وَأَنَا أَسْمَعُ، عَنِ ابْنِ وَهْبٍ، عَنْ حَنْظَلَةَ بْنِ أَبِي سُفْيَانَ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏', '"‏ الْفِطْرَةُ قَصُّ الأَظْفَارِ وَأَخْذُ الشَّارِبِ وَحَلْقُ الْعَانَةِ ‏"‏ ‏.‏', '"‏ الفطره قص الاظفار واخذ الشارب وحلق العانه ‏"‏ ‏.‏', 'It was narrated from Ibn ''Umar that the Messenger of Allah (ﷺ) said:"The deeds connected to the Fitrah are: Clipping the nails, removing the mustache and shaving the pubes', NULL, '5527b190b04858ea7c87772f1c63facfa25c57d1bd2a07a0720720920250cfda', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (221, 'nasai', 251, 13, 'Book 1, Hadith 13', 13, NULL, NULL, 'أَخْبَرَنَا عَلِيُّ بْنُ حُجْرٍ، قَالَ أَنْبَأَنَا عَبِيدَةُ بْنُ حُمَيْدٍ، عَنْ يُوسُفَ بْنِ صُهَيْبٍ، عَنْ حَبِيبِ بْنِ يَسَارٍ، عَنْ زَيْدِ بْنِ أَرْقَمَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ مَنْ لَمْ يَأْخُذْ شَارِبَهُ فَلَيْسَ مِنَّا ‏"‏ ‏.‏', '"‏ من لم ياخذ شاربه فليس منا ‏"‏ ‏.‏', 'It was narrated that Zaid bin Arqam said:"The Messenger of Allah (ﷺ) said: ''Whoever does not trim his mustache, he is not from one of us', NULL, '151916b52283260a5571d11cff0386791136569e2a52bad1ac5a2401ca62f236', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (222, 'nasai', 251, 14, 'Book 1, Hadith 14', 14, NULL, NULL, 'أَخْبَرَنَا قُتَيْبَةُ، قَالَ حَدَّثَنَا جَعْفَرٌ، - هُوَ ابْنُ سُلَيْمَانَ - عَنْ أَبِي عِمْرَانَ الْجَوْنِيِّ، عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ وَقَّتَ لَنَا رَسُولُ اللَّهِ صلى الله عليه وسلم فِي قَصِّ الشَّارِبِ وَتَقْلِيمِ الأَظْفَارِ وَحَلْقِ الْعَانَةِ وَنَتْفِ الإِبْطِ أَنْ لاَ نَتْرُكَ أَكْثَرَ مِنْ أَرْبَعِينَ يَوْمًا', '. وَقَالَ مَرَّةً أُخْرَى أَرْبَعِينَ لَيْلَةً .', '. وقال مره اخري اربعين ليله .', 'It was narrated that Anas bin Malik said:"A time limit was set for us, by the Messenger of Allah (ﷺ), regarding trimming the mustache, clipping the nails and plucking the pubes; we were not to leave that for more than forty days," on one occasion he said: "Forty nights', NULL, 'fef3725815a827b25537db764703ed9addf20a79b7b0d5b2a40b7fcd0a4525e0', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (223, 'nasai', 251, 15, 'Book 1, Hadith 15', 15, NULL, NULL, 'أَخْبَرَنَا عُبَيْدُ اللَّهِ بْنُ سَعِيدٍ، قَالَ حَدَّثَنَا يَحْيَى، - هُوَ ابْنُ سَعِيدٍ - عَنْ عُبَيْدِ اللَّهِ، أَخْبَرَنِي نَافِعٌ، عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ أَحْفُوا الشَّوَارِبَ وَأَعْفُوا اللِّحَى ‏"‏ ‏.‏', '"‏ احفوا الشوارب واعفوا اللحي ‏"‏ ‏.‏', 'It was narrated from Ibn ''Umar that the Prophet (ﷺ) said:"Trim the mustache and let the beard grow', NULL, '91e29bb877639eaccfbe3bb41cad6fbbc90cddbb17fc82347e05a2d5cdb32479', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (224, 'nasai', 251, 16, 'Book 1, Hadith 16', 16, NULL, NULL, 'أَخْبَرَنَا عَمْرُو بْنُ عَلِيٍّ، قَالَ حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، قَالَ حَدَّثَنَا أَبُو جَعْفَرٍ الْخَطْمِيُّ، عُمَيْرُ بْنُ يَزِيدَ قَالَ حَدَّثَنِي الْحَارِثُ بْنُ فُضَيْلٍ، وَعُمَارَةُ بْنُ خُزَيْمَةَ بْنِ ثَابِتٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي قُرَادٍ، قَالَ خَرَجْتُ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم إِلَى الْخَلاَءِ وَكَانَ إِذَا أَرَادَ الْحَاجَةَ أَبْعَدَ', '.', '.', 'It was narrated that ''Abdur-Rahman bin Abi Qurad said:"I went out with the Messenger of Allah (ﷺ) to an isolated area, and when he wanted to relieve himself he moved far away', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (225, 'nasai', 251, 17, 'Book 1, Hadith 17', 17, NULL, NULL, 'أَخْبَرَنَا عَلِيُّ بْنُ حُجْرٍ، قَالَ أَنْبَأَنَا إِسْمَاعِيلُ، عَنْ مُحَمَّدِ بْنِ عَمْرٍو، عَنْ أَبِي سَلَمَةَ، عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'كَانَ إِذَا ذَهَبَ الْمَذْهَبَ أَبْعَدَ قَالَ فَذَهَبَ لِحَاجَتِهِ - وَهُوَ فِي بَعْضِ أَسْفَارِهِ - فَقَالَ ‏ "‏ ائْتِنِي بِوَضُوءٍ ‏"‏ ‏.‏ فَأَتَيْتُهُ بِوَضُوءٍ فَتَوَضَّأَ وَمَسَحَ عَلَى الْخُفَّيْنِ ‏.‏ قَالَ الشَّيْخُ إِسْمَاعِيلُ هُوَ ابْنُ جَعْفَرِ بْنِ أَبِي كَثِيرٍ الْقَارِئُ ‏.‏', 'كان اذا ذهب المذهب ابعد قال فذهب لحاجته - وهو في بعض اسفاره - فقال ‏ "‏ ائتني بوضوء ‏"‏ ‏.‏ فاتيته بوضوء فتوضا ومسح علي الخفين ‏.‏ قال الشيخ اسماعيل هو ابن جعفر بن ابي كثير القارئ ‏.‏', 'It was narrated from Al-Mughirah bin Shu''bah that when the Prophet (ﷺ) would go away (to relieve himself) he would go far away. He went to relieve himself when he was on one of his journeys, and said:"Bring me (water for) Wudu''." So I brought him (water for) Wudu'', and he performed Wudu'' and wiped over his Khuffs. The Shaikh [1] said: "Isma''il (one of the narrators) is Ibn Ja''far bin Abi Kathir Al-Qari. [1] Meaning the author, and it appears that Ibn As-Sunni who heard the text, said this', NULL, '9a23715aa4a10cf8938983ccbe32b703f96d0896e81900567f8c2a595c1ecc97', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (226, 'nasai', 251, 18, 'Book 1, Hadith 18', 18, NULL, NULL, 'أَخْبَرَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، قَالَ أَنْبَأَنَا عِيسَى بْنُ يُونُسَ، قَالَ أَنْبَأَنَا الأَعْمَشُ، عَنْ شَقِيقٍ، عَنْ حُذَيْفَةَ، قَالَ كُنْتُ أَمْشِي مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم فَانْتَهَى إِلَى سُبَاطَةِ قَوْمٍ فَبَالَ قَائِمًا فَتَنَحَّيْتُ عَنْهُ فَدَعَانِي وَكُنْتُ عِنْدَ عَقِبَيْهِ حَتَّى فَرَغَ ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ', '.', '.', 'It was narrated that Hudhaifah said:"I was walking with the Messenger of Allah (ﷺ) and he came to some people''s garbage dump and urinated while standing up. I turned to go away, but he called me back (to conceal him), and I was just behind him. Then when he had finished, he performed Wudu'' and wiped over his Khuffs', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (227, 'nasai', 251, 19, 'Book 1, Hadith 19', 19, NULL, NULL, 'أَخْبَرَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، قَالَ أَنْبَأَنَا إِسْمَاعِيلُ، عَنْ عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ، عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِذَا دَخَلَ الْخَلاَءَ قَالَ', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ  .', 'اللهم اني اعوذ بك من الخبث والخبائث .', 'It was narrated that Anas bin Malik said:"The Messenger of Allah (ﷺ) entered Al-Khala'' (the toilet) and said: ''Allahumma inni a''uthu bika min al-khubuthi wal-khaba''ith (O Allah, I seek refuge with You from male and female devils)."[1] [1] See Ma''alam As-Sunan by Al-Khattabi. And Al-Khala'' is the area one relieves oneself in. It refers to outside or other than that, it should not be understood to mean toilet only', NULL, '0cfb6716226b0930ddb8881c04b4808fbaa3287cd47404c17d071e5e469deae2', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (228, 'nasai', 251, 20, 'Book 1, Hadith 20', 20, NULL, NULL, 'أَخْبَرَنَا مُحَمَّدُ بْنُ سَلَمَةَ، وَالْحَارِثُ بْنُ مِسْكِينٍ، قِرَاءَةً عَلَيْهِ وَأَنَا أَسْمَعُ، وَاللَّفْظُ، لَهُ عَنِ ابْنِ الْقَاسِمِ، قَالَ حَدَّثَنِي مَالِكٌ، عَنْ إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ، عَنْ رَافِعِ بْنِ إِسْحَاقَ، أَنَّهُ سَمِعَ أَبَا أَيُّوبَ الأَنْصَارِيَّ، وَهُوَ بِمِصْرَ يَقُولُ وَاللَّهِ مَا أَدْرِي كَيْفَ أَصْنَعُ بِهَذِهِ الْكَرَايِيسِ وَقَدْ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ إِذَا ذَهَبَ أَحَدُكُمْ إِلَى الْغَائِطِ أَوِ الْبَوْلِ فَلاَ يَسْتَقْبِلِ الْقِبْلَةَ وَلاَ يَسْتَدْبِرْهَا ‏"‏ ‏.‏', '"‏ اذا ذهب احدكم الي الغائط او البول فلا يستقبل القبله ولا يستدبرها ‏"‏ ‏.‏', 'It was narrated from Rafi'' bin Ishaq that he heard Abu Ayyub Al-Ansari say - when he was in Egypt:"By Allah, I do not know what I should do with these Karais (toilets). The Messenger of Allah (ﷺ) said: ''When any one of you goes to defecate or urinate, let him not face toward the Qiblah, nor turn his back towards it', NULL, '4fcbe3305420b9c2cea83ecbad44044f3a36b521136cd0a5ebfe70e463593b87', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (229, 'nasai', 251, 21, 'Book 1, Hadith 21', 21, NULL, NULL, 'أَخْبَرَنَا مُحَمَّدُ بْنُ مَنْصُورٍ، قَالَ حَدَّثَنَا سُفْيَانُ، عَنِ الزُّهْرِيِّ، عَنْ عَطَاءِ بْنِ يَزِيدَ، عَنْ أَبِي أَيُّوبَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏', '"‏ لاَ تَسْتَقْبِلُوا الْقِبْلَةَ وَلاَ تَسْتَدْبِرُوهَا لِغَائِطٍ أَوْ بَوْلٍ وَلَكِنْ شَرِّقُوا أَوْ غَرِّبُوا ‏"‏ ‏.‏', '"‏ لا تستقبلوا القبله ولا تستدبروها لغائط او بول ولكن شرقوا او غربوا ‏"‏ ‏.‏', 'It was narrated from Abu Ayyub that the Prophet (ﷺ) said:"Do not face towards the Qiblah nor turn your backs toward it when defecating or urinating, rather face toward the east or the west', NULL, '87e8e3e5de18f0d4bd3db6fc3f51684a4e029c498407201499cbdb8def711a2e', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (230, 'nasai', 251, 22, 'Book 1, Hadith 22', 22, NULL, NULL, 'أَخْبَرَنَا يَعْقُوبُ بْنُ إِبْرَاهِيمَ، قَالَ أَنْبَأَنَا غُنْدَرٌ، قَالَ أَنْبَأَنَا مَعْمَرٌ، قَالَ أَنْبَأَنَا ابْنُ شِهَابٍ، عَنْ عَطَاءِ بْنِ يَزِيدَ، عَنْ أَبِي أَيُّوبَ الأَنْصَارِيِّ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ إِذَا أَتَى أَحَدُكُمُ الْغَائِطَ فَلاَ يَسْتَقْبِلِ الْقِبْلَةَ وَلَكِنْ لِيُشَرِّقْ أَوْ لِيُغَرِّبْ ‏"‏ ‏.‏', '"‏ اذا اتي احدكم الغائط فلا يستقبل القبله ولكن ليشرق او ليغرب ‏"‏ ‏.‏', 'It was narrated that Abu Ayyub Al-Ansari said:"The Messenger of Allah (ﷺ) said: ''When any one of you goes to defecate, let him not face toward the Qiblah, rather let him face towards the east or the west', NULL, '2f7fa47675b3a35f262ee99c7571246f15dca690778e45a0f51100d3417b51fa', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (231, 'nasai', 251, 23, 'Book 1, Hadith 23', 23, NULL, NULL, 'أَخْبَرَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، عَنْ مَالِكٍ، عَنْ يَحْيَى بْنِ سَعِيدٍ، عَنْ مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ، عَنْ عَمِّهِ، وَاسِعِ بْنِ حَبَّانَ، عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، قَالَ لَقَدِ ارْتَقَيْتُ عَلَى ظَهْرِ بَيْتِنَا فَرَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم عَلَى لَبِنَتَيْنِ مُسْتَقْبِلَ بَيْتِ الْمَقْدِسِ لِحَاجَتِهِ', '.', '.', 'It was narrated that ''Abdullah bin ''Umar said:"I climbed on the roof of our house and saw the Messenger of Allah (ﷺ) on two bricks, facing toward Bait Al-Maqdis (jerusalem), relieving himself', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (232, 'nasai', 251, 24, 'Book 1, Hadith 24', 24, NULL, NULL, 'أَخْبَرَنَا يَحْيَى بْنُ دُرُسْتَ، قَالَ أَنْبَأَنَا أَبُو إِسْمَاعِيلَ، - وَهُوَ الْقَنَّادُ - قَالَ حَدَّثَنِي يَحْيَى بْنُ أَبِي كَثِيرٍ، أَنَّ عَبْدَ اللَّهِ بْنَ أَبِي قَتَادَةَ، حَدَّثَهُ عَنْ أَبِيهِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏', '"‏ إِذَا بَالَ أَحَدُكُمْ فَلاَ يَأْخُذْ ذَكَرَهُ بِيَمِينِهِ ‏"‏ ‏.‏', '"‏ اذا بال احدكم فلا ياخذ ذكره بيمينه ‏"‏ ‏.‏', 'It was narrated from ''Abdullah bin Abi Qatadah, from his father, that the Messenger of Allah (ﷺ said:"When any one of you urinates, let him not hold his penis in his right hand)', NULL, 'de9137da7aa600f7b8869648d1fdf576a710e90b36f2345e9789c0d1722fb022', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (233, 'nasai', 251, 25, 'Book 1, Hadith 25', 25, NULL, NULL, 'أَخْبَرَنَا هَنَّادُ بْنُ السَّرِيِّ، عَنْ وَكِيعٍ، عَنْ هِشَامٍ، عَنْ يَحْيَى، - هُوَ ابْنُ أَبِي كَثِيرٍ - عَنْ عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ، عَنْ أَبِيهِ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏', '"‏ إِذَا دَخَلَ أَحَدُكُمُ الْخَلاَءَ فَلاَ يَمَسَّ ذَكَرَهُ بِيَمِينِهِ ‏"‏ ‏.‏', '"‏ اذا دخل احدكم الخلاء فلا يمس ذكره بيمينه ‏"‏ ‏.‏', 'It was narrated from ''Abdullah bin Abi Qatadah that his father said:"The Messenger of Allah (ﷺ) said: ''When any one of you enters Al-Khala'' (the toilet), let him not touch his penis with his right hand', NULL, '0ffa21701192bbe9483854989e80bc7071bf47384819e990d0feed1c7d812088', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (234, 'nasai', 251, 26, 'Book 1, Hadith 26', 26, NULL, NULL, 'أَخْبَرَنَا مُؤَمَّلُ بْنُ هِشَامٍ، قَالَ أَنْبَأَنَا إِسْمَاعِيلُ، قَالَ أَخْبَرَنَا شُعْبَةُ، عَنْ سُلَيْمَانَ، عَنْ أَبِي وَائِلٍ، عَنْ حُذَيْفَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم', 'أَتَى سُبَاطَةَ قَوْمٍ فَبَالَ قَائِمًا ‏.‏', 'اتي سباطه قوم فبال قائما ‏.‏', 'It was narrated from Hudhifah that the Messenger of Allah (ﷺ)came to some people''s garbage dump and urinated while standing', NULL, '60a7598af0d602e82bcc9b268dc049258c0b1868c5c8e182d5c4843dcb889056', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (235, 'nasai', 251, 27, 'Book 1, Hadith 27', 27, NULL, NULL, 'أَخْبَرَنَا مُحَمَّدُ بْنُ بَشَّارٍ، قَالَ أَنْبَأَنَا مُحَمَّدٌ، قَالَ أَنْبَأَنَا شُعْبَةُ، عَنْ مَنْصُورٍ، قَالَ سَمِعْتُ أَبَا وَائِلٍ، أَنَّ حُذَيْفَةَ، قَالَ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم أَتَى سُبَاطَةَ قَوْمٍ فَبَالَ قَائِمًا', '.', '.', 'It was narrated that Mansur said:"I heard Abu Wa''il (say) that Hudhaifah said: ''The Messenger of Allah (ﷺ) came to some people''s garbage dump and urinated while standing', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (236, 'nasai', 251, 28, 'Book 1, Hadith 28', 28, NULL, NULL, 'أَخْبَرَنَا سُلَيْمَانُ بْنُ عُبَيْدِ اللَّهِ، قَالَ أَنْبَأَنَا بَهْزٌ، قَالَ أَنْبَأَنَا شُعْبَةُ، عَنْ سُلَيْمَانَ، وَمَنْصُورٌ، عَنْ أَبِي وَائِلٍ، عَنْ حُذَيْفَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'مَشَى إِلَى سُبَاطَةِ قَوْمٍ فَبَالَ قَائِمًا ‏.‏ قَالَ سُلَيْمَانُ فِي حَدِيثِهِ وَمَسَحَ عَلَى خُفَّيْهِ وَلَمْ يَذْكُرْ مَنْصُورٌ الْمَسْحَ ‏.‏', 'مشي الي سباطه قوم فبال قائما ‏.‏ قال سليمان في حديثه ومسح علي خفيه ولم يذكر منصور المسح ‏.‏', 'It was narrated from Hudhaifah that the Prophet (ﷺ) went to some people''s garbage dump and urinated while standing. In his narration, Sulaiman bin ''Ubaidullah said:"And he wiped over his Khuffs," but Mansur did not mention the wiping. [1] [1]Meaning, in this route, since Shu''bah narrated it from both Sulaiman and Mansur', NULL, 'a7808f5b5231e94fc58cc87dd42c7ac560c314304329af8539e14509e4a813e0', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (237, 'nasai', 251, 29, 'Book 1, Hadith 29', 29, NULL, NULL, 'أَخْبَرَنَا عَلِيُّ بْنُ حُجْرٍ، قَالَ أَنْبَأَنَا شَرِيكٌ، عَنِ الْمِقْدَامِ بْنِ شُرَيْحٍ، عَنْ أَبِيهِ، عَنْ عَائِشَةَ، قَالَتْ مَنْ حَدَّثَكُمْ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم', 'بَالَ قَائِمًا فَلاَ تُصَدِّقُوهُ مَا كَانَ يَبُولُ إِلاَّ جَالِسًا ‏.‏', 'بال قائما فلا تصدقوه ما كان يبول الا جالسا ‏.‏', 'It was narrated that ''Aishah said:"Whoever tells you that the Messenger of Allah (ﷺ) urinated standing up, do not believe him, for he would not urinate except while squatting', NULL, '24428c3c77b6ec88291e0a46c57d5ad2805e2e4a678dab1ee6eb095062e64fe5', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (238, 'nasai', 251, 30, 'Book 1, Hadith 30', 30, NULL, NULL, 'أَخْبَرَنَا هَنَّادُ بْنُ السَّرِيِّ، عَنْ أَبِي مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ زَيْدِ بْنِ وَهْبٍ، عَنْ عَبْدِ الرَّحْمَنِ ابْنِ حَسَنَةَ، قَالَ خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ صلى الله عليه وسلم وَفِي يَدِهِ كَهَيْئَةِ الدَّرَقَةِ فَوَضَعَهَا ثُمَّ جَلَسَ خَلْفَهَا فَبَالَ إِلَيْهَا فَقَالَ بَعْضُ الْقَوْمِ انْظُرُوا يَبُولُ كَمَا تَبُولُ الْمَرْأَةُ فَسَمِعَهُ فَقَالَ', 'أَوَمَا عَلِمْتَ مَا أَصَابَ صَاحِبُ بَنِي إِسْرَائِيلَ كَانُوا إِذَا أَصَابَهُمْ شَىْءٌ مِنَ الْبَوْلِ قَرَضُوهُ بِالْمَقَارِيضِ فَنَهَاهُمْ صَاحِبُهُمْ فَعُذِّبَ فِي قَبْرِهِ  .', 'اوما علمت ما اصاب صاحب بني اسرائيل كانوا اذا اصابهم شيء من البول قرضوه بالمقاريض فنهاهم صاحبهم فعذب في قبره .', 'It was narrated that ''Abdur-Rahman bin Hasanah said:"The Messenger of Allah (ﷺ) came out to us with a small leather shield in his hand. He put it down, then he sat behind it and urinated toward it. Some of the people said: ''Look, he is urinating like a woman.'' He heard that and said: ''Do you not know what happened to the companion of the Children of Israel? If they got any urine on themselves they would clip that part of their garments off. Their companion told them not to do that and he was punished in his grave', NULL, '12e09a533c21944dbaff189f58a0f73a8857b0c86b37a4f869775e9fa0d6fece', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (239, 'nasai', 251, 31, 'Book 1, Hadith 31', 31, NULL, NULL, 'أَخْبَرَنَا هَنَّادُ بْنُ السَّرِيِّ، عَنْ وَكِيعٍ، عَنِ الأَعْمَشِ، قَالَ سَمِعْتُ مُجَاهِدًا، يُحَدِّثُ عَنْ طَاوُسٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ مَرَّ رَسُولُ اللَّهِ صلى الله عليه وسلم عَلَى قَبْرَيْنِ فَقَالَ', 'إِنَّهُمَا يُعَذَّبَانِ وَمَا يُعَذَّبَانِ فِي كَبِيرٍ أَمَّا هَذَا فَكَانَ لاَ يَسْتَنْزِهُ مِنْ بَوْلِهِ وَأَمَّا هَذَا فَإِنَّهُ كَانَ يَمْشِي بِالنَّمِيمَةِ  . ثُمَّ دَعَا بِعَسِيبٍ رَطْبٍ فَشَقَّهُ بِاثْنَيْنِ فَغَرَسَ عَلَى هَذَا وَاحِدًا وَعَلَى هَذَا وَاحِدًا ثُمَّ قَالَ  لَعَلَّهُ يُخَفَّفُ عَنْهُمَا مَا لَمْ يَيْبَسَا  . خَالَفَهُ مَنْصُورٌ رَوَاهُ عَنْ مُجَاهِدٍ عَنِ ابْنِ عَبَّاسٍ وَلَمْ يَذْكُرْ طَاوُسًا .', 'انهما يعذبان وما يعذبان في كبير اما هذا فكان لا يستنزه من بوله واما هذا فانه كان يمشي بالنميمه . ثم دعا بعسيب رطب فشقه باثنين فغرس علي هذا واحدا وعلي هذا واحدا ثم قال لعله يخفف عنهما ما لم ييبسا . خالفه منصور رواه عن مجاهد عن ابن عباس ولم يذكر طاوسا .', 'It was narrated that Ibn ''Abbas said:"The Messenger of Allah (ﷺ) passed by two graves and said: ''These two are being punished, but they are not being punished for something that was difficult to avoid. As for this, he used not to take precautions to avoid (his body to clothes being soiled by) urine, and this one used to walk around spreading malicious gossip.'' Then he called for a fresh palm-leaf stalk and split it in two, and placed one piece on each of the two graves. They said: ''O Messenger of Allah, why did you do that?'' He said: ''Perhaps the torment will be reduced for them so long as this does not dry out.''" Mansur Contradicted him, he reported it from Mujahid from ibn ''Abbas but he did not mention Tawus in it', NULL, 'dbd9d6105344af8deed5f37efafe328eab53c3ff4f7ff41298dd6c440da75726', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (240, 'nasai', 251, 32, 'Book 1, Hadith 32', 32, NULL, NULL, 'أَخْبَرَنَا أَيُّوبُ بْنُ مُحَمَّدٍ الْوَزَّانُ، قَالَ حَدَّثَنَا حَجَّاجٌ، قَالَ قَالَ ابْنُ جُرَيْجٍ أَخْبَرَتْنِي حُكَيْمَةُ بِنْتُ أُمَيْمَةَ، عَنْ أُمِّهَا، أُمَيْمَةَ بِنْتِ رُقَيْقَةَ قَالَتْ كَانَ لِلنَّبِيِّ صلى الله عليه وسلم قَدَحٌ مِنْ عَيْدَانٍ يَبُولُ فِيهِ وَيَضَعُهُ تَحْتَ السَّرِيرِ', '.', '.', 'It was narrated that Umaimah bint Ruqaiqah said:"The Prophet (ﷺ) had a vessel made from a date tree in which he would urinate and place it under the bed', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (241, 'nasai', 251, 33, 'Book 1, Hadith 33', 33, NULL, NULL, 'أَخْبَرَنَا عَمْرُو بْنُ عَلِيٍّ، قَالَ أَنْبَأَنَا أَزْهَرُ، أَنْبَأَنَا ابْنُ عَوْنٍ، عَنْ إِبْرَاهِيمَ، عَنِ الأَسْوَدِ، عَنْ عَائِشَةَ، قَالَتْ يَقُولُونَ إِنَّ النَّبِيَّ صلى الله عليه وسلم أَوْصَى إِلَى عَلِيٍّ لَقَدْ دَعَا بِالطَّسْتِ لِيَبُولَ فِيهَا فَانْخَنَثَتْ نَفْسُهُ وَمَا أَشْعُرُ فَإِلَى مَنْ أَوْصَى قَالَ الشَّيْخُ أَزْهَرُ هُوَ ابْنُ سَعْدٍ السَّمَّانُ', '.', '.', 'It was narrated that ''Aishah said:"They say that the Prophet (ﷺ) made a will for ''Ali,[1] but he called for a basin in which to urinate, then he went flaccid suddenly (and died), so how could he leave a will?!" The Shaikh said: Azhar (one of the narrators) is Ibn Sa''d As-Samman. [1] Meaning, appointing him as the Khalifah', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (242, 'nasai', 251, 34, 'Book 1, Hadith 34', 34, NULL, NULL, 'أَخْبَرَنَا عُبَيْدُ اللَّهِ بْنُ سَعِيدٍ، قَالَ أَنْبَأَنَا مُعَاذُ بْنُ هِشَامٍ، قَالَ حَدَّثَنِي أَبِي، عَنْ قَتَادَةَ، عَنْ عَبْدِ اللَّهِ بْنِ سَرْجِسَ، أَنَّ نَبِيَّ اللَّهِ صلى الله عليه وسلم قَالَ ‏', '"‏ لاَ يَبُولَنَّ أَحَدُكُمْ فِي جُحْرٍ ‏"‏ ‏.‏ قَالُوا لِقَتَادَةَ وَمَا يُكْرَهُ مِنَ الْبَوْلِ فِي الْجُحْرِ قَالَ يُقَالُ إِنَّهَا مَسَاكِنُ الْجِنِّ ‏.‏', '"‏ لا يبولن احدكم في جحر ‏"‏ ‏.‏ قالوا لقتاده وما يكره من البول في الجحر قال يقال انها مساكن الجن ‏.‏', 'It was narrated from Qatadah, from ''Abdullah bin Sarjis, that the Prophet of Allah (ﷺ) said:"None of you should urinate into a burrow in the ground." They said to Qatadah: "Why is it disliked to urinate into a burrow in the ground?" He said: "It is said that these are dwelling-places of the jinn', NULL, '7b56f154f54eb912c7c69dada0f7870a21651fcecdbd959e6169051d65538cb5', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (243, 'nasai', 251, 35, 'Book 1, Hadith 35', 35, NULL, NULL, 'أَخْبَرَنَا قُتَيْبَةُ، قَالَ حَدَّثَنَا اللَّيْثُ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرٍ، عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم أَنَّهُ نَهَى عَنِ الْبَوْلِ فِي الْمَاءِ الرَّاكِدِ', '.', '.', 'It was narrated from Jabir that the Messenger of Allah (ﷺ) forbade urinating into standing water', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (244, 'nasai', 251, 36, 'Book 1, Hadith 36', 36, NULL, NULL, 'أَخْبَرَنَا عَلِيُّ بْنُ حُجْرٍ، قَالَ أَنْبَأَنَا ابْنُ الْمُبَارَكِ، عَنْ مَعْمَرٍ، عَنِ الأَشْعَثِ بْنِ عَبْدِ اللَّهِ، عَنِ الْحَسَنِ، عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ لاَ يَبُولَنَّ أَحَدُكُمْ فِي مُسْتَحَمِّهِ فَإِنَّ عَامَّةَ الْوَسْوَاسِ مِنْهُ ‏"‏ ‏.‏', '"‏ لا يبولن احدكم في مستحمه فان عامه الوسواس منه ‏"‏ ‏.‏', 'It was narrated from ''Abdullah bin Mughaffal that the Prophet (ﷺ) said:"None of you should urinate in the place where he bathes, for most Waswas (devilish whispers) [1] come from that." [1] I.e., with regard to whether the urine has soiled his body or not', NULL, '6585c20afd15b907adc06f7f64d4487f49ca0d84f3561a1c5e9553e452dd135c', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (245, 'nasai', 251, 37, 'Book 1, Hadith 37', 37, NULL, NULL, 'أَخْبَرَنَا مَحْمُودُ بْنُ غَيْلاَنَ، حَدَّثَنَا زَيْدُ بْنُ الْحُبَابِ، وَقَبِيصَةُ، قَالاَ أَنْبَأَنَا سُفْيَانُ، عَنِ الضَّحَّاكِ بْنِ عُثْمَانَ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، قَالَ مَرَّ رَجُلٌ عَلَى النَّبِيِّ صلى الله عليه وسلم وَهُوَ يَبُولُ فَسَلَّمَ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيْهِ السَّلاَمَ', '.', '.', 'It was narrated that Ibn ''Umar said:"A man passed by the Prophet (ﷺ) when he was urinating and greeted him with Salam, but he did not return his greeting', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (246, 'nasai', 251, 38, 'Book 1, Hadith 38', 38, NULL, NULL, 'أَخْبَرَنَا مُحَمَّدُ بْنُ بَشَّارٍ، قَالَ حَدَّثَنَا مُعَاذُ بْنُ مُعَاذٍ، قَالَ أَنْبَأَنَا سَعِيدٌ، عَنْ قَتَادَةَ، عَنِ الْحَسَنِ، عَنْ حُضَيْنٍ أَبِي سَاسَانَ، عَنِ الْمُهَاجِرِ بْنِ قُنْفُذٍ، أَنَّهُ سَلَّمَ عَلَى النَّبِيِّ صلى الله عليه وسلم وَهُوَ يَبُولُ فَلَمْ يَرُدَّ عَلَيْهِ السَّلاَمَ حَتَّى تَوَضَّأَ فَلَمَّا تَوَضَّأَ رَدَّ عَلَيْهِ', '.', '.', 'It was narrated from Al-Muhajir bin Qunfudh that he greeted the Prophet (ﷺ) with Salam while he was urinating, and he did not return the greeting until he had performed Wudu''. When he had performed Wudu'' he returned the greeting', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (247, 'nasai', 251, 39, 'Book 1, Hadith 39', 39, NULL, NULL, 'أَخْبَرَنَا أَحْمَدُ بْنُ عَمْرِو بْنِ السَّرْحِ، قَالَ أَنْبَأَنَا ابْنُ وَهْبٍ، قَالَ أَخْبَرَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، عَنْ أَبِي عُثْمَانَ بْنِ سَنَّةَ الْخُزَاعِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم', 'نَهَى أَنْ يَسْتَطِيبَ أَحَدُكُمْ بِعَظْمٍ أَوْ رَوْثٍ ‏.‏', 'نهي ان يستطيب احدكم بعظم او روث ‏.‏', 'It was narrated from ''Abdullah bin Mas''ud, that the Messenger of Allah (ﷺ) forbade cleaning oneself with bones or dung', NULL, '5d7a489c8caa611f32477a5aa53f93a09dc153ccfe66e3318d19ffb2ab827bf7', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (248, 'nasai', 251, 40, 'Book 1, Hadith 40', 40, NULL, NULL, 'أَخْبَرَنَا يَعْقُوبُ بْنُ إِبْرَاهِيمَ، قَالَ حَدَّثَنَا يَحْيَى، - يَعْنِي ابْنَ سَعِيدٍ - عَنْ مُحَمَّدِ بْنِ عَجْلاَنَ، قَالَ أَخْبَرَنِي الْقَعْقَاعُ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏', '"‏ إِنَّمَا أَنَا لَكُمْ مِثْلُ الْوَالِدِ أُعَلِّمُكُمْ إِذَا ذَهَبَ أَحَدُكُمْ إِلَى الْخَلاَءِ فَلاَ يَسْتَقْبِلِ الْقِبْلَةَ وَلاَ يَسْتَدْبِرْهَا وَلاَ يَسْتَنْجِ بِيَمِينِهِ ‏"‏ وَكَانَ يَأْمُرُ بِثَلاَثَةِ أَحْجَارٍ وَنَهَى عَنِ الرَّوْثِ وَالرِّمَّةِ ‏.‏', '"‏ انما انا لكم مثل الوالد اعلمكم اذا ذهب احدكم الي الخلاء فلا يستقبل القبله ولا يستدبرها ولا يستنج بيمينه ‏"‏ وكان يامر بثلاثه احجار ونهي عن الروث والرمه ‏.‏', 'It was narrated from Abu Hurairah that the Prophet (ﷺ) said:"I am like a father teaching you. When any one of you goes to Al-Khala'' (the toilet), let him not face toward the Qiblah nor turn his back toward it, and let him not clean himself with his right hand." And he used to tell them to use three stones, and he forbade using dung or old bones', NULL, '12a879f763bcfba909eb1130b39a3df0b0cf8b2553591ceda333cd964d9e3379', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (249, 'nasai', 251, 41, 'Book 1, Hadith 41', 41, NULL, NULL, 'أَخْبَرَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، قَالَ أَنْبَأَنَا أَبُو مُعَاوِيَةَ، قَالَ حَدَّثَنَا الأَعْمَشُ، عَنْ إِبْرَاهِيمَ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ، عَنْ سَلْمَانَ، قَالَ قَالَ لَهُ رَجُلٌ إِنَّ صَاحِبَكُمْ لَيُعَلِّمُكُمْ حَتَّى الْخِرَاءَةَ', '. قَالَ أَجَلْ نَهَانَا أَنْ نَسْتَقْبِلَ الْقِبْلَةَ بِغَائِطٍ أَوْ بَوْلٍ أَوْ نَسْتَنْجِيَ بِأَيْمَانِنَا أَوْ نَكْتَفِيَ بِأَقَلَّ مِنْ ثَلاَثَةِ أَحْجَارٍ .', '. قال اجل نهانا ان نستقبل القبله بغائط او بول او نستنجي بايماننا او نكتفي باقل من ثلاثه احجار .', 'It was narrated that Salman said, that a man said to him:"Your companion (meaning, the Prophet(ﷺ)) even teaches you how to go to the toilet!" He said: "Yes, he forbade us from facing the Qiblah when defecating or urinating, or cleaning ourselves with out right hands, or to use less than three stones', NULL, 'bec1bd5901aa45f171a240bf97cc2b8130e6b9ddff8d9b0f4ee04d8b254ceb1f', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (250, 'nasai', 251, 42, 'Book 1, Hadith 42', 42, NULL, NULL, 'أَخْبَرَنَا أَحْمَدُ بْنُ سُلَيْمَانَ، قَالَ حَدَّثَنَا أَبُو نُعَيْمٍ، عَنْ زُهَيْرٍ، عَنْ أَبِي إِسْحَاقَ، قَالَ لَيْسَ أَبُو عُبَيْدَةَ ذَكَرَهُ وَلَكِنْ عَبْدُ الرَّحْمَنِ بْنُ الأَسْوَدِ عَنْ أَبِيهِ، أَنَّهُ سَمِعَ عَبْدَ اللَّهِ، يَقُولُ أَتَى النَّبِيُّ صلى الله عليه وسلم الْغَائِطَ وَأَمَرَنِي أَنْ آتِيَهُ بِثَلاَثَةِ أَحْجَارٍ فَوَجَدْتُ حَجَرَيْنِ وَالْتَمَسْتُ الثَّالِثَ فَلَمْ أَجِدْهُ فَأَخَذْتُ رَوْثَةً فَأَتَيْتُ بِهِنَّ النَّبِيَّ صلى الله عليه وسلم فَأَخَذَ الْحَجَرَيْنِ وَأَلْقَى الرَّوْثَةَ وَقَالَ', 'هَذِهِ رِكْسٌ  . قَالَ أَبُو عَبْدِ الرَّحْمَنِ الرِّكْسُ طَعَامُ الْجِنِّ .', 'هذه ركس . قال ابو عبد الرحمن الركس طعام الجن .', 'Abdur-Rahman bin Al-Aswad (narrated) from his father that he heard ''Abdullah say:"The Prophet (ﷺ) wanted to defecate, and he told me to bring him three stones. I found two stones and looked for a third, but I could not find any, so I picked up a piece of dung and brought them to the Prophet (ﷺ). He took the two stones and three away the dung and said: "This is Riks." Abu ''Abdur-Rahman (An-Nasai'') said: Riks is the food of the jinn', NULL, 'f2a8f064dd85f1d8d6594ab083235a30c46c1848833d81cc30bcfcf1f9fdb25b', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published')
INSERT INTO public.hadith_narrations (id, collection_id, book_id, hadith_number, in_book_reference, international_number, chapter_title_arabic, chapter_title_english, sanad_arabic, matn_arabic, matn_clean, translation_english, translation_urdu, text_checksum, source_edition, version_number, is_current, status) VALUES
  (251, 'nasai', 251, 43, 'Book 1, Hadith 43', 43, NULL, NULL, 'أَخْبَرَنَا إِسْحَاقُ بْنُ إِبْرَاَهِيمَ، قَالَ أَنْبَأَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، عَنْ هِلاَلِ بْنِ يِسَافٍ، عَنْ سَلَمَةَ بْنِ قَيْسٍ، عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم قَالَ ‏', '"‏ إِذَا اسْتَجْمَرْتَ فَأَوْتِرْ ‏"‏ ‏.‏', '"‏ اذا استجمرت فاوتر ‏"‏ ‏.‏', 'It was narrated from Salamah bin Qais that the Messenger of Allah (ﷺ) said:"When you clean yourselves (with stones, after defecating), use an odd number', NULL, '5abbcd67495290c71843075b807ce44ee5961967f3c179789430041b8bb3abe0', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (252, 'nasai', 251, 44, 'Book 1, Hadith 44', 44, NULL, NULL, 'أَخْبَرَنَا قُتَيْبَةُ، قَالَ حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ أَبِي حَازِمٍ، عَنْ أَبِيهِ، عَنْ مُسْلِمِ بْنِ قُرْطٍ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏', '"‏ إِذَا ذَهَبَ أَحَدُكُمْ إِلَى الْغَائِطِ فَلْيَذْهَبْ مَعَهُ بِثَلاَثَةِ أَحْجَارٍ فَلْيَسْتَطِبْ بِهَا فَإِنَّهَا تَجْزِي عَنْهُ ‏"‏ ‏.‏', '"‏ اذا ذهب احدكم الي الغائط فليذهب معه بثلاثه احجار فليستطب بها فانها تجزي عنه ‏"‏ ‏.‏', 'It was narrated from ''Aishah that the Messenger of Allah (ﷺ) said:"When any one of you goes to the Gha''it (toilet to defecate), let him take with him three stones and clean himself with them, for that will suffice him', NULL, '742ecd89b5ebff43a79cbf090a93c9d0fe7e43d50ba3f995cd28cc00ea416606', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (253, 'nasai', 251, 45, 'Book 1, Hadith 45', 45, NULL, NULL, 'أَخْبَرَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، قَالَ أَنْبَأَنَا النَّضْرُ، قَالَ أَنْبَأَنَا شُعْبَةُ، عَنْ عَطَاءِ بْنِ أَبِي مَيْمُونَةَ، قَالَ سَمِعْتُ أَنَسَ بْنَ مَالِكٍ، يَقُولُ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِذَا دَخَلَ الْخَلاَءَ أَحْمِلُ أَنَا وَغُلاَمٌ مَعِي نَحْوِي إِدَاوَةً مِنْ مَاءٍ فَيَسْتَنْجِي بِالْمَاءِ', '.', '.', 'Anas bin Malik said:"When the Messenger of Allah (ﷺ) would go to the toilet, I and another boy like me would bring a small leather vessel of water and he would clean himself with water', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (254, 'nasai', 251, 46, 'Book 1, Hadith 46', 46, NULL, NULL, 'أَخْبَرَنَا قُتَيْبَةُ، قَالَ حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ قَتَادَةَ، عَنْ مُعَاذَةَ، عَنْ عَائِشَةَ، أَنَّهَا قَالَتْ مُرْنَ أَزْوَاجَكُنَّ أَنْ يَسْتَطِيبُوا بِالْمَاءِ فَإِنِّي أَسْتَحْيِيهِمْ مِنْهُ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ يَفْعَلُهُ', '.', '.', 'It was narrated that ''Aishah said:"Tell your husbands to clean themselves with water, for I am too shy to tell them myself. The Messenger of Allah (ﷺ) used to do that', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (255, 'nasai', 251, 47, 'Book 1, Hadith 47', 47, NULL, NULL, 'أَخْبَرَنَا إِسْمَاعِيلُ بْنُ مَسْعُودٍ، قَالَ حَدَّثَنَا خَالِدٌ، قَالَ أَنْبَأَنَا هِشَامٌ، عَنْ يَحْيَى، عَنْ عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ، عَنْ أَبِي قَتَادَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏', '"‏ إِذَا شَرِبَ أَحَدُكُمْ فَلاَ يَتَنَفَّسْ فِي إِنَائِهِ وَإِذَا أَتَى الْخَلاَءَ فَلاَ يَمَسَّ ذَكَرَهُ بِيَمِينِهِ وَلاَ يَتَمَسَّحْ بِيَمِينِهِ ‏"‏ ‏.‏', '"‏ اذا شرب احدكم فلا يتنفس في انائه واذا اتي الخلاء فلا يمس ذكره بيمينه ولا يتمسح بيمينه ‏"‏ ‏.‏', 'It was narrated from Abu Qatadah that the Messenger of Allah (ﷺ) said:"When any one of you drinks, let him not breathe into the vessel, and when he goes to the toilet let him not touch his penis with his right hand, nor wipe himself with this right hand', NULL, '646489e8876a21402c8f8f5dd5ca650a9d42d1e49d1c7c70b5e702680f6f232e', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (256, 'nasai', 251, 48, 'Book 1, Hadith 48', 48, NULL, NULL, 'أَخْبَرَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ، قَالَ حَدَّثَنَا عَبْدُ الْوَهَّابِ، عَنْ أَيُّوبَ، عَنْ يَحْيَى بْنِ أَبِي كَثِيرٍ، عَنِ ابْنِ أَبِي قَتَادَةَ، عَنْ أَبِيهِ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'نَهَى أَنْ يَتَنَفَّسَ فِي الإِنَاءِ وَأَنْ يَمَسَّ ذَكَرَهُ بِيَمِينِهِ وَأَنْ يَسْتَطِيبَ بِيَمِينِهِ ‏.‏', 'نهي ان يتنفس في الاناء وان يمس ذكره بيمينه وان يستطيب بيمينه ‏.‏', 'It was narrated from Ibn Abi Qatadah, from his father, that the Prophet (ﷺ) forbade breathing into the vessel (when drinking), touching one''s penis with one''s right hand, and cleaning oneself with one''s right hand', NULL, '9a633f3a6e2f911b266b3b9d5925b7557dc09e81d6c3ac7260b5bc140e53334e', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (257, 'nasai', 251, 49, 'Book 1, Hadith 49', 49, NULL, NULL, 'أَخْبَرَنَا عَمْرُو بْنُ عَلِيٍّ، وَشُعَيْبُ بْنُ يُوسُفَ، وَاللَّفْظُ، لَهُ عَنْ عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ، عَنْ سُفْيَانَ، عَنْ مَنْصُورٍ، وَالأَعْمَشِ، عَنْ إِبْرَاهِيمَ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ، عَنْ سَلْمَانَ، قَالَ قَالَ الْمُشْرِكُونَ إِنَّا لَنَرَى صَاحِبَكُمْ يُعَلِّمُكُمُ الْخِرَاءَةَ', '. قَالَ أَجَلْ نَهَانَا أَنْ يَسْتَنْجِيَ أَحَدُنَا بِيَمِينِهِ وَيَسْتَقْبِلَ الْقِبْلَةَ وَقَالَ   لاَ يَسْتَنْجِي أَحَدُكُمْ بِدُونِ ثَلاَثَةِ أَحْجَارٍ  .', '. قال اجل نهانا ان يستنجي احدنا بيمينه ويستقبل القبله وقال لا يستنجي احدكم بدون ثلاثه احجار .', 'It was narrated that Salman said:"The idolators said: ''We see that your companion teaches you how to go to the toilet.'' He said: ''Yes, he forbade us from cleaning ourselves with our right hand, and from facing toward the Qiblah, and he said: ''None of you should clean with less than three stones', NULL, '049c892d74b54d624793844c7cb8d6b49dc24284f6c8860f4436b06ad090f2cc', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (258, 'nasai', 251, 50, 'Book 1, Hadith 50', 50, NULL, NULL, 'أَخْبَرَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الْمُبَارَكِ الْمُخَرِّمِيُّ، قَالَ حَدَّثَنَا وَكِيعٌ، عَنْ شَرِيكٍ، عَنْ إِبْرَاهِيمَ بْنِ جَرِيرٍ، عَنْ أَبِي زُرْعَةَ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم', 'تَوَضَّأَ فَلَمَّا اسْتَنْجَى دَلَكَ يَدَهُ بِالأَرْضِ ‏.‏', 'توضا فلما استنجي دلك يده بالارض ‏.‏', 'It was narrated from Abu Hurairah that the Prophet (ﷺ) performed Wudu'', and when he had performed Istinja'' he rubbed his hand on the ground', NULL, '1a48bb4436011ba643c04d8190f46de285dd4d5ae97f5461107f036d2b8a7ea8', 'NASAI Darussalam Reference Edition', 1, TRUE, 'published'),
  (259, 'ibnmajah', 302, 1, 'Book 0, Hadith 1', 1, NULL, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ قَالَ: حَدَّثَنَا شَرِيكٌ عَنِ الأَعْمَشِ عَنْ أَبِي صَالِحٍ عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَا أَمَرْتُكُمْ بِهِ فَخُذُوهُ وَمَا نَهَيْتُكُمْ عَنْهُ فَانْتَهُوا»', 'حدثنا ابو بكر بن ابي شيبه قال: حدثنا شريك عن الاعمش عن ابي صالح عن ابي هريره قال: قال رسول الله صلي الله عليه وسلم: «ما امرتكم به فخذوه وما نهيتكم عنه فانتهوا»', 'Abu Hurairah narrated that:The Prophet said: "Whatever I have commanded you do it, and whatever I have forbidden you, refrain from it', NULL, '6d80734cde700caba9e2bd1b606b8e8115b05ac06c8ff625afec58cab2ce9570', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (260, 'ibnmajah', 302, 2, 'Book 0, Hadith 2', 2, NULL, NULL, 'حَدَّثَنَا أَبُو عَبْدِ اللَّهِ، قَالَ حَدَّثَنَا مُحَمَّدُ بْنُ الصَّبَّاحِ، قَالَ أَنْبَأَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ', 'ذَرُونِي مَا تَرَكْتُكُمْ فَإِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِسُؤَالِهِمْ وَاخْتِلاَفِهِمْ عَلَى أَنْبِيَائِهِمْ فَإِذَا أَمَرْتُكُمْ بِشَىْءٍ فَخُذُوا مِنْهُ مَا اسْتَطَعْتُمْ وَإِذَا نَهَيْتُكُمْ عَنْ شَىْءٍ فَانْتَهُوا  .', 'ذروني ما تركتكم فانما هلك من كان قبلكم بسؤالهم واختلافهم علي انبيائهم فاذا امرتكم بشيء فخذوا منه ما استطعتم واذا نهيتكم عن شيء فانتهوا .', 'Abu Hurairah narrated that:The Prophet said: "Leave me as I have left you (Don''t ask me the minor things that I have avoided to tell you). For those who came before you were doomed because of their questions and differences with their Prophets. If I commanded you to do something, then do as much of it as you can, and if I forbid you from doing something, then refrain from it', NULL, '29586c79d370725bdbd957e6ba59c69bc4d9a782c62e7d34ce77c7c3de90393e', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (261, 'ibnmajah', 302, 3, 'Book 0, Hadith 3', 3, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، وَوَكِيعٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ', 'مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ  .', 'من اطاعني فقد اطاع الله ومن عصاني فقد عصي الله .', 'Abu Hurairah narrated that:The Prophet said: "Whoever obeys me, obeys Allah; and whoever disobeys me, disobeys Allah', NULL, '94b9be3a24b43e6cdd5a244107f45f0c9a34f8658a08fe111d4de503e54cd0b6', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (262, 'ibnmajah', 302, 4, 'Book 0, Hadith 4', 4, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ، حَدَّثَنَا زَكَرِيَّا بْنُ عَدِيٍّ، عَنِ ابْنِ الْمُبَارَكِ، عَنْ مُحَمَّدِ بْنِ سُوقَةَ، عَنْ أَبِي جَعْفَرٍ، قَالَ كَانَ ابْنُ عُمَرَ إِذَا سَمِعَ مِنْ، رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ حَدِيثًا لَمْ يَعْدُهُ وَلَمْ يُقَصِّرْ دُونَهُ', '.', '.', 'Abu Ja''far said:"Whenever Ibn ''Umar heard a Hadith from the Messanger of Allah (ﷺ), he would not do more than it said, and he would not do less', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (263, 'ibnmajah', 302, 5, 'Book 0, Hadith 5', 5, NULL, NULL, 'حَدَّثَنَا هِشَامُ بْنُ عَمَّارٍ الدِّمَشْقِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ عِيسَى بْنِ سُمَيْعٍ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ سُلَيْمَانَ الأَفْطَسُ، عَنِ الْوَلِيدِ بْنِ عَبْدِ الرَّحْمَنِ الْجُرَشِيِّ، عَنْ جُبَيْرِ بْنِ نُفَيْرٍ، عَنْ أَبِي الدَّرْدَاءِ، قَالَ خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ وَنَحْنُ نَذْكُرُ الْفَقْرَ وَنَتَخَوَّفُهُ فَقَالَ', 'آلْفَقْرَ تَخَافُونَ وَالَّذِي نَفْسِي بِيَدِهِ لَتُصَبَّنَّ عَلَيْكُمُ الدُّنْيَا صَبًّا حَتَّى لاَ يُزِيغَ قَلْبَ أَحَدٍ مِنْكُمْ إِزَاغَةً إِلاَّ هِيَهْ وَايْمُ اللَّهِ لَقَدْ تَرَكْتُكُمْ عَلَى مِثْلِ الْبَيْضَاءِ لَيْلُهَا وَنَهَارُهَا سَوَاءٌ  . قَالَ أَبُو الدَّرْدَاءِ صَدَقَ وَاللَّهِ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ تَرَكَنَا وَاللَّهِ عَلَى مِثْلِ الْبَيْضَاءِ لَيْلُهَا وَنَهَارُهَا سَوَاءٌ .', 'الفقر تخافون والذي نفسي بيده لتصبن عليكم الدنيا صبا حتي لا يزيغ قلب احد منكم ازاغه الا هيه وايم الله لقد تركتكم علي مثل البيضاء ليلها ونهارها سواء . قال ابو الدرداء صدق والله رسول الله صلي الله عليه وسلم تركنا والله علي مثل البيضاء ليلها ونهارها سواء .', 'Abu Darda'' said:"The Messenger of Allah (ﷺ) came out to us when we were speaking of poverty and how we feared it. He said: ''Is it poverty that you fear? By the One in Whose Hand is my soul, (the delights and luxuries of) this world will come to you in plenty, and nothing will cause the heart of anyone of you to deviate except that. By Allah, I am leaving you upon something like Bayda (white, bright, clear path) the night and day of which are the same', NULL, '11eaf4ad047d0935cbc424e29a260a7008f77e602f9e979afc0fca5d40f946b5', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (264, 'ibnmajah', 302, 6, 'Book 0, Hadith 6', 6, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، حَدَّثَنَا شُعْبَةُ، عَنْ مُعَاوِيَةَ بْنِ قُرَّةَ، عَنْ أَبِيهِ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ', 'لاَ تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي مَنْصُورِينَ لاَ يَضُرُّهُمْ مَنْ خَذَلَهُمْ حَتَّى تَقُومَ السَّاعَةُ  .', 'لا تزال طائفه من امتي منصورين لا يضرهم من خذلهم حتي تقوم الساعه .', 'Mu''awiyah bin Qurrah narrated that his father said:The Messenger of Allah (ﷺ) said: "A group of my Ummah will continue to prevail and they will never be harmed by those who forsake them, until the Hour begins', NULL, '85e9dae22673a424588dcaa4e694187eacd410bc24090d4cc1c73fa582a823d8', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (265, 'ibnmajah', 302, 7, 'Book 0, Hadith 7', 7, NULL, NULL, 'حَدَّثَنَا أَبُو عَبْدِ اللَّهِ، قَالَ حَدَّثَنَا هِشَامُ بْنُ عَمَّارٍ، قَالَ حَدَّثَنَا يَحْيَى بْنُ حَمْزَةَ، قَالَ حَدَّثَنَا أَبُو عَلْقَمَةَ، نَصْرُ بْنُ عَلْقَمَةَ عَنْ عُمَيْرِ بْنِ الأَسْوَدِ، وَكَثِيرِ بْنِ مُرَّةَ الْحَضْرَمِيِّ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ قَالَ', 'لاَ تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي قَوَّامَةً عَلَى أَمْرِ اللَّهِ لاَ يَضُرُّهَا مَنْ خَالَفَهَا  .', 'لا تزال طائفه من امتي قوامه علي امر الله لا يضرها من خالفها .', 'Abu Hurairah narrated that:The Messenger of Allah (ﷺ) said: "A group of my Ummah will continue to adhere steadfastly to the command of Allah and those who oppose them will not be able to harm them', NULL, '73c00aef95a0418efa733534703c81ca5183afbdb59d11472e7703ebbf2dbd8b', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (266, 'ibnmajah', 302, 8, 'Book 0, Hadith 8', 8, NULL, NULL, 'حَدَّثَنَا أَبُو عَبْدِ اللَّهِ، قَالَ حَدَّثَنَا هِشَامُ بْنُ عَمَّارٍ، حَدَّثَنَا الْجَرَّاحُ بْنُ مَلِيحٍ، حَدَّثَنَا بَكْرُ بْنُ زُرْعَةَ، قَالَ سَمِعْتُ أَبَا عِنَبَةَ الْخَوْلاَنِيَّ، وَكَانَ، قَدْ صَلَّى الْقِبْلَتَيْنِ مَعَ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ يَقُولُ', 'لاَ يَزَالُ اللَّهُ يَغْرِسُ فِي هَذَا الدِّينِ غَرْسًا يَسْتَعْمِلُهُمْ فِي طَاعَتِهِ  .', 'لا يزال الله يغرس في هذا الدين غرسا يستعملهم في طاعته .', 'Abu ''Inabah Al-Khawlani said that:The Messenger of Allah (ﷺ) said: "Allah will continue to plant new people in this religion and use them in His obedience', NULL, 'c5cabc80e5ae7faf37e3190de4c9508a2fb553c78b5fa1ed782f385d82ce114a', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (267, 'ibnmajah', 302, 9, 'Book 0, Hadith 9', 9, NULL, NULL, 'حَدَّثَنَا يَعْقُوبُ بْنُ حُمَيْدِ بْنِ كَاسِبٍ، حَدَّثَنَا الْقَاسِمُ بْنُ نَافِعٍ، حَدَّثَنَا الْحَجَّاجُ بْنُ أَرْطَاةَ، عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، قَالَ قَامَ مُعَاوِيَةُ خَطِيبًا فَقَالَ أَيْنَ عُلَمَاؤُكُمْ أَيْنَ عُلَمَاؤُكُمْ سَمِعْتُ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ يَقُولُ', 'لاَ تَقُومُ السَّاعَةُ إِلاَّ وَطَائِفَةٌ مِنْ أُمَّتِي ظَاهِرُونَ عَلَى النَّاسِ لاَ يُبَالُونَ مَنْ خَذَلَهُمْ وَلاَ مَنْ نَصَرَهُمْ  .', 'لا تقوم الساعه الا وطائفه من امتي ظاهرون علي الناس لا يبالون من خذلهم ولا من نصرهم .', 'Amr bin Shu''aib narrated that:His father said: "Mu''awiyah stood up to deliver a sermon and said: ''Where are your scholars? Where are your scholars? For I heard the Messenger of Allah (ﷺ) say: The Hour will not begin until a group of my Ummah will prevail over the people, and they will not care who lets them down and who supports them', NULL, '0ca771dc8d0238fb3c2ccc6cf51d1d18f336564ded5ffb1550c16f6ec6d40694', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (268, 'ibnmajah', 302, 10, 'Book 0, Hadith 10', 10, NULL, NULL, 'حَدَّثَنَا هِشَامُ بْنُ عَمَّارٍ، حَدَّثَنَا مُحَمَّدُ بْنُ شُعَيْبٍ، حَدَّثَنَا سَعِيدُ بْنُ بَشِيرٍ، عَنْ قَتَادَةَ، عَنْ أَبِي قِلاَبَةَ، عَنْ أَبِي أَسْمَاءَ الرَّحَبِيِّ، عَنْ ثَوْبَانَ، أَنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ قَالَ', 'لاَ يَزَالُ طَائِفَةٌ مِنْ أُمَّتِي عَلَى الْحَقِّ مَنْصُورِينَ لاَ يَضُرُّهُمْ مَنْ خَالَفَهُمْ حَتَّى يَأْتِيَ أَمْرُ اللَّهِ عَزَّ وَجَلَّ  .', 'لا يزال طائفه من امتي علي الحق منصورين لا يضرهم من خالفهم حتي ياتي امر الله عز وجل .', 'It was narrated from Thawban that:The Messenger of Allah (ﷺ) said: "A group among my Ummah will continue to follow the truth and prevail, and those who oppose them will not be able to harm them, until the command of Allah comes to pass', NULL, '1fae09a25b1476c737c3d97602254afbc93542ede1b312581703eac2566396b3', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (269, 'ibnmajah', 302, 11, 'Book 0, Hadith 11', 11, NULL, NULL, 'حَدَّثَنَا أَبُو سَعِيدٍ عَبْدُ اللَّهِ بْنُ سَعِيدٍ، حَدَّثَنَا أَبُو خَالِدٍ الأَحْمَرُ، قَالَ سَمِعْتُ مُجَالِدًا، يَذْكُرُ عَنِ الشَّعْبِيِّ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ كُنَّا عِنْدَ النَّبِيِّ ـ صلى الله عليه وسلم ـ فَخَطَّ خَطًّا وَخَطَّ خَطَّيْنِ عَنْ يَمِينِهِ وَخَطَّ خَطَّيْنِ عَنْ يَسَارِهِ ثُمَّ وَضَعَ يَدَهُ فِي الْخَطِّ الأَوْسَطِ فَقَالَ', 'هَذَا سَبِيلُ اللَّهِ  . ثُمَّ تَلاَ هَذِهِ الآيَةَ {وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ وَلاَ تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَنْ سَبِيلِهِ} .', 'هذا سبيل الله . ثم تلا هذه الايه {وان هذا صراطي مستقيما فاتبعوه ولا تتبعوا السبل فتفرق بكم عن سبيله} .', 'Jabir bin ''Abdullah said that:We were with the Prophet (ﷺ), and he drew a line (in the sand), then he drew two lines to its right and two to its left. Then he put his hand on the middle line and said : ''This is the path of Allah. Then he recited the Verse: And verily, this (i.e. Allah''s Commandments) is My straight path, so follow it and follow not (other) paths, for they will separate you from His path', NULL, 'b63a9a94c2ac8904c219ee42e34b91a2258dc723f53dc88e4e759bbc409d3c7e', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (270, 'ibnmajah', 302, 12, 'Book 0, Hadith 12', 12, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا زَيْدُ بْنُ الْحُبَابِ، عَنْ مُعَاوِيَةَ بْنِ صَالِحٍ، حَدَّثَنِي الْحَسَنُ بْنُ جَابِرٍ، عَنِ الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ الْكِنْدِيِّ، أَنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ قَالَ', 'يُوشِكُ الرَّجُلُ مُتَّكِئًا عَلَى أَرِيكَتِهِ يُحَدَّثُ بِحَدِيثٍ مِنْ حَدِيثِي فَيَقُولُ بَيْنَنَا وَبَيْنَكُمْ كِتَابُ اللَّهِ عَزَّ وَجَلَّ فَمَا وَجَدْنَا فِيهِ مِنْ حَلاَلٍ اسْتَحْلَلْنَاهُ وَمَا وَجَدْنَا فِيهِ مِنْ حَرَامٍ حَرَّمْنَاهُ . أَلاَ وَإِنَّ مَا حَرَّمَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ مِثْلُ مَا حَرَّمَ اللَّهُ  .', 'يوشك الرجل متكئا علي اريكته يحدث بحديث من حديثي فيقول بيننا وبينكم كتاب الله عز وجل فما وجدنا فيه من حلال استحللناه وما وجدنا فيه من حرام حرمناه . الا وان ما حرم رسول الله صلي الله عليه وسلم مثل ما حرم الله .', 'Miqdam bin Ma''dikarib Al-Kindi narrated that:The Messenger of Allah (ﷺ) said: "Soon there will come a time that a man will be reclining on his pillow, and when one of my Ahadith is narrated he will say: ''The Book of Allah is (sufficient) between us and you. Whatever it states is permissible, we will take as permissible, and whatever it states is forbidden, we will take as forbidden.'' Verily, whatever the Messenger of Allah (ﷺ) has forbidden is like that which Allah has forbidden', NULL, '7d2431f31a04886674c2d5be3d93f32ec4a8e6f98931f1503025652a24c2b089', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (271, 'ibnmajah', 302, 13, 'Book 0, Hadith 13', 13, NULL, NULL, 'حَدَّثَنَا نَصْرُ بْنُ عَلِيٍّ الْجَهْضَمِيُّ، حَدَّثَنَا سُفْيَانُ بْنُ عُيَيْنَةَ، فِي بَيْتِهِ أَنَا سَأَلْتُهُ، عَنْ سَالِمٍ أَبِي النَّضْرِ، ثُمَّ مَرَّ فِي الْحَدِيثِ قَالَ أَوْ زَيْدِ بْنِ أَسْلَمَ عَنْ عُبَيْدِ اللَّهِ بْنِ أَبِي رَافِعٍ عَنْ أَبِيهِ أَنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ قَالَ', 'لاَ أُلْفِيَنَّ أَحَدَكُمْ مُتَّكِئًا عَلَى أَرِيكَتِهِ يَأْتِيهِ الأَمْرُ مِمَّا أَمَرْتُ بِهِ أَوْ نَهَيْتُ عَنْهُ فَيَقُولُ لاَ أَدْرِي مَا وَجَدْنَا فِي كِتَابِ اللَّهِ اتَّبَعْنَاهُ  .', 'لا الفين احدكم متكئا علي اريكته ياتيه الامر مما امرت به او نهيت عنه فيقول لا ادري ما وجدنا في كتاب الله اتبعناه .', 'It was narrated from Ubaidullah bin Abu Rafi from his father, that:The Messenger of Allah (ﷺ) said: "I do not want to find anyone of you reclining on his pillow, and when bad news comes to him of something that I have commanded or forbidden, he says, ''I do not know, whatever we find in the Book of Allah, we will follow', NULL, 'f80b5b7bd8268d43d11552c76d7794931a6b2d71d7c7a4049ddac39195e80faa', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (272, 'ibnmajah', 302, 14, 'Book 0, Hadith 14', 14, NULL, NULL, 'حَدَّثَنَا أَبُو مَرْوَانَ، مُحَمَّدُ بْنُ عُثْمَانَ الْعُثْمَانِيُّ حَدَّثَنَا إِبْرَاهِيمُ بْنُ سَعْدِ بْنِ إِبْرَاهِيمَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ، عَنْ أَبِيهِ، عَنِ الْقَاسِمِ بْنِ مُحَمَّدٍ، عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ قَالَ', 'مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ مِنْهُ فَهُوَ رَدٌّ  .', 'من احدث في امرنا هذا ما ليس منه فهو رد .', 'Aishah narrated that:The Messenger of Allah (ﷺ) said: "Whoever innovates something in this matter of ours (i.e. Islam) that is not part of it, will have it rejected', NULL, '67806fb7afcac406bf8b1522a57e43dded5304fa173fffe84a5faa364955d2ba', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (273, 'ibnmajah', 302, 15, 'Book 0, Hadith 15', 15, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ رُمْحِ بْنِ الْمُهَاجِرِ الْمِصْرِيُّ، أَنْبَأَنَا اللَّيْثُ بْنُ سَعْدٍ، عَنِ ابْنِ شِهَابٍ، عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ، أَنَّ عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ، حَدَّثَهُ أَنَّ رَجُلاً مِنَ الأَنْصَارِ خَاصَمَ الزُّبَيْرَ عِنْدَ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ فِي شِرَاجِ الْحَرَّةِ الَّتِي يَسْقُونَ بِهَا النَّخْلَ فَقَالَ الأَنْصَارِيُّ سَرِّحِ الْمَاءَ يَمُرُّ', '. فَأَبَى عَلَيْهِ فَاخْتَصَمَا عِنْدَ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ فَقَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ  اسْقِ يَا زُبَيْرُ ثُمَّ أَرْسِلِ الْمَاءَ إِلَى جَارِكَ  . فَغَضِبَ الأَنْصَارِيُّ فَقَالَ يَا رَسُولَ اللَّهِ أَنْ كَانَ ابْنَ عَمَّتِكَ فَتَلَوَّنَ وَجْهُ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ ثُمَّ قَالَ  يَا زُبَيْرُ اسْقِ ثُمَّ احْبِسِ الْمَاءَ حَتَّى يَرْجِعَ إِلَى الْجَدْرِ  . قَالَ فَقَالَ الزُّبَيْرُ وَاللَّهِ إِنِّي لأَحْسَبُ هَذِهِ الآيَةَ نَزَلَتْ فِي ذَلِكَ {فَلاَ وَرَبِّكَ لاَ يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لاَ يَجِدُوا فِي أَنْفُسِهِمْ حَرَجًا مِمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْلِيمًا} .', '. فابي عليه فاختصما عند رسول الله صلي الله عليه وسلم فقال رسول الله صلي الله عليه وسلم اسق يا زبير ثم ارسل الماء الي جارك . فغضب الانصاري فقال يا رسول الله ان كان ابن عمتك فتلون وجه رسول الله صلي الله عليه وسلم ثم قال يا زبير اسق ثم احبس الماء حتي يرجع الي الجدر . قال فقال الزبير والله اني لاحسب هذه الايه نزلت في ذلك {فلا وربك لا يؤمنون حتي يحكموك فيما شجر بينهم ثم لا يجدوا في انفسهم حرجا مما قضيت ويسلموا تسليما} .', 'It was narrated from Urwah bin Zubair that ''Abdullah bin Zubair told him that:A man from the Ansar had a dispute with Zubair in the presence of the Messenger of Allah (ﷺ) concerning a stream in the Harrah which they used to irrigate the date-palm trees. The Ansari said: "Let the water flow" but Zubair refused. So they referred that dispute to the Messenger of Allah (ﷺ) who said: "Irrigate (your land), O Zubair., and then let the water flow to your neighbor." The Ansari became angry and said "O Messenger of Allah, is it because he is your cousin?" The face of the Messenger of Allah (ﷺ) changed color (because of anger) and he said: "O Zubair, irrigate (your land) then block the water until it flows back to the walls around the date-palm trees." Zubair said: "By Allah, I think that this verse was revealed concerning this matter. '' But no, by your Lord, they can have no Faith, until they make you (O Muhammad) judge in all disputes between them, and find in themselves no resistance against your decisions, and accept (them) with full submission', NULL, '4fb6d458e258c4dae9575621ec014acd16fe1d9d25438592960646d0b0c3a9fe', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (274, 'ibnmajah', 302, 16, 'Book 0, Hadith 16', 16, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى النَّيْسَابُورِيُّ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَنْبَأَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنْ سَالِمٍ، عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ قَالَ', 'لاَ تَمْنَعُوا إِمَاءَ اللَّهِ أَنْ يُصَلِّينَ فِي الْمَسْجِدِ  . فَقَالَ ابْنٌ لَهُ إِنَّا لَنَمْنَعُهُنَّ . فَقَالَ فَغَضِبَ غَضَبًا شَدِيدًا وَقَالَ إِنِّي أُحَدِّثُكَ عَنْ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ وَإِنَّكَ تَقُولُ إِنَّا لَنَمْنَعُهُنَّ .', 'لا تمنعوا اماء الله ان يصلين في المسجد . فقال ابن له انا لنمنعهن . فقال فغضب غضبا شديدا وقال اني احدثك عن رسول الله صلي الله عليه وسلم وانك تقول انا لنمنعهن .', 'It was narrated from Ibn Umar that:The Messenger of Allah (ﷺ) said:" Do not prevent the female slaves of Allah from praying in the mosque." A son of his said: We will indeed prevent them!" He got very angry and said: "I tell you a Hadith from the Messenger of Allah (ﷺ) and you say, we will indeed prevent them?', NULL, '5bed7752c4e888cf5e2f1d6fa64a7b46e5c8da085c6078717ea7dafb6c7eeb36', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (275, 'ibnmajah', 302, 17, 'Book 0, Hadith 17', 17, NULL, NULL, 'حَدَّثَنَا أَحْمَدُ بْنُ ثَابِتٍ الْجَحْدَرِيُّ، وَأَبُو عُمَرَ حَفْصُ بْنُ عَمْرٍو قَالاَ حَدَّثَنَا عَبْدُ الْوَهَّابِ الثَّقَفِيُّ، حَدَّثَنَا أَيُّوبُ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ، أَنَّهُ كَانَ جَالِسًا إِلَى جَنْبِهِ ابْنُ أَخٍ لَهُ فَخَذَفَ فَنَهَاهُ وَقَالَ إِنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ نَهَى عَنْهَا وَقَالَ', 'إِنَّهَا لاَ تَصِيدُ صَيْدًا وَلاَ تَنْكِي عَدُوًّا وَإِنَّهَا تَكْسِرُ السِّنَّ وَتَفْقَأُ الْعَيْنَ  . قَالَ فَعَادَ ابْنُ أَخِيهِ يَخْذِفُ فَقَالَ أُحَدِّثُكَ أَنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ نَهَى عَنْهَا ثُمَّ عُدْتَ تَخْذِفُ لاَ أُكَلِّمُكَ أَبَدًا .', 'انها لا تصيد صيدا ولا تنكي عدوا وانها تكسر السن وتفقا العين . قال فعاد ابن اخيه يخذف فقال احدثك ان رسول الله صلي الله عليه وسلم نهي عنها ثم عدت تخذف لا اكلمك ابدا .', 'It was narrated from Sa''eed bin Jubair that :Abdullah bin Mughaffal was sitting beside a nephew of his, the nephew hurled a pebble and he told him not to do that, and he said: "The Messenger of Allah (ﷺ) had forbidden that. He (the Prophet) said: ''It cannot be used for hunting and it cannot harm an enemy, but it may break a tooth or put an eye out." He said." His nephew hurled another pebble and he ("Abdullah bin Mughaffal) said: ''I tell you that the Messenger of Allah forbade that (and you go hurl another pebble)? I will never speak to you again', NULL, '51df777d0d6c88e9b525f2ae9dbbfc4acacd7e738966e8c993d1528226f15ae0', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (276, 'ibnmajah', 302, 18, 'Book 0, Hadith 18', 18, NULL, NULL, 'حَدَّثَنَا هِشَامُ بْنُ عَمَّارٍ، حَدَّثَنَا يَحْيَى بْنُ حَمْزَةَ، حَدَّثَنِي بُرْدُ بْنُ سِنَانٍ، عَنْ إِسْحَاقَ بْنِ قَبِيصَةَ، عَنْ أَبِيهِ، أَنَّ عُبَادَةَ بْنَ الصَّامِتِ الأَنْصَارِيَّ النَّقِيبَ، صَاحِبَ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ غَزَا مَعَ مُعَاوِيَةَ أَرْضَ الرُّومِ فَنَظَرَ إِلَى النَّاسِ وَهُمْ يَتَبَايَعُونَ كِسَرَ الذَّهَبِ بِالدَّنَانِيرِ وَكِسَرَ الْفِضَّةِ بِالدَّرَاهِمِ فَقَالَ يَا أَيُّهَا النَّاسُ إِنَّكُمْ تَأْكُلُونَ الرِّبَا سَمِعْتُ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ يَقُولُ', 'لاَ تَبْتَاعُوا الذَّهَبَ بِالذَّهَبِ إِلاَّ مِثْلاً بِمِثْلٍ لاَ زِيَادَةَ بَيْنَهُمَا وَلاَ نَظِرَةَ  . فَقَالَ لَهُ مُعَاوِيَةُ يَا أَبَا الْوَلِيدِ لاَ أَرَى الرِّبَا فِي هَذَا إِلاَّ مَا كَانَ مِنْ نَظِرَةٍ . فَقَالَ عُبَادَةُ أُحَدِّثُكَ عَنْ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ وَتُحَدِّثُنِي عَنْ رَأْيِكَ لَئِنْ أَخْرَجَنِي اللَّهُ لاَ أُسَاكِنْكَ بِأَرْضٍ لَكَ عَلَىَّ فِيهَا إِمْرَةٌ . فَلَمَّا قَفَلَ لَحِقَ بِالْمَدِينَةِ فَقَالَ لَهُ عُمَرُ بْنُ الْخَطَّابِ مَا أَقْدَمَكَ يَا أَبَا الْوَلِيدِ فَقَصَّ عَلَيْهِ الْقِصَّةَ وَمَا قَالَ مِنْ مُسَاكَنَتِهِ فَقَالَ ارْجِعْ يَا أَبَا الْوَلِيدِ إِلَى أَرْضِكَ فَقَبَحَ اللَّهُ أَرْضًا لَسْتَ فِيهَا وَأَمْثَالُكَ . وَكَتَبَ إِلَى مُعَاوِيَةَ لاَ إِمْرَةَ لَكَ عَلَيْهِ وَاحْمِلِ النَّاسَ عَلَى مَا قَالَ فَإِنَّهُ هُوَ الأَمْرُ .', 'لا تبتاعوا الذهب بالذهب الا مثلا بمثل لا زياده بينهما ولا نظره . فقال له معاويه يا ابا الوليد لا اري الربا في هذا الا ما كان من نظره . فقال عباده احدثك عن رسول الله صلي الله عليه وسلم وتحدثني عن رايك لئن اخرجني الله لا اساكنك بارض لك علي فيها امره . فلما قفل لحق بالمدينه فقال له عمر بن الخطاب ما اقدمك يا ابا الوليد فقص عليه القصه وما قال من مساكنته فقال ارجع يا ابا الوليد الي ارضك فقبح الله ارضا لست فيها وامثالك . وكتب الي معاويه لا امره لك عليه واحمل الناس علي ما قال فانه هو الامر .', 'It was narrated from Ishaq bin Qabisah from his father that :Ubadah bin Samit Al-Ansari, head of the army unit, the Companion of the Messenger of Allah (ﷺ), went on a military campaign with Mu''awiyah in the land of the Byzantines. He saw people trading pieces of gold for Dinar and pieces of silver for Dirham. He said: "O people, you are consuming Riba (usury)! For I heard the Messenger of Allah (ﷺ) say: ''Do not sell gold for gold unless it is like for like; there should be no increase and no delay (between the two transactions).''" Mu''awiyah said to him: "O Abu Walid, I do not think there is any Riba involved in this , except in cases where there is a delay." ''Ubadah said to him: "I tell you a Hadith from the Messenger of Allah (ﷺ) and you tell me your opinion! If Allah brings me back safely I will never live in a land in which you have authority over me." When he returned, he stayed in Al-Madinah, and ''Umar bin Khattab said to him: "What brought you here, O Abu Walid?" So he told him the story, and what he had said about not living in the same land as Mu''awiyah. ''Umar said: "Go back to your land, O Abu Walid, for what a bad land is the land from where you and people like you are absent." Then he wrote to Mu''awiyah and said: "You have no authority over him; make the people follow what he says , for he is right', NULL, '791e426da8246081794316b43f2a5a2894a751c1272d90ab02ac52abdcb267a8', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (277, 'ibnmajah', 302, 19, 'Book 0, Hadith 19', 19, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ الْخَلاَّدِ الْبَاهِلِيُّ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، عَنْ شُعْبَةَ، عَنِ ابْنِ عَجْلاَنَ، أَنْبَأَنَا عَوْنُ بْنُ عَبْدِ اللَّهِ، عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ إِذَا حَدَّثْتُكُمْ عَنْ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ فَظُنُّوا بِرَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ الَّذِي هُوَ أَهْنَاهُ وَأَهْدَاهُ وَأَتْقَاهُ', '.', '.', 'Abdullah bin Mas''ud said:"When I tell you of a Hadith from the Messenger of Alllah (ﷺ), then think of the Messenger of Allah (ﷺ) as being the best, the utmost rightly guided and the one with the utmost Taqwa (piety, righteousness)', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (278, 'ibnmajah', 302, 20, 'Book 0, Hadith 20', 20, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، عَنْ شُعْبَةَ، عَنْ عَمْرِو بْنِ مُرَّةَ، عَنْ أَبِي الْبَخْتَرِيِّ، عَنْ أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ، عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، قَالَ إِذَا حَدَّثْتُكُمْ عَنْ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ بِحَدِيثٍ فَظُنُّوا بِهِ الَّذِي هُوَ أَهْنَاهُ وَأَهْدَاهُ وَأَتْقَاهُ', '.', '.', 'It was narrated that Ali bin Abu Talib said :"When I narrate a Hadith from the Messenger of Allah (ﷺ), to you, then think of him as being the best, the most rightly guided and the one with the utmost Taqwa (piety, righteousness)', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (279, 'ibnmajah', 302, 21, 'Book 0, Hadith 21', 21, NULL, NULL, 'حَدَّثَنَا عَلِيُّ بْنُ الْمُنْذِرِ، حَدَّثَنَا مُحَمَّدُ بْنُ الْفُضَيْلِ، حَدَّثَنَا الْمَقْبُرِيُّ، عَنْ جَدِّهِ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ ـ صلى الله عليه وسلم ـ أَنَّهُ قَالَ', 'لاَ أَعْرِفَنَّ مَا يُحَدَّثُ أَحَدُكُمْ عَنِّي الْحَدِيثَ وَهُوَ مُتَّكِئٌ عَلَى أَرِيكَتِهِ فَيَقُولُ اقْرَأْ قُرْآنًا . مَا قِيلَ مِنْ قَوْلٍ حَسَنٍ فَأَنَا قُلْتُهُ  .', 'لا اعرفن ما يحدث احدكم عني الحديث وهو متكئ علي اريكته فيقول اقرا قرانا . ما قيل من قول حسن فانا قلته .', 'It was narrated from Abu Hurairah that :The Prophet said "I do not want to hear of anyone of you who, upon hearing a Hadith narrated from me, says while reclining on his pillow: ''Recite Qur''an (to verify this Hadith).'' (Here the Propher SAW said) Any excellent word that is said, it is I who have said it." [How can you reject what I have said?]', NULL, 'd9e070a5f51bcf238dd77d038aecbff13a49fde0508117d47d5e46b8109d70ab', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (280, 'ibnmajah', 302, 22, 'Book 0, Hadith 22', 22, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ عَبَّادِ بْنِ آدَمَ، حَدَّثَنَا أَبِي، عَنْ شُعْبَةَ، عَنْ مُحَمَّدِ بْنِ عَمْرٍو، عَنْ أَبِي سَلَمَةَ، عَنْ أَبِي هُرَيْرَةَ، ح وَحَدَّثَنَا هَنَّادُ بْنُ السَّرِيِّ، حَدَّثَنَا عَبْدَةُ بْنُ سُلَيْمَانَ، حَدَّثَنَا مُحَمَّدُ بْنُ عَمْرٍو، عَنْ أَبِي سَلَمَةَ، أَنَّ أَبَا هُرَيْرَةَ، قَالَ لِرَجُلٍ يَا ابْنَ أَخِي إِذَا حَدَّثْتُكَ عَنْ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ حَدِيثًا فَلاَ تَضْرِبْ لَهُ الأَمْثَالَ', '. قَالَ أَبُو الْحَسَنِ حَدَّثَنَا يَحْيَى بْنُ عَبْدِ اللَّهِ الْكَرَابِيسِيُّ، حَدَّثَنَا عَلِيُّ بْنُ الْجَعْدِ، عَنْ شُعْبَةَ، عَنْ عَمْرِو بْنِ مُرَّةَ، مِثْلَ حَدِيثِ عَلِيٍّ رضى الله تعالى عنه .', '. قال ابو الحسن حدثنا يحيي بن عبد الله الكرابيسي، حدثنا علي بن الجعد، عن شعبه، عن عمرو بن مره، مثل حديث علي رضي الله تعالي عنه .', 'It was narrated from Abu Salamah that :Abu Hurairah said to a man "O son of my brother, when I narrate a Hadith of the Messenger of Allah (ﷺ), to you, then do not try to make any examples for it', NULL, 'aa71690a0032118b7a86eb057bb0a1255fb41ed62e771acb9968b281e7724f74', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (281, 'ibnmajah', 302, 23, 'Book 0, Hadith 23', 23, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا مُعَاذُ بْنُ مُعَاذٍ، عَنِ ابْنِ عَوْنٍ، حَدَّثَنَا مُسْلِمٌ الْبَطِينُ، عَنْ إِبْرَاهِيمَ التَّيْمِيِّ، عَنْ أَبِيهِ، عَنْ عَمْرِو بْنِ مَيْمُونٍ، قَالَ مَا أَخْطَأَنِي ابْنُ مَسْعُودٍ عَشِيَّةَ خَمِيسٍ إِلاَّ أَتَيْتُهُ فِيهِ قَالَ فَمَا سَمِعْتُهُ يَقُولُ لِشَىْءٍ قَطُّ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ فَلَمَّا كَانَ ذَاتَ عَشِيَّةٍ قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ - قَالَ فَنَكَسَ', '. قَالَ فَنَظَرْتُ إِلَيْهِ فَهُوَ قَائِمٌ مُحَلَّلَةً أَزْرَارُ قَمِيصِهِ قَدِ اغْرَوْرَقَتْ عَيْنَاهُ وَانْتَفَخَتْ أَوْدَاجُهُ قَالَ أَوْ دُونَ ذَلِكَ أَوْ فَوْقَ ذَلِكَ أَوْ قَرِيبًا مِنْ ذَلِكَ أَوْ شَبِيهًا بِذَلِكَ .', '. قال فنظرت اليه فهو قائم محلله ازرار قميصه قد اغرورقت عيناه وانتفخت اوداجه قال او دون ذلك او فوق ذلك او قريبا من ذلك او شبيها بذلك .', 'Amr bin Maimun said :"I used to visit Ibn Mas''ud every Thursday afternoon but he never uttered the words: ''The Messenger of Allah (ﷺ) said.'' Then one evening, he said: ''The Messenger of Allah (ﷺ) said,'' then he let his head hang down." He said: "I looked at him and saw his shirt was unfastened; his eyes were filled with tears, and his veins were bulging out (with fear). He said:'' Or more than that, or less than that, or close to that or something similar', NULL, 'ac495da487738bcb164ecdecd16aa7443181e9f75420b44a7f8992d47ff8a583', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (282, 'ibnmajah', 302, 24, 'Book 0, Hadith 24', 24, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا مُعَاذُ بْنُ مُعَاذٍ، عَنِ ابْنِ عَوْنٍ، عَنْ مُحَمَّدِ بْنِ سِيرِينَ، قَالَ كَانَ أَنَسُ بْنُ مَالِكٍ إِذَا حَدَّثَ عَنْ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ حَدِيثًا فَفَرَغَ مِنْهُ قَالَ أَوْ كَمَا قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ', '.', '.', 'Muhammad bin Sirin said :"Whenever Anas bin Malik finished narrating a Hadith from the Messenger of Allah (ﷺ), he would say, ''Or as the Messenger of Allah (ﷺ) said', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (283, 'ibnmajah', 302, 25, 'Book 0, Hadith 25', 25, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا غُنْدَرٌ، عَنْ شُعْبَةَ، ح وَحَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ، حَدَّثَنَا شُعْبَةُ، عَنْ عَمْرِو بْنِ مُرَّةَ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى، قَالَ قُلْنَا لِزَيْدِ بْنِ أَرْقَمَ حَدِّثْنَا عَنْ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ', '. قَالَ كَبِرْنَا وَنَسِينَا وَالْحَدِيثُ عَنْ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ شَدِيدٌ .', '. قال كبرنا ونسينا والحديث عن رسول الله صلي الله عليه وسلم شديد .', 'It was narrated that ''Abdur-Rahman bin Abi Laila said:We said to Zaid bin Arqam: ''Tell us a Hadith from the Messenger of Allah (ﷺ).'' He said: ''We have grown old and have forgotten, and (narrating) Ahadith from the Messenger of Allah (ﷺ) is difficult (not a simple matter)', NULL, '4588714110e11fc1a9c9f78962baa7a1aec49e677a08ea663caa28e0722af2cf', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (284, 'ibnmajah', 302, 26, 'Book 0, Hadith 26', 26, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ، حَدَّثَنَا أَبُو النَّضْرِ، عَنْ شُعْبَةَ، عَنْ عَبْدِ اللَّهِ بْنِ أَبِي السَّفَرِ، قَالَ سَمِعْتُ الشَّعْبِيَّ، يَقُولُ جَالَسْتُ ابْنَ عُمَرَ سَنَةً فَمَا سَمِعْتُهُ يُحَدِّثُ، عَنْ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ شَيْئًا', '.', '.', 'It was narrated that ''Abdullah bin Abu Safar said:"I heard Ash-Sha''bi saying: ''I sat with Ibn ''Umar for a year and I did not hear him narrate anything from the Messenger of Allah (ﷺ)', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (285, 'ibnmajah', 302, 27, 'Book 0, Hadith 27', 27, NULL, NULL, 'حَدَّثَنَا الْعَبَّاسُ بْنُ عَبْدِ الْعَظِيمِ الْعَنْبَرِيُّ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَنْبَأَنَا مَعْمَرٌ، عَنِ ابْنِ طَاوُسٍ، عَنْ أَبِيهِ، قَالَ سَمِعْتُ ابْنَ عَبَّاسٍ، يَقُولُ إِنَّمَا كُنَّا نَحْفَظُ الْحَدِيثَ وَالْحَدِيثُ يُحْفَظُ عَنْ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ فَأَمَّا إِذَا رَكِبْتُمُ الصَّعْبَ وَالذَّلُولَ فَهَيْهَاتَ', '.', '.', 'It was narrated from Ibn Tawus that his father said:"I heard Ibn ''Abbas saying: ''We used to memorize Ahadith, and Ahadith were memorized from the Messenger of Allah (ﷺ). But if you go to the extremes of either exaggeration or negligence (in narrating Ahadith), there is no way we can trust your Ahadith', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (286, 'ibnmajah', 302, 28, 'Book 0, Hadith 28', 28, NULL, NULL, 'حَدَّثَنَا أَحْمَدُ بْنُ عَبْدَةَ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ مُجَالِدٍ، عَنِ الشَّعْبِيِّ، عَنْ قَرَظَةَ بْنِ كَعْبٍ، قَالَ بَعَثَنَا عُمَرُ بْنُ الْخَطَّابِ إِلَى الْكُوفَةِ وَشَيَّعَنَا فَمَشَى مَعَنَا إِلَى مَوْضِعٍ يُقَالُ لَهُ صِرَارٌ', '. فَقَالَ أَتَدْرُونَ لِمَ مَشَيْتُ مَعَكُمْ قَالَ قُلْنَا لِحَقِّ صُحْبَةِ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ وَلِحَقِّ الأَنْصَارِ . قَالَ لَكِنِّي مَشَيْتُ مَعَكُمْ لِحَدِيثٍ أَرَدْتُ أَنْ أُحَدِّثَكُمْ بِهِ فَأَرَدْتُ أَنْ تَحْفَظُوهُ لِمَمْشَاىَ مَعَكُمْ إِنَّكُمْ تَقْدُمُونَ عَلَى قَوْمٍ لِلْقُرْآنِ فِي صُدُورِهِمْ هَزِيزٌ كَهَزِيزِ الْمِرْجَلِ فَإِذَا رَأَوْكُمْ مَدُّوا إِلَيْكُمْ أَعْنَاقَهُمْ وَقَالُوا أَصْحَابُ مُحَمَّدٍ . فَأَقِلُّوا الرِّوَايَةَ عَنْ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ ثُمَّ أَنَا شَرِيكُكُمْ .', '. فقال اتدرون لم مشيت معكم قال قلنا لحق صحبه رسول الله صلي الله عليه وسلم ولحق الانصار . قال لكني مشيت معكم لحديث اردت ان احدثكم به فاردت ان تحفظوه لممشاي معكم انكم تقدمون علي قوم للقران في صدورهم هزيز كهزيز المرجل فاذا راوكم مدوا اليكم اعناقهم وقالوا اصحاب محمد . فاقلوا الروايه عن رسول الله صلي الله عليه وسلم ثم انا شريككم .', 'It was narrated that Qarazah bin Ka''b said:"Umar bin Al-Khattab sent us to Kufah, and he accompanied us as far as a place called Sirar. He said: ''Do you know why I walked with you?'' We said: ''Because of the rights of the Messenger of Allah (ﷺ) and because of the rights of the Ansar.'' He said: ''No, rather it is because of words that I wanted to say to you. I wanted you to memorize it due to my walking with you. You are going to people in whose hearts the Qur''an bubbles like water in a copper cauldron. When they see you, they will look up at you, saying: "The Companions of Muhammad!" But do not recite many reports from the Messenger of Allah (ﷺ), then I will be your partner', NULL, '8344b8b114ed24ff0226358a0b3329f55c818f4a3aa6401acbb681f500a433eb', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (287, 'ibnmajah', 302, 29, 'Book 0, Hadith 29', 29, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا عَبْدُ الرَّحْمَنِ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ يَحْيَى بْنِ سَعِيدٍ، عَنِ السَّائِبِ بْنِ يَزِيدَ، قَالَ صَحِبْتُ سَعْدَ بْنَ مَالِكٍ مِنَ الْمَدِينَةِ إِلَى مَكَّةَ فَمَا سَمِعْتُهُ يُحَدِّثُ عَنِ النَّبِيِّ ـ صلى الله عليه وسلم ـ بِحَدِيثٍ وَاحِدٍ', '.', '.', 'It was narrated that Sa''ib bin Yazid said:"I accompanied Sa''d bin Malik from Al-Madinah to Makkah and I did not hear him narrate a single Hadith from the Prophet (ﷺ)', NULL, 'cdb4ee2aea69cc6a83331bbe96dc2caa9a299d21329efb0336fc02a82e1839a8', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (288, 'ibnmajah', 302, 30, 'Book 0, Hadith 30', 30, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَسُوَيْدُ بْنُ سَعِيدٍ، وَعَبْدُ اللَّهِ بْنُ عَامِرِ بْنِ زُرَارَةَ، وَإِسْمَاعِيلُ بْنُ مُوسَى، قَالُوا حَدَّثَنَا شَرِيكٌ، عَنْ سِمَاكٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، عَنْ أَبِيهِ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ', 'مَنْ كَذَبَ عَلَىَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ  .', 'من كذب علي متعمدا فليتبوا مقعده من النار .', 'It was narrated from ''Abdur-Rahman bin ''Abdullah bin Mas''ud that his father said:"The Messenger of Allah (ﷺ) said: ''Whoever tells lies about me deliberately, let him take his place in Hell', NULL, '17dc778cf49d44622abdcb92e5525e24d14de7361166f22d47c0d812fcef9bc3', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (289, 'ibnmajah', 302, 31, 'Book 0, Hadith 31', 31, NULL, NULL, 'حَدَّثَنَا عَبْدُ اللَّهِ بْنُ عَامِرِ بْنِ زُرَارَةَ، وَإِسْمَاعِيلُ بْنُ مُوسَى، قَالاَ حَدَّثَنَا شَرِيكٌ، عَنْ مَنْصُورٍ، عَنْ رِبْعِيِّ بْنِ حِرَاشٍ، عَنْ عَلِيٍّ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ', 'لاَ تَكْذِبُوا عَلَىَّ فَإِنَّ الْكَذِبَ عَلَىَّ يُولِجُ النَّارَ  .', 'لا تكذبوا علي فان الكذب علي يولج النار .', 'It was narrated from that ''Ali said:"The Messenger of Allah (ﷺ) said: ''Do not tell lies about me, for telling lies about me leads to Hell (Fire)', NULL, '33a845b0c8da6c09e86d1f598ec8fba7660f070b3288517b35caeb4e89c61a06', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (290, 'ibnmajah', 302, 32, 'Book 0, Hadith 32', 32, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ رُمْحٍ الْمِصْرِيُّ، حَدَّثَنَا اللَّيْثُ بْنُ سَعْدٍ، عَنِ ابْنِ شِهَابٍ، عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ', 'مَنْ كَذَبَ عَلَىَّ - حَسِبْتُهُ قَالَ مُتَعَمِّدًا - فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ  .', 'من كذب علي - حسبته قال متعمدا - فليتبوا مقعده من النار .', 'It was narrated that Anas bin Malik said:"The Messenger of Allah (ﷺ) said: ''Whoever tells lies about me'', I (the narrator) think that he also said ''deliberately'', let him take his place in Hell', NULL, 'e42bfcd23d651e372d699c18026fae0425aaaa8dc350bd783ad9c5619ea43cae', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (291, 'ibnmajah', 302, 33, 'Book 0, Hadith 33', 33, NULL, NULL, 'حَدَّثَنَا أَبُو خَيْثَمَةَ، زُهَيْرُ بْنُ حَرْبٍ حَدَّثَنَا هُشَيْمٌ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرٍ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ', 'مَنْ كَذَبَ عَلَىَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ  .', 'من كذب علي متعمدا فليتبوا مقعده من النار .', 'It was narrated from that Jabir said:"The Messenger of Allah (ﷺ) said: ''Whoever tells lies about me deliberately, let him take his place in Hell', NULL, '17dc778cf49d44622abdcb92e5525e24d14de7361166f22d47c0d812fcef9bc3', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (292, 'ibnmajah', 302, 34, 'Book 0, Hadith 34', 34, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا مُحَمَّدُ بْنُ بِشْرٍ، عَنْ مُحَمَّدِ بْنِ عَمْرٍو، عَنْ أَبِي سَلَمَةَ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ', 'مَنْ تَقَوَّلَ عَلَىَّ مَا لَمْ أَقُلْ فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ  .', 'من تقول علي ما لم اقل فليتبوا مقعده من النار .', 'It was narrated that Abu Hurairah said:"The Messenger of Allah (ﷺ) said: ''Whoever attributes to me something that I have not said, let him take his place in Hell', NULL, 'c1ecd6ef1af982380185102c0f2f71b8b14cb5aa4b20acfd1c3ad88e786b6a62', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (293, 'ibnmajah', 302, 35, 'Book 0, Hadith 35', 35, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا يَحْيَى بْنُ يَعْلَى التَّيْمِيُّ، عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ، عَنْ مَعْبَدِ بْنِ كَعْبٍ، عَنْ أَبِي قَتَادَةَ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ يَقُولُ عَلَى هَذَا الْمِنْبَرِ', 'إِيَّاكُمْ وَكَثْرَةَ الْحَدِيثِ عَنِّي فَمَنْ قَالَ عَلَىَّ فَلْيَقُلْ حَقًّا أَوْ صِدْقًا وَمَنْ تَقَوَّلَ عَلَىَّ مَا لَمْ أَقُلْ فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ  .', 'اياكم وكثره الحديث عني فمن قال علي فليقل حقا او صدقا ومن تقول علي ما لم اقل فليتبوا مقعده من النار .', 'It was narrated that Abu Qatadah said:"While he was on this pulpit, I heard the Messenger of Allah (ﷺ) saying: '' Beware of narrating too many Ahadith from me. Whoever attributes something to me, let him speak the truth faithfully. Whoever attributes to say something that I did not say, let him take his place in Hell', NULL, '17750897854d1d83d6c6facd627831983a0f357a33f2018f1bb5856d10706c16', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (294, 'ibnmajah', 302, 36, 'Book 0, Hadith 36', 36, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَمُحَمَّدُ بْنُ بَشَّارٍ، قَالاَ حَدَّثَنَا غُنْدَرٌ، مُحَمَّدُ بْنُ جَعْفَرٍ حَدَّثَنَا شُعْبَةُ، عَنْ جَامِعِ بْنِ شَدَّادٍ أَبِي صَخْرَةَ، عَنْ عَامِرِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ، عَنْ أَبِيهِ، قَالَ قُلْتُ لِلزُّبَيْرِ بْنِ الْعَوَّامِ مَا لِيَ لاَ أَسْمَعُكَ تُحَدِّثُ عَنْ رَسُولِ اللَّهِ ـ صلى الله عليه وسلم ـ كَمَا أَسْمَعُ ابْنَ مَسْعُودٍ وَفُلاَنًا وَفُلاَنًا قَالَ أَمَا إِنِّي لَمْ أُفَارِقْهُ مُنْذُ أَسْلَمْتُ وَلَكِنِّي سَمِعْتُ مِنْهُ كَلِمَةً يَقُولُ', 'مَنْ كَذَبَ عَلَىَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ  .', 'من كذب علي متعمدا فليتبوا مقعده من النار .', 'It was narrated from ''Amir bin ''Abdullah bin Zubair that his father said:"I said to Zubair bin Awwam: ''Why do I not hear you narrating Ahadith from the Messenger of Allah (ﷺ) as I hear Ibn Mas''ud and so-and-so and so-and-so?'' He said: ''I never left him from the time I became Muslim, but I heard him say a word: ''Whoever tells a lie about me deliberately, let him take his place in Hell', NULL, '17dc778cf49d44622abdcb92e5525e24d14de7361166f22d47c0d812fcef9bc3', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (295, 'ibnmajah', 302, 37, 'Book 0, Hadith 37', 37, NULL, NULL, 'حَدَّثَنَا سُوَيْدُ بْنُ سَعِيدٍ، حَدَّثَنَا عَلِيُّ بْنُ مُسْهِرٍ، عَنْ مُطَرِّفٍ، عَنْ عَطِيَّةَ، عَنْ أَبِي سَعِيدٍ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ', 'مَنْ كَذَبَ عَلَىَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ  .', 'من كذب علي متعمدا فليتبوا مقعده من النار .', 'It was narrated from Abu Sa''eed said:"The Messenger of Allah (ﷺ) said: ''Whoever tells lies about me deliberately, let him take his place in Hell', NULL, '17dc778cf49d44622abdcb92e5525e24d14de7361166f22d47c0d812fcef9bc3', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (296, 'ibnmajah', 302, 38, 'Book 0, Hadith 38', 38, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا عَلِيُّ بْنُ هَاشِمٍ، عَنِ ابْنِ أَبِي لَيْلَى، عَنِ الْحَكَمِ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى، عَنْ عَلِيٍّ، عَنِ النَّبِيِّ ـ صلى الله عليه وسلم ـ قَالَ', 'مَنْ حَدَّثَ عَنِّي حَدِيثًا وَهُوَ يُرَى أَنَّهُ كَذِبٌ فَهُوَ أَحَدُ الْكَاذِبَيْنِ  .', 'من حدث عني حديثا وهو يري انه كذب فهو احد الكاذبين .', 'It was narrated from ''Ali that:The Prophet (ﷺ) said: ''"Whoever narrates a Hadith from me thinking it to be false, then he is one of the two liars." (Either the one who invents a lie or the one who repeats it; both are liars)', NULL, 'cc2b8e5356a8f622bc97a8f1623c9163da95c339f6d6179019f675d249d913a8', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (297, 'ibnmajah', 302, 39, 'Book 0, Hadith 39', 39, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، قَالَ حَدَّثَنَا وَكِيعٌ، ح وَحَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، قَالاَ حَدَّثَنَا شُعْبَةُ، عَنِ الْحَكَمِ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى، عَنْ سَمُرَةَ بْنِ جُنْدُبٍ، عَنِ النَّبِيِّ ـ صلى الله عليه وسلم ـ قَالَ', 'مَنْ حَدَّثَ عَنِّي حَدِيثًا وَهُوَ يَرَى أَنَّهُ كَذِبٌ فَهُوَ أَحَدُ الْكَاذِبَيْنِ  .', 'من حدث عني حديثا وهو يري انه كذب فهو احد الكاذبين .', 'It was narrated from Samurah bin Jundub that:The Prophet (ﷺ) said: ''"Whoever narrated a Hadith from me thinking it to be false, then he is one of the two liars', NULL, '377e344b7fd6b4bb85f4170a527bb9770b4ec212ca9c5f2c03b0e8d7d5fdf6a2', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (298, 'ibnmajah', 302, 40, 'Book 0, Hadith 40', 40, NULL, NULL, 'حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا مُحَمَّدُ بْنُ فُضَيْلٍ، عَنِ الأَعْمَشِ، عَنِ الْحَكَمِ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى، عَنْ عَلِيٍّ، عَنِ النَّبِيِّ ـ صلى الله عليه وسلم ـ قَالَ', 'مَنْ رَوَى عَنِّي حَدِيثًا وَهُوَ يَرَى أَنَّهُ كَذِبٌ فَهُوَ أَحَدُ الْكَاذِبَيْنِ  . حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ، أَنْبَأَنَا الْحَسَنُ بْنُ مُوسَى الأَشْيَبُ، عَنْ شُعْبَةَ، مِثْلَ حَدِيثِ سَمُرَةَ بْنِ جُنْدُبٍ .', 'من روي عني حديثا وهو يري انه كذب فهو احد الكاذبين . حدثنا محمد بن عبد الله، انبانا الحسن بن موسي الاشيب، عن شعبه، مثل حديث سمره بن جندب .', 'It was narrated from `Ali that:The Prophet (ﷺ) said: "Whoever narrates a Hadith from me thinking it to be false, then he is one of the two liars." Another chain similar to the narration of Samurah bin Jundub', NULL, 'f9c909f720eb53ba11dd1676130a35d71d80bd5e40958cae515ea83462a367b9', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (299, 'ibnmajah', 302, 41, 'Book 0, Hadith 41', 41, NULL, NULL, 'حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا وَكِيعٌ، عَنْ سُفْيَانَ، عَنْ حَبِيبِ بْنِ أَبِي ثَابِتٍ، عَنْ مَيْمُونِ بْنِ أَبِي شَبِيبٍ، عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ', 'مَنْ حَدَّثَ عَنِّي بِحَدِيثٍ وَهُوَ يَرَى أَنَّهُ كَذِبٌ فَهُوَ أَحَدُ الْكَاذِبَيْنِ  .', 'من حدث عني بحديث وهو يري انه كذب فهو احد الكاذبين .', 'It was narrated that Mughirah bin Shu''bah said:The Messenger of Allah (ﷺ) said: ''"Whoever narrates a Hadith from me thinking it to be false, then he is one of the two liars', NULL, '3db04e1b07e8d31a30b7ddd830079f56bace435bce3282306f77e80e8d076808', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (300, 'ibnmajah', 302, 42, 'Book 0, Hadith 42', 42, NULL, NULL, 'حَدَّثَنَا عَبْدُ اللَّهِ بْنُ أَحْمَدَ بْنِ بَشِيرِ بْنِ ذَكْوَانَ الدِّمَشْقِيُّ، حَدَّثَنَا الْوَلِيدُ بْنُ مُسْلِمٍ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ الْعَلاَءِ، - يَعْنِي ابْنَ زَبْرٍ - حَدَّثَنِي يَحْيَى بْنُ أَبِي الْمُطَاعِ، قَالَ سَمِعْتُ الْعِرْبَاضَ بْنَ سَارِيَةَ، يَقُولُ قَامَ فِينَا رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ذَاتَ يَوْمٍ فَوَعَظَنَا مَوْعِظَةً بَلِيغَةً وَجِلَتْ مِنْهَا الْقُلُوبُ وَذَرَفَتْ مِنْهَا الْعُيُونُ فَقِيلَ يَا رَسُولَ اللَّهِ وَعَظْتَنَا مَوْعِظَةَ مُوَدِّعٍ فَاعْهَدْ إِلَيْنَا بِعَهْدٍ فَقَالَ', 'عَلَيْكُمْ بِتَقْوَى اللَّهِ وَالسَّمْعِ وَالطَّاعَةِ وَإِنْ عَبْدًا حَبَشِيًّا وَسَتَرَوْنَ مِنْ بَعْدِي اخْتِلاَفًا شَدِيدًا فَعَلَيْكُمْ بِسُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيِّينَ عَضُّوا عَلَيْهَا بِالنَّوَاجِذِ وَإِيَّاكُمْ وَالأُمُورَ الْمُحْدَثَاتِ فَإِنَّ كُلَّ بِدْعَةٍ ضَلاَلَةٌ  .', 'عليكم بتقوي الله والسمع والطاعه وان عبدا حبشيا وسترون من بعدي اختلافا شديدا فعليكم بسنتي وسنه الخلفاء الراشدين المهديين عضوا عليها بالنواجذ واياكم والامور المحدثات فان كل بدعه ضلاله .', 'Yahya bin Abu Muta'' said:I heard ''Irbad bin Sariyah say: ''One day, the Messenger of Allah (ﷺ) stood up among us and delivered a deeply moving speech to us that melted our hearts and caused our eyes to overflow with tears. It was said to him: ''O Messenger of Allah, you have delivered a speech of farewell, so enjoin something upon us.'' He said: ''I urge you to fear Allah, and to listen and obey, even if (your leader) is an Abyssinian slave. After I am gone, you will see great conflict. I urge you to adhere to my Sunnah and the path of the Rightly-Guided Caliphs, and cling stubbornly to it. And beware of newly-invented matters, for every innovation is a going astray', NULL, '76776f36c206411c01488f7dbd43908f9ea6470687ce6e0a788eec0300b5073f', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published')
INSERT INTO public.hadith_narrations (id, collection_id, book_id, hadith_number, in_book_reference, international_number, chapter_title_arabic, chapter_title_english, sanad_arabic, matn_arabic, matn_clean, translation_english, translation_urdu, text_checksum, source_edition, version_number, is_current, status) VALUES
  (301, 'ibnmajah', 302, 43, 'Book 0, Hadith 43', 43, NULL, NULL, 'حَدَّثَنَا إِسْمَاعِيلُ بْنُ بِشْرِ بْنِ مَنْصُورٍ، وَإِسْحَاقُ بْنُ إِبْرَاهِيمَ السَّوَّاقُ، قَالاَ حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ، عَنْ مُعَاوِيَةَ بْنِ صَالِحٍ، عَنْ ضَمْرَةَ بْنِ حَبِيبٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَمْرٍو السَّلَمِيِّ، أَنَّهُ سَمِعَ الْعِرْبَاضَ بْنَ سَارِيَةَ، يَقُولُ وَعَظَنَا رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ مَوْعِظَةً ذَرَفَتْ مِنْهَا الْعُيُونُ وَوَجِلَتْ مِنْهَا الْقُلُوبُ فَقُلْنَا يَا رَسُولَ اللَّهِ إِنَّ هَذِهِ لَمَوْعِظَةُ مُوَدِّعٍ فَمَاذَا تَعْهَدُ إِلَيْنَا قَالَ', 'قَدْ تَرَكْتُكُمْ عَلَى الْبَيْضَاءِ لَيْلُهَا كَنَهَارِهَا لاَ يَزِيغُ عَنْهَا بَعْدِي إِلاَّ هَالِكٌ مَنْ يَعِشْ مِنْكُمْ فَسَيَرَى اخْتِلاَفًا كَثِيرًا فَعَلَيْكُمْ بِمَا عَرَفْتُمْ مِنْ سُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيِّينَ عَضُّوا عَلَيْهَا بِالنَّوَاجِذِ وَعَلَيْكُمْ بِالطَّاعَةِ وَإِنْ عَبْدًا حَبَشِيًّا فَإِنَّمَا الْمُؤْمِنُ كَالْجَمَلِ الأَنِفِ حَيْثُمَا قِيدَ انْقَادَ  .', 'قد تركتكم علي البيضاء ليلها كنهارها لا يزيغ عنها بعدي الا هالك من يعش منكم فسيري اختلافا كثيرا فعليكم بما عرفتم من سنتي وسنه الخلفاء الراشدين المهديين عضوا عليها بالنواجذ وعليكم بالطاعه وان عبدا حبشيا فانما المؤمن كالجمل الانف حيثما قيد انقاد .', 'It was narrated from ''Abdur-Rahman bin ''Amr As-Sulami that:He heard Al-''Irbad bin Sariyah say: "The Messenger of Allah (ﷺ) delivered a moving speech to us which made our eyes flow with tears and made our hearts melt. We said: ''O Messenger of Allah. This is a speech of farewell. What did you enjoin upon us?'' He said: ''I am leaving you upon a (path of) brightness whose night is like its day. No one will deviate from it after I am gone but one who is doomed. Whoever among you lives will see great conflict. I urge you to adhere to what you know of my Sunnah and the path of the Rightly-Guided Caliphs, and cling stubbornly to it. And you must obey, even if (your leader is) an Abyssinian leader. For the true believer is like a camel with a ring in its nose; wherever it is driven, it complies', NULL, '5b04aa5d6784b9a7524809e77e7fe46c70e5b1a23039dee749e21e4c5fea44a5', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (302, 'ibnmajah', 302, 44, 'Book 0, Hadith 44', 44, NULL, NULL, 'حَدَّثَنَا يَحْيَى بْنُ حَكِيمٍ، حَدَّثَنَا عَبْدُ الْمَلِكِ بْنُ الصَّبَّاحِ الْمِسْمَعِيُّ، حَدَّثَنَا ثَوْرُ بْنُ يَزِيدَ، عَنْ خَالِدِ بْنِ مَعْدَانَ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَمْرٍو، عَنِ الْعِرْبَاضِ بْنِ سَارِيَةَ، قَالَ صَلَّى بِنَا رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ صَلاَةَ الصُّبْحِ ثُمَّ أَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَوَعَظَنَا مَوْعِظَةً بَلِيغَةً', '. فَذَكَرَ نَحْوَهُ .', '. فذكر نحوه .', 'It was narrated from ''Irbad bin Sariyah said:"The Messenger of Allah (ﷺ) led us in Fajr (morning) prayer, then he turned to us and delivered an eloquent speech". And he mentioned something similar (as no)', NULL, '87947028738102d206e22b00574263a59ff2ea74bd97305b64ac83e6cf149a29', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (303, 'ibnmajah', 302, 45, 'Book 0, Hadith 45', 45, NULL, NULL, 'حَدَّثَنَا سُوَيْدُ بْنُ سَعِيدٍ، وَأَحْمَدُ بْنُ ثَابِتٍ الْجَحْدَرِيُّ، قَالاَ حَدَّثَنَا عَبْدُ الْوَهَّابِ الثَّقَفِيُّ، عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ، عَنْ أَبِيهِ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ كَانَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ إِذَا خَطَبَ احْمَرَّتْ عَيْنَاهُ وَعَلاَ صَوْتُهُ وَاشْتَدَّ غَضَبُهُ كَأَنَّهُ مُنْذِرُ جَيْشٍ يَقُولُ', 'صَبَّحَكُمْ مَسَّاكُمْ  . وَيَقُولُ  بُعِثْتُ أَنَا وَالسَّاعَةَ كَهَاتَيْنِ  . وَيَقْرِنُ بَيْنَ إِصْبَعَيْهِ السَّبَّابَةِ وَالْوُسْطَى ثُمَّ يَقُولُ  أَمَّا بَعْدُ فَإِنَّ خَيْرَ الأُمُورِ كِتَابُ اللَّهِ وَخَيْرَ الْهَدْىِ هَدْىُ مُحَمَّدٍ وَشَرَّ الأُمُورِ مُحْدَثَاتُهَا وَكُلَّ بِدْعَةٍ ضَلاَلَةٌ  . وَكَانَ يَقُولُ  مَنْ تَرَكَ مَالاً فَلأَهْلِهِ وَمَنْ تَرَكَ دَيْنًا أَوْ ضَيَاعًا فَعَلَىَّ وَإِلَىَّ  .', 'صبحكم مساكم . ويقول بعثت انا والساعه كهاتين . ويقرن بين اصبعيه السبابه والوسطي ثم يقول اما بعد فان خير الامور كتاب الله وخير الهدي هدي محمد وشر الامور محدثاتها وكل بدعه ضلاله . وكان يقول من ترك مالا فلاهله ومن ترك دينا او ضياعا فعلي والي .', 'It was narrated that Jabir bin ''Abdullah said:"When the Messenger of Allah (ﷺ) delivered a sermon, his eyes would turn red, he would raise his voice and he would speak with intensity, as if he were warning of an (enemy) army, saying, ''They will surely attack you in the morning, or they will surely attack you in the evening!'' He would say: ''I and the Hour have been sent like these two,'' and he would hold his index and middle finger. Then he would say: ''The best of guidance is the guidance of Muhammad. The most evil matters are those that are newly-invented, and every innovation (Bid''ah) is a going astray.'' And he used to say: ''Whoever dies and leaves behind some wealth, it is for his family, and whoever leaves behind a debt or dependent children, then they are both my responsibility', NULL, '18ade238c3487b767e54c4ebf6055a7c102bd5dca0a34202096d8f4f33429075', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (304, 'ibnmajah', 302, 46, 'Book 0, Hadith 46', 46, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ عُبَيْدِ بْنِ مَيْمُونٍ الْمَدَنِيُّ أَبُو عُبَيْدٍ، حَدَّثَنَا أَبِي، عَنْ مُحَمَّدِ بْنِ جَعْفَرِ بْنِ أَبِي كَثِيرٍ، عَنْ مُوسَى بْنِ عُقْبَةَ، عَنْ أَبِي إِسْحَاقَ، عَنْ أَبِي الأَحْوَصِ، عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، أَنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ قَالَ', 'إِنَّمَا هُمَا اثْنَتَانِ الْكَلاَمُ وَالْهَدْىُ فَأَحْسَنُ الْكَلاَمِ كَلاَمُ اللَّهِ وَأَحْسَنُ الْهَدْىِ هَدْىُ مُحَمَّدٍ أَلاَ وَإِيَّاكُمْ وَمُحْدَثَاتِ الأُمُورِ فَإِنَّ شَرَّ الأُمُورِ مُحْدَثَاتُهَا وَكُلُّ مُحْدَثَةٍ بِدْعَةٌ وَكُلُّ بِدْعَةٍ ضَلاَلَةٌ أَلاَ لاَ يَطُولَنَّ عَلَيْكُمُ الأَمَدُ فَتَقْسُوَ قُلُوبُكُمْ أَلاَ إِنَّ مَا هُوَ آتٍ قَرِيبٌ وَإِنَّمَا الْبَعِيدُ مَا لَيْسَ بِآتٍ أَلاَ إِنَّ الشَّقِيَّ مَنْ شَقِيَ فِي بَطْنِ أُمِّهِ وَالسَّعِيدَ مَنْ وُعِظَ بِغَيْرِهِ أَلاَ إِنَّ قِتَالَ الْمُؤْمِنِ كُفْرٌ وَسِبَابُهُ فُسُوقٌ وَلاَ يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلاَثٍ أَلاَ وَإِيَّاكُمْ وَالْكَذِبَ فَإِنَّ الْكَذِبَ لاَ يَصْلُحُ بِالْجِدِّ وَلاَ بِالْهَزْلِ وَلاَ يَعِدِ الرَّجُلُ صَبِيَّهُ ثُمَّ لاَ يَفِيَ لَهُ فَإِنَّ الْكَذِبَ يَهْدِي إِلَى الْفُجُورِ وَإِنَّ الْفُجُورَ يَهْدِي إِلَى النَّارِ وَإِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ وَإِنَّ الْبِرَّ يَهْدِي إِلَى الْجَنَّةِ وَإِنَّهُ يُقَالُ لِلصَّادِقِ صَدَقَ وَبَرَّ . وَيُقَالُ لِلْكَاذِبِ كَذَبَ وَفَجَرَ . أَلاَ وَإِنَّ الْعَبْدَ يَكْذِبُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ كَذَّابًا  .', 'انما هما اثنتان الكلام والهدي فاحسن الكلام كلام الله واحسن الهدي هدي محمد الا واياكم ومحدثات الامور فان شر الامور محدثاتها وكل محدثه بدعه وكل بدعه ضلاله الا لا يطولن عليكم الامد فتقسو قلوبكم الا ان ما هو ات قريب وانما البعيد ما ليس بات الا ان الشقي من شقي في بطن امه والسعيد من وعظ بغيره الا ان قتال المؤمن كفر وسبابه فسوق ولا يحل لمسلم ان يهجر اخاه فوق ثلاث الا واياكم والكذب فان الكذب لا يصلح بالجد ولا بالهزل ولا يعد الرجل صبيه ثم لا يفي له فان الكذب يهدي الي الفجور وان الفجور يهدي الي النار وان الصدق يهدي الي البر وان البر يهدي الي الجنه وانه يقال للصادق صدق وبر . ويقال للكاذب كذب وفجر . الا وان العبد يكذب حتي يكتب عند الله كذابا .', 'It was narrated from Abdullah bin Mas''ud that:the Messenger of Allah (ﷺ) said: "Verily there are two things - words and guidance. The best words are the words of Allah, and the best guidance in the guidance of Muhammad. Beware of newly-invented matters, for every newly-invented matter is an innovation (Bid''ah) and every innovation is a going-stray. Do not let the desire for a long life causes your hearts to grow hard. That which is bound to happen is close to you, and the only thing that is far away is that which is not going to happen. The one who is doomed to Hell is doomed from his mother''s womb, and the one who is destined for Paradise is the one who learns from the lessons of others. Killing a believer constitutes disbelief (Kufr) and verbally abusing him is immorality (Fusuq). It is not permissible for a Muslim to forsake his brother for more than three days. Beware of lying, for lying is never good, whether it is done seriously or in jest. A man should not make a promise to a child that he will not keep. Lying leads to immorality and immorality leads to Hell. Truthfulness leads to righteousness and righteousness leads to Paradise. It will be said of the truthful person: ''He spoke the truth and was righteous'', and it will be said of the liar, ''He told lies and was immoral.'' "For a person continues to tell lies until he is recorded with Allah as a liar', NULL, '69f04dcd6522251cc630bc2f7eba001a6f7457a9031ead3e6c0eab0d3eccc4aa', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (305, 'ibnmajah', 302, 47, 'Book 0, Hadith 47', 47, NULL, NULL, 'حَدَّثَنَا مُحَمَّدُ بْنُ خَالِدِ بْنِ خِدَاشٍ، حَدَّثَنَا إِسْمَاعِيلُ ابْنُ عُلَيَّةَ، حَدَّثَنَا أَيُّوبُ، ح وَحَدَّثَنَا أَحْمَدُ بْنُ ثَابِتٍ الْجَحْدَرِيُّ، وَيَحْيَى بْنُ حَكِيمٍ، قَالاَ حَدَّثَنَا عَبْدُ الْوَهَّابِ، حَدَّثَنَا أَيُّوبُ، عَنْ عَبْدِ اللَّهِ بْنِ أَبِي مُلَيْكَةَ، عَنْ عَائِشَةَ، قَالَتْ تَلاَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ هَذِهِ الآيَةَ {هُوَ الَّذِي أَنْزَلَ عَلَيْكَ الْكِتَابَ مِنْهُ آيَاتٌ مُحْكَمَاتٌ هُنَّ أُمُّ الْكِتَابِ وَأُخَرُ مُتَشَابِهَاتٌ}', 'إِلَى قَوْلِهِ {وَمَا يَذَّكَّرُ إِلاَّ أُولُو الأَلْبَابِ} . فَقَالَ  يَا عَائِشَةُ إِذَا رَأَيْتُمُ الَّذِينَ يُجَادِلُونَ فِيهِ فَهُمُ الَّذِينَ عَنَاهُمُ اللَّهُ فَاحْذَرُوهُمْ  .', 'الي قوله {وما يذكر الا اولو الالباب} . فقال يا عائشه اذا رايتم الذين يجادلون فيه فهم الذين عناهم الله فاحذروهم .', 'It was narrated that ''Aishah said:"The Messenger of Allah (ﷺ) recited the following Verse: ''It is He Who has sent down to you (Muhammad) the Book (this Qur''an). In it are verses that are entirely clear, they are the foundations of the Book; and others not entirely clear (up to His saying: ) ''And none receive admonition except men of understanding.'' Then he said: ''O ''Aishah, if you see those who dispute concerning it (the Qur''an), they are those whom Allah has referred to here, so beware of them', NULL, 'b1def56c445a33dbd77b58505e20fba0456a726f9b7b0330ad8fee7dd9910871', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (306, 'ibnmajah', 302, 48, 'Book 0, Hadith 48', 48, NULL, NULL, 'حَدَّثَنَا عَلِيُّ بْنُ الْمُنْذِرِ، حَدَّثَنَا مُحَمَّدُ بْنُ فُضَيْلٍ، ح وَحَدَّثَنَا حَوْثَرَةُ بْنُ مُحَمَّدٍ، حَدَّثَنَا مُحَمَّدُ بْنُ بِشْرٍ، قَالاَ حَدَّثَنَا حَجَّاجُ بْنُ دِينَارٍ، عَنْ أَبِي غَالِبٍ، عَنْ أَبِي أُمَامَةَ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ', 'مَا ضَلَّ قَوْمٌ بَعْدَ هُدًى كَانُوا عَلَيْهِ إِلاَّ أُوتُوا الْجَدَلَ  . ثُمَّ تَلاَ هَذِهِ الآيَةَ {بَلْ هُمْ قَوْمٌ خَصِمُونَ} .', 'ما ضل قوم بعد هدي كانوا عليه الا اوتوا الجدل . ثم تلا هذه الايه {بل هم قوم خصمون} .', 'It was narrated that Abu Umamah said:"The Messenger of Allah (ﷺ) said: ''No people go astray after having followed right guidance, but those who indulge in disputes.'' Then he recited the Verse: "Nay! But they are a quarrelsome people', NULL, '0b29bfaf594029fa3274c662b10206a8e3fd1722f8ddac6d0d152d9dca874e45', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (307, 'ibnmajah', 302, 49, 'Book 0, Hadith 49', 49, NULL, NULL, 'حَدَّثَنَا دَاوُدُ بْنُ سُلَيْمَانَ الْعَسْكَرِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ عَلِيٍّ أَبُو هَاشِمٍ بْنُ أَبِي خِدَاشٍ الْمَوْصِلِيُّ، قَالَ حَدَّثَنَا مُحَمَّدُ بْنُ مِحْصَنٍ، عَنْ إِبْرَاهِيمَ بْنِ أَبِي عَبْلَةَ، عَنْ عَبْدِ اللَّهِ بْنِ الدَّيْلَمِيِّ، عَنْ حُذَيْفَةَ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ', 'لاَ يَقْبَلُ اللَّهُ لِصَاحِبِ بِدْعَةٍ صَوْمًا وَلاَ صَلاَةً وَلاَ صَدَقَةً وَلاَ حَجًّا وَلاَ عُمْرَةً وَلاَ جِهَادًا وَلاَ صَرْفًا وَلاَ عَدْلاً يَخْرُجُ مِنَ الإِسْلاَمِ كَمَا تَخْرُجُ الشَّعَرَةُ مِنَ الْعَجِينِ  .', 'لا يقبل الله لصاحب بدعه صوما ولا صلاه ولا صدقه ولا حجا ولا عمره ولا جهادا ولا صرفا ولا عدلا يخرج من الاسلام كما تخرج الشعره من العجين .', 'It was narrated that Hudhaifah said:"The Messenger of Allah (ﷺ) said: ''Allah will not accept any fasting, prayer, charity, Hajj, ''Umrah, Jihad, or any other obligatory or voluntary action from a person who follows innovation (Bid''ah). He comes out of Islam like a hair pulled out of dough', NULL, 'fe0454dc9aab36f438d53216b7e01c33d1d2ef3c22ff3903c62729a594f3b5f8', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published'),
  (308, 'ibnmajah', 302, 50, 'Book 0, Hadith 50', 50, NULL, NULL, 'حَدَّثَنَا عَبْدُ اللَّهِ بْنُ سَعِيدٍ، حَدَّثَنَا بِشْرُ بْنُ مَنْصُورٍ الْخَيَّاطُ، عَنْ أَبِي زَيْدٍ، عَنْ أَبِي الْمُغِيرَةِ، عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ', 'أَبَى اللَّهُ أَنْ يَقْبَلَ عَمَلَ صَاحِبِ بِدْعَةٍ حَتَّى يَدَعَ بِدْعَتَهُ  .', 'ابي الله ان يقبل عمل صاحب بدعه حتي يدع بدعته .', 'It was narrated that ''Abdullah bin ''Abbas said:"The Messenger of Allah (ﷺ) said: ''Allah refuses to accept the good deeds of one who follows innovation until he gives up that innovation', NULL, '006ade86069ba220dd2f527091c1a2acc684cc624c289e4a81c1a8d692dbf2e8', 'IBNMAJAH Darussalam Reference Edition', 1, TRUE, 'published')
